package approval

import java.time.Instant

case class ApprovalRecord(
    buildId: String,
    developerId: String,
    version: String,
    approvedDigest: String,
    approvedAt: Instant,
    reviewer: String,
    malwareReportId: String
)

class ReviewLedger {

    private var approvals =
        Map.empty[String, ApprovalRecord]

    def recordApproval(
        buildId: String,
        developerId: String,
        version: String,
        digest: String,
        reviewer: String,
        malwareReportId: String
    ): ApprovalRecord = {

        val approval =
            ApprovalRecord(
                buildId,
                developerId,
                version,
                digest,
                Instant.now(),
                reviewer,
                malwareReportId
            )

        approvals +=
            buildId -> approval

        approval
    }

    def findApproval(
        buildId: String
    ): Option[ApprovalRecord] = {

        approvals.get(
            buildId
        )
    }

    def isApproved(
        buildId: String
    ): Boolean = {

        approvals.contains(
            buildId
        )
    }

    def latestDigest(
        buildId: String
    ): Option[String] = {

        approvals
            .get(buildId)
            .map(_.approvedDigest)
    }

    def latestApproval(
        developerId: String
    ): Seq[ApprovalRecord] = {

        approvals.values
            .filter(
                _.developerId ==
                    developerId
            )
            .toSeq
            .sortBy(
                _.approvedAt
            )
            .reverse
    }
}
