<?php

namespace Approval;

class ApprovedBuild
{
    public string $buildId;

    public string $developerId;

    public string $version;

    public string $bundleDigest;

    public string $bundleLocation;

    public string $signatureId;

    public function __construct(
        string $buildId,
        string $developerId,
        string $version,
        string $bundleDigest,
        string $bundleLocation,
        string $signatureId
    )
    {
        $this->buildId = $buildId;
        $this->developerId = $developerId;
        $this->version = $version;
        $this->bundleDigest = $bundleDigest;
        $this->bundleLocation = $bundleLocation;
        $this->signatureId = $signatureId;
    }
}

class ApprovedBuildStore
{
    /**
     * @var array<string, ApprovedBuild>
     */
    private array $approvedBuilds = [];

    public function save(
        ApprovedBuild $build
    ): void
    {
        $this->approvedBuilds[
            $build->buildId
        ] = $build;
    }

    public function find(
        string $buildId
    ): ?ApprovedBuild
    {
        return $this->approvedBuilds[
            $buildId
        ] ?? null;
    }

    public function exists(
        string $buildId
    ): bool
    {
        return isset(
            $this->approvedBuilds[
                $buildId
            ]
        );
    }

    public function findByDeveloper(
        string $developerId
    ): array
    {
        return array_values(
            array_filter(
                $this->approvedBuilds,
                fn (ApprovedBuild $build) =>
                    $build->developerId ===
                    $developerId
            )
        );
    }

    public function approvedDigest(
        string $buildId
    ): ?string
    {
        return $this->find(
            $buildId
        )?->bundleDigest;
    }
}
