const std = @import("std");
const BundleManifest = @import("BundleManifest.zig").BundleManifest;
const ApprovedBuild = @import("../approval/ApprovedBuildStore.zig").ApprovedBuild;
const DigestCalculator = @import("../shared/DigestCalculator.zig").DigestCalculator;

pub const OptimizedBundle = struct {
    bundle_id: []const u8,
    source_build_id: []const u8,
    optimized_digest: []const u8,
    manifest: BundleManifest,
    output_path: []const u8,
};

pub const BundleComposer = struct {

    allocator: std.mem.Allocator,

    pub fn compose(
        self: *BundleComposer,
        build: ApprovedBuild,
        optimizedPath: []const u8,
    ) !OptimizedBundle {

        const digest =
            try DigestCalculator
                .sha256File(
                    self.allocator,
                    optimizedPath,
                );

        const manifest =
            BundleManifest.init(
                build.buildId,
                build.version,
                build.bundleDigest,
                digest,
            );

        return OptimizedBundle{
            .bundle_id =
                try self.generateBundleId(
                    build.buildId,
                    digest,
                ),

            .source_build_id =
                build.buildId,

            .optimized_digest =
                digest,

            .manifest =
                manifest,

            .output_path =
                optimizedPath,
        };
    }

    fn generateBundleId(
        self: *BundleComposer,
        buildId: []const u8,
        digest: []const u8,
    ) ![]const u8 {

        _ = self;

        return std.fmt.allocPrint(
            std.heap.page_allocator,
            "{s}-{s}",
            .{
                buildId,
                digest[0..12],
            },
        );
    }
};
