local BundleManifest = {}

BundleManifest.__index = BundleManifest

function BundleManifest.new(
    sourceBuildId,
    version,
    approvedDigest,
    optimizedDigest
)

    local manifest = {

        source_build_id =
            sourceBuildId,

        version =
            version,

        approved_digest =
            approvedDigest,

        optimized_digest =
            optimizedDigest,

        optimization_profile =
            "release",

        generated_at =
            os.time()
    }

    setmetatable(
        manifest,
        BundleManifest
    )

    return manifest
end

function BundleManifest:isCompatible(
    approvedBuild
)

    return self.source_build_id ==
               approvedBuild.buildId
       and
           self.version ==
               approvedBuild.version
end

function BundleManifest:approvedDigest()

    return self.approved_digest

end

function BundleManifest:optimizedDigest()

    return self.optimized_digest

end

function BundleManifest:sourceBuild()

    return self.source_build_id

end

return BundleManifest
