## FILE: storage/BundleArchive.zig

```
const std = @import("std");

pub const OptimizedBundle = struct {
    bundle_id: []const u8,
    source_build_id: []const u8,
    version: []const u8,
    optimized_digest: []const u8,
    bundle_path: []const u8,
    manifest_path: []const u8,
    profile: []const u8,
    created_at: i64,
};

pub const BundleArchive = struct {
    allocator: std.mem.Allocator,
    bundles: std.StringHashMap(OptimizedBundle),

    pub fn init(
        allocator: std.mem.Allocator,
    ) BundleArchive {

        return .{
            .allocator = allocator,
            .bundles = std.StringHashMap(
                OptimizedBundle,
            ).init(allocator),
        };
    }

    pub fn storeBundle(
        self: *BundleArchive,
        bundle: OptimizedBundle,
    ) !void {

        try self.validateBundle(
            bundle,
        );

        try self.bundles.put(
            bundle.bundle_id,
            bundle,
        );
    }

    pub fn findBundle(
        self: *BundleArchive,
        bundleId: []const u8,
    ) !OptimizedBundle {

        const bundle =
            self.bundles.get(
                bundleId,
            ) orelse
                return error.BundleNotFound;

        return bundle;
    }

    pub fn latestForBuild(
        self: *BundleArchive,
        buildId: []const u8,
    ) !OptimizedBundle {

        var iterator =
            self.bundles.iterator();

        var newest:
            ?OptimizedBundle = null;

        while (
            iterator.next()
        ) |entry| {

            const bundle =
                entry.value_ptr.*;

            if (
                !std.mem.eql(
                    u8,
                    bundle.source_build_id,
                    buildId,
                )
            ) {
                continue;
            }

            if (
                newest == null or
                bundle.created_at >
                    newest.?.created_at
            ) {
                newest = bundle;
            }
        }

        return newest
            orelse
                error.BundleNotFound;
    }

    pub fn exists(
        self: *BundleArchive,
        bundleId: []const u8,
    ) bool {

        return self.bundles.contains(
            bundleId,
        );
    }

    fn validateBundle(
        self: *BundleArchive,
        bundle: OptimizedBundle,
    ) !void {

        _ = self;

        if (
            bundle.bundle_id.len == 0
        ) {
            return error.InvalidBundleId;
        }

        if (
            bundle.source_build_id.len == 0
        ) {
            return error.InvalidSourceBuild;
        }

        if (
            bundle.version.len == 0
        ) {
            return error.InvalidVersion;
        }

        if (
            bundle.optimized_digest.len == 0
        ) {
            return error.InvalidDigest;
        }

        if (
            bundle.bundle_path.len == 0
        ) {
            return error.InvalidBundlePath;
        }

        if (
            bundle.manifest_path.len == 0
        ) {
            return error.InvalidManifestPath;
        }
    }

    pub fn remove(
        self: *BundleArchive,
        bundleId: []const u8,
    ) void {

        _ = self.bundles.remove(
            bundleId,
        );
    }
};
