```
defmodule Optimization.PublicationAssembler do
  alias Approval.ReviewLedger
  alias Approval.ApprovedBuildStore
  alias Optimization.BundleManifest
  alias Storage.BundleArchive
  alias Storage.PublicationStore
  alias Shared.ManifestEncoder

  def build_publication(
        build_id,
        bundle_id,
        developer_id,
        repositories
      ) do

    with {:ok, approval} <-
           ReviewLedger.find(
             repositories.review_ledger,
             build_id
           ),

         {:ok, approved_build} <-
           ApprovedBuildStore.find(
             repositories.build_store,
             build_id
           ),

         {:ok, bundle} <-
           BundleArchive.find_bundle(
             repositories.bundle_archive,
             bundle_id
           ) do

      validate_developer!(
        approval,
        developer_id
      )

      validate_version!(
        approved_build,
        bundle
      )

      validate_profile!(
        bundle
      )

      manifest =
        create_manifest(
          approval,
          approved_build,
          bundle
        )

      publication =
        %{
          publication_id:
            generate_publication_id(
              build_id,
              bundle.bundle_id
            ),

          build_id:
            build_id,

          bundle_id:
            bundle.bundle_id,

          developer_id:
            developer_id,

          version:
            bundle.version,

          publication_manifest:
            manifest,

          artifact_location:
            bundle.bundle_path,

          created_at:
            DateTime.utc_now()
        }

      persist_publication(
        publication,
        repositories.publication_store
      )
    end
  end

  defp validate_developer!(
         approval,
         developer_id
       ) do

    if approval.developer_id != developer_id do
      raise "Developer mismatch"
    end
  end

  defp validate_version!(
         approved_build,
         bundle
       ) do

    if approved_build.version != bundle.version do
      raise "Version mismatch"
    end
  end

  defp validate_profile!(
         bundle
       ) do

    allowed_profiles = [
      "release",
      "optimized",
      "universal"
    ]

    unless bundle.profile in allowed_profiles do
      raise "Unsupported optimization profile"
    end
  end

  defp create_manifest(
         approval,
         approved_build,
         bundle
       ) do

    BundleManifest.new(
      bundle.source_build_id,
      bundle.version,
      approved_build.bundleDigest,
      bundle.optimized_digest
    )
    |> ManifestEncoder.encode()
  end

    defp persist_publication(
         publication,
         publication_store
       ) do

    PublicationStore.save(
      publication_store,
      publication
    )

    {:ok, publication}
  end

  defp generate_publication_id(
         build_id,
         bundle_id
       ) do

    "pub-" <>
      build_id <>
      "-" <>
      bundle_id
  end

  def validate_for_publication(
        build_id,
        bundle_id,
        repositories
      ) do

    with {:ok, approval} <-
           ReviewLedger.find(
             repositories.review_ledger,
             build_id
           ),

         {:ok, approved_build} <-
           ApprovedBuildStore.find(
             repositories.build_store,
             build_id
           ),

         {:ok, bundle} <-
           BundleArchive.find_bundle(
             repositories.bundle_archive,
             bundle_id
           ) do

      cond do
        approval.status != "APPROVED" ->
          {:error, :approval_missing}

        approved_build.version != bundle.version ->
          {:error, :version_mismatch}

        approved_build.buildId != bundle.source_build_id ->
          {:error, :source_build_mismatch}

        true ->
          {:ok,
            %{
              build: approved_build,
              bundle: bundle
            }}
      end
    end
  end

  def publication_preview(
        build_id,
        bundle_id,
        repositories
      ) do

    with {:ok, result} <-
           validate_for_publication(
             build_id,
             bundle_id,
             repositories
           ) do

      %{
        build_id:
          result.build.buildId,

        bundle_id:
          result.bundle.bundle_id,

        version:
          result.bundle.version,

        profile:
          result.bundle.profile,

        optimized_digest:
          result.bundle.optimized_digest
      }
    end
  end
end
