```
#pragma once

#include <stdexcept>
#include <string>

#include "../storage/PublicationStore.h"
#include "../identity/DeveloperDirectory.h"

class MarketplacePublisher
{
public:

    MarketplacePublisher(
        PublicationStore& publicationStore,
        DeveloperDirectory& developerDirectory
    )
        : publicationStore_(publicationStore),
          developerDirectory_(developerDirectory)
    {
    }

    PublicationRecord publish(
        const std::string& publicationId,
        const std::string& developerId
    )
    {
        PublicationRecord publication =
            publicationStore_.find(
                publicationId
            );

        validateDeveloper(
            publication,
            developerId
        );

        validatePublication(
            publication
        );

        validateReleaseState(
            publication
        );

        PublicationRecord released =
            publication;

        released.status =
            PublicationStatus::Published;

        released.publishedAt =
            Timestamp::utcNow();

        publicationStore_.update(
            released
        );

        return released;
    }

    bool canPublish(
        const std::string& publicationId,
        const std::string& developerId
    )
    {
        PublicationRecord publication =
            publicationStore_.find(
                publicationId
            );

        if (
            publication.status !=
            PublicationStatus::Pending
        )
        {
            return false;
        }

        return developerDirectory_
            .ownsApplication(
                developerId,
                publication.buildId
            );
    }

private:

    PublicationStore&
        publicationStore_;

    DeveloperDirectory&
        developerDirectory_;

    void validateDeveloper(
        const PublicationRecord& publication,
        const std::string& developerId
    )
    {
        if (
            !developerDirectory_
                .ownsApplication(
                    developerId,
                    publication.buildId
                )
        )
        {
            throw std::runtime_error(
                "Developer does not own build."
            );
        }
    }

    void validatePublication(
        const PublicationRecord& publication
    )
    {
        if (
            publication.bundleId.empty()
        )
        {
            throw std::runtime_error(
                "Bundle missing."
            );
        }

        if (
            publication.publicationManifest.empty()
        )
        {
            throw std::runtime_error(
                "Manifest missing."
            );
        }

        if (
            publication.artifactLocation.empty()
        )
        {
            throw std::runtime_error(
                "Artifact missing."
            );
        }
    }

    void validateReleaseState(
        const PublicationRecord& publication
    )
    {
        if (
            publication.status !=
            PublicationStatus::Pending
        )
        {
            throw std::runtime_error(
                "Publication already processed."
            );
        }
    }
};
