## FILE: jobs/CleanupJob.php

```
<?php

namespace Jobs;

use Storage\BundleArchive;
use Storage\PublicationStore;

final class CleanupJob
{
    public function __construct(
        private BundleArchive $bundleArchive,
        private PublicationStore $publicationStore
    ) {
    }

    public function execute(
        \DateTimeImmutable $cutoff
    ): void {

        foreach (
            $this->publicationStore->all()
            as $publication
        ) {

            if (
                $publication->status ===
                'PUBLISHED'
            ) {
                continue;
            }

            if (
                $publication->createdAt >=
                $cutoff
            ) {
                continue;
            }

            $this->bundleArchive->remove(
                $publication->bundleId
            );

            $this->publicationStore->delete(
                $publication->publicationId
            );
        }
    }

    public function dryRun(
        \DateTimeImmutable $cutoff
    ): array {

        $expired = [];

        foreach (
            $this->publicationStore->all()
            as $publication
        ) {

            if (
                $publication->status !==
                'PENDING'
            ) {
                continue;
            }

            if (
                $publication->createdAt <
                $cutoff
            ) {

                $expired[] =
                    $publication->publicationId;
            }
        }

        return $expired;
    }
}
