import Foundation

final class UploadGateway {

    private let reviewLedger: ReviewLedger
    private let approvedBuildStore: ApprovedBuildStore
    private let bundleComposer: BundleComposer
    private let bundleArchive: BundleArchive

    init(
        reviewLedger: ReviewLedger,
        approvedBuildStore: ApprovedBuildStore,
        bundleComposer: BundleComposer,
        bundleArchive: BundleArchive
    ) {
        self.reviewLedger = reviewLedger
        self.approvedBuildStore = approvedBuildStore
        self.bundleComposer = bundleComposer
        self.bundleArchive = bundleArchive
    }

    func uploadOptimizedBundle(
        request: UploadBundleRequest
    ) throws -> UploadBundleResponse {

        guard
            reviewLedger.isApproved(
                buildId: request.buildId
            )
        else {
            throw GatewayError.buildNotApproved
        }

        guard let approvedBuild =
            approvedBuildStore.find(
                buildId: request.buildId
            )
        else {
            throw GatewayError.buildNotFound
        }

        let bundle =
            try bundleComposer.compose(
                approvedBuild: approvedBuild,
                optimizedBundlePath: request.bundlePath,
                optimizationProfile: request.profile
            )

        try bundleArchive.storeBundle(
            bundle
        )

        return UploadBundleResponse(
            bundleId: bundle.bundle_id,
            buildId: bundle.source_build_id,
            optimizedDigest: bundle.optimized_digest
        )
    }
}

struct UploadBundleRequest {

    let buildId: String

    let bundlePath: String

    let profile: String
}

struct UploadBundleResponse {

    let bundleId: String

    let buildId: String

    let optimizedDigest: String
}

enum GatewayError: Error {

    case buildNotFound

    case buildNotApproved
}
