import Foundation

final class PublishGateway {

    private let assembler: PublicationAssembler

    private let publisher: MarketplacePublisher

    init(
        assembler: PublicationAssembler,
        publisher: MarketplacePublisher
    ) {
        self.assembler = assembler
        self.publisher = publisher
    }

    func publish(
        request: PublishRequest
    ) throws -> PublishResponse {

        let publication =
            try assembler.buildPublication(
                buildId: request.buildId,
                bundleId: request.bundleId,
                developerId: request.developerId
            )

        let released =
            try publisher.publish(
                publicationId: publication.publicationId,
                developerId: request.developerId
            )

        return PublishResponse(
            publicationId: released.publicationId,
            status: "PUBLISHED",
            publishedAt: released.publishedAt
        )
    }

    func preview(
        request: PublishRequest
    ) throws -> PublicationPreview {

        let publication =
            try assembler.publicationPreview(
                buildId: request.buildId,
                bundleId: request.bundleId
            )

        return PublicationPreview(
            buildId: publication.build_id,
            bundleId: publication.bundle_id,
            version: publication.version
        )
    }
}

struct PublishRequest {

    let buildId: String

    let bundleId: String

    let developerId: String
}

struct PublishResponse {

    let publicationId: String

    let status: String

    let publishedAt: Date
}

struct PublicationPreview {

    let buildId: String

    let bundleId: String

    let version: String
}
