## FILE: identity/DeveloperDirectory.scala

```
package identity

import scala.collection.mutable

case class Developer(
    developerId: String,
    organizationId: String,
    applications: Set[String],
    active: Boolean,
    verified: Boolean
)

class DeveloperDirectory {

    private val developers =
        mutable.Map.empty[
            String,
            Developer
        ]

    def register(
        developer: Developer
    ): Unit = {

        developers.put(
            developer.developerId,
            developer
        )
    }

    def find(
        developerId: String
    ): Option[Developer] = {

        developers.get(
            developerId
        )
    }

    def requireDeveloper(
        developerId: String
    ): Developer = {

        find(
            developerId
        ).getOrElse {
            throw new IllegalArgumentException(
                "Unknown developer."
            )
        }
    }

    def ownsApplication(
        developerId: String,
        buildId: String
    ): Boolean = {

        val developer =
            requireDeveloper(
                developerId
            )

        developer.active &&
        developer.verified &&
        developer.applications.contains(
            buildId
        )
    }

    def belongsToOrganization(
        developerId: String,
        organizationId: String
    ): Boolean = {

        requireDeveloper(
            developerId
        ).organizationId ==
            organizationId
    }

    def updateApplications(
        developerId: String,
        applications: Set[String]
    ): Unit = {

        val existing =
            requireDeveloper(
                developerId
            )

        developers.update(
            developerId,
            existing.copy(
                applications =
                    applications
            )
        )
    }

    def deactivate(
        developerId: String
    ): Unit = {

        val existing =
            requireDeveloper(
                developerId
            )

        developers.update(
            developerId,
            existing.copy(
                active = false
            )
        )
    }
