#include "SafetyValidator.h"

#include <stdexcept>

SafetyValidator::SafetyValidator(
    const SafetyPolicyService& policyService
)
    : policyService_(policyService) {
}

ValidationResult
SafetyValidator::validate(
    const ExecutionPlan& plan
) const {

    if (!plan.isExecutable()) {
        throw std::runtime_error(
            "Execution plan is incomplete."
        );
    }

    MissionSafetyPolicy policy =
        policyService_.loadPolicy(
            plan.missionId()
        );

    validateMissionIdentity(
        plan,
        policy
    );

    validatePolicyRevision(
        plan,
        policy
    );

    validateAltitudeProfile(
        plan,
        policy
    );

    validateEmergencyCorridors(
        plan,
        policy
    );

    return ValidationResult(
        true,
        "Execution plan validated."
    );
}

void SafetyValidator::validateMissionIdentity(
    const ExecutionPlan& plan,
    const MissionSafetyPolicy& policy
) const {

    if (plan.missionId() != policy.missionId()) {

        throw std::runtime_error(
            "Mission identifier mismatch."
        );
    }
}

void SafetyValidator::validatePolicyRevision(
    const ExecutionPlan& plan,
    const MissionSafetyPolicy& policy
) const {

    if (plan.policyRevision() !=
        policy.policyRevision()) {

        throw std::runtime_error(
            "Safety policy revision mismatch."
        );
    }
}

void SafetyValidator::validateAltitudeProfile(
    const ExecutionPlan& plan,
    const MissionSafetyPolicy& policy
) const {

    if (!policy.altitudeLimitsCompatible(
            plan.altitudeProfile())) {

        throw std::runtime_error(
            "Altitude profile violates safety policy."
        );
    }
}

void SafetyValidator::validateEmergencyCorridors(
    const ExecutionPlan& plan,
    const MissionSafetyPolicy& policy
) const {

    if (!policy.corridorsCompatible(
            plan.navigationGraph())) {

        throw std::runtime_error(
            "Emergency corridor validation failed."
        );
    }
}
bool
SafetyValidator::supports(
    const ExecutionPlan& plan
) const {

    return plan.isExecutable();
}

