SafetyValidator::buildReport(
    const ExecutionPlan& plan
) const {

    ValidationReport report;

    report.missionId =
        plan.missionId();

    report.policyRevision =
        plan.policyRevision();

    report.validatedChecks = {
        "Mission Identity",
        "Policy Revision",
        "Altitude Profile",
        "Emergency Corridors"
    };

    report.success = true;

    return report;
}

DispatchAuthorization
SafetyValidator::authorize(
    const ExecutionPlan& plan
) const {

    ValidationResult result =
        validate(
            plan
        );

    if (!result.success()) {

        throw std::runtime_error(
            "Mission validation failed."
        );
    }

    return DispatchAuthorization(
        plan.missionId(),
        plan.policyRevision(),
        true
    );
}
