package com.publisher.approval.service;

import com.publisher.approval.events.ApprovalEventPublisher;
import com.publisher.approval.models.ApprovalEvent;
import com.publisher.repositories.ApprovalRepository;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;

import java.time.Instant;
import java.util.Optional;
import java.util.UUID;

@Service
public class ApprovalService {

    private static final Logger logger =
            LoggerFactory.getLogger(
                    ApprovalService.class
            );

    private final ApprovalRepository approvalRepository;

    private final ApprovalEventPublisher eventPublisher;

    public ApprovalService(

            ApprovalRepository approvalRepository,

            ApprovalEventPublisher eventPublisher

    ) {

        this.approvalRepository =
                approvalRepository;

        this.eventPublisher =
                eventPublisher;
    }

    public void approveDocument(

            String documentId,

            String reviewerId

    ) {

        logger.info(
                "Approving document {} by {}",
                documentId,
                reviewerId
        );

        Optional<ApprovalRepository.ApprovalRecord>
                existingApproval =

                approvalRepository
                        .findByDocumentId(
                                documentId
                        );

        if (existingApproval.isPresent()) {

            throw new IllegalStateException(
                    "Document already approved"
            );
        }

        ApprovalRepository.ApprovalRecord
                approvalRecord =

                new ApprovalRepository.ApprovalRecord(

                        UUID.randomUUID()
                                .toString(),

                        documentId,

                        reviewerId,

                        Instant.now(),

                        true
                );

        approvalRepository.save(
                approvalRecord
        );

        ApprovalEvent event =

                ApprovalEvent.builder()

                        .eventId(
                                UUID.randomUUID()
                                        .toString()
                        )

                        .documentId(
                                documentId
                        )

                        .reviewerId(
                                reviewerId
                        )

                        .approved(
                                true
                        )

                        .approvalTimestamp(
                                Instant.now()
                        )

                        .build();

        eventPublisher.publishApproval(
                event
        );

        logger.info(
                "Approval completed for {}",
                documentId
        );
    }

    public boolean isApproved(
            String documentId
    ) {

        return approvalRepository
                .findByDocumentId(
                        documentId
                )
                .map(
                        ApprovalRepository
                                .ApprovalRecord::isApproved
                )
                .orElse(false);
    }

    public Optional<
            ApprovalRepository.ApprovalRecord
            > getApproval(

            String documentId

    ) {

        return approvalRepository
                .findByDocumentId(
                        documentId
                );
    }

    public void revokeApproval(
            String documentId
    ) {

        Optional<
                ApprovalRepository.ApprovalRecord
                > approval =

                approvalRepository
                        .findByDocumentId(
                                documentId
                        );

        if (approval.isEmpty()) {

            return;
        }

        ApprovalRepository.ApprovalRecord
                record = approval.get();

        record.setApproved(
                false
        );

        approvalRepository.save(
                record
        );

        logger.info(
                "Approval revoked for {}",
                documentId
        );
    }
}
