package com.publisher.approval.events;

import com.publisher.messaging.KafkaProducer;
import com.publisher.models.ApprovalEvent;
import com.publisher.security.EventSigner;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

import java.time.Instant;

@Component
public class ApprovalEventPublisher {

    private static final Logger logger =
            LoggerFactory.getLogger(
                    ApprovalEventPublisher.class
            );

    private final KafkaProducer kafkaProducer;

    private final EventSigner eventSigner;

    public ApprovalEventPublisher(

            KafkaProducer kafkaProducer,

            EventSigner eventSigner

    ) {

        this.kafkaProducer =
                kafkaProducer;

        this.eventSigner =
                eventSigner;
    }

    public void publishApproval(
            ApprovalEvent event
    ) {

        validateEvent(event);

        String signature =
                eventSigner.sign(
                        event
                );

        event.setSignature(
                signature
        );

        event.setPublishedAt(
                Instant.now()
        );

        kafkaProducer.publish(

                "document-approvals",

                event.getDocumentId(),

                event
        );

        logger.info(

                "Published approval event. eventId={}, documentId={}",

                event.getEventId(),

                event.getDocumentId()
        );
    }

    private void validateEvent(
            ApprovalEvent event
    ) {

        if (event == null) {

            throw new IllegalArgumentException(
                    "Event cannot be null"
            );
        }

        if (event.getEventId() == null ||
                event.getEventId().isBlank()) {

            throw new IllegalArgumentException(
                    "Missing event id"
            );
        }

        if (event.getDocumentId() == null ||
                event.getDocumentId().isBlank()) {

            throw new IllegalArgumentException(
                    "Missing document id"
            );
        }

        if (event.getReviewerId() == null ||
                event.getReviewerId().isBlank()) {

            throw new IllegalArgumentException(
                    "Missing reviewer"
            );
        }

        if (event.getApprovalTimestamp() == null) {

            throw new IllegalArgumentException(
                    "Missing approval timestamp"
            );
        }

        if (!event.isApproved()) {

            throw new IllegalArgumentException(
                    "Only approval events may be published"
            );
        }
    }

    public boolean canPublish(
            ApprovalEvent event
    ) {

        if (event == null) {
            return false;
        }

        if (!event.isApproved()) {
            return false;
        }

        return event.getDocumentId() != null;
    }

    public String previewSignature(
            ApprovalEvent event
    ) {

        return eventSigner.sign(
                event
        );
    }
}
