```
package com.publisher.security;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.publisher.models.ApprovalEvent;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.util.Base64;

@Component
public class EventSigner {

    private static final Logger logger =
            LoggerFactory.getLogger(
                    EventSigner.class
            );

    private static final String HMAC_ALGORITHM =
            "HmacSHA256";

    private final ObjectMapper objectMapper =
            new ObjectMapper();

    private final String signingKey =
            System.getenv()
                    .getOrDefault(
                            "EVENT_SIGNING_KEY",
                            "local-dev-signing-key"
                    );

    public String sign(
            ApprovalEvent event
    ) {

        try {

            String payload =
                    canonicalize(
                            event
                    );

            Mac mac =
                    Mac.getInstance(
                            HMAC_ALGORITHM
                    );

            SecretKeySpec keySpec =
                    new SecretKeySpec(

                            signingKey.getBytes(
                                    StandardCharsets.UTF_8
                            ),

                            HMAC_ALGORITHM
                    );

            mac.init(
                    keySpec
            );

            byte[] digest =
                    mac.doFinal(

                            payload.getBytes(
                                    StandardCharsets.UTF_8
                            )
                    );

            return Base64
                    .getEncoder()
                    .encodeToString(
                            digest
                    );

        } catch (Exception ex) {

            logger.error(
                    "Failed to sign event",
                    ex
            );

            throw new RuntimeException(
                    "Signing failed",
                    ex
            );
        }
    }

    public boolean verify(

            ApprovalEvent event,

            String signature

    ) {

        String expected =
                sign(
                        event
                );

        return expected.equals(
                signature
        );
    }

    private String canonicalize(
            ApprovalEvent event
    ) throws Exception {

        SigningPayload payload =
                new SigningPayload(

                        event.getEventId(),

                        event.getDocumentId(),

                        event.getReviewerId(),

                        event.isApproved(),

                        event.getApprovalTimestamp()
                                .toEpochMilli()
                );

        return objectMapper
                .writeValueAsString(
                        payload
                );
    }

    public boolean hasSignature(
            ApprovalEvent event
    ) {

        return event.getSignature() != null
                &&
                !event.getSignature()
                        .isBlank();
    }

    private static class SigningPayload {

        public String eventId;

        public String documentId;

        public String reviewerId;

        public boolean approved;

        public long approvalTimestamp;

        public SigningPayload(

                String eventId,

                String documentId,

                String reviewerId,

                boolean approved,

                long approvalTimestamp

        ) {

            this.eventId =
                    eventId;

            this.documentId =
                    documentId;

            this.reviewerId =
                    reviewerId;

            this.approved =
                    approved;

            this.approvalTimestamp =
                    approvalTimestamp;
        }
    }
}
