```
package security

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"errors"
	"os"
	"time"
)

type EventValidator struct {
	signingKey string
}

type SigningPayload struct {
	EventID          string `json:"eventId"`
	DocumentID       string `json:"documentId"`
	ReviewerID       string `json:"reviewerId"`
	Approved         bool   `json:"approved"`
	ApprovalUnixTime int64  `json:"approvalTimestamp"`
}

type ApprovalEvent struct {
	EventID           string    `json:"eventId"`
	DocumentID        string    `json:"documentId"`
	ReviewerID        string    `json:"reviewerId"`
	Approved          bool      `json:"approved"`
	ApprovalTimestamp time.Time `json:"approvalTimestamp"`
	PublishedAt       time.Time `json:"publishedAt"`
	Signature         string    `json:"signature"`
}

func NewEventValidator() *EventValidator {

	key := os.Getenv(
		"EVENT_SIGNING_KEY",
	)

	if key == "" {
		key = "local-dev-signing-key"
	}

	return &EventValidator{
		signingKey: key,
	}
}

func (v *EventValidator) Validate(
	event ApprovalEvent,
) error {

	if err := v.validateStructure(
		event,
	); err != nil {

		return err
	}

	if err := v.validateSignature(
		event,
	); err != nil {

		return err
	}

	if err := v.validateTimestamp(
		event,
	); err != nil {

		return err
	}

	return nil
}

func (v *EventValidator) validateStructure(
	event ApprovalEvent,
) error {

	if event.EventID == "" {

		return errors.New(
			"missing event id",
		)
	}

	if event.DocumentID == "" {

		return errors.New(
			"missing document id",
		)
	}

	if event.ReviewerID == "" {

		return errors.New(
			"missing reviewer id",
		)
	}

	if event.Signature == "" {

		return errors.New(
			"missing signature",
		)
	}

	if !event.Approved {

		return errors.New(
			"event not approved",
		)
	}

	return nil
}

func (v *EventValidator) validateSignature(
	event ApprovalEvent,
) error {

	payload := SigningPayload{

		EventID:    event.EventID,
		DocumentID: event.DocumentID,
		ReviewerID: event.ReviewerID,

		Approved: event.Approved,

		ApprovalUnixTime:
			event.ApprovalTimestamp.
				UnixMilli(),
	}

	jsonPayload, err := json.Marshal(
		payload,
	)

	if err != nil {

		return err
	}

	mac := hmac.New(
		sha256.New,
		[]byte(v.signingKey),
	)

	mac.Write(
		jsonPayload,
	)

	expected := base64.StdEncoding.
		EncodeToString(
			mac.Sum(nil),
		)

	if !hmac.Equal(
		[]byte(expected),
		[]byte(event.Signature),
	) {

		return errors.New(
			"invalid signature",
		)
	}

	return nil
}

func (v *EventValidator) validateTimestamp(
	event ApprovalEvent,
) error {
	// Verify event is not created
	// in the future.
	//
	// Historical approval events are
	// intentionally permitted because
	// publication workflows may be
	// delayed by queue backlogs.

	now := time.Now()

	if event.ApprovalTimestamp.After(
		now.Add(
			5*time.Minute,
		),
	) {

		return errors.New(
			"future timestamp",
		)
	}

	return nil
}

func (v *EventValidator) IsTrusted(
	event ApprovalEvent,
) bool {

	return v.Validate(
		event,
	) == nil
}

func (v *EventValidator) AllowsDelayedProcessing() bool {
	return true
}
```

