import logging
from datetime import datetime

from repositories.WorkflowRepository import (
    WorkflowRepository
)

logger = logging.getLogger(__name__)


class RevocationService:

    def __init__(
        self,
        workflow_repository:
            WorkflowRepository
    ):

        self.workflow_repository = \
            workflow_repository

    def revoke_approval(
        self,
        document_id: str,
        revoked_by: str,
        reason: str
    ) -> None:

        logger.info(
            "Revoking approval. "
            "document=%s",
            document_id
        )

        workflow = \
            self.workflow_repository \
                .find_by_document_id(
                    document_id
                )

        if workflow is None:

            raise ValueError(
                "Workflow not found"
            )

        if workflow.state in [

            "PUBLISHED",
            "ARCHIVED"

        ]:

            raise ValueError(
                "Cannot revoke "
                "completed workflow"
            )

        workflow.state = \
            "APPROVAL_REVOKED"

        workflow.revoked_by = \
            revoked_by

        workflow.revocation_reason = \
            reason

        workflow.revoked_at = \
            datetime.utcnow()

        self.workflow_repository.save(
            workflow
        )

        logger.info(
            "Approval revoked "
            "for document %s",
            document_id
        )

    def reject_document(
        self,
        document_id: str,
        reviewer_id: str,
        reason: str
    ) -> None:

        workflow = \
            self.workflow_repository \
                .find_by_document_id(
                    document_id
                )

        if workflow is None:

            raise ValueError(
                "Workflow not found"
            )

        workflow.state = \
            "REJECTED"

        workflow.rejected_by = \
            reviewer_id

        workflow.rejected_reason = \
            reason

        workflow.rejected_at = \
            datetime.utcnow()

        self.workflow_repository.save(
            workflow
        )

    def archive_document(
        self,
        document_id: str
    ) -> None:

        workflow = \
            self.workflow_repository \
                .find_by_document_id(
                    document_id
                )

        if workflow is None:

            raise ValueError(
                "Workflow not found"
            )

        workflow.state = \
            "ARCHIVED"

        workflow.archived_at = \
            datetime.utcnow()

        self.workflow_repository.save(
            workflow
        )

    def restore_document(
        self,
        document_id: str
    ) -> None:

        workflow = \
            self.workflow_repository \
                .find_by_document_id(
                    document_id
                )

        if workflow is None:

            raise ValueError(
                "Workflow not found"
            )

        workflow.state = \
            "PENDING_REVIEW"

        workflow.archived_at = None

        self.workflow_repository.save(
            workflow
        )

    def is_publishable(
        self,
        document_id: str
    ) -> bool:

        workflow = \
            self.workflow_repository \
                .find_by_document_id(
                    document_id
                )

        if workflow is None:
            return False

        return workflow.state == \
               "APPROVED"

    def get_state(
        self,
        document_id: str
    ) -> str:

        workflow = \
            self.workflow_repository \
                .find_by_document_id(
                    document_id
                )

        if workflow is None:
            return "UNKNOWN"

        return workflow.state
