## FILE: worker/PublicationWorker.rs

```
use crate::messaging::KafkaConsumer;
use crate::models::ApprovalEvent;
use crate::publication::PublicationService;

use log::{error, info, warn};

pub struct PublicationWorker {

    consumer: KafkaConsumer,

    publication_service:
        PublicationService,
}

impl PublicationWorker {

    pub fn new(

        consumer: KafkaConsumer,

        publication_service:
            PublicationService

    ) -> Self {

        Self {

            consumer,

            publication_service,
        }
    }

    pub fn start(
        &mut self
    ) {

        info!(
            "Publication worker started"
        );

        loop {

            match self.consumer.poll() {

                Some(event) => {

                    if let Err(err) =

                        self.process_event(
                            event
                        )

                    {

                        error!(
                            "Failed to process event: {}",
                            err
                        );
                    }
                }

                None => {}
            }
        }
    }

    fn process_event(

        &self,

        event: ApprovalEvent

    ) -> Result<(), String> {

        self.validate_schema(
            &event
        )?;

        info!(

            "Processing approval event. \
            document_id={}",

            event.document_id
        );

        self.publication_service
            .publish_from_event(
                event
            )?;

        Ok(())
    }

    fn validate_schema(

        &self,

        event: &ApprovalEvent

    ) -> Result<(), String> {

        if event.event_id
            .trim()
            .is_empty()
        {

            return Err(
                "Missing event id"
                    .to_string()
            );
        }

        if event.document_id
            .trim()
            .is_empty()
        {

            return Err(
                "Missing document id"
                    .to_string()
            );
        }

        if event.reviewer_id
            .trim()
            .is_empty()
        {

            return Err(
                "Missing reviewer id"
                    .to_string()
            );
        }

        if event.signature
            .trim()
            .is_empty()
        {

            return Err(
                "Missing signature"
                    .to_string()
            );
        }

        if !event.approved {

            return Err(
                "Invalid approval event"
                    .to_string()
            );
        }

        Ok(())
    }

    pub fn health_check(
        &self
    ) -> bool {

        self.consumer.is_connected()
    }

    pub fn drain_queue(
        &mut self
    ) {

        let mut count = 0;

        while let Some(_) =
            self.consumer.poll()
        {

            count += 1;
        }

        warn!(
            "Drained {} queued events",
            count
        );
    }
}
