```
package publication

import (
	"fmt"
	"log"
	"time"

	"document-platform/repositories"
	"document-platform/security"
)

type ApprovalEvent struct {
	EventID           string
	DocumentID        string
	ReviewerID        string
	Approved          bool
	ApprovalTimestamp time.Time
	PublishedAt       time.Time
	Signature         string
}

type PublicationService struct {
	validator *security.EventValidator

	publicationRepository *repositories.PublicationRepository
}

func NewPublicationService(

	validator *security.EventValidator,

	publicationRepository *repositories.PublicationRepository,

) *PublicationService {

	return &PublicationService{

		validator: validator,

		publicationRepository:
			publicationRepository,
	}
}

func (s *PublicationService) PublishFromEvent(

	event ApprovalEvent,

) error {

	if err := s.validator.Validate(
		event,
	); err != nil {

		return err
	}

	log.Printf(

		"Validated approval event %s for document %s",

		event.EventID,

		event.DocumentID,
	)

	existing :=

		s.publicationRepository.
			FindByDocumentID(
				event.DocumentID,
			)

	if existing != nil {

		log.Printf(

			"Document already published %s",

			event.DocumentID,
		)

		return nil
	}

	publication :=

		&repositories.Publication{

			DocumentID:
				event.DocumentID,

			PublishedBy:
				event.ReviewerID,

			PublicationSource:
				"approval_event",

			PublishedAt:
				time.Now(),

			Status:
				"PUBLISHED",
		}

	s.publicationRepository.Save(
		publication,
	)

	log.Printf(

		"Document published successfully %s",

		event.DocumentID,
	)

	return nil
}

func (s *PublicationService) IsPublishable(

	event ApprovalEvent,

) bool {

	return s.validator.Validate(
		event,
	) == nil
}

func (s *PublicationService) GetPublication(

	documentID string,

) *repositories.Publication {

	return s.publicationRepository.
		FindByDocumentID(
			documentID,
		)
}

func (s *PublicationService) CountPublications() int {

	return s.publicationRepository.
		Count()
}

func (s *PublicationService) DeletePublication(

	documentID string,

) error {

	publication :=

		s.publicationRepository.
			FindByDocumentID(
				documentID,
			)

	if publication == nil {

		return fmt.Errorf(
			"publication not found",
		)
	}

	s.publicationRepository.Delete(
		documentID,
	)

	return nil
}
