package com.publisher.messaging;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.publisher.models.ApprovalEvent;
import org.apache.kafka.clients.producer.KafkaProducer;
import org.apache.kafka.clients.producer.ProducerRecord;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Component;

import java.util.Properties;

@Component
public class KafkaProducer {

    private static final Logger logger =
            LoggerFactory.getLogger(
                    KafkaProducer.class
            );

    private final org.apache.kafka.clients.producer.KafkaProducer<String, String>
            producer;

    private final ObjectMapper mapper =
            new ObjectMapper();

    public KafkaProducer() {

        Properties props =
                new Properties();

        props.put(
                "bootstrap.servers",
                "kafka:9092"
        );

        props.put(
                "key.serializer",
                "org.apache.kafka.common.serialization.StringSerializer"
        );

        props.put(
                "value.serializer",
                "org.apache.kafka.common.serialization.StringSerializer"
        );

        props.put(
                "acks",
                "all"
        );

        props.put(
                "retries",
                3
        );

        this.producer =
                new org.apache.kafka.clients.producer.KafkaProducer<>(
                        props
                );
    }

    public void publish(

            String topic,

            String key,

            ApprovalEvent event

    ) {

        try {

            String payload =
                    mapper.writeValueAsString(
                            event
                    );

            ProducerRecord<String, String>
                    record =

                    new ProducerRecord<>(

                            topic,

                            key,

                            payload
                    );

            producer.send(

                    record,

                    (metadata, exception) -> {

                        if (exception != null) {

                            logger.error(
                                    "Kafka publish failed",
                                    exception
                            );

                            return;
                        }

                        logger.info(

                                "Event published topic={} partition={} offset={}",

                                metadata.topic(),

                                metadata.partition(),

                                metadata.offset()
                        );
                    }
            );

        } catch (Exception ex) {

            throw new RuntimeException(

                    "Unable to publish event",

                    ex
            );
        }
    }

    public void flush() {

        producer.flush();
    }

    public void close() {

        producer.close();
    }

    public boolean isHealthy() {

        try {

            producer.partitionsFor(
                    "document-approvals"
            );

            return true;

        } catch (Exception ex) {

            return false;
        }
    }
}
