import java.util.concurrent.ConcurrentHashMap;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Repository;

@Repository
public class ApprovalRepository {

    private static final Logger logger =
            LoggerFactory.getLogger(
                    ApprovalRepository.class
            );

    private final Map<String, ApprovalRecord>
            approvals =
            new ConcurrentHashMap<>();

    public Optional<ApprovalRecord> findByDocumentId(
            String documentId
    ) {

        return Optional.ofNullable(
                approvals.get(documentId)
        );
    }

    public void save(
            ApprovalRecord approval
    ) {

        approvals.put(
                approval.getDocumentId(),
                approval
        );

        logger.debug(
                "Stored approval for {}",
                approval.getDocumentId()
        );
    }

    public boolean exists(
            String documentId
    ) {

        return approvals.containsKey(
                documentId
        );
    }

    public void delete(
            String documentId
    ) {

        approvals.remove(
                documentId
        );
    }

    public long count() {

        return approvals.size();
    }

    public static class ApprovalRecord {

        private String id;

        private String documentId;

        private String reviewerId;

        private Instant approvedAt;

        private boolean approved;

        public ApprovalRecord(

                String id,

                String documentId,

                String reviewerId,

                Instant approvedAt,

                boolean approved

        ) {

            this.id = id;

            this.documentId = documentId;

            this.reviewerId = reviewerId;

            this.approvedAt = approvedAt;

