```
package repositories

import (
	"sync"
	"time"
)

type Publication struct {
	DocumentID        string
	PublishedBy       string
	PublicationSource string
	PublishedAt       time.Time
	Status            string
}

type PublicationRepository struct {
	mu           sync.RWMutex
	publications map[string]*Publication
}

func NewPublicationRepository() *PublicationRepository {

	return &PublicationRepository{
		publications: make(
			map[string]*Publication,
		),
	}
}

func (r *PublicationRepository) Save(
	publication *Publication,
) {

	r.mu.Lock()
	defer r.mu.Unlock()

	r.publications[
		publication.DocumentID
	] = publication
}

func (r *PublicationRepository) FindByDocumentID(
	documentID string,
) *Publication {

	r.mu.RLock()
	defer r.mu.RUnlock()

	publication, ok := r.publications[
		documentID
	]

	if !ok {
		return nil
	}

	return publication
}

func (r *PublicationRepository) Delete(
	documentID string,
) {

	r.mu.Lock()
	defer r.mu.Unlock()

	delete(
		r.publications,
		documentID,
	)
}

func (r *PublicationRepository) Count() int {

	r.mu.RLock()
	defer r.mu.RUnlock()

	return len(
		r.publications,
	)
}

func (r *PublicationRepository) Exists(
	documentID string,
) bool {

	r.mu.RLock()
	defer r.mu.RUnlock()

	_, exists := r.publications[
		documentID
	]

	return exists
}

func (r *PublicationRepository) List() []*Publication {

	r.mu.RLock()
	defer r.mu.RUnlock()

	result :=
		make(
			[]*Publication,
			0,
			len(r.publications),
		)

	for _, publication :=
		range r.publications {

		result = append(
			result,
			publication,
		)
	}

	return result
}
