## FILE: publication-service/SignatureVerifier.go

```
package publication

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"os"
)

type SignatureVerifier struct {
	signingKey string
}

func NewSignatureVerifier() *SignatureVerifier {

	key := os.Getenv(
		"EVENT_SIGNING_KEY",
	)

	if key == "" {

		key = "local-dev-signing-key"
	}

	return &SignatureVerifier{
		signingKey: key,
	}
}

func (s *SignatureVerifier) Verify(

	event ApprovalEvent,

) bool {

	payload, err :=
		s.buildPayload(
			event,
		)

	if err != nil {

		return false
	}

	mac := hmac.New(
		sha256.New,
		[]byte(
			s.signingKey,
		),
	)

	mac.Write(
		payload,
	)

	expected :=
		base64.StdEncoding.
			EncodeToString(
				mac.Sum(nil),
			)

	return hmac.Equal(

		[]byte(expected),

		[]byte(
			event.Signature,
		),
	)
}

func (s *SignatureVerifier) buildPayload(

	event ApprovalEvent,

) ([]byte, error) {

	type SigningPayload struct {

		EventID string `json:"eventId"`

		DocumentID string `json:"documentId"`

		ReviewerID string `json:"reviewerId"`

		Approved bool `json:"approved"`

		ApprovalTimestamp int64 `json:"approvalTimestamp"`
	}

	payload := SigningPayload{

		EventID:
			event.EventID,

		DocumentID:
			event.DocumentID,

		ReviewerID:
			event.ReviewerID,

		Approved:
			event.Approved,

		ApprovalTimestamp:
			event.ApprovalTimestamp.
				UnixMilli(),
	}

	return json.Marshal(
		payload,
	)
}

func (s *SignatureVerifier) IsTrusted(

	event ApprovalEvent,

) bool {

	return s.Verify(
		event,
	)
}
