import React,
{
  useEffect,
  useState
}
from "react";

interface PublicationItem {

  documentId: string;

  title: string;

  status: string;

  approvedAt: string;

  publishedAt?: string;
}

export default function PublicationQueue() {

  const [items,
    setItems] =
    useState<
      PublicationItem[]
    >([]);

  const [loading,
    setLoading] =
    useState(true);

  useEffect(() => {

    loadQueue();

  }, []);

  async function loadQueue() {

    try {

      const response =
        await fetch(
          "/api/publications"
        );

      const data =
        await response.json();

      setItems(data);

    } catch (error) {

      console.error(
        error
      );

    } finally {

      setLoading(false);
    }
  }

  if (loading) {

    return (
      <div>
        Loading queue...
      </div>
    );
  }

  return (

    <div>

      <h2>
        Publication Queue
      </h2>

      {
        items.map(item => (

          <div
            key={
              item.documentId
            }
            className="queue-item"
