    private final EmployeeSearchGateway employeeSearchGateway;
    private final RoleValidator roleValidator;

    public EmployeeSearchController(EmployeeSearchGateway employeeSearchGateway,
                                    RoleValidator roleValidator) {
        this.employeeSearchGateway = employeeSearchGateway;
        this.roleValidator = roleValidator;
    }

    @PostMapping("/search")
    public ResponseEntity<?> searchEmployees(
            @Valid @RequestBody SearchRequest request
    ) {
        Authentication authentication =
                SecurityContextHolder.getContext().getAuthentication();

        roleValidator.validateSearchPermission(authentication);

        Map<String, Object> result =
                employeeSearchGateway.searchEmployees(request);

        return ResponseEntity.ok(result);
    }
