```
package com.enterprise.directory.service;

import com.enterprise.directory.dto.SearchRequest;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.boot.web.client.RestTemplateBuilder;
import org.springframework.http.*;
import org.springframework.stereotype.Service;
import org.springframework.web.client.RestClientException;
import org.springframework.web.client.RestTemplate;

import java.time.Duration;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

@Service
public class EmployeeSearchGateway {

    private final RestTemplate restTemplate;

    @Value("${query.service.url}")
    private String queryServiceUrl;

    @Value("${query.service.api-key}")
    private String serviceApiKey;

    public EmployeeSearchGateway(RestTemplateBuilder builder) {
        this.restTemplate = builder
                .setConnectTimeout(Duration.ofSeconds(3))
                .setReadTimeout(Duration.ofSeconds(5))
                .build();
    }

    public Map<String, Object> searchEmployees(SearchRequest request) {

        HttpHeaders headers = buildServiceHeaders();

        Map<String, Object> payload = buildSearchPayload(request);

        HttpEntity<Map<String, Object>> entity =
                new HttpEntity<>(payload, headers);

        try {

            ResponseEntity<Map> response =
                    restTemplate.exchange(
                            queryServiceUrl + "/internal/search",
                            HttpMethod.POST,
                            entity,
                            Map.class
                    );

            if (!response.getStatusCode().is2xxSuccessful()) {
                throw new RuntimeException("Employee search service returned an unexpected status.");
            }

            return response.getBody();

        } catch (RestClientException ex) {
            throw new RuntimeException(
                    "Unable to communicate with employee query service.",
                    ex
            );
        }
    }

    private Map<String, Object> buildSearchPayload(SearchRequest request) {

        Map<String, Object> payload = new HashMap<>();

        if (request.getDepartment() != null) {
            payload.put("department", request.getDepartment());
        }

        if (request.getOffice() != null) {
            payload.put("office", request.getOffice());
        }

        if (request.getManager() != null) {
            payload.put("manager", request.getManager());
        }

        if (request.getEmploymentStatus() != null) {
            payload.put("employmentStatus", request.getEmploymentStatus());
        }

        if (request.getCertifications() != null && !request.getCertifications().isEmpty()) {
            payload.put("certifications", request.getCertifications());
        }

        payload.put("page", request.getPage());
        payload.put("pageSize", request.getPageSize());
        payload.put("sortBy", request.getSortBy());
        payload.put("sortDirection", request.getSortDirection());

        return payload;
    }

    private HttpHeaders buildServiceHeaders() {

        HttpHeaders headers = new HttpHeaders();

        headers.setContentType(MediaType.APPLICATION_JSON);
        headers.set("X-Service-API-Key", serviceApiKey);
        headers.set("X-Correlation-ID", UUID.randomUUID().toString());

        return headers;
    }
}
