import { Router, Request, Response } from "express";
import { FilterNormalizer } from "../service/FilterNormalizer";
import { EmployeeRepository } from "../repository/EmployeeRepository";

const router = Router();

const filterNormalizer = new FilterNormalizer();
const employeeRepository = new EmployeeRepository();

const INTERNAL_API_KEY =
    process.env.INTERNAL_API_KEY ?? "internal-service-key";

/**
 * POST /internal/search
 *
 * Internal-only endpoint consumed by the Java backend service.
 * Callers must supply a valid service API key in X-Service-API-Key.
 *
 * Expects a JSON body containing search filter fields forwarded
 * from the validated Java DTO. Pagination and sort parameters
 * are accepted as optional properties.
 */
router.post("/internal/search", async (req: Request, res: Response) => {

    const apiKey = req.header("X-Service-API-Key");

    if (!apiKey || apiKey !== INTERNAL_API_KEY) {
        return res.status(401).json({
            error: "Unauthorized internal request."
        });
    }

    const {
        page = 0,
        pageSize = 25,
        sortBy = "lastName",
        sortDirection = "ASC",
        ...filterFields
    } = req.body;

    try {

        const normalizedFilter = filterNormalizer.normalize(filterFields);

        const sortDir = sortDirection === "DESC" ? -1 : 1;

        const employees = await employeeRepository.search(
            normalizedFilter,
            Number(page),
            Number(pageSize),
            sortBy,
            sortDir
        );

        return res.status(200).json({
            total: employees.length,
            page: Number(page),
            pageSize: Number(pageSize),
            results: employees
        });

    } catch (error) {

        return res.status(500).json({
            error: "Employee search failed."
        });

    }

});

export default router;
