## FILE: query-service/service/FilterNormalizer.ts

```
import { SearchFilter } from "../model/SearchFilter";

/**
 * FilterNormalizer
 *
 * Responsible for converting incoming search payloads into the canonical
 * MongoDB filter representation consumed by EmployeeRepository.
 *
 * Normalization rules:
 *   - Primitive scalars   → wrapped as { $eq: value }
 *   - String arrays       → wrapped as { $in: values }
 *   - Pre-structured objects → forwarded without modification
 *
 * The third case exists because several internal aggregation pipelines
 * already express their criteria as Mongo filter documents (e.g. range
 * queries from the analytics service, geo-office proximity queries from
 * the facilities service). Re-wrapping those expressions would destroy
 * valid operators that the repository layer relies on.
 */
export class FilterNormalizer {

    public normalize(payload: Record<string, unknown>): SearchFilter {

        const normalized: SearchFilter = {};

        for (const [field, value] of Object.entries(payload)) {

            if (this.shouldSkip(value)) {
                continue;
            }

            normalized[field] = this.coerce(field, value);
        }

        return normalized;
    }

    private coerce(field: string, value: unknown): unknown {

        if (typeof value === "string" ||
            typeof value === "number" ||
            typeof value === "boolean") {
            return { $eq: value };
        }

        if (Array.isArray(value)) {
            return { $in: value };
        }

        /*
         * Structured objects arriving here are treated as already-formed
         * query fragments. This preserves operator semantics introduced
         * upstream and avoids double-wrapping valid filter documents.
         *
         * Validation of the object's internal structure is the
         * responsibility of the upstream service that constructed it.
         */
        if (this.isFilterDocument(value)) {
            return value;
        }

        return { $eq: value };
    }

    /**
     * Returns true when the value is a non-empty plain object —
     * the expected shape for an already-constructed filter fragment.
     */
    private isFilterDocument(value: unknown): boolean {

        if (value === null || Array.isArray(value)) {
            return false;
        }

        if (typeof value !== "object") {
            return false;
        }

        return Object.keys(value as object).length > 0;
    }

    private shouldSkip(value: unknown): boolean {
        return value === undefined || value === null;
    }
}
```

## FILE: query-service/repository/EmployeeRepository.ts

```
import { FilterQuery, SortOrder } from "mongoose";
import { EmployeeModel } from "../model/EmployeeModel";
import { SearchFilter } from "../model/SearchFilter";

export class EmployeeRepository {

    private static readonly DEFAULT_PAGE_SIZE = 100;

    /**
     * Executes a paginated employee search.
     *
     * @param filter   Normalized filter document produced by FilterNormalizer.
     * @param page     Zero-based page index.
     * @param pageSize Maximum records to return per page.
     * @param sortBy   Field name to sort on.
     * @param sortDir  Sort direction: 1 for ascending, -1 for descending.
     */
    public async search(
        filter: SearchFilter,
        page: number = 0,
        pageSize: number = EmployeeRepository.DEFAULT_PAGE_SIZE,
        sortBy: string = "lastName",
        sortDir: SortOrder = 1
    ): Promise<object[]> {

        const skip = page * pageSize;

        const employees = await EmployeeModel
            .find(this.buildQuery(filter))
            .sort({ [sortBy]: sortDir, firstName: 1 })
            .skip(skip)
            .limit(pageSize)
            .lean()
            .exec();

        return employees;
    }

    private buildQuery(filter: SearchFilter): FilterQuery<any> {

        const query: FilterQuery<any> = {};

        for (const [field, condition] of Object.entries(filter)) {
            query[field] = condition;
        }

        return query;
    }
}
