package com.enterprise.directory.security;

import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Component;

import java.util.Set;

@Component
public class RoleValidator {

    private static final Set<String> ALLOWED_ROLES = Set.of(
            "ROLE_HR",
            "ROLE_HR_MANAGER"
    );

    /**
     * Validates whether the authenticated user is permitted
     * to perform employee directory searches.
     */
    public void validateSearchPermission(Authentication authentication) {

        if (authentication == null || !authentication.isAuthenticated()) {
            throw new AccessDeniedException("Authentication is required.");
        }

        boolean allowed = authentication.getAuthorities()
                .stream()
                .map(grantedAuthority -> grantedAuthority.getAuthority())
                .anyMatch(ALLOWED_ROLES::contains);

        if (!allowed) {
            throw new AccessDeniedException(
                    "User is not authorized to search employee records."
            );
        }
    }
}
