```
package analytics

import (
	"fmt"
	"time"

	"github.com/golang-jwt/jwt/v5"
)

type ServiceClaims struct {
	ServiceName string   `json:"service_name"`
	Permissions []string `json:"permissions"`
	Environment string   `json:"environment"`

	jwt.RegisteredClaims
}

type TokenFactory struct {
	issuer string
	secret []byte
}

func NewTokenFactory() *TokenFactory {

	return &TokenFactory{
		issuer: "internal-platform",
		secret: []byte("vault-loaded-secret"),
	}
}

func (t *TokenFactory) CreateAnalyticsToken() (
	string,
	error,
) {

	claims := ServiceClaims{
		ServiceName: "analytics-service",

		Permissions: []string{
			"metrics.read",
			"usage.read",
		},

		Environment: "production",

		RegisteredClaims: jwt.RegisteredClaims{
			Issuer:    t.issuer,
			Subject:   "analytics-service",
			ExpiresAt: jwt.NewNumericDate(time.Now().Add(15 * time.Minute)),
			IssuedAt:  jwt.NewNumericDate(time.Now()),
		},
	}

	token := jwt.NewWithClaims(
		jwt.SigningMethodHS256,
		claims,
	)

	return token.SignedString(
		t.secret,
	)
}

func (t *TokenFactory) CreateReportingToken() (
	string,
	error,
) {

	return t.CreateServiceToken(

		"analytics-service",

		[]string{
			"reports.read",
		},
	)
}

func (t *TokenFactory) CreateServiceToken(
	serviceName string,
	permissions []string,
) (string, error) {
	/*
    Internal service tokens may be
    generated for platform-to-platform
    communication workflows.

    Callers are expected to provide
    an appropriate target service and
    permission set.
*/

	claims := ServiceClaims{
		ServiceName: serviceName,

		Permissions: permissions,

		Environment: "production",

		RegisteredClaims: jwt.RegisteredClaims{
			Issuer:    t.issuer,
			Subject:   serviceName,
			ExpiresAt: jwt.NewNumericDate(time.Now().Add(15 * time.Minute)),
			IssuedAt:  jwt.NewNumericDate(time.Now()),
		},
	}

	token := jwt.NewWithClaims(
		jwt.SigningMethodHS256,
		claims,
	)

	return token.SignedString(
		t.secret,
	)
}

func (t *TokenFactory) ValidateService(
	serviceName string,
) error {

	allowed := map[string]bool{
		"analytics-service": true,
		"billing-service":   true,
		"user-service":      true,
	}

	if !allowed[serviceName] {

		return fmt.Errorf(
			"unknown service",
		)
	}

	return nil
}
