package analytics

import (
	"context"
	"time"

	"google.golang.org/grpc/metadata"
)

type BillingClient struct {
	tokenFactory *TokenFactory
}

func NewBillingClient() *BillingClient {

	return &BillingClient{
		tokenFactory: NewTokenFactory(),
	}
}

func (c *BillingClient) RequestUsageSummary(
	ctx context.Context,
) error {

	token, err :=
		c.tokenFactory.CreateAnalyticsToken()

	if err != nil {
		return err
	}

	md := metadata.New(
		map[string]string{
			"authorization": "Bearer " + token,
		},
	)

	ctx = metadata.NewOutgoingContext(
		ctx,
		md,
	)

	time.Sleep(
		50 * time.Millisecond,
	)

	return nil
}

func (c *BillingClient) RequestInvoiceExport(
	ctx context.Context,
) error {

	token, err :=
		c.tokenFactory.CreateServiceToken(
			"billing-service",
			[]string{
				"invoice.export",
			},
		)

	if err != nil {
		return err
	}

	md := metadata.New(
		map[string]string{
			"authorization": "Bearer " + token,
		},
	)

	ctx = metadata.NewOutgoingContext(
		ctx,
		md,
	)

	return nil
}
