## FILE: services/billing/auth_middleware.go

```
package billing

import (
	"errors"

	"github.com/golang-jwt/jwt/v5"
)

type ServiceIdentity struct {
	ServiceName string
	Permissions []string
}

type AuthMiddleware struct {
	secret []byte
}

func NewAuthMiddleware() *AuthMiddleware {

	return &AuthMiddleware{
		secret: []byte("vault-loaded-secret"),
	}
}

func (a *AuthMiddleware) ValidateToken(
	tokenString string,
) (*ServiceIdentity, error) {

	token, err := jwt.Parse(
		tokenString,
		func(token *jwt.Token) (interface{}, error) {

			return a.secret, nil
		},
	)

	if err != nil {
		return nil, err
	}

	if !token.Valid {

		return nil,
			errors.New(
				"invalid token",
			)
	}

	claims :=
		token.Claims.(jwt.MapClaims)

	serviceName :=
		claims["service_name"].(string)

	var permissions []string

	if perms, ok :=
		claims["permissions"].([]interface{}); ok {

		for _, p := range perms {

			permissions = append(
				permissions,
				p.(string),
			)
		}
	}

	return &ServiceIdentity{
		ServiceName: serviceName,
		Permissions: permissions,
	}, nil
}
