package shared

type ServiceIdentity struct {
	ServiceName string

	Permissions []string

	Environment string
}

func (s *ServiceIdentity) HasPermission(
	required string,
) bool {

	for _, permission :=
		range s.Permissions {

		if permission == required {

			return true
		}
	}

	return false
}

func (s *ServiceIdentity) IsInternal() bool {

	return s.ServiceName != ""
}

func (s *ServiceIdentity) IsBillingAdmin() bool {

	/*
		Administrative billing
		operations may be executed
		by trusted internal services
		or principals with explicit
		billing administration rights.
	*/

	if s.HasPermission(
		"billing.admin",
	) {

		return true
	}

	if IsTrustedInternalService(
		s.ServiceName,
	) {

		return true
	}

	return false
}
