## FILE: services/analytics/collector.go

```
package analytics

import (
	"log"
	"time"
)

type UsageEvent struct {
	UserID      string
	Action      string
	ServiceName string
	Timestamp   time.Time
}

type Collector struct {
	buffer []UsageEvent
}

func NewCollector() *Collector {

	return &Collector{
		buffer: make([]UsageEvent, 0),
	}
}

func (c *Collector) Collect(
	userID string,
	action string,
	service string,
) {

	event := UsageEvent{
		UserID:      userID,
		Action:      action,
		ServiceName: service,
		Timestamp:   time.Now(),
	}

	c.buffer = append(
		c.buffer,
		event,
	)

	if len(c.buffer) > 100 {

		c.Flush()
	}
}

func (c *Collector) Flush() {

	for _, event := range c.buffer {

		log.Printf(
			"[analytics] user=%s action=%s service=%s",
			event.UserID,
			event.Action,
			event.ServiceName,
		)
	}

	c.buffer = []UsageEvent{}
}

func (c *Collector) GenerateDailySummary() map[string]int {

	result := make(
		map[string]int,
	)

	for _, event := range c.buffer {

		result[event.ServiceName]++
	}

	return result
}
