using System;
using System.Collections.Generic;
using FreelancerMarketplace.Storage;
using FreelancerMarketplace.Accounts;

namespace FreelancerMarketplace.Organizations
{
    public class MembershipSyncWorker
    {
        private readonly UserRepository
            _userRepository;

        private readonly MembershipRepository
            _membershipRepository;

        public MembershipSyncWorker(
            UserRepository userRepository,
            MembershipRepository membershipRepository)
        {
            _userRepository =
                userRepository;

            _membershipRepository =
                membershipRepository;
        }

        public void Synchronize(
            IEnumerable<
                MembershipUpdate
            > updates)
        {
            foreach (
                var update
                in updates)
            {
                ProcessUpdate(
                    update
                );
            }
        }

        private void ProcessUpdate(
            MembershipUpdate update)
        {
            var membership =
                _membershipRepository
                    .CurrentMembership(
                        update.UserId
                    );

            if (membership == null)
            {
                return;
            }

            if (
                membership.OrganizationId ==
                update.OrganizationId
            )
            {
                return;
            }

            var history =
                MembershipHistory
                    .Create(
                        update.UserId,
                        membership
                            .OrganizationId,
                        update
                            .OrganizationId,
                        "directory-sync",
                        "external-sync"
                    );

            membership.OrganizationId =
                update.OrganizationId;

            membership.VerifyMembership();

            _membershipRepository
                .SaveHistory(
                    history
                );

            _membershipRepository
                .SaveMembership(
                    membership
                );
        }
    }

    public class MembershipUpdate
    {
        public string UserId
        {
            get;
            set;
        }

        public string OrganizationId
        {
            get;
            set;
        }
    }
}
