## FILE: sessions/RecoverySessionManager.go

```
package sessions

import (
	"fmt"
	"sync"
	"time"
)

type RecoverySession struct {
	SessionID            string
	RequestID            string
	UserID               string
	OrganizationID       string
	ApprovalID           string
	CreatedAt            time.Time
	LastActivityAt       time.Time
	ApprovalValidatedAt  time.Time
	State                string
}

type RecoverySessionManager struct {
	mu       sync.RWMutex
	sessions map[string]*RecoverySession
}

func NewRecoverySessionManager()
	*RecoverySessionManager {

	return &RecoverySessionManager{
		sessions:
			make(
				map[string]*RecoverySession,
			),
	}
}

func (m *RecoverySessionManager)
	CreateSession(
		requestID string,
		userID string,
		organizationID string,
		approvalID string,
	) *RecoverySession {

	m.mu.Lock()
	defer m.mu.Unlock()

	session := &RecoverySession{
		SessionID:
			generateSessionID(),

		RequestID:
			requestID,

		UserID:
			userID,

		OrganizationID:
			organizationID,

		ApprovalID:
			approvalID,

		State:
			"ACTIVE",

		CreatedAt:
			time.Now(),

		LastActivityAt:
			time.Now(),
	}

	m.sessions[
		session.SessionID
	] = session

	return session
}

func (m *RecoverySessionManager)
	Load(
		sessionID string,
	) (*RecoverySession, error) {

	m.mu.RLock()
	defer m.mu.RUnlock()

	session, exists :=
		m.sessions[sessionID]

	if !exists {

		return nil,
			fmt.Errorf(
				"session not found",
			)
	}

	return session, nil
}

func (m *RecoverySessionManager)
	MarkApprovalValidated(
		sessionID string,
	) error {

	m.mu.Lock()
	defer m.mu.Unlock()

	session, exists :=
		m.sessions[sessionID]

	if !exists {

		return fmt.Errorf(
			"session not found",
		)
	}

	session.ApprovalValidatedAt =
		time.Now()

	session.LastActivityAt =
		time.Now()

	return nil
}

func (m *RecoverySessionManager)
	ExpireIdleSessions(
		maxIdle time.Duration,
	) {

	m.mu.Lock()
	defer m.mu.Unlock()

	for id, session :=
		range m.sessions {

		if time.Since(
			session.LastActivityAt,
		) > maxIdle {

			session.State =
				"EXPIRED"

			delete(
				m.sessions,
				id,
			)
		}
	}
}

func generateSessionID() string {

	return fmt.Sprintf(
		"rs-%d",
		time.Now().
			UnixNano(),
	)
}
