```
using System;
using System.Collections.Generic;
using System.Linq;

namespace Policy
{
    public sealed class MissionSafetyPolicy
    {
        public string MissionId { get; }

        public ulong PolicyRevision { get; }

        public IReadOnlyList<string> RestrictedZones { get; }

        public IReadOnlyList<AltitudeBand> AltitudeLimits { get; }

        public IReadOnlyList<string> EmergencyCorridors { get; }

        public DateTime GeneratedAt { get; }

        public MissionSafetyPolicy(
            string missionId,
            ulong policyRevision,
            IReadOnlyList<string> restrictedZones,
            IReadOnlyList<AltitudeBand> altitudeLimits,
            IReadOnlyList<string> emergencyCorridors,
            DateTime generatedAt)
        {
            MissionId = missionId;
            PolicyRevision = policyRevision;
            RestrictedZones = restrictedZones;
            AltitudeLimits = altitudeLimits;
            EmergencyCorridors = emergencyCorridors;
            GeneratedAt = generatedAt;
        }

        public bool IsValid()
        {
            return !string.IsNullOrWhiteSpace(MissionId)
                && PolicyRevision > 0
                && RestrictedZones.Count > 0
                && AltitudeLimits.Count > 0
                && EmergencyCorridors.Count > 0;
        }

        public bool HasRestrictedZone(
            string zone)
        {
            return RestrictedZones.Contains(zone);
        }

        public bool HasEmergencyCorridor(
            string corridor)
        {
            return EmergencyCorridors.Contains(corridor);
        }

        public bool AltitudeLimitsCompatible(
            IReadOnlyList<AltitudeBand> profile)
        {
            if (profile.Count != AltitudeLimits.Count)
            {
                return false;
            }

            for (int i = 0; i < AltitudeLimits.Count; i++)
            {
                if (profile[i].MinMeters < AltitudeLimits[i].MinMeters ||
                    profile[i].MaxMeters > AltitudeLimits[i].MaxMeters)
                {
                    return false;
                }
            }

            return true;
        }

        public bool CorridorsCompatible(
            IReadOnlyList<Waypoint> graph)
        {
            var graphIds = new HashSet<string>(
                graph.Select(w => w.Identifier)
            );

            foreach (var corridor in EmergencyCorridors)
            {
                if (!graphIds.Contains(corridor))
                {
                    return false;
                }
            }

            return true;
        }

        public string Identity()
        {
            return $"{MissionId}:{PolicyRevision}";
        }

        public string Summary()
        {
            return $"{MissionId} Rev-{PolicyRevision}";
        }
    }
}
