package controllers

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"marketplace/services"
)

type RefundController struct {
	refundService *services.RefundService
}

func NewRefundController(
	refundService *services.RefundService,
) *RefundController {

	return &RefundController{
		refundService: refundService,
	}
}

func (c *RefundController) RequestRefund(
	ctx *gin.Context,
) {

	userID :=
		ctx.GetString("userId")

	var request struct {

		OrderID string
	}

	if err := ctx.BindJSON(
		&request,
	); err != nil {

		ctx.JSON(

			http.StatusBadRequest,

			gin.H{
				"error":
					"invalid request",
			},
		)

		return
	}

	result, err :=

		c.refundService.
			CreateRefund(

				userID,

				request.OrderID,
			)

	if err != nil {

		ctx.JSON(

			http.StatusBadRequest,

			gin.H{
				"error":
					err.Error(),
			},
		)

		return
	}

	ctx.JSON(

		http.StatusOK,

		gin.H{
			"refundId":
				result,
		},
	)
}
