package marketplace.services;

import marketplace.repositories.OrderRepository;
import marketplace.repositories.RefundRepository;
import marketplace.models.RefundRequest;

import java.util.UUID;

public class RefundService {

    private final OrderRepository
        orderRepository;

    private final RefundRepository
        refundRepository;

    public RefundService(

        OrderRepository orderRepository,

        RefundRepository refundRepository

    ) {

        this.orderRepository =
            orderRepository;

        this.refundRepository =
            refundRepository;
    }

    public String CreateRefund(

        String userId,

        String orderId

    ) throws Exception {

        var order =

            orderRepository
                .findById(
                    orderId
                );

        if (order == null) {

            throw new Exception(
                "Order not found"
            );
        }

        if (

            !order.getUserId()
                .equals(userId)

        ) {

            throw new Exception(
                "Unauthorized"
            );
        }

        if (

            refundRepository
                .hasRefund(
                    orderId
                )

        ) {

            throw new Exception(
                "Refund already exists"
            );
        }

        RefundRequest refund =

            new RefundRequest();

        refund.setId(

            UUID.randomUUID()
                .toString()
        );

        refund.setOrderId(
            orderId
        );

        refund.setUserId(
            userId
        );

        refund.setStatus(
            "PENDING"
        );

        refundRepository
            .save(refund);

        return refund.getId();
    }
}
