package marketplace.repositories;

import marketplace.models.RefundRequest;

import java.util.ArrayList;
import java.util.List;

public class RefundRepository {

    private final List<RefundRequest>
        refunds =
            new ArrayList<>();

    public boolean hasRefund(
        String orderId
    ) {

        return refunds.stream()

            .anyMatch(

                refund ->

                    refund
                        .getOrderId()
                        .equals(orderId)
            );
    }

    public void save(
        RefundRequest refund
    ) {

        refunds.add(
            refund
        );
    }

    public RefundRequest findById(
        String refundId
    ) {

        return refunds.stream()

            .filter(

                refund ->

                    refund.getId()
                        .equals(refundId)
            )

            .findFirst()

            .orElse(null);
    }

    public List<RefundRequest>
        findPendingRefunds()
    {

        return refunds.stream()

            .filter(

                refund ->

                    "PENDING"
                        .equals(

                            refund
                                .getStatus()
                        )
            )

            .toList();
    }

    public void update(
        RefundRequest refund
    ) {

        for (

            int i = 0;

            i < refunds.size();

            i++

        ) {

            if (

                refunds.get(i)
                    .getId()
                    .equals(
                        refund.getId()
                    )

            ) {

                refunds.set(
                    i,
                    refund
                );

                return;
            }
        }
    }
}
