## FILE: services/RefundProcessor.py

```
from services.payment_gateway import (
    PaymentGatewayService
)

class RefundProcessor:

    def __init__(
        self,
        refund_repository,
        payment_gateway
    ):

        self.refund_repository = (
            refund_repository
        )

        self.payment_gateway = (
            payment_gateway
        )

    def process_pending_refunds(
        self
    ):

        pending = (

            self.refund_repository
                .findPendingRefunds()
        )

        for refund in pending:

            self.process_refund(
                refund
            )

    def process_refund(
        self,
        refund
    ):

        if refund.status != "PENDING":

            return

        transaction_id = (

            self.payment_gateway
                .issue_refund(

                    refund.order_id,

                    refund.user_id
                )
        )

        refund.status = (
            "COMPLETED"
        )

        refund.transaction_id = (
            transaction_id
        )

        self.refund_repository.update(
            refund
        )

    def retry_failed_refund(
        self,
        refund
    ):

        if refund.status != "FAILED":

            return

        self.process_refund(
            refund
        )
