const jwt =
    require(
        "jsonwebtoken"
    );

function authenticate(

    req,
    res,
    next

) {

    const authHeader =

        req.headers.authorization;

    if (!authHeader) {

        return res.status(401)
            .json({

                error:
                    "Unauthorized"
            });
    }

    const token =

        authHeader.replace(
            "Bearer ",
            ""
        );

    try {

        const payload =

            jwt.verify(

                token,

                process.env.JWT_SECRET
            );

        req.user = {

            id:
                payload.sub,

            email:
                payload.email
        };

        next();

    } catch {

        return res.status(401)
            .json({

                error:
                    "Invalid token"
            });
    }
}

module.exports = {
    authenticate
};
