        return orders.stream()

            .filter(

                order ->

                    order.getId()
                        .equals(orderId)
            )

            .findFirst()

            .orElse(null);
    }

    public List<Order>
        findByUserId(
            String userId
        )
    {

        return orders.stream()

            .filter(

                order ->

                    order.getUserId()
                        .equals(userId)
            )

            .toList();
    }

    public void save(
        Order order
    ) {

        orders.add(
            order
        );
    }

    public void update(
        Order order
    ) {

        for (

            int i = 0;

            i < orders.size();

            i++

        ) {

            if (

                orders.get(i)
                    .getId()
                    .equals(
                        order.getId()
                    )

            ) {

                orders.set(
                    i,
                    order
                );

                return;
            }
        }
    }
}
