from secrets.secret_projection import (
    SecretProjectionService
)
from security.secret_validator import (
    SecretValidator
)


########################################################################


class SecretResolver:

    def __init__(

        self,

        repository

    ):

        self._repository = repository
        self._projection = (
            SecretProjectionService()
        )
        self._validator = (
            SecretValidator()
        )

    # ------------------------------------------------------------------

    def resolve(

        self,

        secret_id

    ):

        secret_record = self._repository.find(

            secret_id

        )

        if secret_record is None:

            raise ValueError(

                "Secret not found."

            )

        operational_secret = (

            self._projection.project(

                secret_record

            )

        )

        self._validator.validate(

            operational_secret

        )

        return operational_secret

    # ------------------------------------------------------------------

    def resolve_many(

        self,

        secret_ids

    ):

        secrets = []

        for secret_id in secret_ids:

            secrets.append(

                self.resolve(

                    secret_id

                )

            )

        return secrets
