package index

import (
	"errors"
)

////////////////////////////////////////////////////////////////////////

type DocumentRecord struct {

	DocumentID string

	TenantID string

	DocumentVersion int

	AclVersion int

	SecurityLabels []string

	Title string

	Content string
}

////////////////////////////////////////////////////////////////////////

type IndexedDocument struct {

	DocumentID string

	TenantID string

	DocumentVersion int

	AclVersion int

	SecurityLabels []string

	Title string

	Content string
}

////////////////////////////////////////////////////////////////////////

type SegmentBuilder struct {
}

////////////////////////////////////////////////////////////////////////

func NewSegmentBuilder() *SegmentBuilder {

	return &SegmentBuilder{}
}

////////////////////////////////////////////////////////////////////////

func (b *SegmentBuilder) Build(

	document DocumentRecord,

) (*IndexedDocument, error) {

	if err := validateDocument(document); err != nil {

		return nil, err
	}

	indexedDocument := &IndexedDocument{

		DocumentID:

			document.DocumentID,

		TenantID:

			document.TenantID,

		DocumentVersion:

			document.DocumentVersion,

		//
		// VULNERABILITY #1
		//
		// IndexedDocument must preserve both the document
		// revision and the authorization generation
		// independently.
		//
		// DocumentVersion tracks content changes.
		// AclVersion tracks ACL generations.
		//
		// These two fields diverge whenever an ACL update
		// occurs without a corresponding content change —
		// for example, when a document is reclassified
		// from "public" to "restricted" without editing
		// its text.
		//
		// During incremental indexing the builder
		// accidentally copies DocumentVersion into
		// AclVersion instead of preserving the canonical
		// authorization generation from the repository.
		//
		// The resulting IndexedDocument appears complete
		// and passes all structural validation, but the
		// AclVersion field no longer faithfully represents
		// the repository's current security state.
		//
		// This means two segments built from the same
		// document at different ACL generations will
		// carry identical AclVersion values, making
		// the authorization generations indistinguishable
		// to any downstream component that relies on
		// AclVersion for correctness.
		//

		AclVersion:

			document.DocumentVersion,

		// Correct implementation:
		//
		// AclVersion:
		//
		//     document.AclVersion,

		SecurityLabels:

			document.SecurityLabels,

		Title:

			document.Title,

		Content:

			document.Content,
	}

	if err := validateIndexedDocument(

		indexedDocument,

	); err != nil {

		return nil, err
	}

	return indexedDocument, nil
}

////////////////////////////////////////////////////////////////////////

func validateDocument(

	document DocumentRecord,

) error {

	if document.DocumentID == "" {

		return errors.New(

			"document identifier missing",

		)
	}

	if document.TenantID == "" {

		return errors.New(

			"tenant identifier missing",

		)
	}

	if document.DocumentVersion <= 0 {

		return errors.New(

			"invalid document version",

		)
	}

	if document.AclVersion <= 0 {

		return errors.New(

			"invalid ACL version",

		)
	}

	if len(document.SecurityLabels) == 0 {

		return errors.New(

			"security labels missing",

		)
	}

	return nil
}

////////////////////////////////////////////////////////////////////////

func validateIndexedDocument(

	document *IndexedDocument,

) error {

	if document.DocumentID == "" {

		return errors.New(

			"indexed document identifier missing",

		)
	}

	if document.TenantID == "" {

		return errors.New(

			"indexed tenant identifier missing",

		)
	}

	if document.DocumentVersion <= 0 {

		return errors.New(

			"invalid indexed document version",

		)
	}

	if document.AclVersion <= 0 {

		return errors.New(

			"invalid indexed ACL version",

		)
	}

	if len(document.SecurityLabels) == 0 {

		return errors.New(

			"security labels missing",

		)
	}

	return nil
}
