using System;

namespace FreelancerMarketplace.Accounts
{
    public class OrganizationMembership
    {
        public string UserId { get; set; }

        public string OrganizationId { get; set; }

        public string MembershipRole { get; set; }

        public bool Active { get; set; }

        public DateTime JoinedAt { get; set; }

        public DateTime LastVerifiedAt { get; set; }

        public bool CanApproveRecoveries()
        {
            if (!Active)
            {
                return false;
            }

            return MembershipRole switch
            {
                "organization-admin" => true,
                "security-admin" => true,
                _ => false
            };
        }

        public bool BelongsTo(
            string organizationId)
        {
            return Active &&
                   String.Equals(
                       OrganizationId,
                       organizationId,
                       StringComparison
                           .OrdinalIgnoreCase
                   );
        }

        public void VerifyMembership()
        {
            LastVerifiedAt =
                DateTime.UtcNow;
        }
    }
}
