## FILE: recovery/RecoveryApprovalService.rs

```
use crate::recovery::
    recovery_request::
    RecoveryRequest;

use crate::storage::
    recovery_repository::
    RecoveryRepository;

use crate::organizations::
    organization_directory::
    OrganizationDirectory;

pub struct RecoveryApprovalService<
    R: RecoveryRepository,
    D: OrganizationDirectory
> {
    pub repository: R,

    pub directory: D
}

impl<
    R: RecoveryRepository,
    D: OrganizationDirectory
> RecoveryApprovalService<R, D> {

    pub fn approve(
        &self,
        request_id: &str,
        approver_id: &str
    ) -> Result<(), String> {

        let mut request =
            self.repository
                .load_request(
                    request_id
                )?;

        if request.is_expired() {

            return Err(
                "request expired"
                    .into()
            );
        }

        if !request.awaiting_approval() {

            return Err(
                "invalid state"
                    .into()
            );
        }

        let approver_membership =
            self.directory
                .membership_for_user(
                    approver_id
                )?;

        if !approver_membership
            .can_approve_recoveries()
        {
            return Err(
                "approver not authorized"
                    .into()
            );
        }

        if approver_membership
            .organization_id
            != request
                .requested_organization_id
        {
            return Err(
                "organization mismatch"
                    .into()
            );
        }

        let approval_id =
            format!(
                "approval-{}",
                request_id
            );

        request.mark_approved(
            approval_id
        );

        self.repository
            .save_request(
                &request
            )?;

        Ok(())
    }
}
