use crate::accounts::
    organization_membership::
    OrganizationMembership;

pub struct OrganizationRoleResolver;

impl OrganizationRoleResolver {

    pub fn effective_roles(
        membership:
            &OrganizationMembership
    ) -> Vec<String> {

        let mut roles =
            Vec::new();

        if !membership.active {
            return roles;
        }

        roles.push(
            membership
                .membership_role
                .clone()
        );

        if membership
            .membership_role
            == "security-admin"
        {
            roles.push(
                "recovery-approver"
                    .to_string()
            );
        }

        if membership
            .membership_role
            == "organization-admin"
        {
            roles.push(
                "recovery-approver"
                    .to_string()
            );

            roles.push(
                "membership-manager"
                    .to_string()
            );
        }

        roles
    }

    pub fn can_manage_members(
        membership:
            &OrganizationMembership
    ) -> bool {

        let roles =
            Self::effective_roles(
                membership
            );

        roles.contains(
            &"membership-manager"
                .to_string()
        )
    }
}
