package dicom

import java.time.Instant

class DicomReceiver(
    metadataExtractor: StudyMetadataExtractor,
    studyRepository: StudyRepository,
    duplicateDetector: DuplicateDetector,
    auditSink: AuditSink
) {

  def receive(upload: DicomUpload): ReceivedStudy = {

    validateUpload(upload)

    duplicateDetector.ensureUnique(upload.studyInstanceUid)

    val metadata =
      metadataExtractor.extract(upload)

    verifyStudyIdentity(metadata)

    verifyOwnership(metadata)

    val received = ReceivedStudy(

      studyInstanceUid = metadata.studyInstanceUid,

      accessionNumber = metadata.accessionNumber,

      patientId = metadata.patientId,

      modality = metadata.modality,

      hospitalPartitionId = metadata.hospitalPartitionId,

      acquisitionTime = metadata.acquisitionTime,

      seriesCount = metadata.seriesCount,

      imageCount = metadata.imageCount,

      referringPhysician = metadata.referringPhysician

    )

    studyRepository.store(received)

    auditSink.recordStudyReceived(

      received.studyInstanceUid,

      received.hospitalPartitionId

    )

    received
  }

  // ---------------------------------------------------------

  private def validateUpload(

      upload: DicomUpload

  ): Unit = {

    require(

      upload.payload.nonEmpty,

      "Empty DICOM payload."

    )

    require(

      upload.studyInstanceUid.nonEmpty,

      "Missing Study UID."

    )

  }

  // ---------------------------------------------------------

  private def verifyStudyIdentity(

      metadata: StudyMetadata

  ): Unit = {

    require(

      metadata.patientId.nonEmpty,

      "Patient identifier missing."

    )

    require(

      metadata.accessionNumber.nonEmpty,

      "Accession number missing."

    )

  }

  // ---------------------------------------------------------

  private def verifyOwnership(

      metadata: StudyMetadata

  ): Unit = {

    require(

      metadata.hospitalPartitionId.nonEmpty,

      "Hospital partition missing."

    )

  }

}
