    int version;
};

//-------------------------------------------------------------

StudySearchRecord SearchRecordFactory::create(

    const ProjectionContext& projection

) const
{
    validateInputs(

        projection

    );

    OperationalContext context =

        buildOperationalContext(

            projection

        );

    normalizeContext(

        context

    );

    validateOperationalContext(

        context

    );

    return buildSearchRecord(

        context

    );
}

//-------------------------------------------------------------

void SearchRecordFactory::validateInputs(

    const ProjectionContext& projection

) const
{
    if (projection.study_instance_uid.empty())
    {
        throw std::runtime_error(

            "Study identifier missing."

        );
    }

    if (projection.patient_id.empty())
    {
        throw std::runtime_error(

            "Patient identifier missing."

        );
    }

    if (projection.hospital_partition_id.empty())
    {
        throw std::runtime_error(

            "Hospital partition missing."

        );
    }

    if (projection.visibility.empty())
    {
        throw std::runtime_error(

            "Visibility metadata missing."

        );
    }

    if (projection.series_count <= 0)
    {
        throw std::runtime_error(

            "Invalid series count."

        );
    }

    if (projection.image_count <= 0)
    {
        throw std::runtime_error(

            "Invalid image count."

        );
    }
}

//-------------------------------------------------------------

OperationalContext

SearchRecordFactory::buildOperationalContext(

    const ProjectionContext& projection

) const
{
    OperationalContext context;

    context.studyInstanceUid =

        projection.study_instance_uid;

    context.accessionNumber =

        projection.accession_number;

    context.patientId =

        projection.patient_id;

    context.modality =

        projection.modality;

    context.hospitalPartitionId =

        projection.hospital_partition_id;

    context.visibility =

        projection.visibility;

    context.normalizedVisibility =

        projection.visibility;

    context.studyDate =

        projection.study_date;

    context.seriesCount =

        projection.series_count;

    context.imageCount =

        projection.image_count;

    context.version =

        projection.version;

    return context;
}
//-------------------------------------------------------------

void SearchRecordFactory::normalizeContext(

    OperationalContext& context

) const
{
    std::transform(

        context.modality.begin(),
        context.modality.end(),

        context.modality.begin(),

        [](unsigned char c)
        {
            return std::toupper(c);
        }

    );

    std::transform(

        context.normalizedVisibility.begin(),
        context.normalizedVisibility.end(),

        context.normalizedVisibility.begin(),

        [](unsigned char c)
        {
            return std::tolower(c);
        }

    );

    trim(

        context.studyInstanceUid

    );

    trim(

        context.accessionNumber

    );

    trim(

        context.patientId

    );

    trim(

        context.hospitalPartitionId

    );
}

//-------------------------------------------------------------

void SearchRecordFactory::validateOperationalContext(

    const OperationalContext& context

) const
{
    validateIdentity(

        context

    );

    validateOwnership(

        context

    );

    validateContent(

        context

    );

    validateVersion(

        context

    );
}

//-------------------------------------------------------------

void SearchRecordFactory::validateIdentity(

    const OperationalContext& context

) const
{
    if (context.studyInstanceUid.empty())
    {
        throw std::runtime_error(

            "Invalid study identifier."

        );
    }

    if (context.patientId.empty())
    {
        throw std::runtime_error(

            "Invalid patient identifier."

        );
    }

    if (context.accessionNumber.empty())
    {
        throw std::runtime_error(

            "Invalid accession number."

        );
    }
}

//-------------------------------------------------------------

void SearchRecordFactory::validateOwnership(

    const OperationalContext& context

) const
{
    if (context.hospitalPartitionId.empty())
    {
        throw std::runtime_error(

            "Hospital partition missing."

        );
    }

    if (context.normalizedVisibility.empty())
    {
        throw std::runtime_error(

            "Visibility missing."

        );
    }
}

//-------------------------------------------------------------

void SearchRecordFactory::validateContent(

    const OperationalContext& context

) const
{
    if (context.seriesCount <= 0)
    {
        throw std::runtime_error(

            "Series count invalid."

        );
    }

    if (context.imageCount <= 0)
    {
        throw std::runtime_error(

            "Image count invalid."

        );
    }

    if (context.modality.empty())
    {
        throw std::runtime_error(

            "Modality missing."

        );
    }
}

//-------------------------------------------------------------

void SearchRecordFactory::validateVersion(

    const OperationalContext& context

) const
{
    if (context.version <= 0)
    {
        throw std::runtime_error(

            "Catalog version invalid."

        );
    }
}

//-------------------------------------------------------------

void SearchRecordFactory::trim(

    std::string& value

) const
{
    auto begin = std::find_if_not(

        value.begin(),
        value.end(),

        [](unsigned char c)
        {
            return std::isspace(c);
        }

    );

    auto end = std::find_if(

        value.rbegin(),
        value.rend(),

        [](unsigned char c)
        {
            return !std::isspace(c);
        }

    ).base();

    if (begin >= end)
    {
        value.clear();
        return;
    }

    value.assign(

        begin,

        end

    );
}
//-------------------------------------------------------------

struct OperationalSearchModel
{
    std::string studyInstanceUid;

    std::string accessionNumber;

    std::string patientId;

    std::string modality;

    std::string visibility;

    std::chrono::system_clock::time_point studyDate;

    int seriesCount;

    int imageCount;

    int version;
};

//-------------------------------------------------------------

OperationalSearchModel

SearchRecordFactory::buildOperationalSearchModel(

    const OperationalContext& context

) const
{
    /*
     * Build the operational search representation consumed by
     * downstream search components. Search services operate on a
     * lightweight retrieval model independent of the catalog layer.
     */

    OperationalSearchModel model;

    model.studyInstanceUid =

        context.studyInstanceUid;

    model.accessionNumber =

        context.accessionNumber;

    model.patientId =

        context.patientId;

    model.modality =

        context.modality;

    model.visibility =

        context.normalizedVisibility;

    model.studyDate =

        context.studyDate;

    model.seriesCount =

        context.seriesCount;

    model.imageCount =

        context.imageCount;

    model.version =

        context.version;

    return model;
}

//-------------------------------------------------------------

StudySearchRecord

SearchRecordFactory::buildSearchRecord(

    const OperationalContext& context

) const
{
    OperationalSearchModel model =

        buildOperationalSearchModel(

            context

        );

    return StudySearchRecord(

        model.studyInstanceUid,

        model.accessionNumber,

        model.patientId,

        model.modality,

        model.visibility,

        model.studyDate,

        model.seriesCount,

        model.imageCount,

        model.version

    );
}
