## FILE: search/RadiologySearchService.fs

```
namespace Search

open System

type RadiologySearchService
(
    planner : SearchPlanner,
    authorizer : SearchAuthorization,
    repository : StudyIndexRepository,
    paginator : ResultPaginator,
    audit : AuthorizationAudit
) =

    //------------------------------------------------------------------

    member _.Search
    (
        request : SearchRequest,
        session : RadiologistSession
    ) : SearchResponse =

        _.ValidateSession(session)

        _.ValidateRequest(request)

        let authorization =

            authorizer.BuildAuthorization(

                session

            )

        let plan =

            planner.BuildSearchPlan(

                request,

                authorization

            )

        let studies =

            repository.Search(

                plan

            )

        _.ValidateResults(

            studies,

            authorization

        )

        let page =

            paginator.Page(

                studies,

                request.Page,

                request.PageSize

            )

        audit.RecordSearch(

            session.UserId,

            request.Query,

            page.TotalResults

        )

        SearchResponse(

            page.Items,

            page.TotalResults

        )

    //------------------------------------------------------------------

    member private _.ValidateSession
    (
        session : RadiologistSession
    ) =

        if not session.Authenticated then

            raise(

                UnauthorizedAccessException(

                    "Authentication required."

                )

            )

        if session.ExpiresAt <= DateTime.UtcNow then

            raise(

                UnauthorizedAccessException(

                    "Session expired."

                )

            )

        if String.IsNullOrWhiteSpace(

            session.Department

        ) then

            raise(

                InvalidOperationException(

                    "Department missing."

                )

            )

    //------------------------------------------------------------------

    member private _.ValidateRequest
    (
        request : SearchRequest
    ) =

        if String.IsNullOrWhiteSpace(

            request.Query

        ) then

            raise(

                InvalidOperationException(

                    "Search query required."

                )

            )

        if request.PageSize <= 0 then

            raise(

                InvalidOperationException(

                    "Invalid page size."

                )

            )

        if request.Page < 1 then

            raise(

                InvalidOperationException(

                    "Invalid page."

                )

            )

    //------------------------------------------------------------------

    member private _.ValidateResults
    (
        studies : seq<StudySearchRecord>,
        authorization : SearchAuthorizationContext
    ) =

        for study in studies do

            study.Validate()

            if not (

                authorization.AllowedModalities.Contains(

                    study.Modality

                )

            ) then

                raise(

                    UnauthorizedAccessException(

                        "Unauthorized modality."

                    )

                )

            if not (

                authorization.VisibilityLevels.Contains(

                    study.Visibility

                )

            ) then

                raise(

                    UnauthorizedAccessException(

                        "Visibility violation."

                    )

                )

            if not (

                study.IsCurrentVersion(

                    authorization.RequiredCatalogVersion

                )

            ) then

                raise(

                    InvalidOperationException(

                        "Catalog version mismatch."

                    )

                )

    //------------------------------------------------------------------

    member _.Preview
    (
        request : SearchRequest,
        session : RadiologistSession
    ) =

        let response =

            _.Search(

                request,

                session

            )

        response.Results
        |> Seq.truncate 10
