class StudyRepository

  def initialize(

      @database : StudyDatabase

  )

  end

  #-------------------------------------------------------------

  def find(

      study_uid : String

  ) : CatalogStudy

    raise "Study identifier required." if study_uid.empty?

    study =

      @database.load(

        study_uid

      )

    validate(

      study

    )

    study

  end

  #-------------------------------------------------------------

  def exists?(

      study_uid : String

  ) : Bool

    @database.exists?(

      study_uid

    )

  end

  #-------------------------------------------------------------

  def store(

      study : CatalogStudy

  )

    validate(

      study

    )

    @database.save(

      study

    )

  end

  #-------------------------------------------------------------

  private def validate(

      study : CatalogStudy

  )

    raise "Study UID missing." if study.study_instance_uid.empty?

    raise "Patient identifier missing." if study.patient_id.empty?

    raise "Hospital partition missing." if study.hospital_partition_id.empty?

    raise "Visibility missing." if study.visibility.empty?

    raise "Invalid series count." if study.series_count <= 0

    raise "Invalid image count." if study.image_count <= 0

    raise "Invalid catalog version." if study.version <= 0

  end

end
