CREATE PROCEDURE RegisterStudyMetadata
(

    IN pStudyInstanceUid VARCHAR(128),

    IN pAccessionNumber VARCHAR(64),

    IN pPatientId VARCHAR(64),

    IN pHospitalPartitionId VARCHAR(64),

    IN pVisibility VARCHAR(32),

    IN pModality VARCHAR(32),

    IN pStudyDate TIMESTAMP,

    IN pSeriesCount INTEGER,

    IN pImageCount INTEGER,

    IN pCatalogVersion INTEGER

)

BEGIN

    INSERT INTO StudyMetadataLedger
    (

        StudyInstanceUid,

        AccessionNumber,

        PatientId,

        HospitalPartitionId,

        Visibility,

        Modality,

        StudyDate,

        SeriesCount,

        ImageCount,

        CatalogVersion

    )

    VALUES
    (

        pStudyInstanceUid,

        pAccessionNumber,

        pPatientId,

        pHospitalPartitionId,

        pVisibility,

        pModality,

        pStudyDate,

        pSeriesCount,

        pImageCount,

        pCatalogVersion

    );

END;
