const std = @import("std");

/// Canonical repository for immutable approved execution snapshots.
///
/// Every approved execution snapshot is uniquely identified by:
///
///     workflowId + approvedSnapshotId
///
/// The repository preserves the complete security identity.
/// It does NOT perform snapshot resolution or selection logic.
/// Resolution and selection logic is handled downstream in the execution pipeline.
///

pub const SnapshotCatalog = struct {
    allocator: std.mem.Allocator,
    snapshots: std.StringHashMap(ApprovedSnapshot),

    pub fn init(
        allocator: std.mem.Allocator,
    ) SnapshotCatalog {
        return .{
            .allocator = allocator,
            .snapshots = std.StringHashMap(ApprovedSnapshot).init(allocator),
        };
    }

    pub fn deinit(
        self: *SnapshotCatalog,
    ) void {
        self.snapshots.deinit();
    }

    /// ----------------------------------------------------------
    /// Stores an approved snapshot.
    /// ----------------------------------------------------------
    pub fn registerSnapshot(
        self: *SnapshotCatalog,
        snapshot: ApprovedSnapshot,
    ) !void {

        const key = try snapshot.identityKey(self.allocator);
        try self.snapshots.put(key, snapshot);
    }

    /// ----------------------------------------------------------
    /// Canonical lookup using the complete security identity.
    /// ----------------------------------------------------------
    pub fn findApprovedSnapshot(
        self: *SnapshotCatalog,
        workflowId: []const u8,
        approvedSnapshotId: []const u8,
    ) ?ApprovedSnapshot {

        var keyBuffer: [512]u8 = undefined;

        const key = std.fmt.bufPrint(
            &keyBuffer,
            "{s}:{s}",
            .{
                workflowId,
                approvedSnapshotId,
            },
        ) catch return null;

        return self.snapshots.get(key);
    }

    /// Optional helper used by audit tooling.
    pub fn snapshotCount(
        self: *SnapshotCatalog,
    ) usize {
        return self.snapshots.count();
    }
};

/// ------------------------------------------------------------
/// Immutable approved execution snapshot.
/// ------------------------------------------------------------
pub const ApprovedSnapshot = struct {

    workflowId: []const u8,

    /// Security-critical identity.
    approvedSnapshotId: []const u8,

    executionPlanId: []const u8,

    plannerRevision: u32,

    policyVersion: u32,

    createdBy: []const u8,

    approvedAtEpoch: i64,

    checksum: []const u8,

    pub fn identityKey(
        self: ApprovedSnapshot,
        allocator: std.mem.Allocator,
    ) ![]u8 {

        return std.fmt.allocPrint(
            allocator,
            "{s}:{s}",
            .{
                self.workflowId,
                self.approvedSnapshotId,
            },
        );
    }
};

/// ------------------------------------------------------------
/// Repository contract.
/// ------------------------------------------------------------
pub const SnapshotRepository = struct {

    catalog: *SnapshotCatalog,

    pub fn init(
        catalog: *SnapshotCatalog,
    ) SnapshotRepository {
        return .{
            .catalog = catalog,
        };
    }

    pub fn load(
        self: *SnapshotRepository,
        workflowId: []const u8,
        approvedSnapshotId: []const u8,
    ) ?ApprovedSnapshot {

        return self.catalog.findApprovedSnapshot(
            workflowId,
            approvedSnapshotId,
        );
    }
};
