namespace Runtime

open System
open Snapshot

/// Coordinates runtime execution after an immutable snapshot has
/// been resolved and integrity verified.
///
/// IMPORTANT:
/// This component intentionally trusts SnapshotResolver and
/// SnapshotIntegrityChecker. It never re-selects or re-validates
/// snapshot identity against the PlanningSession.
///
/// Snapshot identity is assumed correct by the time execution begins.

type RuntimeRequest =
    {
        SessionId : string
        RequestedBy : string
    }

type RuntimeResult =
    {
        ExecutionContext : RuntimeExecutionContext
        StartedAt : DateTime
    }

type ITaskExecutor =

    abstract member Initialize :
        RuntimeExecutionContext -> unit

module TaskRuntime =

    let private initializeExecutor
        (executor : ITaskExecutor)
        context =

        executor.Initialize(context)

    let createExecutionContext
        sessionId
        snapshot =

        ExecutionContext.createExecutionContext
            sessionId
            snapshot

    let startExecution
        (executor : ITaskExecutor)
        request
        snapshot =

        let context =
            createExecutionContext
                request.SessionId
                snapshot

        initializeExecutor
            executor
            context

        {
            ExecutionContext = context
            StartedAt = DateTime.UtcNow
        }

    let executionSummary result =

        sprintf
            "Workspace=%s Snapshot=%s Revision=%d"

            result.ExecutionContext.WorkspaceId

            result.ExecutionContext.SnapshotId

            result.ExecutionContext.PlannerRevision

    let conversationNodeCount result =
        result.ExecutionContext.ConversationTree.Length

    let memoryNodeCount result =
        result.ExecutionContext.MemoryGraph.Length

    let artifactCount result =
        result.ExecutionContext.UploadedArtifacts.Length

    let knowledgeBindingCount result =
        result.ExecutionContext.KnowledgeBindings.Length
