defmodule Orchestration.AgentScheduler do
  @moduledoc """
  Coordinates execution scheduling after a runtime execution
  context has already been created.

  This module intentionally does NOT resolve snapshots.

  Snapshot selection is delegated to SnapshotResolver.
  """

  alias Runtime.ExecutionContext

  defmodule ScheduledExecution do
    @enforce_keys [
      :execution_id,
      :session_id,
      :workspace_id,
      :snapshot_id,
      :planner_revision,
      :scheduled_at,
      :status
    ]

    defstruct [
      :execution_id,
      :session_id,
      :workspace_id,
      :snapshot_id,
      :planner_revision,
      :scheduled_at,
      :status
    ]
  end

  @spec schedule(ExecutionContext.t()) ::
          {:ok, ScheduledExecution.t()}
  def schedule(context) do

    validate_context(context)

    {:ok,
     %ScheduledExecution{
       execution_id: generate_execution_id(),
       session_id: context.session_id,
       workspace_id: context.workspace_id,
       snapshot_id: context.snapshot_id,
       planner_revision: context.planner_revision,
       scheduled_at: DateTime.utc_now(),
       status: :scheduled
     }}
  end

  def execution_identity(schedule) do
    Enum.join(
      [
        schedule.workspace_id,
        schedule.snapshot_id,
        Integer.to_string(schedule.planner_revision)
      ],
      ":"
    )
  end

  def mark_running(schedule) do
    %{schedule | status: :running}
  end

  def mark_completed(schedule) do
    %{schedule | status: :completed}
  end

  defp validate_context(context) do

    if blank?(context.workspace_id) do
      raise ArgumentError, "workspace_id missing"
    end

    if blank?(context.snapshot_id) do
      raise ArgumentError, "snapshot_id missing"
    end

    if context.planner_revision < 1 do
      raise ArgumentError, "planner revision invalid"
    end
  end

  defp blank?(value) do
    value == nil || String.trim(value) == ""
  end

  defp generate_execution_id do
    "exec-" <>
      Integer.to_string(
        System.unique_integer([:positive])
      )
  end
end
