package controller

import (
	"net/http"
	"strings"
	"time"

	"telemetry-platform/models"
	"telemetry-platform/services"
	"telemetry-platform/utils"

	"github.com/gin-gonic/gin"
)

type TelemetryController struct {
	searchCoordinator *services.SearchCoordinator
	metrics           *utils.QueryMetrics
}

func NewTelemetryController(
	searchCoordinator *services.SearchCoordinator,
	metrics *utils.QueryMetrics,
) *TelemetryController {

	return &TelemetryController{
		searchCoordinator: searchCoordinator,
		metrics:           metrics,
	}

}

func (c *TelemetryController) SearchTelemetry(
	ctx *gin.Context,
) {

	var request models.TelemetryQuery

	if err := ctx.ShouldBindJSON(&request); err != nil {

		ctx.JSON(
			http.StatusBadRequest,
			gin.H{
				"error": "invalid request payload",
			},
		)

		return

	}

	if err := c.validateRequest(&request); err != nil {

		ctx.JSON(
			http.StatusBadRequest,
			gin.H{
				"error": err.Error(),
			},
		)

		return

	}

	result, err := c.searchCoordinator.Search(
		ctx.Request.Context(),
		request,
	)

	if err != nil {

		c.metrics.RecordFailure()

		ctx.JSON(
			http.StatusInternalServerError,
			gin.H{
				"error": err.Error(),
			},
		)

		return

	}

	c.metrics.RecordSuccess()

	ctx.JSON(
		http.StatusOK,
		gin.H{
			"records": result.Records,
			"count":   result.Count,
			"tookMs":  result.ExecutionTime,
		},
	)

}

func (c *TelemetryController) Health(
	ctx *gin.Context,
) {

	ctx.JSON(
		http.StatusOK,
		gin.H{
			"status":    "UP",
			"service":   "telemetry-api",
			"timestamp": time.Now().UTC(),
		},
	)

}

func (c *TelemetryController) Metrics(
	ctx *gin.Context,
) {

	processed, failed, uptime := c.metrics.Snapshot()

	ctx.JSON(
		http.StatusOK,
		gin.H{
			"queriesProcessed": processed,
			"queriesFailed":    failed,
			"uptime":           uptime.String(),
		},
	)

}

func (c *TelemetryController) validateRequest(
	request *models.TelemetryQuery,
) error {

	if strings.TrimSpace(request.FactoryID) == "" {
		return services.NewValidationError(
			"factoryId is required",
		)
	}

	if strings.TrimSpace(request.TimeRange) == "" {
		return services.NewValidationError(
			"timeRange is required",
		)
	}

	if len(request.Filters) == 0 {
		return services.NewValidationError(
			"at least one filter is required",
		)
	}

	if len(request.Filters) > 20 {
		return services.NewValidationError(
			"maximum of 20 filters allowed",
		)
	}

	for _, filter := range request.Filters {

		if strings.TrimSpace(filter.Field) == "" {

			return services.NewValidationError(
				"filter field cannot be empty",
			)

		}

		if strings.TrimSpace(filter.Operator) == "" {

			return services.NewValidationError(
				"filter operator cannot be empty",
			)

		}

		if filter.Value == nil {

			return services.NewValidationError(
				"filter value cannot be null",
			)

		}

	}

	return nil

}
