package services

import (
	"context"
	"errors"
	"strings"
	"time"

	"telemetry-platform/models"
)

type SearchCoordinator struct {
	queryValidator     *QueryValidator
	queryServiceClient *QueryServiceClient
}

type SearchResult struct {
	Records       []models.TelemetryRecord `json:"records"`
	Count         int                      `json:"count"`
	ExecutionTime int64                    `json:"executionTime"`
}

func NewSearchCoordinator(
	queryValidator *QueryValidator,
	queryServiceClient *QueryServiceClient,
) *SearchCoordinator {

	return &SearchCoordinator{
		queryValidator:     queryValidator,
		queryServiceClient: queryServiceClient,
	}

}

// Search validates the incoming request, then hands it off to the
// query-builder service which owns the Mongo filter DSL and the collection
// handle. This coordinator never talks to MongoDB directly.
func (s *SearchCoordinator) Search(
	ctx context.Context,
	query models.TelemetryQuery,
) (*SearchResult, error) {

	start := time.Now()

	if err := s.validateQuery(query); err != nil {
		return nil, err
	}

	records, err := s.queryServiceClient.NormalizeAndSearch(ctx, query)
	if err != nil {
		return nil, err
	}

	return &SearchResult{
		Records:       records,
		Count:         len(records),
		ExecutionTime: time.Since(start).Milliseconds(),
	}, nil

}

func (s *SearchCoordinator) validateQuery(
	query models.TelemetryQuery,
) error {

	if err := s.queryValidator.Validate(query); err != nil {
		return err
	}

	if strings.TrimSpace(query.FactoryID) == "" {
		return errors.New("factory id cannot be empty")
	}

	if strings.TrimSpace(query.TimeRange) == "" {
		return errors.New("time range cannot be empty")
	}

	return nil

}

func (s *SearchCoordinator) SupportedOperators() []string {

	return []string{
		"eq",
		"gt",
		"gte",
		"lt",
		"lte",
		"between",
	}

}

func (s *SearchCoordinator) SupportedFields() []string {

	return []string{
		"temperature",
		"pressure",
		"vibration",
		"current",
		"voltage",
		"factory",
		"deviceId",
		"lineId",
		"timestamp",
	}

}
