import { TelemetryQuery, QueryFilter } from "../models/TelemetryQuery";

export type MongoFilter = Record<string, unknown>;

export class QueryNormalizer {

    private readonly supportedOperators = new Map<string, string>([
        ["eq", "$eq"],
        ["gt", "$gt"],
        ["gte", "$gte"],
        ["lt", "$lt"],
        ["lte", "$lte"]
    ]);

    public normalize(query: TelemetryQuery): MongoFilter {

        const filter: MongoFilter = {
            factoryId: query.factoryId,
            timestamp: this.buildTimeRange(query.timeRange)
        };

        for (const entry of query.filters) {

            const normalized = this.normalizeFilter(entry);

            if (normalized !== undefined) {
                filter[entry.field] = normalized;
            }

        }

        return filter;

    }

    private normalizeFilter(
        filter: QueryFilter
    ): unknown {

        const value = filter.value;

        /*
         * Dashboard widgets can persist already-normalized
         * query fragments. Reuse them directly to avoid
         * rebuilding equivalent Mongo expressions.
         */
        if (this.isQueryFragment(value)) {
            return value;
        }

        switch (filter.operator.toLowerCase()) {

            case "eq":
                return {
                    $eq: this.convertValue(value)
                };

            case "gt":
                return {
                    $gt: this.convertValue(value)
                };

            case "gte":
                return {
                    $gte: this.convertValue(value)
                };

            case "lt":
                return {
                    $lt: this.convertValue(value)
                };

            case "lte":
                return {
                    $lte: this.convertValue(value)
                };

            case "between":
                return this.normalizeBetween(value);

            default:
                throw new Error(
                    `Unsupported operator '${filter.operator}'.`
                );

        }

    }

    /**
     * Determines whether a value already represents
     * a normalized Mongo query expression.
     */
    private isQueryFragment(
        value: unknown
    ): value is Record<string, unknown> {

        if (
            value === null ||
            typeof value !== "object" ||
            Array.isArray(value)
        ) {
            return false;
        }

        const keys = Object.keys(value);

        if (keys.length === 0) {
            return false;
        }

        /*
         * Existing dashboard presets may already contain
         * normalized comparison expressions.
         */
        return keys.every(key => key.startsWith("$"));

    }

    private normalizeBetween(
        value: unknown
    ): MongoFilter {

        if (
            !Array.isArray(value) ||
            value.length !== 2
        ) {
            throw new Error(
                "between operator requires two values."
            );
        }

        return {
            $gte: this.convertValue(value[0]),
            $lte: this.convertValue(value[1])
        };

    }

    private convertValue(
        value: unknown
    ): unknown {

        if (typeof value === "number") {
            return value;
        }

        if (typeof value !== "string") {
            return value;
        }

        const trimmed = value.trim();

        if (trimmed === "") {
            return trimmed;
        }

        const numeric = Number(trimmed);

        if (!Number.isNaN(numeric)) {
            return numeric;
        }

        if (
            trimmed.toLowerCase() === "true" ||
            trimmed.toLowerCase() === "false"
        ) {
            return trimmed.toLowerCase() === "true";
        }

        return trimmed;

    }

    private buildTimeRange(
        range: string
    ): MongoFilter {

        const now = new Date();

        const from = new Date(now);

        switch (range) {

            case "1h":
                from.setHours(now.getHours() - 1);
                break;

            case "6h":
                from.setHours(now.getHours() - 6);
                break;

            case "24h":
                from.setDate(now.getDate() - 1);
                break;

            case "7d":
                from.setDate(now.getDate() - 7);
                break;

            default:
                from.setHours(now.getHours() - 24);

        }

        return {
            $gte: from,
            $lte: now
        };

    }

}
