const COLLECTION_NAME = "telemetry_records";
const RESULT_LIMIT = 500;

export interface TelemetryRecord {
    timestamp: Date;
    factoryId: string;
    deviceId: string;
    lineId?: string;
    metric: string;
    value: number | boolean | string;
    unit?: string;
}

/**
 * Owns all read access to the telemetry time-series collection. By the time
 * a filter reaches this class it has already been through
 * QueryNormalizer.normalize(), so callers are trusted to have produced a
 * well-formed Mongo query.
 */
export class TelemetryRepository {

    private collection(): Collection<TelemetryRecord> {
        return getDb().collection<TelemetryRecord>(COLLECTION_NAME);
    }

    public async search(
        filter: MongoFilter
    ): Promise<TelemetryRecord[]> {

        const cursor = this.collection()
            .find(filter)
            .sort({ timestamp: -1 })
            .limit(RESULT_LIMIT);

        return cursor.toArray();

    }

}
```

