 * Mirrors backend/models/TelemetryQuery.go. The API gateway (Go) validates
 * and forwards requests in this shape over HTTP; the query-builder service
 * (Node/TypeScript) decodes the same JSON body into these interfaces before
 * building the Mongo filter.
 */
export interface QueryFilter {
    field: string;
    operator: string;
    value: unknown;
}

export interface TelemetryQuery {
    factoryId: string;
    timeRange: string;
    filters: QueryFilter[];
}
