import React, { useCallback, useMemo, useState } from "react";

interface SearchFilter {
    field: string;
    operator: string;
    value: string;
}

interface SearchRequest {
    factoryId: string;
    timeRange: string;
    filters: SearchFilter[];
}

interface TelemetryRecord {
    timestamp: string;
    deviceId: string;
    metric: string;
    value: number;
}

const AVAILABLE_FIELDS = [
    "temperature",
    "pressure",
    "vibration",
    "current",
    "voltage",
    "factory",
    "deviceId",
    "lineId"
];

const OPERATORS = [
    "eq",
    "gt",
    "gte",
    "lt",
    "lte",
    "between"
];

const DEFAULT_FILTER: SearchFilter = {
    field: "temperature",
    operator: "gt",
    value: ""
};

export default function TelemetryDashboard() {

    const [factoryId, setFactoryId] = useState("factory-east-01");

    const [timeRange, setTimeRange] = useState("24h");

    const [filters, setFilters] = useState<SearchFilter[]>([
        DEFAULT_FILTER
    ]);

    const [results, setResults] = useState<TelemetryRecord[]>([]);

    const [loading, setLoading] = useState(false);

    const requestPayload = useMemo<SearchRequest>(() => {

        return {
            factoryId,
            timeRange,
            filters
        };

    }, [factoryId, timeRange, filters]);

    const updateFilter = useCallback((
        index: number,
        key: keyof SearchFilter,
        value: string
    ) => {

        setFilters(previous => {

            const updated = [...previous];

            updated[index] = {
                ...updated[index],
                [key]: value
            };

            return updated;

        });

    }, []);

    const addFilter = () => {

        setFilters(previous => [
            ...previous,
            {
                field: "temperature",
                operator: "eq",
                value: ""
            }
        ]);

    };

    const removeFilter = (index: number) => {

        setFilters(previous =>
            previous.filter((_, i) => i !== index)
        );

    };

    const executeSearch = async () => {

        setLoading(true);

        try {

            const response = await fetch(
                "/api/v1/telemetry/search",
                {
                    method: "POST",
                    headers: {
                        "Content-Type": "application/json"
                    },
                    body: JSON.stringify(requestPayload)
                }
            );

            if (!response.ok) {
                throw new Error("Search request failed.");
            }

            const data = await response.json();

            setResults(data.records ?? []);

        } catch (err) {

            console.error(err);

            alert("Unable to load telemetry.");

        } finally {

            setLoading(false);

        }

    };

    return (

        <div style={{ padding: "2rem" }}>

            <h2>Telemetry Explorer</h2>

            <div>

                <label>

                    Factory

                    <input
                        value={factoryId}
                        onChange={e => setFactoryId(e.target.value)}
                    />

                </label>

            </div>

            <div style={{ marginTop: "1rem" }}>

                <label>

                    Time Range

                    <select
                        value={timeRange}
                        onChange={e => setTimeRange(e.target.value)}
                    >

                        <option value="1h">Last Hour</option>
                        <option value="6h">Last 6 Hours</option>
                        <option value="24h">Last 24 Hours</option>
                        <option value="7d">Last 7 Days</option>

                    </select>

                </label>

            </div>

            <hr />

            {filters.map((filter, index) => (

                <div
                    key={index}
                    style={{
                        display: "flex",
                        gap: "10px",
                        marginBottom: "12px"
                    }}
                >

                    <select
                        value={filter.field}
                        onChange={e =>
                            updateFilter(
                                index,
                                "field",
                                e.target.value
                            )
                        }
                    >

                        {AVAILABLE_FIELDS.map(field => (

                            <option
                                key={field}
                                value={field}
                            >
                                {field}
                            </option>

                        ))}

                    </select>

                    <select
                        value={filter.operator}
                        onChange={e =>
                            updateFilter(
                                index,
                                "operator",
                                e.target.value
                            )
                        }
                    >

                        {OPERATORS.map(op => (

                            <option
                                key={op}
                                value={op}
                            >
                                {op}
                            </option>

                        ))}

                    </select>

                    <input
                        placeholder="Value"
                        value={filter.value}
                        onChange={e =>
                            updateFilter(
                                index,
                                "value",
                                e.target.value
                            )
                        }
                    />

                    <button
                        onClick={() =>
                            removeFilter(index)
                        }
                    >
                        Remove
                    </button>

                </div>

            ))}

            <button onClick={addFilter}>

                Add Filter

            </button>

            <button
                style={{ marginLeft: "12px" }}
                disabled={loading}
                onClick={executeSearch}
            >

                {loading ? "Searching..." : "Search"}

            </button>

            <hr />

            <h3>

                Results ({results.length})

            </h3>

            <table>

                <thead>

                    <tr>

                        <th>Timestamp</th>
                        <th>Device</th>
                        <th>Metric</th>
                        <th>Value</th>

                    </tr>

                </thead>

                <tbody>

                    {results.map(record => (

                        <tr
                            key={
                                record.deviceId +
                                record.timestamp
                            }
                        >

                            <td>{record.timestamp}</td>
                            <td>{record.deviceId}</td>
                            <td>{record.metric}</td>
                            <td>{record.value}</td>

                        </tr>

                    ))}

                </tbody>

            </table>

        </div>

    );

}
