package models

import "time"

// TelemetryRecord is a single telemetry reading returned by the
// query-builder service after a search request has been executed against
// the MongoDB time-series collection. The API gateway never talks to Mongo
// directly, so this struct only needs to describe the JSON shape the
// query-builder service replies with.
type TelemetryRecord struct {
	Timestamp time.Time   `json:"timestamp"`
	FactoryID string      `json:"factoryId"`
	DeviceID  string      `json:"deviceId"`
	LineID    string      `json:"lineId,omitempty"`
	Metric    string      `json:"metric"`
	Value     interface{} `json:"value"`
	Unit      string      `json:"unit,omitempty"`
}
