## FILE: backend/services/QueryValidator.go

```
package services

import (
	"errors"
	"fmt"
	"strings"

	"telemetry-platform/models"
)

type QueryValidator struct {
	allowedFields    map[string]struct{}
	allowedOperators map[string]struct{}
	maxFilters       int
}

func NewQueryValidator() *QueryValidator {

	return &QueryValidator{
		allowedFields: map[string]struct{}{
			"temperature": {},
			"pressure":    {},
			"vibration":   {},
			"current":     {},
			"voltage":     {},
			"factory":     {},
			"deviceId":    {},
			"lineId":      {},
			"timestamp":   {},
		},

		allowedOperators: map[string]struct{}{
			"eq":      {},
			"gt":      {},
			"gte":     {},
			"lt":      {},
			"lte":     {},
			"between": {},
		},

		maxFilters: 20,
	}

}

func (v *QueryValidator) Validate(
	query models.TelemetryQuery,
) error {

	if err := v.validateFactory(query.FactoryID); err != nil {
		return err
	}

	if err := v.validateTimeRange(query.TimeRange); err != nil {
		return err
	}

	if err := v.validateFilters(query.Filters); err != nil {
		return err
	}

	return nil

}

func (v *QueryValidator) validateFactory(
	factory string,
) error {

	if strings.TrimSpace(factory) == "" {
		return errors.New("factoryId is required")
	}

	return nil

}

func (v *QueryValidator) validateTimeRange(
	timeRange string,
) error {

	switch timeRange {

	case "1h", "6h", "24h", "7d":
		return nil

	default:
		return fmt.Errorf(
			"unsupported time range '%s'",
			timeRange,
		)

	}

}

func (v *QueryValidator) validateFilters(
	filters []models.QueryFilter,
) error {

	if len(filters) == 0 {
		return errors.New("at least one filter is required")
	}

	if len(filters) > v.maxFilters {
		return fmt.Errorf(
			"maximum %d filters allowed",
			v.maxFilters,
		)
	}

	seen := make(map[string]struct{})

	for _, filter := range filters {

		if err := v.validateFilter(filter); err != nil {
			return err
		}

		key := strings.ToLower(
			filter.Field +
				":" +
				filter.Operator,
		)

		if _, exists := seen[key]; exists {

			return fmt.Errorf(
				"duplicate filter '%s'",
				key,
			)

		}

		seen[key] = struct{}{}

	}

	return nil

}

func (v *QueryValidator) validateFilter(
	filter models.QueryFilter,
) error {

	field := strings.TrimSpace(filter.Field)

	if field == "" {
		return errors.New("filter field cannot be empty")
	}

	if _, ok := v.allowedFields[field]; !ok {

		return fmt.Errorf(
			"unsupported field '%s'",
			field,
		)

	}

	operator := strings.ToLower(
		strings.TrimSpace(filter.Operator),
	)

	if _, ok := v.allowedOperators[operator]; !ok {

		return fmt.Errorf(
			"unsupported operator '%s'",
			operator,
		)

	}

	if filter.Value == nil {
		return errors.New("filter value cannot be null")
	}

	if operator == "between" {

		values, ok := filter.Value.([]interface{})

		if !ok || len(values) != 2 {

			return errors.New(
				"between operator expects two values",
			)

		}

	}

	return nil

}

func (v *QueryValidator) AllowedFields() []string {

	return []string{
		"temperature",
		"pressure",
		"vibration",
		"current",
		"voltage",
		"factory",
		"deviceId",
		"lineId",
		"timestamp",
	}

}

func (v *QueryValidator) AllowedOperators() []string {

	return []string{
		"eq",
		"gt",
		"gte",
		"lt",
		"lte",
		"between",
	}

}
