import express, { Request, Response } from "express";

import { QueryNormalizer } from "./QueryNormalizer";
import { TelemetryRepository } from "../repository/TelemetryRepository";
import { connect } from "../utils/MongoConnection";
import { TelemetryQuery } from "../models/TelemetryQuery";

/**
 * Internal-only HTTP surface for the query-builder service. The Go API
 * gateway is the sole caller of this endpoint; it is never exposed to the
 * public internet, which is why request bodies are trusted to already carry
 * a field/operator-validated TelemetryQuery.
 */

const PORT = Number(process.env.QUERY_SERVICE_PORT ?? 4500);
const MONGO_URI = process.env.MONGO_URI ?? "mongodb://localhost:27017";
const MONGO_DATABASE = process.env.MONGO_DATABASE ?? "telemetry";

const normalizer = new QueryNormalizer();
const repository = new TelemetryRepository();

const app = express();
app.use(express.json());

app.post(
    "/internal/telemetry/search",
    async (req: Request, res: Response) => {

        const query = req.body as TelemetryQuery;

        try {

            const filter = normalizer.normalize(query);
            const records = await repository.search(filter);

            res.json({ records });

        } catch (err) {

            res.status(400).json({
                error: err instanceof Error ? err.message : "invalid query"
            });

        }

    }
);

app.get("/internal/health", (_req: Request, res: Response) => {
    res.json({ status: "UP" });
});

async function start(): Promise<void> {

    await connect(MONGO_URI, MONGO_DATABASE);

    app.listen(PORT, () => {
        console.log(`query-builder service listening on ${PORT}`);
    });

}

start().catch(err => {
    console.error("failed to start query-builder service", err);
    process.exit(1);
});
