using System;
using FreelancerMarketplace.Storage;

namespace FreelancerMarketplace.Recovery
{
    public class RecoveryEligibilityService
    {
        private readonly UserRepository
            _userRepository;

        private readonly MembershipRepository
            _membershipRepository;

        public RecoveryEligibilityService(
            UserRepository userRepository,
            MembershipRepository membershipRepository)
        {
            _userRepository =
                userRepository;

            _membershipRepository =
                membershipRepository;
        }

        public EligibilityResult Evaluate(
            string userId)
        {
            var user =
                _userRepository
                    .LoadIdentity(
                        userId
                    );

            if (user == null)
            {
                return EligibilityResult
                    .Reject(
                        "user_not_found"
                    );
            }

            if (!user.Active)
            {
                return EligibilityResult
                    .Reject(
                        "account_inactive"
                    );
            }

            var membership =
                _membershipRepository
                    .CurrentMembership(
                        userId
                    );

            if (membership == null)
            {
                return EligibilityResult
                    .Reject(
                        "membership_missing"
                    );
            }

            if (!membership.Active)
            {
                return EligibilityResult
                    .Reject(
                        "membership_inactive"
                    );
            }

            return EligibilityResult
                .Approve(
                    membership
                        .OrganizationId
                );
        }
    }

    public class EligibilityResult
    {
        public bool Allowed { get; set; }

        public string OrganizationId
        {
            get;
            set;
        }

        public string Reason
        {
            get;
            set;
        }

        public static EligibilityResult
            Approve(
                string organizationId)
        {
            return new EligibilityResult
            {
                Allowed = true,
                OrganizationId =
                    organizationId
            };
        }

        public static EligibilityResult
            Reject(
                string reason)
        {
            return new EligibilityResult
            {
                Allowed = false,
                Reason = reason
            };
        }
    }
}
