package recovery

import storage.RecoveryRepository
import storage.UserRepository

class RecoveryCompletionService(

    private val recoveryRepository:
        RecoveryRepository,

    private val userRepository:
        UserRepository
) {

    fun completeRecovery(
        requestId: String,
        recoveryToken: String
    ): RecoveryResult {

        val request =
            recoveryRepository
                .loadRequest(
                    requestId
                )

        if (
            request.status !=
            "APPROVED"
        ) {

            return RecoveryResult(
                false,
                "request_not_approved"
            )
        }

        if (
            request.isExpired()
        ) {

            return RecoveryResult(
                false,
                "request_expired"
            )
        }

        val user =
            userRepository
                .loadIdentity(
                    request.userId
                )

        if (user == null) {

            return RecoveryResult(
                false,
                "user_not_found"
            )
        }

        if (
            !validateToken(
                recoveryToken,
                request
            )
        ) {

            return RecoveryResult(
                false,
                "invalid_token"
            )
        }

        user.markRecovered()

        userRepository
            .saveIdentity(
                user
            )

        request.markCompleted()

        recoveryRepository
            .saveRequest(
                request
            )

        return RecoveryResult(
            true,
            "recovery_completed"
        )
    }

    private fun validateToken(
        token: String,
        request: RecoveryRequest
    ): Boolean {

        return token ==
            request.approvalId
    }
}

data class RecoveryResult(
    val success: Boolean,
    val reason: String
)
