            RecoveryRepository recoveryRepository,
            UserRepository userRepository)
        {
            _recoveryRepository =
                recoveryRepository;

            _userRepository =
                userRepository;
        }

        public RecoveryContext BuildContext(
            string requestId)
        {
            var request =
                _recoveryRepository
                    .LoadRequest(
                        requestId
                    );

            var user =
                _userRepository
                    .LoadIdentity(
                        request.UserId
                    );

            return new RecoveryContext
            {
                RequestId =
                    request.RequestId,

                UserId =
                    request.UserId,

                ApprovalId =
                    request.ApprovalId,

                RequestedOrganizationId =
                    request
                        .RequestedOrganizationId,

                CurrentOrganizationId =
                    user
                        .OrganizationId,

                Status =
                    request.Status
            };
        }

        public bool CanProceed(
            RecoveryContext context)
        {
            // TODO:
// Revisit whether approval context
// should be revalidated for long-
// running recovery requests.
            if (
                context.Status !=
                "APPROVED"
            )
            {
                return false;
            }

            return true;
        }
    }

