package com.company.expense.services;

import com.company.expense.models.Expense;
import com.company.expense.repositories.ApprovalRepository;
import com.company.expense.repositories.ExpenseRepository;
import org.springframework.stereotype.Service;

@Service
public class ExpenseService {

    private final ExpenseRepository expenseRepository;
    private final ApprovalRepository approvalRepository;

    public ExpenseService(
            ExpenseRepository expenseRepository,
            ApprovalRepository approvalRepository
    ) {
        this.expenseRepository = expenseRepository;
        this.approvalRepository = approvalRepository;
    }

    public void createExpense(Expense expense) {
        expense.setStatus("PENDING");
        expenseRepository.save(expense);
    }

    public void updateExpense(
            Long expenseId,
            Expense updatedExpense
    ) {

        Expense existing =
                expenseRepository.findById(expenseId);

        existing.setAmount(
                updatedExpense.getAmount()
        );

        existing.setDescription(
                updatedExpense.getDescription()
        );

        expenseRepository.update(existing);

        /*
         * Any modification after approval
         * requires re-approval.
         */
        approvalRepository.invalidateApproval(
                expenseId
        );
    }

    public Expense getExpense(Long expenseId) {
        return expenseRepository.findById(expenseId);
    }
}
