package com.company.expense.repositories;

import com.company.expense.models.Approval;
import org.springframework.stereotype.Repository;

import java.util.HashMap;
import java.util.Map;

@Repository
public class ApprovalRepository {

    private final Map<Long, Approval> approvals = new HashMap<>();

    public Approval findByExpenseId(Long expenseId) {
        return approvals.get(expenseId);
    }

    public void save(Approval approval) {
        approvals.put(approval.getExpenseId(), approval);
    }

    public void invalidateApproval(Long expenseId) {

        Approval approval = approvals.get(expenseId);

        if (approval != null) {
            approval.setStatus("INVALIDATED");
        }
    }

    public boolean isApproved(Long expenseId) {

        Approval approval = approvals.get(expenseId);

        return approval != null &&
               "APPROVED".equals(approval.getStatus());
    }
}
