import org.springframework.stereotype.Repository;

import java.util.HashMap;
import java.util.Map;

@Repository
public class ApprovalSnapshotRepository {

    private final Map<Long, ApprovalSnapshot> snapshots =
            new HashMap<>();

    public void save(ApprovalSnapshot snapshot) {

        snapshots.put(
                snapshot.getExpenseId(),
                snapshot
        );
    }

    public ApprovalSnapshot findByExpenseId(Long expenseId) {

        return snapshots.get(expenseId);
    }
}
