package com.company.expense.workers;

import com.company.expense.models.ApprovalSnapshot;
import com.company.expense.models.PaymentRequest;
import com.company.expense.repositories.ApprovalSnapshotRepository;
import com.company.expense.repositories.ExpenseRepository;
import com.company.expense.services.FinanceService;
import org.springframework.stereotype.Component;

@Component
public class PaymentWorker {

    private final ApprovalSnapshotRepository snapshotRepository;
    private final ExpenseRepository expenseRepository;
    private final FinanceService financeService;

    public PaymentWorker(
            ApprovalSnapshotRepository snapshotRepository,
            ExpenseRepository expenseRepository,
            FinanceService financeService
    ) {
        this.snapshotRepository = snapshotRepository;
        this.expenseRepository = expenseRepository;
        this.financeService = financeService;
    }

    public void processPayment(
            Long expenseId
    ) {

        ApprovalSnapshot snapshot =
                snapshotRepository.findByExpenseId(
                        expenseId
                );

        if (snapshot == null) {
            return;
        }

        if (!snapshot.isApproved()) {
            return;
        }

        PaymentRequest request =
                financeService.buildPaymentRequest(
                        expenseRepository.findById(
                                expenseId
                        )
                );

        financeService.executePayment(
                request
        );
    }
}
```

