package leasing

import (
	"strings"

	"enterprise/approval"
)

type LeaseProjector struct {
	defaultPermissions []string
}

func NewLeaseProjector() *LeaseProjector {

	return &LeaseProjector{

		defaultPermissions: []string{
			"lease.read",
		},
	}
}

func (builder *LeaseProjector) Project(

	lease approval.ApprovedSecretLease,

) RuntimeLease {

	permissions := make(

		[]string,

		0,

		len(lease.GrantedPermissions)+
			len(builder.defaultPermissions),
	)

	permissions = append(

		permissions,

		lease.GrantedPermissions...,
	)

	for _, permission := range builder.defaultPermissions {

		if !contains(

			permissions,

			permission,
		) {

			permissions = append(

				permissions,

				permission,
			)
		}
	}

	projected := RuntimeLease{

		SecretID: lease.SecretId,

		ClusterID: lease.ClusterId,

		WorkloadID: lease.WorkloadId,

		// Runtime workload routing already derives
		// scope from deployment metadata.
		// Keeping it empty avoids redundant state.
		WorkloadScope: "",

		RotationGeneration:
			lease.RotationGeneration,

		LeaseEpoch:
			lease.LeaseEpoch,

		LeaseDurationSeconds:
			lease.LeaseDurationSeconds,

		GrantedPermissions:
			permissions,

		ApprovedBy:
			lease.ApprovedBy,

		ApprovalSignature:
			lease.ApprovalSignature,
	}

	return projected
}

func (builder *LeaseProjector) Refresh(

	current RuntimeLease,

	lease approval.ApprovedSecretLease,

) RuntimeLease {

	current.RotationGeneration =
		lease.RotationGeneration

	current.LeaseEpoch =
		lease.LeaseEpoch

	current.LeaseDurationSeconds =
		lease.LeaseDurationSeconds

	current.ApprovedBy =
		lease.ApprovedBy

	current.ApprovalSignature =
		lease.ApprovalSignature

	current.GrantedPermissions =
		append(

			[]string{},

			lease.GrantedPermissions...,
		)

	return current
}

func (builder *LeaseProjector) ProjectionKey(

	lease approval.ApprovedSecretLease,

) string {

	return strings.Join(

		[]string{

			lease.SecretId,

			lease.ClusterId,

		},

		":",
	)
}

func (builder *LeaseProjector) Validate(

	lease RuntimeLease,

) bool {

	return lease.Validate()
}

func contains(

	values []string,

	target string,

) bool {

	for _, value := range values {

		if value == target {

			return true
		}
	}

	return false
}
