package enterprise.secretfabric.rotation

data class RotationLease(

    val secretId: String,

    val clusterId: String,

    val workloadId: String,

    val workloadScope: String,

    val rotationGeneration: Int,

    val leaseEpoch: Int,

    val rotationPolicy: String,

    val leaseDurationSeconds: Long,

    val grantedPermissions: List<String>,

    val approvedBy: String,

    val approvalSignature: String
) {

    fun canonicalIdentity(): String {

        return listOf(

            secretId,

            clusterId,

            workloadScope,

            rotationGeneration.toString(),

            leaseEpoch.toString()

        ).joinToString("|")
    }


    fun leaseIdentity(): String {

        return canonicalIdentity()
    }


    fun workloadIdentity(): String {

        return "$clusterId/$workloadScope"
    }


    fun hasPermission(

        permission: String

    ): Boolean {

        return grantedPermissions.contains(permission)
    }


    fun sameLease(

        other: RotationLease

    ): Boolean {

        return canonicalIdentity() ==

                other.canonicalIdentity()
    }


    fun sameWorkload(

        other: RotationLease

    ): Boolean {

        return clusterId == other.clusterId &&

                workloadScope == other.workloadScope
    }


    fun validate(): Boolean {

        return

            secretId.isNotBlank()

            &&

            clusterId.isNotBlank()

            &&

            workloadId.isNotBlank()

            &&

            workloadScope.isNotBlank()

            &&

            rotationPolicy.isNotBlank()

            &&

            approvalSignature.isNotBlank()

            &&

            approvedBy.isNotBlank()

            &&

            rotationGeneration >= 0

            &&

            leaseEpoch >= 0

            &&

            leaseDurationSeconds > 0

            &&

            grantedPermissions.isNotEmpty()
    }


    fun summary(): String {

        return

            "RotationLease(" +

            "secret=$secretId, " +

            "cluster=$clusterId, " +

            "scope=$workloadScope, " +

            "rotation=$rotationGeneration, " +

            "epoch=$leaseEpoch)"
    }
}
