package enterprise.secretfabric.cluster

final case class ClusterBinding(

    secretId: String,

    clusterId: String,

    workloadId: String,

    workloadScope: String,

    rotationGeneration: Int,

    leaseEpoch: Int,

    nodePool: String,

    namespace: String,

    serviceAccount: String,

    bindingHash: String,

    approvalSignature: String
) {

    def canonicalIdentity: String =

        Seq(

            secretId,

            clusterId,

            workloadScope,

            rotationGeneration.toString,

            leaseEpoch.toString

        ).mkString("|")


    def leaseIdentity: String =

        canonicalIdentity


    def workloadIdentity: String =

        clusterId +

        "/" +

        namespace +

        "/" +

        serviceAccount


    def deploymentTarget: String =

        clusterId +

        "/" +

        nodePool


    def sameLease(

        other: ClusterBinding

    ): Boolean =

        canonicalIdentity ==

        other.canonicalIdentity


    def sameWorkload(

        other: ClusterBinding

    ): Boolean =

        workloadId == other.workloadId &&

        workloadScope == other.workloadScope


    def validate: Boolean =

        secretId.nonEmpty &&

        clusterId.nonEmpty &&

        workloadId.nonEmpty &&

        workloadScope.nonEmpty &&

        nodePool.nonEmpty &&

        namespace.nonEmpty &&

        serviceAccount.nonEmpty &&

        bindingHash.nonEmpty &&

        approvalSignature.nonEmpty &&

        rotationGeneration >= 0 &&

        leaseEpoch >= 0


    override def toString: String =

        s"ClusterBinding(" +

        s"secret=$secretId, " +

        s"cluster=$clusterId, " +

        s"scope=$workloadScope, " +

        s"rotation=$rotationGeneration, " +

        s"epoch=$leaseEpoch)"
}
