import Foundation

public struct RuntimeSecretLease {

    public let runtimeLease: RuntimeLease

    public let rotationLease: RotationLease

    public let clusterBinding: ClusterBinding

    public let synchronizedAt: Date

    public let synchronizedBy: String

    public let synchronizationVersion: String

    public init(

        runtimeLease: RuntimeLease,

        rotationLease: RotationLease,

        clusterBinding: ClusterBinding,

        synchronizedAt: Date,

        synchronizedBy: String,

        synchronizationVersion: String

    ) {

        self.runtimeLease = runtimeLease

        self.rotationLease = rotationLease

        self.clusterBinding = clusterBinding

        self.synchronizedAt = synchronizedAt

        self.synchronizedBy = synchronizedBy

        self.synchronizationVersion = synchronizationVersion
    }


    public var canonicalIdentity: String {

        return runtimeLease.canonicalIdentity()
    }


    public var secretId: String {

        return runtimeLease.secretID
    }


    public var clusterId: String {

        return runtimeLease.clusterID
    }


    public var workloadScope: String {

        return runtimeLease.workloadScope
    }


    public var rotationGeneration: Int {

        return runtimeLease.rotationGeneration
    }


    public var leaseEpoch: Int {

        return runtimeLease.leaseEpoch
    }


    public func leaseIdentities() -> [String] {

        return [

            runtimeLease.canonicalIdentity(),

            rotationLease.canonicalIdentity(),

            clusterBinding.canonicalIdentity()

        ]
    }


    public func allComponentsAgree() -> Bool {

        let identities = leaseIdentities()

        guard let first = identities.first else {

            return false
        }

        return identities.allSatisfy {

            $0 == first
        }
    }


    public func validate() -> Bool {

        return

            !secretId.isEmpty

            &&

            !clusterId.isEmpty

            &&

            !workloadScope.isEmpty

            &&

            !synchronizedBy.isEmpty

            &&

            !synchronizationVersion.isEmpty

            &&

            allComponentsAgree()
    }


    public func summary() -> String {

        return """

        RuntimeSecretLease(

            secret=\(secretId),

            cluster=\(clusterId),

            scope=\(workloadScope),

            rotation=\(rotationGeneration),

            epoch=\(leaseEpoch)

        )

        """
    }
}
