class MaterializedRuntimeSecret {

  final String secretId;

  final String clusterId;

  final String workloadId;

  final String workloadScope;

  final int rotationGeneration;

  final int leaseEpoch;

  final String runtimeSecret;

  final String deliveryChannel;

  final List<String> grantedPermissions;

  final String approvalSignature;

  const MaterializedRuntimeSecret({

    required this.secretId,

    required this.clusterId,

    required this.workloadId,

    required this.workloadScope,

    required this.rotationGeneration,

    required this.leaseEpoch,

    required this.runtimeSecret,

    required this.deliveryChannel,

    required this.grantedPermissions,

    required this.approvalSignature,
  });


  String canonicalIdentity() {

    return [

      secretId,

      clusterId,

      workloadScope,

      rotationGeneration.toString(),

      leaseEpoch.toString(),

    ].join("|");
  }


  String runtimeIdentity() {

    return canonicalIdentity();
  }


  String workloadIdentity() {

    return "$clusterId/$workloadScope";
  }


  bool permits(

    String permission,

  ) {

    return grantedPermissions.contains(

      permission,

    );
  }


  bool sameLease(

    MaterializedRuntimeSecret other,

  ) {

    return canonicalIdentity() ==

        other.canonicalIdentity();
  }


  bool sameWorkload(

    MaterializedRuntimeSecret other,

  ) {

    return

        clusterId == other.clusterId &&

        workloadScope == other.workloadScope;
  }


  bool isValid() {

    return

        secretId.isNotEmpty &&

        clusterId.isNotEmpty &&

        workloadId.isNotEmpty &&

        workloadScope.isNotEmpty &&

        runtimeSecret.isNotEmpty &&

        deliveryChannel.isNotEmpty &&

        approvalSignature.isNotEmpty &&

        rotationGeneration >= 0 &&

        leaseEpoch >= 0 &&

        grantedPermissions.isNotEmpty;
  }


  Map<String, dynamic> toRecord() {

    return {

      "secretId": secretId,

      "clusterId": clusterId,

      "workloadId": workloadId,

      "workloadScope": workloadScope,

      "rotationGeneration": rotationGeneration,

      "leaseEpoch": leaseEpoch,

      "runtimeSecret": runtimeSecret,

      "deliveryChannel": deliveryChannel,

      "approvalSignature": approvalSignature,

      "permissions": grantedPermissions,
    };
  }


  String summary() {

    return

      "MaterializedRuntimeSecret("

      "secret=$secretId, "

      "cluster=$clusterId, "

      "scope=$workloadScope, "

      "rotation=$rotationGeneration, "

      "epoch=$leaseEpoch)";
  }
}
