namespace Enterprise.SecretFabric.Approval

open System

type SecretAccessRequest =
    {
        RequestId : string

        SecretId : string

        WorkloadId : string

        WorkloadScope : string

        ClusterId : string

        Namespace : string

        ServiceAccount : string

        RequestedPermissions : string list

        LeaseDurationSeconds : int

        RequestedBy : string
    }

module SecretApprovalAuthority =

    let private generateLeaseEpoch () =

        DateTimeOffset.UtcNow.ToUnixTimeSeconds()
        |> int


    let private generateRotationGeneration
        (request : SecretAccessRequest) =

        abs(request.SecretId.GetHashCode()) % 100000


    let private approvalSignature
        (lease : ApprovedSecretLease) =

        String.concat
            ":"
            [

                lease.SecretId

                lease.ClusterId

                lease.WorkloadScope

                string lease.RotationGeneration

                string lease.LeaseEpoch

            ]


    let approve
        (request : SecretAccessRequest)
        (approver : string) =

        let lease =

            {

                SecretId = request.SecretId

                ClusterId = request.ClusterId

                WorkloadId = request.WorkloadId

                WorkloadScope = request.WorkloadScope

                RotationGeneration =
                    generateRotationGeneration request

                LeaseEpoch =
                    generateLeaseEpoch ()

                LeaseDurationSeconds =
                    request.LeaseDurationSeconds

                GrantedPermissions =
                    request.RequestedPermissions

                ApprovedBy =
                    approver

                ApprovedAt =
                    DateTime.UtcNow

                ApprovalSignature =
                    ""

            }

        { lease with

            ApprovalSignature =
                approvalSignature lease
        }


    let verify
        (lease : ApprovedSecretLease) =

        lease.ApprovalSignature =

            approvalSignature lease


    let renew
        (lease : ApprovedSecretLease) =

        let renewed =

            {

                lease with

                    LeaseEpoch =
                        generateLeaseEpoch ()

                    ApprovedAt =
                        DateTime.UtcNow

                    ApprovalSignature =
                        ""

            }

        {

            renewed with

                ApprovalSignature =
                    approvalSignature renewed

        }


    let revoke
        (lease : ApprovedSecretLease) =

        {

            lease with

                LeaseDurationSeconds = 0

        }


    let isExpired
        (lease : ApprovedSecretLease) =

        let expiry =

            lease.ApprovedAt.AddSeconds(

                float lease.LeaseDurationSeconds

            )

        DateTime.UtcNow > expiry


    let summary
        (lease : ApprovedSecretLease) =

        sprintf

            "ApprovedSecretLease(secret=%s, cluster=%s, scope=%s, rotation=%d, epoch=%d)"

            lease.SecretId

            lease.ClusterId

            lease.WorkloadScope

            lease.RotationGeneration

            lease.LeaseEpoch
