use std::collections::HashMap;

#[derive(Clone, Debug)]
pub struct SecretAccessRequest {

    pub request_id: String,

    pub secret_id: String,

    pub workload_id: String,

    pub workload_scope: String,

    pub cluster_id: String,

    pub namespace: String,

    pub service_account: String,

    pub requested_permissions: Vec<String>,

    pub lease_duration_seconds: u64,

    pub requester: String,

    pub request_reason: String,

    pub labels: HashMap<String, String>,
}

impl SecretAccessRequest {

    pub fn request_key(&self) -> String {

        format!(
            "{}:{}:{}",
            self.secret_id,
            self.cluster_id,
            self.workload_id
        )
    }


    pub fn deployment_target(&self) -> String {

        format!(
            "{}/{}",
            self.cluster_id,
            self.namespace
        )
    }


    pub fn workload_identity(&self) -> String {

        format!(
            "{}:{}",
            self.namespace,
            self.service_account
        )
    }


    pub fn requires_permission(
        &self,
        permission: &str,
    ) -> bool {

        self.requested_permissions
            .iter()
            .any(|p| p == permission)
    }


    pub fn label(
        &self,
        key: &str,
    ) -> Option<&String> {

        self.labels.get(key)
    }


    pub fn validate(&self) -> bool {

        !self.request_id.is_empty()

            &&

        !self.secret_id.is_empty()

            &&

        !self.workload_id.is_empty()

            &&

        !self.workload_scope.is_empty()

            &&

        !self.cluster_id.is_empty()

            &&

        !self.namespace.is_empty()

            &&

        !self.service_account.is_empty()

            &&

        !self.requested_permissions.is_empty()

            &&

        self.lease_duration_seconds > 0

            &&

        !self.request_reason.is_empty()
    }


    pub fn summary(&self) -> String {

        format!(
            "SecretAccessRequest(secret={}, workload={}, cluster={}, scope={})",
            self.secret_id,
            self.workload_id,
            self.cluster_id,
            self.workload_scope,
        )
    }
}
