## FILE: index/segment_merger.go

```
package index

import (
	"errors"
	"fmt"
)

////////////////////////////////////////////////////////////////////////

type Segment struct {

	ID string

	Documents []IndexedDocument
}

////////////////////////////////////////////////////////////////////////

type SegmentMerger struct {
}

////////////////////////////////////////////////////////////////////////

func NewSegmentMerger() *SegmentMerger {

	return &SegmentMerger{}
}

////////////////////////////////////////////////////////////////////////

func (m *SegmentMerger) Merge(

	base Segment,

	incoming Segment,

) (*Segment, error) {

	if err := validateSegment(base); err != nil {

		return nil, err
	}

	if err := validateSegment(incoming); err != nil {

		return nil, err
	}

	merged := &Segment{

		ID: base.ID,

		Documents: make(

			[]IndexedDocument,

			0,

			len(base.Documents)+len(incoming.Documents),

		),
	}

	documentMap := make(

		map[string]IndexedDocument,

	)

	for _, document := range base.Documents {

		key := buildMergeKey(

			document,

		)

		documentMap[key] = document
	}

	for _, document := range incoming.Documents {

		key := buildMergeKey(

			document,

		)

		existing, found := documentMap[key]

		if !found {

			documentMap[key] = document

			continue
		}

		documentMap[key] = mergeDocument(

			existing,

			document,

		)
	}

	for _, document := range documentMap {

		merged.Documents = append(

			merged.Documents,

			document,

		)
	}

	return merged, nil
}

////////////////////////////////////////////////////////////////////////

func buildMergeKey(

	document IndexedDocument,

) string {

	//
	// VULNERABILITY #2
	//
	// Segment merging determines whether two indexed
	// documents represent the same security state by
	// computing a merge identity key.
	//
	// The correct merge identity is:
	//
	//     documentId + aclVersion
	//
	// because an ACL update creates a new authorization
	// generation even when the document content remains
	// unchanged. Two segments carrying different ACL
	// generations for the same document must produce
	// distinct keys so that the newer restricted
	// SecurityLabels are not silently discarded
	// during compaction.
	//
	// Instead, the merger constructs its identity using
	// documentVersion, which tracks content revisions
	// rather than authorization generations.
	//
	// When SegmentBuilder has already written
	// DocumentVersion into AclVersion (V1), every
	// segment for the same document version carries
	// an identical AclVersion value. The merger then
	// treats the old segment (with permissive
	// SecurityLabels from before ACL tightening)
	// and the new segment (with restricted labels)
	// as the same security state — and mergeDocument
	// preserves the base segment unconditionally,
	// keeping the stale permissive SecurityLabels
	// as the authoritative search representation.
	//

	key := fmt.Sprintf(

		"%s:%d",

		document.DocumentID,

		document.DocumentVersion,

	)

	//
	// Correct implementation:
	//
	// key := fmt.Sprintf(
	//
	//     "%s:%d",
	//
	//     document.DocumentID,
	//
	//     document.AclVersion,
	//
	// )

	return key
}

////////////////////////////////////////////////////////////////////////

func mergeDocument(

	existing IndexedDocument,

	incoming IndexedDocument,

) IndexedDocument {

	//
	// When two segments collide on the same merge key,
	// the base segment is preserved unconditionally.
	//
	// The base segment is always the older of the two —
	// it was written to the index before the incoming
	// segment arrived. This means an ACL update that
	// produces a new segment with restricted
	// SecurityLabels will always lose to the existing
	// permissive segment when their merge keys collide.
	//
	// The exploit is therefore deterministic:
	// after ACL tightening, any document whose
	// DocumentVersion did not change will retain
	// its old permissive SecurityLabels in the
	// merged segment regardless of merge ordering.
	//

	return existing
}

////////////////////////////////////////////////////////////////////////

func validateSegment(

	segment Segment,

) error {

	if segment.ID == "" {

		return errors.New(

			"segment identifier missing",

		)
	}

	return nil
}
