////////////////////////////////////////////////////////////////////////

type SearchService struct {

	index *index.SearchIndex

	planner *QueryPlanner

	authorizer *SearchAuthorizer
}

////////////////////////////////////////////////////////////////////////

func NewSearchService(

	searchIndex *index.SearchIndex,

) *SearchService {

	return &SearchService{

		index: searchIndex,

		planner: NewQueryPlanner(),

		authorizer: NewSearchAuthorizer(),
	}
}

////////////////////////////////////////////////////////////////////////

func (s *SearchService) Search(

	query string,

	tenantID string,

	userGroups []string,

) ([]index.IndexedDocument, error) {

	plan, err := s.planner.BuildPlan(

		SearchQuery{

			Query: query,

			TenantID: tenantID,
		},
	)

	if err != nil {

		return nil, err
	}

	results := s.index.Search(

		plan.NormalizedQuery,

	)

	authorized := []index.IndexedDocument{}

	for _, document := range results {

		doc := document

		err := s.authorizer.Authorize(

			&doc,

			tenantID,

			userGroups,
		)

		if err == nil {

			authorized = append(

				authorized,

				doc,
			)
		}
	}

	return authorized, nil
}

////////////////////////////////////////////////////////////////////////

func (s *SearchService) GetDocument(

	documentID string,

	tenantID string,

	userGroups []string,

) (*index.IndexedDocument, error) {

	document, found := s.index.FindDocument(

		documentID,
	)

	if !found {

		return nil, errors.New(

			"document not found",
		)
	}

	if err := s.authorizer.Authorize(

		document,

		tenantID,

		userGroups,
	); err != nil {

		return nil, err
	}

	return document, nil
}

////////////////////////////////////////////////////////////////////////

func (s *SearchService) Health() map[string]string {

	return map[string]string{

		"status": "UP",
	}
}
