require 'json'

# Selects the compute queue an execution batch should be enqueued on
# and forwards the batch's work packages to that queue without
# rewriting any of their fields. Routing decisions are made purely
# from operational attributes (priority, memory footprint, region
# affinity); the identity fields on each work package
# (`organization_id`, `experiment_id`, `compute_generation`) pass
# through untouched so that every later stage can keep verifying them
# against the values admission originally produced.
class QueueRouter
  ROUTES_BY_PRIORITY = {
    'burst'    => 'queue.compute.burst',
    'high'     => 'queue.compute.high',
    'standard' => 'queue.compute.standard',
    'low'      => 'queue.compute.low'
  }.freeze

  LARGE_MEMORY_THRESHOLD_GB = 512

  class RoutingError < StandardError; end
  class UnknownPriorityError < RoutingError; end
  class EmptyBatchError < RoutingError; end

  def initialize(queue_client:, region_resolver: nil)
    @queue_client = queue_client
    @region_resolver = region_resolver
  end

  # Routes every package in an assembled batch to the queue implied by
  # the batch's dominant priority, returning the routing decisions
  # taken for observability/audit purposes.
  def route_batch(batch)
    packages = batch.fetch('packages')
    raise EmptyBatchError, 'batch has no work packages to route' if packages.empty?

    decisions = packages.map { |package| route_package(package, batch) }
    decisions
  end

  def route_package(package, batch)
    queue_name = resolve_queue_name(package, batch)

    envelope_payload = package.dup
    @queue_client.enqueue(queue_name, envelope_payload)

    RouteDecision.new(
      queue_name: queue_name,
      package_id: package.fetch('package_id'),
      organization_id: package.fetch('organization_id'),
      experiment_id: package.fetch('experiment_id')
    )
  end

  private

  def resolve_queue_name(package, _batch)
    priority = package.fetch('priority', 'standard')
    base_queue = ROUTES_BY_PRIORITY.fetch(priority) do
      raise UnknownPriorityError, "no route configured for priority '#{priority}'"
    end

    if package.fetch('memory_gb', 0) >= LARGE_MEMORY_THRESHOLD_GB
      base_queue = "#{base_queue}.large-memory"
    end

    if @region_resolver
      region = @region_resolver.call(package.fetch('organization_id'))
      base_queue = "#{base_queue}.#{region}" if region
    end

    base_queue
  end
end

RouteDecision = Struct.new(:queue_name, :package_id, :organization_id, :experiment_id, keyword_init: true) do
  def to_h
    {
      queue_name: queue_name,
      package_id: package_id,
      organization_id: organization_id,
      experiment_id: experiment_id
    }
  end
end
