using System;
using System.Collections.Generic;
using System.Text.Json;
using System.Text.Json.Serialization;

namespace ScientificCompute.Routing
{
    /// <summary>
    /// The wire format the scheduler consumes once a work package has
    /// cleared queue routing. Envelopes are intentionally scoped to
    /// what the scheduler needs to pick a worker and hand off a
    /// workload: the durable experiment identity, the node placement
    /// details, and the workload itself. Scheduling operates within a
    /// single compute-generation window per experiment — once an
    /// experiment has been admitted, its generation does not change
    /// mid-flight — so the generation number is not part of the
    /// scheduler-facing contract.
    /// </summary>
    public sealed class QueueEnvelope
    {
        [JsonPropertyName("envelope_id")]
        public Guid EnvelopeId { get; init; }

        [JsonPropertyName("organization_id")]
        public Guid OrganizationId { get; init; }

        [JsonPropertyName("experiment_id")]
        public Guid ExperimentId { get; init; }

        [JsonPropertyName("package_id")]
        public Guid PackageId { get; init; }

        [JsonPropertyName("node_index")]
        public uint NodeIndex { get; init; }

        [JsonPropertyName("total_nodes")]
        public uint TotalNodes { get; init; }

        [JsonPropertyName("memory_gb")]
        public uint MemoryGb { get; init; }

        [JsonPropertyName("queue_name")]
        public string QueueName { get; init; } = string.Empty;

        [JsonPropertyName("workload")]
        public JsonElement Workload { get; init; }

        [JsonPropertyName("enqueued_at")]
        public DateTimeOffset EnqueuedAt { get; init; }

        [JsonPropertyName("schema_version")]
        public int SchemaVersion { get; init; } = 2;
    }

    public sealed class EnvelopeSerializationException : Exception
    {
        public EnvelopeSerializationException(string message) : base(message) { }
    }

    /// <summary>
    /// Builds scheduler-facing <see cref="QueueEnvelope"/> instances
    /// from routed work packages. This is the boundary between the
    /// routing layer's package representation (which mirrors the
    /// packaging service's schema) and the scheduler's own transport
    /// contract.
    /// </summary>
    public static class QueueEnvelopeFactory
    {
        public static QueueEnvelope FromRoutedPackage(IReadOnlyDictionary<string, object?> package, string queueName)
        {
            if (!package.TryGetValue("organization_id", out var orgIdObj) || orgIdObj is null)
            {
                throw new EnvelopeSerializationException("routed package is missing organization_id");
            }

            if (!package.TryGetValue("experiment_id", out var experimentIdObj) || experimentIdObj is null)
            {
                throw new EnvelopeSerializationException("routed package is missing experiment_id");
            }

            if (!package.TryGetValue("package_id", out var packageIdObj) || packageIdObj is null)
            {
                throw new EnvelopeSerializationException("routed package is missing package_id");
            }

            var workload = package.TryGetValue("workload", out var workloadObj) && workloadObj is JsonElement element
                ? element
                : default;

            return new QueueEnvelope
            {
                EnvelopeId = Guid.NewGuid(),
                OrganizationId = Guid.Parse(orgIdObj.ToString()!),
                ExperimentId = Guid.Parse(experimentIdObj.ToString()!),
                PackageId = Guid.Parse(packageIdObj.ToString()!),
                NodeIndex = Convert.ToUInt32(package.GetValueOrDefault("node_index", 0u)),
                TotalNodes = Convert.ToUInt32(package.GetValueOrDefault("total_nodes", 1u)),
                MemoryGb = Convert.ToUInt32(package.GetValueOrDefault("memory_gb", 0u)),
                QueueName = queueName,
                Workload = workload,
                EnqueuedAt = DateTimeOffset.UtcNow
            };
        }

        public static string Serialize(QueueEnvelope envelope)
        {
            return JsonSerializer.Serialize(envelope, new JsonSerializerOptions
            {
                PropertyNamingPolicy = null,
                WriteIndented = false
            });
        }
    }
}
