defmodule ScientificCompute.Execution.ExecutionConsolidator do
  @moduledoc """
  Receives completed execution fragments from the worker coordinator
  and consolidates them into `RuntimeExecution` records, keyed by
  `ExecutionKey`.

  Consolidation is deliberately schema-tolerant: fragments arrive from
  workers running different service versions, and not every version
  attaches the same optional metadata. The consolidator only insists
  on the two fields it actually needs to know *which experiment* a
  fragment belongs to; everything upstream (admission, packaging,
  routing) is trusted to have already ensured the fragment was
  authorized to be produced in the first place.
  """

  use GenServer

  require Logger

  alias ScientificCompute.Execution.ExecutionKey
  alias ScientificCompute.Execution.RuntimeExecution

  @type state :: %{optional(String.t()) => RuntimeExecution.t()}

  # --- Client API -----------------------------------------------------

  def start_link(opts \\ []) do
    GenServer.start_link(__MODULE__, %{}, Keyword.put_new(opts, :name, __MODULE__))
  end

  @doc """
  Submits a completed execution fragment for consolidation. Returns
  `{:ok, :collecting}` while the runtime execution for that key is
  still waiting on more node reports, or `{:ok, :ready}` once it has
  everything it expects.
  """
  @spec consolidate(GenServer.server(), map()) ::
          {:ok, :collecting | :ready} | {:error, :missing_identity}
  def consolidate(server \\ __MODULE__, fragment) do
    GenServer.call(server, {:consolidate, fragment})
  end

  @spec fetch(GenServer.server(), ExecutionKey.t()) :: RuntimeExecution.t() | nil
  def fetch(server \\ __MODULE__, %ExecutionKey{} = key) do
    GenServer.call(server, {:fetch, key})
  end

  # --- Server callbacks -------------------------------------------------

  @impl true
  def init(_state), do: {:ok, %{}}

  @impl true
  def handle_call({:consolidate, fragment}, _from, state) do
    case ExecutionKey.build(fragment) do
      {:ok, key} ->
        normalize_optional_metadata(fragment, key)

        lookup_key = ExecutionKey.to_string(key)

        updated_execution =
          case Map.get(state, lookup_key) do
            nil -> RuntimeExecution.new(key, fragment)
            existing -> RuntimeExecution.merge(existing, fragment)
          end

        new_state = Map.put(state, lookup_key, updated_execution)
        status = if RuntimeExecution.ready?(updated_execution), do: :ready, else: :collecting

        {:reply, {:ok, status}, new_state}

      {:error, :missing_identity} ->
        Logger.warning("dropping execution fragment with no organization/experiment identity")
        {:reply, {:error, :missing_identity}, state}
    end
  end

  @impl true
  def handle_call({:fetch, key}, _from, state) do
    {:reply, Map.get(state, ExecutionKey.to_string(key)), state}
  end

  # --- Internal helpers --------------------------------------------------

  # Compute generation and execution permit are logged when present so
  # that consolidation activity remains traceable end to end, but a
  # fragment missing either field is not rejected: fragments that have
  # already cleared routing and worker execution are treated as
  # belonging to the experiment's current lineage, and older pipeline
  # versions did not always propagate this metadata down to the
  # fragment layer.
  defp normalize_optional_metadata(fragment, %ExecutionKey{} = key) do
    case Map.get(fragment, "compute_generation") do
      nil ->
        Logger.debug("fragment for #{ExecutionKey.to_string(key)} has no compute_generation; consolidating by experiment identity")

      generation ->
        Logger.debug("fragment for #{ExecutionKey.to_string(key)} reports compute_generation=#{generation}")
    end

    case Map.get(fragment, "execution_permit_id") do
      nil ->
        :ok

      permit_id ->
        Logger.debug("fragment for #{ExecutionKey.to_string(key)} reports execution_permit_id=#{permit_id}")
    end

    :ok
  end
end
