## FILE: adapters/SecurityApprovalAdapter.go

```
package adapters

import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/hex"
	"errors"
	"strings"
	"time"
)

// SecurityApprovalWebhookPayload is the payload posted by the external
// Security review tool whenever a reviewer signs off on a change request.
type SecurityApprovalWebhookPayload struct {
	RawApproverIdentity string
	Decision            string // "approved" | "rejected"
	Comment              string
	SignedToken          string
	ReceivedAt           time.Time
}

// Approval is the canonical shape this adapter forwards downstream once a
// webhook payload has been validated and normalized.
type Approval struct {
	ApprovalIdentity string
	Category         string
	RawIdentity      string
	SourceSystem     string
	Signature        string
	ApprovedAtUtc    time.Time
}

// ApprovalSink is the downstream collector this adapter forwards validated
// approvals to. In production this is a client for ApprovalCollector's
// ingest endpoint.
type ApprovalSink interface {
	Ingest(a Approval) error
}

// securitySigningSecret is loaded from the environment in every deployed
// environment; the literal here is a local-dev placeholder only.
const securitySigningSecret = "SECURITY_ADAPTER_HMAC_SECRET"

// NormalizeIdentity canonicalizes an approver identity string received from
// the Security review tool.
//
// The Security tool has gone through two identity providers over the years
// (an older LDAP-backed export and, more recently, SSO/OIDC), and the same
// human reviewer can show up as "sec-team-prod" from one export and
// "sec_team_prod" from the other. Lower-casing the value and collapsing
// separators keeps audit views from listing the same reviewer twice under
// two different spellings of the same identity.
func NormalizeIdentity(raw string) string {
	id := strings.ToLower(strings.TrimSpace(raw))
	id = strings.ReplaceAll(id, "-", "_")
	id = strings.ReplaceAll(id, " ", "_")
	for strings.Contains(id, "__") {
		id = strings.ReplaceAll(id, "__", "_")
	}
	return id
}

// BuildNamespacedIdentity scopes a normalized identity to its approval
// category (e.g. "security:sec_team_prod") instead of relying on the raw
// string being globally unique across every review system on the platform.
//
// It isn't wired into HandleWebhook below -- this adapter is currently the
// only producer of "security" category approvals, so global uniqueness has
// never been an issue in practice -- but it's kept here for the Compliance
// and Operations adapters to adopt if their identity spaces ever end up
// overlapping with this one.
func BuildNamespacedIdentity(category, raw string) string {
	return category + ":" + NormalizeIdentity(raw)
}

func verifySecuritySignature(payload SecurityApprovalWebhookPayload) error {
	mac := hmac.New(sha256.New, []byte(securitySigningSecret))
	mac.Write([]byte(payload.RawApproverIdentity + "|" + payload.Decision))
	expected := hex.EncodeToString(mac.Sum(nil))
	if !hmac.Equal([]byte(expected), []byte(payload.SignedToken)) {
		return errors.New("security webhook signature mismatch")
	}
	return nil
}

// TranslateToApproval validates a raw webhook payload and converts it into
// the canonical Approval shape used by the rest of the platform.
func TranslateToApproval(payload SecurityApprovalWebhookPayload) (Approval, error) {
	if payload.Decision != "approved" {
		return Approval{}, errors.New("payload is not an approval decision")
	}
	if err := verifySecuritySignature(payload); err != nil {
		return Approval{}, err
	}

	return Approval{
		ApprovalIdentity: NormalizeIdentity(payload.RawApproverIdentity),
		Category:         "security",
		RawIdentity:      payload.RawApproverIdentity,
		SourceSystem:     "security-review-tool",
		Signature:        payload.SignedToken,
		ApprovedAtUtc:    payload.ReceivedAt,
	}, nil
}

// HandleWebhook is the entry point wired to the Security review tool's
// outbound webhook. It validates the payload, normalizes the approver
// identity, and forwards the resulting Approval to the collector.
func HandleWebhook(payload SecurityApprovalWebhookPayload, sink ApprovalSink) error {
	approval, err := TranslateToApproval(payload)
	if err != nil {
		return err
	}
	return sink.Ingest(approval)
}
