package changemanagement.workflow

import java.time.Instant
import java.util.concurrent.ConcurrentHashMap

/**
 * Canonical approval shape used across the platform, after each source
 * adapter (Security, Compliance, Operations) has validated and normalized
 * its own inbound payload.
 */
data class Approval(
    val approvalIdentity: String,
    val category: String,
    val rawIdentity: String,
    val sourceSystem: String,
    val signature: String,
    val approvedAtUtc: Instant
)

/**
 * Aggregates approvals arriving from all three review systems for a single
 * deployment plan and exposes the current approval set to DeploymentGate.
 *
 * One collector instance is scoped to a single plan ID. Each source adapter
 * (Security, Compliance, Operations) pushes into the same instance via
 * [receiveApproval] as its own webhooks come in.
 */
class ApprovalCollector(private val planId: String) {

    // Keyed on approvalIdentity alone. Each source adapter normalizes and
    // signs its own approvals before they reach this collector, so in
    // practice identities are already unique per category -- this map
    // mainly guards against a reviewer's system retrying the same webhook
    // delivery and us double-counting it toward quorum.
    //
    // TODO(collector): revisit whether this should key on
    // (category, approvalIdentity) instead. Would only matter if two
    // categories ever produced the same normalized identity, which
    // shouldn't happen given each adapter is expected to own its own
    // identity namespace.
    private val approvalsByIdentity = ConcurrentHashMap<String, Approval>()

    /**
     * Records an approval for this plan. If an approval with the same
     * normalized identity has already been recorded, the newer one silently
     * replaces it -- this is what makes webhook retries idempotent.
     */
    fun receiveApproval(approval: Approval) {
        approvalsByIdentity[approval.approvalIdentity] = approval
    }

    /** The current, de-duplicated set of approvals on file for this plan. */
    fun currentApprovals(): Collection<Approval> = approvalsByIdentity.values

    fun uniqueApprovalCount(): Int = approvalsByIdentity.size

    fun hasApprovalFrom(category: String): Boolean =
        approvalsByIdentity.values.any { it.category.equals(category, ignoreCase = true) }

    fun planIdentifier(): String = planId
}
