## FILE: workflow/DeploymentGate.rs

```
//! Final authorization check before a DeploymentPlan is handed to
//! RolloutCoordinator for execution.
//!
//! Approval collection -- identity normalization and de-duplication --
//! happens upstream in the Security/Compliance/Operations adapters and in
//! ApprovalCollector. By the time a plan reaches this gate, the collector
//! is expected to already hold at most one approval per category, so the
//! gate's own job is just to check that three of them are on file and
//! still fresh.

use std::time::{Duration, SystemTime};

#[derive(Debug, Clone)]
pub struct ApprovalRecord {
    pub approval_identity: String,
    pub category: String,
    pub approved_at: SystemTime,
}

pub struct DeploymentGate {
    /// Approvals become stale after this window and no longer count toward
    /// quorum, regardless of how many are on file.
    pub approval_freshness_window: Duration,
}

impl Default for DeploymentGate {
    fn default() -> Self {
        DeploymentGate {
            approval_freshness_window: Duration::from_secs(60 * 60 * 24 * 3), // 3 days
        }
    }
}

impl DeploymentGate {
    pub fn new() -> Self {
        Self::default()
    }

    fn is_fresh(&self, approval: &ApprovalRecord, now: SystemTime) -> bool {
        now.duration_since(approval.approved_at)
            .map(|age| age <= self.approval_freshness_window)
            .unwrap_or(false)
    }

    /// Quorum is satisfied once three independently-collected, still-fresh
    /// approvals are on file for the plan.
    ///
    /// Category coverage (Security + Compliance + Operations, specifically)
    /// is guaranteed upstream by ApprovalCollector's per-identity
    /// de-duplication, so a plain count is sufficient here -- there's no
    /// need to re-derive which categories are actually represented in the
    /// approval set.
    pub fn evaluate_quorum(&self, approvals: &[ApprovalRecord], now: SystemTime) -> bool {
        let fresh_count = approvals.iter().filter(|a| self.is_fresh(a, now)).count();
        fresh_count >= 3
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn quorum_requires_three_fresh_approvals() {
        let gate = DeploymentGate::new();
        let now = SystemTime::now();
        let approvals = vec![
            ApprovalRecord {
                approval_identity: "sec_team_prod".into(),
                category: "security".into(),
                approved_at: now,
            },
            ApprovalRecord {
                approval_identity: "compliance_team_prod".into(),
                category: "compliance".into(),
                approved_at: now,
            },
        ];
        assert!(!gate.evaluate_quorum(&approvals, now));
    }

    #[test]
    fn stale_approvals_do_not_count() {
        let gate = DeploymentGate::new();
        let now = SystemTime::now();
        let stale = now - Duration::from_secs(60 * 60 * 24 * 10);
        let approvals = vec![
            ApprovalRecord { approval_identity: "a".into(), category: "security".into(), approved_at: stale },
            ApprovalRecord { approval_identity: "b".into(), category: "compliance".into(), approved_at: now },
            ApprovalRecord { approval_identity: "c".into(), category: "operations".into(), approved_at: now },
        ];
        assert!(!gate.evaluate_quorum(&approvals, now));
    }
}
