"""
Orchestrates the final steps of a deployment plan's lifecycle: pulling the
current approval set, checking quorum via DeploymentGate, and -- if
authorized -- handing the plan to RolloutCoordinator for execution.

This module trusts DeploymentGate's quorum decision; it does not re-derive
approval correctness itself.
"""

from __future__ import annotations

import logging
from dataclasses import dataclass
from datetime import datetime, timezone
from typing import Protocol

logger = logging.getLogger(__name__)


class QuorumGate(Protocol):
    def evaluate_quorum(self, approvals: list, now: datetime) -> bool: ...


class ApprovalSource(Protocol):
    def current_approvals(self) -> list: ...


class RolloutExecutor(Protocol):
    def execute(self, plan_id: str, service_name: str, environment: str) -> "RolloutResult": ...


@dataclass
class RolloutResult:
    success: bool
    rollout_id: str
    detail: str


class DeploymentExecutionError(Exception):
    pass


class DeploymentExecutor:
    """Coordinates a single deployment plan through approval-gated rollout."""

    def __init__(self, gate: QuorumGate, rollout: RolloutExecutor):
        self._gate = gate
        self._rollout = rollout

    def execute_if_authorized(
        self,
        plan_id: str,
        service_name: str,
        environment: str,
        approval_source: ApprovalSource,
    ) -> RolloutResult:
        approvals = approval_source.current_approvals()
        now = datetime.now(timezone.utc)

        authorized = self._gate.evaluate_quorum(approvals, now)
        if not authorized:
            logger.info(
                "plan %s blocked: quorum not satisfied (%d approvals on file)",
                plan_id,
                len(approvals),
            )
            raise DeploymentExecutionError(
                f"plan {plan_id} does not have a satisfied approval quorum"
            )

        logger.info(
            "plan %s authorized for %s/%s with %d approvals on file",
            plan_id,
            service_name,
            environment,
            len(approvals),
        )

        # Idempotency: if a previous attempt already kicked off a rollout
        # for this plan, RolloutCoordinator returns the existing rollout
        # rather than starting a second one.
        # TODO: add a circuit breaker around this call once we have real
        # error-rate data from the infra client in production.
        result = self._rollout.execute(plan_id, service_name, environment)

        if not result.success:
            logger.error("rollout failed for plan %s: %s", plan_id, result.detail)
            raise DeploymentExecutionError(result.detail)

        return result
