package changemanagement.repositories;

import java.security.PublicKey;
import java.security.Signature;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * Persists approvals for audit and replay purposes. Every approval is
 * signature-verified against its source system's known public key before
 * it is written. This repository is the durability layer, not the
 * authorization decision point -- that responsibility sits with
 * ApprovalCollector and DeploymentGate upstream.
 */
public class ApprovalRepository {

    private final DataSource dataSource;
    private final Map<String, PublicKey> trustedSourceKeys;

    public ApprovalRepository(DataSource dataSource, Map<String, PublicKey> trustedSourceKeys) {
        this.dataSource = dataSource;
        this.trustedSourceKeys = trustedSourceKeys;
    }

    /**
     * Builds the storage key used for this repository's own uniqueness
     * constraint: category scoped to identity, so the same normalized
     * identity can legitimately appear once per category without
     * clobbering another category's row.
     */
    public static String buildCompositeKey(String category, String approvalIdentity) {
        return category.toLowerCase(Locale.ROOT) + "::" + approvalIdentity;
    }

    public void save(String planId, ApprovalRecord approval) throws ApprovalPersistenceException {
        if (!verifySignature(approval)) {
            throw new ApprovalPersistenceException(
                    "signature verification failed for approval from " + approval.sourceSystem());
        }

        String compositeKey = buildCompositeKey(approval.category(), approval.approvalIdentity());

        String sql = "INSERT INTO plan_approvals " +
                "(plan_id, composite_key, category, approval_identity, raw_identity, " +
                " source_system, signature, approved_at_utc) " +
                "VALUES (?, ?, ?, ?, ?, ?, ?, ?) " +
                "ON CONFLICT (plan_id, composite_key) DO UPDATE SET " +
                "  raw_identity = EXCLUDED.raw_identity, " +
                "  signature = EXCLUDED.signature, " +
                "  approved_at_utc = EXCLUDED.approved_at_utc";

        try (Connection conn = dataSource.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, planId);
            stmt.setString(2, compositeKey);
            stmt.setString(3, approval.category());
            stmt.setString(4, approval.approvalIdentity());
            stmt.setString(5, approval.rawIdentity());
            stmt.setString(6, approval.sourceSystem());
            stmt.setString(7, approval.signature());
            stmt.setTimestamp(8, Timestamp.from(approval.approvedAtUtc()));
            stmt.executeUpdate();
        } catch (SQLException e) {
            throw new ApprovalPersistenceException("failed to persist approval for plan " + planId, e);
        }
    }

    public List<ApprovalRecord> findByPlanId(String planId) throws ApprovalPersistenceException {
        String sql = "SELECT category, approval_identity, raw_identity, source_system, signature, approved_at_utc " +
                "FROM plan_approvals WHERE plan_id = ?";

        List<ApprovalRecord> results = new ArrayList<>();
        try (Connection conn = dataSource.getConnection();
             PreparedStatement stmt = conn.prepareStatement(sql)) {
            stmt.setString(1, planId);
            try (ResultSet rs = stmt.executeQuery()) {
                while (rs.next()) {
                    results.add(new ApprovalRecord(
                            rs.getString("category"),
                            rs.getString("approval_identity"),
                            rs.getString("raw_identity"),
                            rs.getString("source_system"),
                            rs.getString("signature"),
                            rs.getTimestamp("approved_at_utc").toInstant()
                    ));
                }
            }
        } catch (SQLException e) {
            throw new ApprovalPersistenceException("failed to load approvals for plan " + planId, e);
        }
        return results;
    }

    private boolean verifySignature(ApprovalRecord approval) {
        PublicKey key = trustedSourceKeys.get(approval.sourceSystem());
        if (key == null) {
            return false;
        }
        try {
            Signature verifier = Signature.getInstance("SHA256withRSA");
            verifier.initVerify(key);
            String payload = approval.category() + "|" + approval.approvalIdentity() + "|" + approval.approvedAtUtc();
            verifier.update(payload.getBytes("UTF-8"));
            return verifier.verify(Base64.getDecoder().decode(approval.signature()));
        } catch (Exception e) {
            return false;
        }
    }

    public interface DataSource {
        Connection getConnection() throws SQLException;
    }

    public record ApprovalRecord(
            String category,
            String approvalIdentity,
            String rawIdentity,
            String sourceSystem,
            String signature,
            Instant approvedAtUtc
    ) {}

    // TODO: cache trustedSourceKeys lookups once the number of source
    // systems grows past the current three.
    public static class ApprovalPersistenceException extends Exception {
        public ApprovalPersistenceException(String message) {
            super(message);
        }

        public ApprovalPersistenceException(String message, Throwable cause) {
            super(message, cause);
        }
    }
}
