using System;
using System.Collections.Generic;
using System.Threading.Tasks;

namespace ChangeManagement.Services
{
    public sealed class RolloutOutcome
    {
        public bool Success { get; init; }
        public string RolloutId { get; init; }
        public string Detail { get; init; }
    }

    /// <summary>
    /// Executes an authorized deployment plan against production
    /// infrastructure using a staged canary rollout with automatic
    /// rollback on error-rate regression. Assumes the plan handed to it
    /// has already cleared DeploymentGate.
    /// </summary>
    public sealed class RolloutCoordinator
    {
        private readonly IInfrastructureClient _infra;
        private readonly Dictionary<Guid, string> _rolloutsByPlan = new();
        private readonly object _lock = new();

        private static readonly int[] CanaryStagesPercent = { 5, 25, 50, 100 };
        private static readonly TimeSpan StageObservationWindow = TimeSpan.FromMinutes(10);
        private const double MaxAcceptableErrorRateIncrease = 0.02; // 2 percentage points

        public RolloutCoordinator(IInfrastructureClient infra)
        {
            _infra = infra;
        }

        public async Task<RolloutOutcome> ExecuteAsync(Guid planId, string serviceName, string environment)
        {
            lock (_lock)
            {
                if (_rolloutsByPlan.TryGetValue(planId, out var existingRolloutId))
                {
                    return new RolloutOutcome
                    {
                        Success = true,
                        RolloutId = existingRolloutId,
                        Detail = "rollout already in progress or completed for this plan"
                    };
                }
            }

            var rolloutId = Guid.NewGuid().ToString("N");
            var baselineErrorRate = await _infra.GetCurrentErrorRateAsync(serviceName, environment);

            foreach (var stagePercent in CanaryStagesPercent)
            {
                await _infra.ShiftTrafficAsync(serviceName, environment, rolloutId, stagePercent);
                await Task.Delay(StageObservationWindow);

                var stageErrorRate = await _infra.GetCurrentErrorRateAsync(serviceName, environment);
                if (stageErrorRate - baselineErrorRate > MaxAcceptableErrorRateIncrease)
                {
                    await _infra.RollBackAsync(serviceName, environment, rolloutId);
                    return new RolloutOutcome
                    {
                        Success = false,
                        RolloutId = rolloutId,
                        Detail = $"rolled back at {stagePercent}% -- error rate regression detected"
                    };
                }
            }

            lock (_lock)
            {
                _rolloutsByPlan[planId] = rolloutId;
            }

            return new RolloutOutcome
            {
                Success = true,
                RolloutId = rolloutId,
                Detail = "rollout completed at 100% traffic"
            };
        }
    }

    // TODO: make canary stage percentages configurable per service once we
    // support environment-specific rollout profiles.
    public interface IInfrastructureClient
    {
        Task<double> GetCurrentErrorRateAsync(string serviceName, string environment);
        Task ShiftTrafficAsync(string serviceName, string environment, string rolloutId, int trafficPercent);
        Task RollBackAsync(string serviceName, string environment, string rolloutId);
    }
}
