package services;

import models.Document;
import models.DocumentAcl;
import repositories.DocumentRepository;

import java.time.Instant;
import java.util.HashSet;
import java.util.Set;

public class DocumentAclManager {

    private final DocumentRepository
            documentRepository;

    private final DocumentAuditService
            auditService;

    public DocumentAclManager(
            DocumentRepository documentRepository,
            DocumentAuditService auditService
    ) {
        this.documentRepository =
                documentRepository;

        this.auditService =
                auditService;
    }

    public void updateAcl(
            String documentId,
            Set<String> allowedGroups,
            String modifiedBy
    ) {

        Document document =
                documentRepository.findById(
                        documentId
                );

        if (document == null) {
            throw new IllegalArgumentException(
                    "Document not found."
            );
        }

        validateAcl(
                allowedGroups
        );

        DocumentAcl newAcl =
                new DocumentAcl(
                        new HashSet<>(
                                allowedGroups
                        ),
                        modifiedBy,
                        Instant.now()
                );

        document.setAcl(
                newAcl
        );

        documentRepository.save(
                document
        );

        auditService.recordAclChange(
                documentId,
                modifiedBy,
                allowedGroups
        );
    }

    public boolean userCanAccess(
            Document document,
            Set<String> userGroups
    ) {

        if (
                document == null
        ) {
            return false;
        }

        DocumentAcl acl =
                document.getAcl();

        if (
                acl == null
        ) {
            return false;
        }

        for (
                String group :
                userGroups
        ) {

            if (
                    acl
                    .getAllowedGroups()
                    .contains(group)
            ) {
                return true;
            }
        }

        return false;
    }

    private void validateAcl(
            Set<String> groups
    ) {

        if (
                groups == null
        ) {
            throw new IllegalArgumentException(
                    "ACL required."
            );
        }

        if (
                groups.isEmpty()
        ) {
            throw new IllegalArgumentException(
                    "At least one group required."
            );
        }

        for (
                String group :
                groups
        ) {

            if (
                    group == null ||
                    group.isBlank()
            ) {
                throw new IllegalArgumentException(
                        "Invalid group."
                );
            }
        }
    }
}
