    public void replaceContent(
            String documentId,
            String content
    ) {

        Document document =
                findById(
                        documentId
                );

        if (
                document == null
        ) {
            throw new IllegalArgumentException(
                    "Document not found."
            );
        }

        document.setContent(
                content
        );

        save(
                document
        );
    }
}
