```
package services

import (
	"enterprise-search/models"
	"time"
)

/*
   Search authorization is evaluated against the indexed
   document representation. Metadata copied here must remain
   consistent with the primary document record.
*/

type IndexMetadataBuilder struct{}

func (b *IndexMetadataBuilder) Build(
	document *models.Document,
) *models.SearchDocument {

	acl := make(
		[]string,
		len(document.Acl.AllowedGroups),
	)

	copy(
		acl,
		document.Acl.AllowedGroups,
	)

	tags := make(
		[]string,
		len(document.Tags),
	)

	copy(
		tags,
		document.Tags,
	)

	return models.NewSearchDocument(
		document.DocumentID,
		document.Title,
		document.Content,
		tags,
		acl,
		document.Version,
	)
}

func (b *IndexMetadataBuilder) BuildTimestamp() time.Time {
	return time.Now().UTC()
}
