package models

import "time"

type SearchDocument struct {
	DocumentID string

	Title string

	Content string

	Tags []string

	IndexedAcl []string

	LastIndexed time.Time

	Version int64
}

func NewSearchDocument(
	documentID string,
	title string,
	content string,
	tags []string,
	indexedAcl []string,
	version int64,
) *SearchDocument {

	return &SearchDocument{
		DocumentID: documentID,
		Title: title,
		Content: content,
		Tags: tags,
		IndexedAcl: indexedAcl,
		LastIndexed: time.Now().UTC(),
		Version: version,
	}
}

func (d *SearchDocument) CanAccess(
	userGroups []string,
) bool {

	for _, group := range userGroups {

		for _, allowed := range d.IndexedAcl {

			if group == allowed {
				return true
			}
		}
	}

	return false
}

func (d *SearchDocument) UpdateIndexTime() {
	d.LastIndexed = time.Now().UTC()
}
