package repositories

import (
	"enterprise-search/models"
)

type SearchIndexRepository struct {
	index map[string]*models.SearchDocument
}

func NewSearchIndexRepository() *SearchIndexRepository {

	return &SearchIndexRepository{
		index: make(
			map[string]*models.SearchDocument,
		),
	}
}

func (r *SearchIndexRepository) Save(
	document *models.SearchDocument,
) {

	r.index[
		document.DocumentID
	] = document
}

func (r *SearchIndexRepository) Find(
	documentID string,
) *models.SearchDocument {

	return r.index[
		documentID
	]
}

func (r *SearchIndexRepository) Exists(
	documentID string,
) bool {

	_, ok := r.index[
		documentID
	]

	return ok
}

func (r *SearchIndexRepository) Delete(
	documentID string,
) {

	delete(
		r.index,
		documentID,
	)
}

func (r *SearchIndexRepository) All() []*models.SearchDocument {

	result := make(
		[]*models.SearchDocument,
		0,
		len(r.index),
	)

	for _, document := range r.index {

		result = append(
			result,
			document,
		)
	}

	return result
}
