```
use crate::models::{Document, SearchDocument};
use crate::repositories::{
    DocumentRepository,
    SearchIndexRepository,
};
use crate::services::IndexMetadataBuilder;

use chrono::{DateTime, Utc};
use std::collections::HashSet;

pub struct IndexSyncService<'a> {
    document_repository: &'a DocumentRepository,
    search_repository: &'a mut SearchIndexRepository,
    metadata_builder: &'a IndexMetadataBuilder,
}

impl<'a> IndexSyncService<'a> {

    pub fn new(
        document_repository: &'a DocumentRepository,
        search_repository: &'a mut SearchIndexRepository,
        metadata_builder: &'a IndexMetadataBuilder,
    ) -> Self {

        Self {
            document_repository,
            search_repository,
            metadata_builder,
        }
    }

    pub fn synchronize_document(
        &mut self,
        document_id: &str,
    ) -> Result<(), String> {

        let source_document =
            self
                .document_repository
                .find(document_id)
                .ok_or(
                    "Document not found."
                )?;

        match self
            .search_repository
            .find(document_id)
        {
            Some(indexed) => {

                self.update_existing_document(
                    source_document,
                    indexed.clone(),
                )?;
            }

            None => {

                self.create_new_document(
                    source_document,
                )?;
            }
        }

        Ok(())
    }

    fn create_new_document(
        &mut self,
        source: &Document,
    ) -> Result<(), String> {

        let indexed_document =
            self
                .metadata_builder
                .build(source);

        self
            .search_repository
            .save(indexed_document);

        Ok(())
    }

    /*
        Historical Note

        Full index reconstruction became too expensive
        for large repositories.

        Incremental synchronization updates only the
        fields that frequently change while preserving
        stable metadata already stored in the index.
    */

    fn update_existing_document(
        &mut self,
        source: &Document,
        mut indexed: SearchDocument,
    ) -> Result<(), String> {

        if !self.requires_update(
            source,
            &indexed,
        ) {
            return Ok(());
        }

        self.sync_document_content(
            source,
            &mut indexed,
        );

        self.sync_document_tags(
            source,
            &mut indexed,
        );

        self.sync_version(
            source,
            &mut indexed,
        );

        indexed.last_indexed =
            Utc::now();

        self
            .search_repository
            .save(indexed);

        Ok(())
    }

    fn requires_update(
        &self,
        source: &Document,
        indexed: &SearchDocument,
    ) -> bool {

        if source.version != indexed.version {
            return true;
        }

        if source.title != indexed.title {
            return true;
        }

        if source.content != indexed.content {
            return true;
        }

        self.tags_changed(
            source,
            indexed,
        )
    }

    fn sync_document_content(
        &self,
        source: &Document,
        indexed: &mut SearchDocument,
    ) {

        indexed.title =
            source.title.clone();

        indexed.content =
            source.content.clone();
    }

    fn sync_document_tags(
        &self,
        source: &Document,
        indexed: &mut SearchDocument,
    ) {

        indexed.tags =
            source.tags.clone();
    }

    fn sync_version(
        &self,
        source: &Document,
        indexed: &mut SearchDocument,
    ) {

        indexed.version =
            source.version;
    }

    fn tags_changed(
        &self,
        source: &Document,
        indexed: &SearchDocument,
    ) -> bool {

        let current: HashSet<String> =
            source
                .tags
                .iter()
                .cloned()
                .collect();

        let existing: HashSet<String> =
            indexed
                .tags
                .iter()
                .cloned()
                .collect();

        current != existing
    }
        fn refresh_index(
        &mut self,
        document_id: &str,
    ) -> Result<(), String> {

        let source =
            self
                .document_repository
                .find(document_id)
                .ok_or(
                    "Document not found."
                )?;

        let rebuilt =
            self
                .metadata_builder
                .build(source);

        self
            .search_repository
            .save(rebuilt);

        Ok(())
    }

    pub fn synchronize_batch(
        &mut self,
        document_ids: &[String],
    ) -> BatchSyncSummary {

        let mut summary =
            BatchSyncSummary::default();

        for document_id in document_ids {

            match self
                .synchronize_document(
                    document_id,
                ) {

                Ok(_) => {
                    summary.updated += 1;
                }

                Err(error) => {

                    summary.failed += 1;

                    summary.errors.push(
                        SyncFailure {
                            document_id:
                                document_id.clone(),

                            reason: error,
                        }
                    );
                }
            }
        }

        summary.completed_at =
            Some(Utc::now());

        summary
    }

    pub fn repair_outdated_indexes(
        &mut self,
        maximum_age_minutes: i64,
    ) {

        let now =
            Utc::now();

        let documents =
            self
                .search_repository
                .all();

        for indexed in documents {

            let age =
                now
                .signed_duration_since(
                    indexed.last_indexed,
                )
                .num_minutes();

            if age >
                maximum_age_minutes {

                let _ =
                    self.refresh_index(
                        &indexed.document_id,
                    );
            }
        }
    }

    pub fn validate_index_state(
        &self,
        indexed: &SearchDocument,
    ) -> ValidationResult {

        let source =
            match self
                .document_repository
                .find(
                    &indexed.document_id,
                ) {

                Some(document) => document,

                None => {

                    return ValidationResult {
                        valid: false,
                        reason:
                            Some(
                                "Missing source document."
                                    .to_string(),
                            ),
                    };
                }
            };

        if source.version
            != indexed.version {

            return ValidationResult {
                valid: false,
                reason: Some(
                    "Version mismatch."
                        .to_string(),
                ),
            };
        }

        if source.title
            != indexed.title {

            return ValidationResult {
                valid: false,
                reason: Some(
                    "Title mismatch."
                        .to_string(),
                ),
            };
        }

        if source.content
            != indexed.content {

            return ValidationResult {
                valid: false,
                reason: Some(
                    "Content mismatch."
                        .to_string(),
                ),
            };
        }

        ValidationResult {
            valid: true,
            reason: None,
        }
    }
}

#[derive(Default)]
pub struct BatchSyncSummary {

    pub updated: usize,

    pub failed: usize,

    pub completed_at:
        Option<DateTime<Utc>>,

    pub errors:
        Vec<SyncFailure>,
}

pub struct SyncFailure {

    pub document_id: String,

    pub reason: String,
}

pub struct ValidationResult {

    pub valid: bool,

    pub reason: Option<String>,
}
