using System;
using System.Collections.Generic;
using System.Linq;
using Models;
using Repositories;

namespace Services
{
    public class SearchAuthorizationService
    {
        private readonly SearchIndexRepository
            _searchIndexRepository;

        private readonly UserRepository
            _userRepository;

        private readonly DocumentAuditService
            _auditService;

        public SearchAuthorizationService(
            SearchIndexRepository searchIndexRepository,
            UserRepository userRepository,
            DocumentAuditService auditService
        )
        {
            _searchIndexRepository =
                searchIndexRepository;

            _userRepository =
                userRepository;

            _auditService =
                auditService;
        }

        public IList<SearchResult> Search(
            string userId,
            string query,
            int limit = 20
        )
        {
            ValidateRequest(
                userId,
                query,
                limit
            );

            var principal =
                ResolvePrincipal(
                    userId
                );

            var indexedDocuments =
                _searchIndexRepository
                    .Search(query);

            var authorizedResults =
                new List<SearchResult>();

            foreach (
                var indexedDocument
                in indexedDocuments
            )
            {
                if (
                    !CanViewDocument(
                        principal,
                        indexedDocument
                    )
                )
                {
                    RecordDeniedAccess(
                        principal,
                        indexedDocument
                    );

                    continue;
                }

                if (
                    !MatchesVisibilityPolicy(
                        principal,
                        indexedDocument
                    )
                )
                {
                    continue;
                }

                if (
                    !EligibleForRanking(
                        indexedDocument
                    )
                )
                {
                    continue;
                }

                authorizedResults.Add(
                    BuildSearchResult(
                        indexedDocument
                    )
                );

                if (
                    authorizedResults.Count >=
                    limit
                )
                {
                    break;
                }
            }

            RecordSuccessfulSearch(
                principal,
                query,
                authorizedResults.Count
            );

            return authorizedResults;
        }

        private UserPrincipal
        ResolvePrincipal(
            string userId
        )
        {
            var principal =
                _userRepository
                    .FindPrincipal(
                        userId
                    );

            if (
                principal == null
            )
            {
                throw new InvalidOperationException(
                    "Unknown user."
                );
            }

            return principal;
        }

        private void ValidateRequest(
            string userId,
            string query,
            int limit
        )
        {
            if (
                string.IsNullOrWhiteSpace(
                    userId
                )
            )
            {
                throw new ArgumentException(
                    "User required."
                );
            }

            if (
                string.IsNullOrWhiteSpace(
                    query
                )
            )
            {
                throw new ArgumentException(
                    "Search query required."
                );
            }

            if (
                limit <= 0
            )
            {
                throw new ArgumentException(
                    "Invalid result limit."
                );
            }

            if (
                limit > 100
            )
            {
                throw new ArgumentException(
                    "Result limit exceeded."
                );
            }
        }

        private bool CanViewDocument(
            UserPrincipal principal,
            SearchDocument indexedDocument
        )
        {
            foreach (
                var group
                in principal.Groups
            )
            {
                if (
                    indexedDocument
                        .IndexedAcl
                        .Contains(group)
                )
                {
                    return true;
                }
            }

            return false;
        }

        private bool MatchesVisibilityPolicy(
            UserPrincipal principal,
            SearchDocument indexedDocument
        )
        {
            if (
                indexedDocument.IsArchived
            )
            {
                return principal
                    .CanViewArchived;
            }

            if (
                indexedDocument.IsDeleted
            )
            {
                return false;
            }

            return true;
        }
                private bool EligibleForRanking(
            SearchDocument indexedDocument
        )
        {
            if (
                indexedDocument == null
            )
            {
                return false;
            }

            if (
                indexedDocument.IsDeleted
            )
            {
                return false;
            }

            if (
                indexedDocument.SearchScore <= 0
            )
            {
                return false;
            }

            return true;
        }

        private SearchResult
        BuildSearchResult(
            SearchDocument indexedDocument
        )
        {
            return new SearchResult
            {
                DocumentId =
                    indexedDocument.DocumentId,

                Title =
                    indexedDocument.Title,

                Snippet =
                    BuildSnippet(
                        indexedDocument.Content
                    ),

                Score =
                    indexedDocument.SearchScore,

                LastModified =
                    indexedDocument.LastIndexed
            };
        }

        private string
        BuildSnippet(
            string content
        )
        {
            if (
                String.IsNullOrWhiteSpace(
                    content
                )
            )
            {
                return String.Empty;
            }

            const int MaxLength = 180;

            if (
                content.Length <=
                MaxLength
            )
            {
                return content;
            }

            return content.Substring(
                0,
                MaxLength
            ) + "...";
        }

        private void
        RecordDeniedAccess(
            UserPrincipal principal,
            SearchDocument indexedDocument
        )
        {
            _auditService
                .RecordSecurityEvent(
                    new AuditEvent
                    {
                        UserId =
                            principal.UserId,

                        DocumentId =
                            indexedDocument.DocumentId,

                        EventType =
                            "SEARCH_ACCESS_DENIED",

                        Timestamp =
                            DateTime.UtcNow
                    }
                );
        }

        private void
        RecordSuccessfulSearch(
            UserPrincipal principal,
            string query,
            int resultCount
        )
        {
            _auditService
                .RecordSearchEvent(
                    new SearchAuditEvent
                    {
                        UserId =
                            principal.UserId,

                        Query =
                            query,

                        ResultCount =
                            resultCount,

                        Timestamp =
                            DateTime.UtcNow
                    }
                );
        }

        private bool
        HasMatchingGroup(
            UserPrincipal principal,
            IEnumerable<string> allowedGroups
        )
        {
            var principalGroups =
                new HashSet<string>(
                    principal.Groups
                );

            foreach (
                var group
                in allowedGroups
            )
            {
                if (
                    principalGroups.Contains(
                        group
                    )
                )
                {
                    return true;
                }
            }

            return false;
        }

        private bool
        IsDocumentVisible(
            SearchDocument indexedDocument
        )
        {
            if (
                indexedDocument.IsDeleted
            )
            {
                return false;
            }

            if (
                indexedDocument.Visibility ==
                DocumentVisibility.Hidden
            )
            {
                return false;
            }

            return true;
        }

        private bool
        CanAccessIndexedDocument(
            UserPrincipal principal,
            SearchDocument indexedDocument
        )
        {
            if (
                !IsDocumentVisible(
                    indexedDocument
                )
            )
            {
                return false;
            }

            if (
                !HasMatchingGroup(
                    principal,
                    indexedDocument.IndexedAcl
                )
            )
            {
                return false;
            }

            return true;
        }
                private IEnumerable<SearchDocument>
        ApplyResultOrdering(
            IEnumerable<SearchDocument> documents
        )
        {
            return documents
                .OrderByDescending(
                    d => d.SearchScore
                )
                .ThenByDescending(
                    d => d.LastIndexed
                )
                .ThenBy(
                    d => d.Title
                );
        }

        private IEnumerable<SearchDocument>
        ApplyResultLimit(
            IEnumerable<SearchDocument> documents,
            int limit
        )
        {
            return documents
                .Take(limit);
        }

        private IEnumerable<SearchDocument>
        FilterAuthorizedDocuments(
            UserPrincipal principal,
            IEnumerable<SearchDocument> candidates
        )
        {
            foreach (
                var document
                in candidates
            )
            {
                if (
                    CanAccessIndexedDocument(
                        principal,
                        document
                    )
                )
                {
                    yield return document;
                }
                else
                {
                    RecordDeniedAccess(
                        principal,
                        document
                    );
                }
            }
        }

        private SearchResult
        ToSearchResult(
            SearchDocument indexedDocument
        )
        {
            return new SearchResult
            {
                DocumentId =
                    indexedDocument.DocumentId,

                Title =
                    indexedDocument.Title,

                Snippet =
                    BuildSnippet(
                        indexedDocument.Content
                    ),

                Score =
                    indexedDocument.SearchScore,

                LastModified =
                    indexedDocument.LastIndexed
            };
        }

        public SearchResult
        GetDocument(
            string userId,
            string documentId
        )
        {
            var principal =
                ResolvePrincipal(
                    userId
                );

            var indexedDocument =
                _searchIndexRepository
                    .Find(
                        documentId
                    );

            if (
                indexedDocument == null
            )
            {
                throw new InvalidOperationException(
                    "Document not found."
                );
            }

            if (
                !CanAccessIndexedDocument(
                    principal,
                    indexedDocument
                )
            )
            {
                RecordDeniedAccess(
                    principal,
                    indexedDocument
                );

                throw new UnauthorizedAccessException(
                    "Access denied."
                );
            }

            return ToSearchResult(
                indexedDocument
            );
        }

        public bool
        CanAccess(
            string userId,
            string documentId
        )
        {
            var principal =
                ResolvePrincipal(
                    userId
                );

            var indexedDocument =
                _searchIndexRepository
                    .Find(
                        documentId
                    );

            if (
                indexedDocument == null
            )
            {
                return false;
            }

            return CanAccessIndexedDocument(
                principal,
                indexedDocument
            );
        }

        public IReadOnlyCollection<SearchResult>
        FilterAccessibleDocuments(
            string userId,
            IEnumerable<SearchDocument> candidates
        )
        {
            var principal =
                ResolvePrincipal(
                    userId
                );

            return ApplyResultOrdering(
                    FilterAuthorizedDocuments(
                        principal,
                        candidates
                    )
                )
                .Select(
                    ToSearchResult
                )
                .ToList()
                .AsReadOnly();
        }
    }
}
