## FILE: security/QueryIntegrityValidator.py

```
import re


class QueryIntegrityValidator:

    MAX_QUERY_LENGTH = 512

    MAX_TERMS = 25

    VALID_PATTERN = re.compile(
        r"^[A-Za-z0-9_\-\s:\".]+$"
    )

    def validate(
        self,
        query: str
    ) -> str:

        if query is None:
            raise ValueError(
                "Query is required."
            )

        normalized = self._normalize(
            query
        )

        self._validate_length(
            normalized
        )

        self._validate_characters(
            normalized
        )

        self._validate_term_count(
            normalized
        )

        return normalized

    def _normalize(
        self,
        query: str
    ) -> str:

        return " ".join(
            query.strip().split()
        )

    def _validate_length(
        self,
        query: str
    ):

        if len(query) == 0:
            raise ValueError(
                "Empty query."
            )

        if len(query) > self.MAX_QUERY_LENGTH:
            raise ValueError(
                "Query too long."
            )

    def _validate_characters(
        self,
        query: str
    ):

        if not self.VALID_PATTERN.fullmatch(
            query
        ):
            raise ValueError(
                "Unsupported characters."
            )

    def _validate_term_count(
        self,
        query: str
    ):

        terms = query.split()

        if len(terms) > self.MAX_TERMS:
            raise ValueError(
                "Too many search terms."
            )

    def tokenize(
        self,
        query: str
    ):

        return [
            token.lower()
            for token in query.split()
        ]
