using System;
using System.Collections.Generic;
using System.Linq;

namespace Repositories
{
    public class AuditRepository
    {
        private readonly List<AuditRecord>
            _records =
                new();

        public void Save(
            AuditRecord record
        )
        {
            _records.Add(record);
        }

        public IReadOnlyCollection<AuditRecord>
        FindByDocument(
            string documentId
        )
        {
            return _records
                .Where(
                    r => r.DocumentId ==
                         documentId
                )
                .OrderByDescending(
                    r => r.Timestamp
                )
                .ToList();
        }

        public IReadOnlyCollection<AuditRecord>
        FindByUser(
            string userId
        )
        {
            return _records
                .Where(
                    r => r.UserId ==
                         userId
                )
                .OrderByDescending(
                    r => r.Timestamp
                )
                .ToList();
        }

        public IReadOnlyCollection<AuditRecord>
        Recent(
            DateTime since
        )
        {
            return _records
                .Where(
                    r => r.Timestamp >=
                         since
                )
                .OrderByDescending(
                    r => r.Timestamp
                )
                .ToList();
        }
    }

    public class AuditRecord
    {
        public string UserId
        {
            get;
            set;
        }

        public string DocumentId
        {
            get;
            set;
        }

        public string Action
        {
            get;
            set;
        }

        public DateTime Timestamp
        {
            get;
            set;
        }

        public string Details
        {
            get;
            set;
        }
    }
