import { SearchQueryService } from "../services/SearchQueryService";
import { SearchAuthorizationService } from "../services/SearchAuthorizationService";
import { QueryIntegrityValidator } from "../security/QueryIntegrityValidator";

export class SearchController {

    constructor(
        private readonly validator: QueryIntegrityValidator,
        private readonly queryService: SearchQueryService,
        private readonly authorizationService: SearchAuthorizationService
    ) {}

    public search(
        request: SearchRequest
    ): SearchResponse {

        const normalizedQuery =
            this.validator.validate(
                request.query
            );

        const candidates =
            this.queryService.executeQuery(
                normalizedQuery,
                request.limit
            );

        const results =
            this.authorizationService
                .FilterAccessibleDocuments(
                    request.userId,
                    candidates
                );

        return {
            query: normalizedQuery,
            totalResults: results.length,
            results: results
        };
    }

    public document(
        request: DocumentRequest
    ) {

        return this.authorizationService
            .GetDocument(
                request.userId,
                request.documentId
            );
    }
