using Microsoft.AspNetCore.Mvc;
using DocumentPlatform.Security;
using DocumentPlatform.Services;

namespace DocumentPlatform.Controllers;

[ApiController]
[Route("api/documents")]
public class UploadController : ControllerBase
{
    private readonly DocumentService _documentService;

    private readonly TenantContext _tenantContext;

    public UploadController(
        DocumentService documentService,
        TenantContext tenantContext
    )
    {
        _documentService = documentService;
        _tenantContext = tenantContext;
    }

    [HttpPost("upload")]
    public async Task<IActionResult> Upload(
        IFormFile file
    )
    {
        if (file == null)
        {
            return BadRequest(
                new
                {
                    error = "File required"
                }
            );
        }

        var tenantId =
            _tenantContext.GetTenantId();

        using var stream =
            file.OpenReadStream();

        var documentId =
            await _documentService
                .CreateDocumentAsync(
                    tenantId,
                    file.FileName,
                    stream
                );

        return Ok(
            new
            {
                documentId,
                tenantId
            }
        );
    }

    [HttpGet("{documentId}")]
    public async Task<IActionResult> GetDocument(
        string documentId
    )
    {
        var tenantId =
            _tenantContext.GetTenantId();

        var document =
            await _documentService
                .GetDocumentAsync(
                    tenantId,
                    documentId
                );

        if (document == null)
        {
            return NotFound();
        }

        return Ok(document);
    }
}
