using DocumentPlatform.Messaging;
using DocumentPlatform.Models;
using DocumentPlatform.Repositories;

namespace DocumentPlatform.Services;

public class DocumentService
{
    private readonly DocumentRepository
        _documentRepository;

    private readonly KafkaProducer
        _producer;

    public DocumentService(
        DocumentRepository documentRepository,
        KafkaProducer producer
    )
    {
        _documentRepository =
            documentRepository;

        _producer = producer;
    }

    public async Task<string>
        CreateDocumentAsync(

        string tenantId,

        string fileName,

        Stream content
    )
    {
        var document =
            new Document
            {
                Id =
                    Guid.NewGuid()
                        .ToString(),

                TenantId =
                    tenantId,

                FileName =
                    fileName,

                UploadedAt =
                    DateTime.UtcNow
            };

        await _documentRepository
            .SaveAsync(document);

        await _producer.PublishAsync(

            "document-uploaded",

            new
            {
                documentId =
                    document.Id,

                tenantId =
                    tenantId
            }
        );

        return document.Id;
    }

    public async Task<Document?>
        GetDocumentAsync(

        string tenantId,

        string documentId
    )
    {
        var document =
            await _documentRepository
                .FindByIdAsync(
                    documentId
                );

        if (document == null)
        {
            return null;
        }

        if (
            document.TenantId !=
            tenantId
        )
        {
            return null;
        }

        return document;
    }
}
