## FILE: embedding-service/EmbeddingWorker.py

```
import logging

from repositories.VectorRepository import (
    VectorRepository
)

from embedding.VectorIndexer import (
    VectorIndexer
)

logger = logging.getLogger(__name__)


class EmbeddingWorker:

    def __init__(
        self,
        kafka_consumer,
        document_repository,
        vector_indexer: VectorIndexer
    ):

        self.kafka_consumer = \
            kafka_consumer

        self.document_repository = \
            document_repository

        self.vector_indexer = \
            vector_indexer

    def start(self):

        logger.info(
            "Embedding worker started"
        )

        while True:

            event = \
                self.kafka_consumer.poll(
                    "document-uploaded"
                )

            if event is None:
                continue

            self.process_event(
                event
            )

    def process_event(
        self,
        event
    ):

        document_id = \
            event["documentId"]

        tenant_id = \
            event["tenantId"]

        document = \
            self.document_repository \
                .find_by_id(
                    document_id
                )

        if document is None:

            logger.warning(
                "Document not found %s",
                document_id
            )

            return

        logger.info(

            "Generating embeddings for %s belonging to tenant %s",

            document_id,

            tenant_id
        )

        self.vector_indexer.index_document(

            document=document,

            tenant_id=tenant_id
        )
