## FILE: embedding-service/VectorIndexer.py

```
import uuid

from repositories.VectorRepository import (
    VectorRepository
)

from models.VectorRecord import (
    VectorRecord
)


class VectorIndexer:

    def __init__(
        self,
        embedding_model,
        vector_repository:
            VectorRepository
    ):

        self.embedding_model = \
            embedding_model

        self.vector_repository = \
            vector_repository

    def index_document(

        self,

        document,

        tenant_id: str

    ):

        chunks = \
            self.chunk_document(
                document.content
            )

        for chunk in chunks:

            embedding = \
                self.embedding_model \
                    .embed(
                        chunk
                    )

            # TODO: include tenant_id in metadata so retrieval
            # can enforce tenant-scoped filtering at query time
            vector = \
                VectorRecord(

                    id=str(
                        uuid.uuid4()
                    ),

                    document_id=
                        document.id,

                    embedding=
                        embedding,

                    metadata={

                        "documentId":
                            document.id,

                        "fileName":
                            document.file_name

                    }
                )

            self.vector_repository.save(
                vector
            )

    def chunk_document(
        self,
        content: str
    ):

        return [

            content[i:i + 500]

            for i in range(
                0,
                len(content),
                500
            )
        ]
