## FILE: repositories/VectorRepository.py

```
from typing import List

from models.VectorRecord import (
    VectorRecord
)


class VectorRepository:

    def __init__(self):

        self._vectors = []

    def save(
        self,
        vector: VectorRecord
    ):

        self._vectors.append(
            vector
        )

    def similarity_search(

        self,

        embedding,

        limit: int = 10

    ) -> List[VectorRecord]:

        results = []

        for vector in self._vectors:

            score = self.cosine_similarity(

                embedding,

                vector.embedding
            )

            results.append(
                (
                    score,
                    vector
                )
            )

        results.sort(
            key=lambda x: x[0],
            reverse=True
        )

        return [

            vector

            for _, vector in

            results[:limit]
        ]

    def cosine_similarity(

        self,

        a,

        b

    ):

        dot = sum(

            x * y

            for x, y in

            zip(a, b)
        )

        norm_a = sum(
            x * x
            for x in a
        ) ** 0.5

        norm_b = sum(
            y * y
            for y in b
        ) ** 0.5

        if norm_a == 0 or \
           norm_b == 0:

            return 0

        return dot / (
            norm_a * norm_b
        )
