package retrieval

import (
	"net/http"

	"ai-platform/security"

	"github.com/gin-gonic/gin"
)

type RetrievalController struct {

	retrievalService
		*RetrievalService
}

func NewRetrievalController(

	retrievalService
		*RetrievalService,

) *RetrievalController {

	return &RetrievalController{

		retrievalService:
			retrievalService,
	}
}

type SearchRequest struct {

	Query string `json:"query"`
}

func (c *RetrievalController) Search(

	ctx *gin.Context,

) {

	var request SearchRequest

	if err := ctx.ShouldBindJSON(
		&request,
	); err != nil {

		ctx.JSON(

			http.StatusBadRequest,

			gin.H{
				"error":
					"invalid request",
			},
		)

		return
	}

	tenantContext :=

		ctx.MustGet(
			"tenantContext",
		).(
			*security.TenantContext,
		)

	queryEmbedding :=

		GenerateEmbedding(
			request.Query,
		)

	results :=

		c.retrievalService.
			Retrieve(

				tenantContext.
					GetTenantId(),

				queryEmbedding,
			)

	ctx.JSON(

		http.StatusOK,

		gin.H{

			"results":
				results,

			"tenant":
				tenantContext.
					GetTenantId(),
		},
	)
}

func (c *RetrievalController) Health(

	ctx *gin.Context,

) {

	ctx.JSON(

		http.StatusOK,

		gin.H{

			"status":
				"healthy",
		},
	)
}
