package retrieval

import (
	"ai-platform/repositories"
)

type RetrievalService struct {

	vectorRepository
		*repositories.VectorRepository
}

func NewRetrievalService(

	vectorRepository
		*repositories.VectorRepository,

) *RetrievalService {

	return &RetrievalService{

		vectorRepository:
			vectorRepository,
	}
}

func (s *RetrievalService) Retrieve(

	tenantID string,

	queryEmbedding []float64,

) []SearchResult {

	vectors :=

		s.vectorRepository.
			SimilaritySearch(

				queryEmbedding,

				20,
			)

	results :=

		make(
			[]SearchResult,
			0,
		)

	// TODO: add tenant-scoped filtering before returning results
	// vector.Metadata["tenantId"] should be compared against tenantID here
	for _, vector := range vectors {

		results = append(

			results,

			SearchResult{

				DocumentID:

					vector.Metadata[
						"documentId"
					],

				FileName:

					vector.Metadata[
						"fileName"
					],
			},
		)
	}

	return results
}
