## FILE: retrieval-service/ContextAssembler.go

```
package retrieval

import (
	"fmt"
	"strings"

	"ai-platform/repositories"
)

type ContextAssembler struct {
	documentRepository *repositories.DocumentRepository
}

type ContextChunk struct {
	DocumentID string
	FileName   string
	Content    string
}

func NewContextAssembler(
	documentRepository *repositories.DocumentRepository,
) *ContextAssembler {

	return &ContextAssembler{
		documentRepository: documentRepository,
	}
}

func (c *ContextAssembler) BuildContext(

	results []SearchResult,

	maxDocuments int,

) string {

	var builder strings.Builder

	documentCount := 0

	for _, result := range results {

		if documentCount >= maxDocuments {
			break
		}

		document :=

			c.documentRepository.
				FindByID(
					result.DocumentID,
				)

		if document == nil {
			continue
		}

		builder.WriteString(
			fmt.Sprintf(
				"\n[Document: %s]\n",
				document.FileName,
			),
		)

		builder.WriteString(
			document.Content,
		)

		builder.WriteString(
			"\n------------------\n",
		)

		documentCount++
	}

	return builder.String()
}

func (c *ContextAssembler) BuildChunks(

	results []SearchResult,

) []ContextChunk {

	chunks := make(
		[]ContextChunk,
		0,
	)

	for _, result := range results {

		document :=

			c.documentRepository.
				FindByID(
					result.DocumentID,
				)

		if document == nil {
			continue
		}

		chunks = append(

			chunks,

			ContextChunk{

				DocumentID:
					document.ID,

				FileName:
					document.FileName,

				Content:
					document.Content,
			},
		)
	}

	return chunks
}

func (c *ContextAssembler) CountDocuments(

	results []SearchResult,

) int {

	return len(results)
}
