using System.Collections.Concurrent;
using AiPlatform.Models;

namespace AiPlatform.Repositories;

public class DocumentRepository
{
    private readonly ConcurrentDictionary<
        string,
        Document
    > _documents =
        new();

    public async Task SaveAsync(
        Document document
    )
    {
        _documents[
            document.Id
        ] = document;

        await Task.CompletedTask;
    }

    public async Task<Document?>
        FindByIdAsync(
            string documentId
        )
    {
        _documents.TryGetValue(

            documentId,

            out var document
        );

        return await Task.FromResult(
            document
        );
    }

    public Document? FindByID(
        string documentId
    )
    {
        _documents.TryGetValue(

            documentId,

            out var document
        );

        return document;
    }

    public async Task<List<Document>>
        FindByTenantAsync(
            string tenantId
        )
    {
        var documents =

            _documents
                .Values
                .Where(
                    d =>
                        d.TenantId ==
                        tenantId
                )
                .OrderByDescending(
                    d => d.UploadedAt
                )
                .ToList();

        return await Task.FromResult(
            documents
        );
    }

    public async Task<bool>
        ExistsAsync(
            string documentId
        )
    {
        return await Task.FromResult(

            _documents.ContainsKey(
                documentId
            )
        );
    }

    public async Task DeleteAsync(
        string documentId
    )
    {
        _documents.TryRemove(

            documentId,

            out _
        );

        await Task.CompletedTask;
    }

    public async Task<int>
        CountAsync()
    {
        return await Task.FromResult(
            _documents.Count
        );
    }

    public async Task<List<Document>>
        SearchByFilenameAsync(

            string tenantId,

            string query

        )
    {
        var documents =

            _documents
                .Values
                .Where(
                    d =>
                        d.TenantId ==
                        tenantId
                        &&
                        d.FileName
                            .Contains(
                                query,
                                StringComparison
                                    .OrdinalIgnoreCase
                            )
                )
                .ToList();

        return await Task.FromResult(
            documents
        );
    }

    public async Task<List<Document>>
        GetRecentDocumentsAsync(

            string tenantId,

            int limit

        )
    {
        var documents =

            _documents
                .Values
                .Where(
                    d =>
                        d.TenantId ==
                        tenantId
                )
                .OrderByDescending(
                    d => d.UploadedAt
                )
                .Take(limit)
                .ToList();

        return await Task.FromResult(
            documents
        );
    }
}
