export interface TenantIdentity {

    userId: string;

    tenantId: string;

    email: string;

    roles: string[];
}

export class TenantContext {

    private identity:
        TenantIdentity;

    constructor(
        identity: TenantIdentity
    ) {

        this.identity =
            identity;
    }

    public getTenantId(): string {

        return this.identity
            .tenantId;
    }

    public getUserId(): string {

        return this.identity
            .userId;
    }

    public getEmail(): string {

        return this.identity
            .email;
    }

    public hasRole(
        role: string
    ): boolean {

        return this.identity
            .roles
            .includes(role);
    }

    public isAdmin(): boolean {

        return this.hasRole(
            "tenant_admin"
        );
    }

    public canAccessTenant(
        tenantId: string
    ): boolean {

        return this.identity
            .tenantId === tenantId;
    }

    public toAuditRecord() {

        return {

            userId:
                this.identity.userId,

            tenantId:
                this.identity.tenantId,

            email:
                this.identity.email
        };
    }
}
