## FILE: messaging/KafkaConsumer.py

```
import json
import logging

from confluent_kafka import Consumer

logger = logging.getLogger(__name__)


class KafkaConsumer:

    def __init__(

        self,

        bootstrap_servers,

        group_id

    ):

        self.consumer = Consumer({

            "bootstrap.servers":
                bootstrap_servers,

            "group.id":
                group_id,

            "auto.offset.reset":
                "earliest"
        })

    def subscribe(
        self,
        topics
    ):

        self.consumer.subscribe(
            topics
        )

    def poll(
        self,
        timeout=1.0
    ):

        msg = self.consumer.poll(
            timeout
        )

        if msg is None:
            return None

        if msg.error():

            logger.error(
                msg.error()
            )

            return None

        try:

            payload = json.loads(

                msg.value()
                    .decode(
                        "utf-8"
                    )
            )

            return payload

        except Exception as exc:

            logger.exception(
                "Failed to parse event"
            )

            return None

    def consume_forever(
        self,
        callback
    ):

        while True:

            event = self.poll()

            if event is None:
                continue

            callback(
                event
            )

    def close(self):

        self.consumer.close()
