using AiPlatform.Models;

namespace AiPlatform.Repositories;

public class TenantRepository
{
    private readonly Dictionary<
        string,
        Tenant
    > _tenants =
        new();

    public async Task<Tenant?>
        FindByIdAsync(
            string tenantId
        )
    {
        _tenants.TryGetValue(

            tenantId,

            out var tenant
        );

        return await Task.FromResult(
            tenant
        );
    }

    public async Task<List<Tenant>>
        GetAllAsync()
    {
        return await Task.FromResult(

            _tenants
                .Values
                .OrderBy(
                    t => t.Name
                )
                .ToList()
        );
    }

    public async Task SaveAsync(
        Tenant tenant
    )
    {
        _tenants[
            tenant.Id
        ] = tenant;

        await Task.CompletedTask;
    }

    public async Task UpdateAsync(
        Tenant tenant
    )
    {
        if (
            !_tenants.ContainsKey(
                tenant.Id
            )
        )
        {
            throw new InvalidOperationException(
                "Tenant not found"
            );
        }

        _tenants[
            tenant.Id
        ] = tenant;

        await Task.CompletedTask;
    }

    public async Task DeleteAsync(
        string tenantId
    )
    {
        _tenants.Remove(
            tenantId
        );

        await Task.CompletedTask;
    }

    public async Task<bool>
        ExistsAsync(
            string tenantId
        )
    {
        return await Task.FromResult(

            _tenants.ContainsKey(
                tenantId
            )
        );
    }

    public async Task<int>
        CountAsync()
    {
        return await Task.FromResult(
            _tenants.Count
        );
    }

    public async Task<List<Tenant>>
        SearchAsync(
            string query
        )
    {
        var results =

            _tenants
                .Values
                .Where(
                    t =>
                        t.Name.Contains(
                            query,
                            StringComparison
                                .OrdinalIgnoreCase
                        )
                )
                .ToList();

        return await Task.FromResult(
            results
        );
    }
}
