import Foundation

//----------------------------------------------------------
// Canonical Rotation Identity
//----------------------------------------------------------

struct ApprovedSecretRotation {

    let secretId: String

    let rotationEpoch: Int64

    let secretVersion: Int64

    let encryptedSecret: String

    let provider: String

    let approvalSignature: String

    let approvalTimestamp: Int64

    //----------------------------------------------------------
    // Validation
    //----------------------------------------------------------

    var isValid: Bool {
        !secretId.isEmpty &&
        rotationEpoch > 0 &&
        secretVersion > 0 &&
        !encryptedSecret.isEmpty &&
        !provider.isEmpty &&
        !approvalSignature.isEmpty
    }

    //----------------------------------------------------------
    // Identity Helpers
    //----------------------------------------------------------

    var identity: String {
        "\(secretId)@\(rotationEpoch):\(secretVersion)"
    }

    func sameRotation(_ other: ApprovedSecretRotation) -> Bool {
        secretId == other.secretId &&
        rotationEpoch == other.rotationEpoch &&
        secretVersion == other.secretVersion
    }

    //----------------------------------------------------------
    // Diagnostics
    //----------------------------------------------------------

    var summary: String {
        "Approved rotation for \(secretId), epoch \(rotationEpoch), version \(secretVersion)"
    }
}
