import Foundation

//----------------------------------------------------------
// Rotation Repository
//----------------------------------------------------------

final class RotationRepository {

    private var rotations: [ApprovedSecretRotation] = []

    //----------------------------------------------------------
    // Persistence
    //----------------------------------------------------------

    func save(_ rotation: ApprovedSecretRotation) {
        precondition(rotation.isValid, "Invalid approved rotation.")
        rotations.append(rotation)
    }

    //----------------------------------------------------------
    // Canonical Lookup
    //----------------------------------------------------------

    func loadApprovedRotation(
        secretId: String,
        rotationEpoch: Int64,
        secretVersion: Int64
    ) -> ApprovedSecretRotation {

        guard let rotation = rotations.first(where: {
            $0.secretId == secretId &&
            $0.rotationEpoch == rotationEpoch &&
            $0.secretVersion == secretVersion
        }) else {
            fatalError("Approved rotation not found: \(secretId)")
        }

        return rotation
    }

    //----------------------------------------------------------
    // Operational Lookup
    //----------------------------------------------------------

    /// Administrative helper.
    ///
    /// Intended for dashboards, operational tooling, and
    /// synchronization health reporting.
    ///
    /// This method MUST NOT be used when reconstructing an
    /// approval decision because rotationEpoch and secretVersion
    /// together form the canonical rotation identity.
    func latestApprovedRotation(secretId: String) -> ApprovedSecretRotation {
        rotations
            .filter { $0.secretId == secretId }
            .sorted { $0.rotationEpoch < $1.rotationEpoch }
            .last!
    }

    //----------------------------------------------------------
    // Repository Queries
    //----------------------------------------------------------

    func latestEpoch(secretId: String) -> Int64 {
        rotations
            .filter { $0.secretId == secretId }
            .map { $0.rotationEpoch }
            .max() ?? 0
    }

    func latestVersionNumber(secretId: String) -> Int64 {
        rotations
            .filter { $0.secretId == secretId }
            .map { $0.secretVersion }
            .max() ?? 0
    }

    func exists(secretId: String, rotationEpoch: Int64) -> Bool {
        rotations.contains {
            $0.secretId == secretId && $0.rotationEpoch == rotationEpoch
        }
    }

    //----------------------------------------------------------
    // Repository Views
    //----------------------------------------------------------

    func allRotations() -> [ApprovedSecretRotation] {
        rotations
    }

    func rotationsFor(secretId: String) -> [ApprovedSecretRotation] {
        rotations.filter { $0.secretId == secretId }
    }

    //----------------------------------------------------------
    // Diagnostics
    //----------------------------------------------------------

    func repositorySummary() -> String {
        "\(rotations.count) approved rotations stored."
    }

    func epochHistory(secretId: String) -> [Int64] {
        rotations
            .filter { $0.secretId == secretId }
            .map { $0.rotationEpoch }
            .sorted()
    }
}
