package publication

import approval.ApprovedSecretRotation

object RotationPublisher {

    //----------------------------------------------------------
    // Publish Rotation
    //----------------------------------------------------------

    def publishRotation(approved: ApprovedSecretRotation): PublishedRotation = {

        require(approved.isValid, "Invalid approved rotation.")

        /*
        ============================================================

        Publication Projection

        PublishedRotation is a synchronization-facing projection
        of ApprovedSecretRotation. Its schema intentionally
        carries only the fields that synchronization and provider
        consumers need at rest: secretId, secretVersion, provider,
        and encryptedSecret.

        rotationEpoch is an internal approval-service concept used
        to track how many times a secretId has been re-approved
        (for example after a compromise or a scheduled rotation
        policy). It is not part of the synchronization contract,
        so it is not carried into the published projection.
        Consumers that need the originating rotation epoch are
        expected to resolve it through canonical
        approval-repository lookup rather than through the
        published artifact itself.

        ============================================================
        */

        PublishedRotation(
            secretId = approved.secretId,
            secretVersion = approved.secretVersion,
            provider = approved.provider,
            encryptedSecret = approved.encryptedSecret,
            publishedTimestamp = System.currentTimeMillis()
        )
    }

    //----------------------------------------------------------
    // Validation
    //----------------------------------------------------------

    def validatePublication(rotation: PublishedRotation): Boolean = {
        rotation.isValid
    }

    //----------------------------------------------------------
    // Publication Metadata
    //----------------------------------------------------------

    def publicationIdentity(rotation: PublishedRotation): String = {
        rotation.publicationIdentity
    }

    def provider(rotation: PublishedRotation): String = {
        rotation.provider
    }

    //----------------------------------------------------------
    // Diagnostics
    //----------------------------------------------------------

    def summary(rotation: PublishedRotation): String = {
        rotation.summary
    }

}
