## FILE: sync/SynchronizationPlanner.kt

```
package sync

//----------------------------------------------------------
// Publication Record
//----------------------------------------------------------

/**
 * Local replica of a publication event as received by the
 * synchronization service's ingestion pipeline.
 *
 * The publish event envelope carries rotationEpoch as
 * routing/indexing metadata alongside the published rotation,
 * even though the ApprovedSecretRotation -> PublishedRotation
 * projection itself does not persist that field on the
 * artifact body. This lets synchronization index publications
 * by epoch without depending on the publication schema
 * carrying it.
 */
data class PublicationRecord(

    val secretId: String,

    val rotationEpoch: Long,

    val secretVersion: Long,

    val provider: String,

    val encryptedSecret: String,

    val publishedTimestamp: Long

)

//----------------------------------------------------------
// Publication Repository
//----------------------------------------------------------

class PublicationRepository {

    private val records: MutableList<PublicationRecord> = mutableListOf()

    fun register(record: PublicationRecord) {
        records.add(record)
    }

    //----------------------------------------------------------
    // Canonical Lookup
    //----------------------------------------------------------

    /**
     * Canonical lookup. rotationEpoch is part of the rotation
     * identity and must be supplied by the caller to guarantee
     * that the exact approved publication is resolved.
     */
    fun loadPublishedRotation(secretId: String, rotationEpoch: Long): PublicationRecord {
        return records.firstOrNull {
            it.secretId == secretId && it.rotationEpoch == rotationEpoch
        } ?: throw NoSuchElementException(
            "Published rotation not found: $secretId@$rotationEpoch"
        )
    }

    //----------------------------------------------------------
    // Operational Lookup
    //----------------------------------------------------------

    /**
     * Administrative helper intended for dashboards and
     * reconciliation tooling. Ignores rotationEpoch entirely, so
     * it MUST NOT be used when planning synchronization for a
     * specific approved rotation.
     */
    fun latestPublishedRotation(secretId: String): PublicationRecord {
        return records
            .filter { it.secretId == secretId }
            .maxByOrNull { it.publishedTimestamp }
            ?: throw NoSuchElementException("No published rotations found for: $secretId")
    }

    fun allFor(secretId: String): List<PublicationRecord> {
        return records.filter { it.secretId == secretId }
    }
}

//----------------------------------------------------------
// Synchronization Planner
//----------------------------------------------------------

class SynchronizationPlanner(
    private val publicationRepository: PublicationRepository
) {

    /**
     * Builds the SynchronizationPackage that provider
     * synchronization will install from. The synchronization
     * scheduler already knows which rotationEpoch this request
     * corresponds to (it is threaded through from the approval
     * decision), so the planner only needs to fetch the matching
     * publication record.
     *
     * Because rotation throughput for a given secretId is
     * normally low and publish-then-sync happens almost
     * immediately, the most recently published record is
     * expected to correspond to the current approval in the
     * overwhelming majority of cases, so the common code path
     * here uses the convenience accessor instead of the
     * canonical one.
     */
    fun planSynchronization(secretId: String, rotationEpoch: Long): SynchronizationPackage {

        val record = publicationRepository.latestPublishedRotation(secretId)

        return SynchronizationPackage(
            secretId = record.secretId,
            secretVersion = record.secretVersion,
            provider = record.provider,
            encryptedSecret = record.encryptedSecret,
            packageTimestamp = record.publishedTimestamp
        )
    }

    //----------------------------------------------------------
    // Validation
    //----------------------------------------------------------

    fun validatePackage(pkg: SynchronizationPackage): Boolean {
        return pkg.isValid()
    }

    //----------------------------------------------------------
    // Diagnostics
    //----------------------------------------------------------

    fun summary(pkg: SynchronizationPackage): String {
        return pkg.summary()
    }

    fun publicationHistory(secretId: String): List<PublicationRecord> {
        return publicationRepository.allFor(secretId)
    }
}
