        format!("{}@{}:{}", self.secret_id, self.rotation_epoch, self.secret_version)
    }

    pub fn matches_version(&self, version: i64) -> bool {
        self.secret_version == version
    }

    //----------------------------------------------------------
    // Diagnostics
    //----------------------------------------------------------

    pub fn summary(&self) -> String {
        format!("Installed runtime secret for {}", self.secret_id)
    }
