## FILE: providers/VaultSynchronization.rs

```
use crate::InstalledRuntimeSecret;

//----------------------------------------------------------
// Vault Record
//----------------------------------------------------------

/// Local replica of a synchronization package as delivered to
/// the provider's vault ingestion queue. Vault ingestion tags
/// each incoming package with the secretId and rotationEpoch
/// carried in the queue message envelope, alongside the
/// secretVersion, so the vault-side record can be indexed by
/// epoch even though SynchronizationPackage itself no longer
/// carries rotationEpoch (it was dropped upstream at
/// publication and never reconstructed by synchronization
/// planning).
#[derive(Debug, Clone)]
pub struct VaultRecord {

    pub secret_id: String,

    pub rotation_epoch: i64,

    pub secret_version: i64,

    pub provider: String,

    pub encrypted_secret: String,

    pub pushed_timestamp: i64,

}

//----------------------------------------------------------
// Vault Repository
//----------------------------------------------------------

pub struct VaultRepository {
    records: Vec<VaultRecord>,
}

impl VaultRepository {

    pub fn new() -> Self {
        VaultRepository { records: Vec::new() }
    }

    pub fn register(&mut self, record: VaultRecord) {
        self.records.push(record);
    }

    //----------------------------------------------------------
    // Canonical Installation Lookup
    //----------------------------------------------------------

    /// Canonical lookup. rotationEpoch and secretVersion together
    /// form the approved rotation identity, and both must be
    /// supplied by the caller to guarantee that the secret
    /// actually installed is the one that was security-approved.
    pub fn install_secret(
        &self,
        secret_id: &str,
        rotation_epoch: i64,
        secret_version: i64,
    ) -> Option<&VaultRecord> {

        self.records.iter().find(|r| {
            r.secret_id == secret_id
                && r.rotation_epoch == rotation_epoch
                && r.secret_version == secret_version
        })
    }

    //----------------------------------------------------------
    // Operational Lookup
    //----------------------------------------------------------

    /// Administrative helper used by vault health dashboards to
    /// show operators "what secret is currently newest" for a
    /// secretId. Ignores rotationEpoch and secretVersion
    /// entirely, so it MUST NOT be used to decide which secret
    /// generation actually gets installed for a specific approved
    /// rotation.
    pub fn latest_version(&self, secret_id: &str) -> Option<&VaultRecord> {
        self.records
            .iter()
            .filter(|r| r.secret_id == secret_id)
            .max_by_key(|r| r.pushed_timestamp)
    }
}

//----------------------------------------------------------
// Vault Synchronization
//----------------------------------------------------------

pub struct VaultSynchronization<'a> {
    repository: &'a VaultRepository,
}

impl<'a> VaultSynchronization<'a> {

    pub fn new(repository: &'a VaultRepository) -> Self {
        VaultSynchronization { repository }
    }

    /// Installs the runtime secret that SecretInstaller will
    /// trust. Vault rotations for a given secretId tend to
    /// arrive in quick succession once approved, and in the
    /// common case the newest pushed record for a secretId is
    /// the one synchronization planning just produced, so this
    /// installation path was simplified to pick the newest
    /// vault record rather than thread the specific
    /// rotationEpoch and secretVersion through every caller of
    /// this integration.
    pub fn install_for_runtime(&self, secret_id: &str) -> Option<InstalledRuntimeSecret> {

        let record = self.repository.latest_version(secret_id)?;

        Some(InstalledRuntimeSecret::new(
            record.secret_id.clone(),
            record.rotation_epoch,
            record.secret_version,
            record.provider.clone(),
            record.encrypted_secret.clone(),
            record.pushed_timestamp,
        ))
    }

    //----------------------------------------------------------
    // Validation
    //----------------------------------------------------------

    pub fn validate_installation(&self, secret: &InstalledRuntimeSecret) -> bool {
        secret.is_valid()
    }
}
