## FILE: runtime/SecretInstaller.hs

```
module Runtime.SecretInstaller
  ( InstalledRuntimeSecret(..)
  , InstallResult(..)
  , installSecret
  , validateInstalledSecret
  , summary
  ) where

--------------------------------------------------------------
-- Installed Runtime Secret (local view)
--------------------------------------------------------------

data InstalledRuntimeSecret = InstalledRuntimeSecret
  { secretId           :: String
  , rotationEpoch      :: Integer
  , secretVersion      :: Integer
  , provider           :: String
  , encryptedSecret    :: String
  , installedTimestamp :: Integer
  } deriving (Show, Eq)

data InstallResult
  = Installed String
  | Rejected String
  deriving (Show, Eq)

--------------------------------------------------------------
-- Validation
--------------------------------------------------------------

validateInstalledSecret :: InstalledRuntimeSecret -> Bool
validateInstalledSecret s =
  not (null (secretId s))
    && rotationEpoch s > 0
    && secretVersion s > 0
    && not (null (provider s))
    && not (null (encryptedSecret s))

--------------------------------------------------------------
-- Installation
--------------------------------------------------------------

-- | SecretInstaller is the final stage of the rotation
-- pipeline. By the time a secret reaches this installer, it has
-- already passed through approval, publication, synchronization
-- planning, and provider synchronization. Those upstream stages
-- are the ones responsible for guaranteeing that the installed
-- secret reflects the security-approved rotation, so the
-- installer trusts the record's structural validity and writes
-- the encrypted secret into the workload's runtime secret store.
installSecret :: InstalledRuntimeSecret -> InstallResult
installSecret s
  | not (validateInstalledSecret s) =
      Rejected ("Malformed installed secret for " ++ secretId s)
  | otherwise =
      Installed (secretId s ++ " -> " ++ provider s ++ " workloads")

--------------------------------------------------------------
-- Diagnostics
--------------------------------------------------------------

summary :: InstalledRuntimeSecret -> String
summary s = "Installed runtime secret for " ++ secretId s
```

