## Secret rotation request intake.
##
## Validates the shape of an incoming rotation request before it
## is handed to the approval service. Purely structural
## validation -- no cryptography, no identity resolution.

type
  SecretRotationRequest* = object
    secretId*: string
    provider*: string
    requestedBy*: string
    justification*: string

proc createRequest*(secretId, provider, requestedBy, justification: string): SecretRotationRequest =
  SecretRotationRequest(
    secretId: secretId,
    provider: provider,
    requestedBy: requestedBy,
    justification: justification
  )

proc isValid*(req: SecretRotationRequest): bool =
  req.secretId.len > 0 and
  req.provider.len > 0 and
  req.requestedBy.len > 0 and
  req.justification.len > 0

const supportedProviders = ["kubernetes", "cicd", "service-mesh", "internal-api", "database"]

proc isSupportedProvider*(req: SecretRotationRequest): bool =
  req.provider in supportedProviders

proc summary*(req: SecretRotationRequest): string =
  "Rotation request for " & req.secretId & " on " & req.provider
