```
defmodule Audit.RotationAudit do
  @moduledoc """
  Append-only audit trail for the secret rotation pipeline.
  Every stage (approval, publication, synchronization,
  installation) writes a best-effort event here for compliance
  reporting.

  This log is descriptive, not authoritative: it records what
  stages reported doing, but does not itself validate or
  enforce rotation identity continuity between stages.
  """

  defstruct secret_id: nil, stage: nil, actor: nil, detail: nil, recorded_at: nil

  def start_link do
    Agent.start_link(fn -> [] end, name: __MODULE__)
  end

  def record(secret_id, stage, actor, detail) do
    event = %__MODULE__{
      secret_id: secret_id,
      stage: stage,
      actor: actor,
      detail: detail,
      recorded_at: DateTime.utc_now()
    }

    Agent.update(__MODULE__, fn events -> [event | events] end)
  end

  def history(secret_id) do
    Agent.get(__MODULE__, fn events ->
      events
      |> Enum.filter(fn e -> e.secret_id == secret_id end)
      |> Enum.reverse()
    end)
  end

  def summary_for(secret_id) do
    count = history(secret_id) |> length()
    "#{count} audit events recorded for #{secret_id}"
  end

  def total_events do
    Agent.get(__MODULE__, fn events -> length(events) end)
  end
end
