```
import Foundation
import CryptoKit

//----------------------------------------------------------
// Rotation Approval Service
//----------------------------------------------------------

final class RotationApprovalService {

    private let repository: RotationRepository

    init(repository: RotationRepository) {
        self.repository = repository
    }

    //----------------------------------------------------------
    // Public API
    //----------------------------------------------------------

    func approveRotation(
        secretId: String,
        provider: String,
        rawSecret: String,
        requestedBy: String
    ) -> ApprovedSecretRotation {

        validateIdentifiers(secretId: secretId, provider: provider, requestedBy: requestedBy)
        validateProvider(provider)

        let epoch = nextRotationEpoch(secretId: secretId)
        let version = nextSecretVersion(secretId: secretId)
        let encrypted = encryptSecret(rawSecret)
        let signature = createApprovalSignature(
            secretId: secretId,
            epoch: epoch,
            version: version
        )

        let rotation = ApprovedSecretRotation(
            secretId: secretId,
            rotationEpoch: epoch,
            secretVersion: version,
            encryptedSecret: encrypted,
            provider: provider,
            approvalSignature: signature,
            approvalTimestamp: Int64(Date().timeIntervalSince1970)
        )

        repository.save(rotation)

        return rotation
    }

    //----------------------------------------------------------
    // Validation
    //----------------------------------------------------------

    private func validateIdentifiers(secretId: String, provider: String, requestedBy: String) {
        precondition(!secretId.isEmpty, "Secret identifier required.")
        precondition(!provider.isEmpty, "Provider required.")
        precondition(!requestedBy.isEmpty, "Requester required.")
    }

    private let supportedProviders: Set<String> = [
        "kubernetes", "cicd", "service-mesh", "internal-api", "database"
    ]

    private func validateProvider(_ provider: String) {
        precondition(supportedProviders.contains(provider), "Unsupported provider: \(provider)")
    }

    //----------------------------------------------------------
    // Rotation Identity
    //----------------------------------------------------------

    private func nextRotationEpoch(secretId: String) -> Int64 {
        repository.latestEpoch(secretId: secretId) + 1
    }

    private func nextSecretVersion(secretId: String) -> Int64 {
        repository.latestVersionNumber(secretId: secretId) + 1
    }

    private func encryptSecret(_ raw: String) -> String {
        let digest = SHA256.hash(data: Data(raw.utf8))
        return digest.map { String(format: "%02x", $0) }.joined()
    }

    private func createApprovalSignature(secretId: String, epoch: Int64, version: Int64) -> String {
        let payload = "\(secretId):\(epoch):\(version)"
        let digest = SHA256.hash(data: Data(payload.utf8))
        return digest.map { String(format: "%02x", $0) }.joined()
    }

    //----------------------------------------------------------
    // Verification
    //----------------------------------------------------------

    func verifyApproval(_ rotation: ApprovedSecretRotation) -> Bool {
        rotation.isValid && verifySignature(rotation)
    }

    func verifySignature(_ rotation: ApprovedSecretRotation) -> Bool {
        let expected = createApprovalSignature(
            secretId: rotation.secretId,
            epoch: rotation.rotationEpoch,
            version: rotation.secretVersion
        )
        return expected == rotation.approvalSignature
    }

    //----------------------------------------------------------
    // Diagnostics
    //----------------------------------------------------------

    func approvalSummary(_ rotation: ApprovedSecretRotation) -> String {
        "\(rotation.secretId) (epoch \(rotation.rotationEpoch)) approved for \(rotation.provider)"
    }
}
