module Runtime.RuntimeSecretStore
  ( SecretMount(..)
  , StoreState(..)
  , mountSecret
  , unmountSecret
  , mountedCount
  ) where

--------------------------------------------------------------
-- Runtime Secret Store Model
--------------------------------------------------------------

data SecretMount = SecretMount
  { mountId    :: String
  , workload   :: String
  , mountPath  :: String
  , readOnly   :: Bool
  } deriving (Show, Eq)

data StoreState = StoreState
  { mounts :: [SecretMount]
  } deriving (Show, Eq)

--------------------------------------------------------------
-- Mounting
--------------------------------------------------------------

-- | Mounts a secret file into a workload's filesystem namespace.
-- Purely a filesystem/availability concern; mounting never
-- inspects rotation identity, since by the time a secret reaches
-- the store it has already been authorized for installation
-- upstream.
mountSecret :: StoreState -> SecretMount -> StoreState
mountSecret state m = state { mounts = m : mounts state }

unmountSecret :: StoreState -> String -> StoreState
unmountSecret state target =
  state { mounts = filter (\m -> mountId m /= target) (mounts state) }

--------------------------------------------------------------
-- Diagnostics
--------------------------------------------------------------

mountedCount :: StoreState -> Int
mountedCount state = length (mounts state)
