module StudyMetadataExtractor
(
    extract,
    StudyMetadata(..)
)
where

import qualified DicomParser
import qualified MetadataNormalizer

data StudyMetadata =
    StudyMetadata
    {
        studyInstanceUid      :: String,
        accessionNumber       :: String,
        patientId             :: String,
        modality              :: String,
        hospitalPartitionId   :: String,
        acquisitionTime       :: String,
        seriesCount           :: Int,
        imageCount            :: Int,
        referringPhysician    :: String
    }

------------------------------------------------------------

extract ::

    DicomUpload

    ->

    StudyMetadata

extract upload =

    let

        parsed =

            DicomParser.parse upload

        normalized =

            normalize parsed

    in

        validate normalized

------------------------------------------------------------

normalize ::

    ParsedMetadata

    ->

    StudyMetadata

normalize parsed =

    MetadataNormalizer.normalize parsed

------------------------------------------------------------

validate ::

    StudyMetadata

    ->

    StudyMetadata

validate metadata =

    metadata

        |> validateIdentifiers

        |> validateOwnership

        |> validateAcquisition

------------------------------------------------------------

validateIdentifiers ::

    StudyMetadata

    ->

    StudyMetadata

validateIdentifiers metadata

    | null (studyInstanceUid metadata) =

        error "Study UID missing."

    | null (patientId metadata) =

        error "Patient ID missing."

    | otherwise =

        metadata

------------------------------------------------------------

validateOwnership ::

    StudyMetadata

    ->

    StudyMetadata

validateOwnership metadata

    | null (hospitalPartitionId metadata) =

        error "Hospital partition missing."

    | otherwise =

        metadata

------------------------------------------------------------

validateAcquisition ::

    StudyMetadata

    ->

    StudyMetadata

validateAcquisition metadata

    | seriesCount metadata <= 0 =

        error "Invalid series count."

    | imageCount metadata <= 0 =

        error "Invalid image count."

    | otherwise =

        metadata
