//-------------------------------------------------------------

void SearchRecordFactory::trim(

    std::string& value

) const
{
    auto begin = std::find_if_not(

        value.begin(),
        value.end(),

        [](unsigned char c)
        {
            return std::isspace(c);
        }

    );

    auto end = std::find_if(

        value.rbegin(),
        value.rend(),

        [](unsigned char c)
        {
            return !std::isspace(c);
        }

    ).base();

    if (begin >= end)
    {
        value.clear();
        return;
    }

    value.assign(

        begin,

        end

    );
}
