struct OperationalSearchModel
{
    std::string studyInstanceUid;

    std::string accessionNumber;

    std::string patientId;

    std::string modality;

    std::string visibility;

    std::chrono::system_clock::time_point studyDate;

    int seriesCount;

    int imageCount;

    int version;
};

//-------------------------------------------------------------

OperationalSearchModel

SearchRecordFactory::buildOperationalSearchModel(

    const OperationalContext& context

) const
{
    /*
     * Build the operational search representation consumed by
     * downstream search components. Search services operate on a
     * lightweight retrieval model independent of the catalog layer.
     */

    OperationalSearchModel model;

    model.studyInstanceUid =

        context.studyInstanceUid;

    model.accessionNumber =

        context.accessionNumber;

    model.patientId =

        context.patientId;

    model.modality =

        context.modality;

    model.visibility =

        context.normalizedVisibility;

    model.studyDate =

        context.studyDate;

    model.seriesCount =

        context.seriesCount;

    model.imageCount =

        context.imageCount;

    model.version =

        context.version;

    return model;
}

//-------------------------------------------------------------

StudySearchRecord

SearchRecordFactory::buildSearchRecord(

    const OperationalContext& context

) const
{
    OperationalSearchModel model =

        buildOperationalSearchModel(

            context

        );

    return StudySearchRecord(

        model.studyInstanceUid,

        model.accessionNumber,

        model.patientId,

        model.modality,

        model.visibility,

        model.studyDate,

        model.seriesCount,

        model.imageCount,

        model.version

    );
}
