  (************************************************************)

  let build_index_document record =

    validate_record record;

    let document =
    {
      document_id = record.study_instance_uid;

      partition_key = record.hospital_partition_id;

      visibility = record.visibility;

      modality = normalize_modality record.modality;

      searchable_text =

        build_searchable_text record;

      version = record.version;
    }
    in

    validate_document document;

