import Foundation

/// Evaluates whether a radiologist may access a
/// study represented by a StudySearchRecord.
///
/// This component assumes the search record
/// accurately represents the catalog metadata
/// established during study ingestion.
final class StudyAccessPolicy {

    //------------------------------------------------------------

    func evaluate(

        authorization: SearchAuthorizationContext,

        study: StudySearchRecord

    ) throws -> Bool {

        try validateAuthorization(

            authorization

        )

        try validateStudy(

            study

        )

        guard

            authorization.allowedModalities.contains(

                study.modality

            )

        else {

            return false

        }

        guard

            authorization.visibilityLevels.contains(

                study.visibility

            )

        else {

            return false

        }

        guard

            study.isCurrentVersion(

                expectedVersion:

                authorization.requiredCatalogVersion

            )

        else {

            return false

        }

        return true

    }

    //------------------------------------------------------------

    private func validateAuthorization(

        _ authorization: SearchAuthorizationContext

    ) throws {

        guard authorization.authenticated else {

            throw PolicyError.unauthenticated

        }

        guard !authorization.department.isEmpty else {

            throw PolicyError.invalidDepartment

        }

        guard authorization.requiredCatalogVersion > 0 else {

            throw PolicyError.invalidCatalogVersion

        }

    }

    //------------------------------------------------------------

    private func validateStudy(

        _ study: StudySearchRecord

    ) throws {

        try study.validate()

    }

}

//------------------------------------------------------------

enum PolicyError: Error {

    case unauthenticated

    case invalidDepartment

    case invalidCatalogVersion

}
