export interface SearchRecordMessage {

    studyInstanceUid: string;

    accessionNumber: string;

    patientId: string;

    hospitalPartitionId: string;

    visibility: string;

    modality: string;

    studyDate: string;

    seriesCount: number;

    imageCount: number;

    version: number;

}

//--------------------------------------------------------------------

export class SearchCodec {

    //---------------------------------------------------------------

    encode(

        record: SearchRecordMessage

    ): string {

        this.validate(

            record

        );

        return JSON.stringify(

            record

        );

    }

    //---------------------------------------------------------------

    decode(

        payload: string

    ): SearchRecordMessage {

        const record =

            JSON.parse(

                payload

            ) as SearchRecordMessage;

        this.validate(

            record

        );

        return record;

    }

    //---------------------------------------------------------------

    private validate(

        record: SearchRecordMessage

    ): void {

        if (!record.studyInstanceUid)

            throw new Error(

                "Study identifier missing."

            );

        if (!record.patientId)

            throw new Error(

                "Patient identifier missing."

            );

        if (!record.hospitalPartitionId)

            throw new Error(

                "Hospital partition missing."

            );

        if (!record.visibility)

            throw new Error(

                "Visibility missing."

            );

        if (!record.modality)

            throw new Error(

                "Modality missing."

            );

        if (record.version <= 0)

            throw new Error(

                "Invalid catalog version."

            );

    }

}
