////////////////////////////////////////////////////////////

public class BookingApi {

    private final ItineraryService itineraryService;

    private final TicketIssuer ticketIssuer;

    ////////////////////////////////////////////////////////

    public BookingApi(

            ItineraryService itineraryService,

            TicketIssuer ticketIssuer

    ) {

        this.itineraryService = itineraryService;

        this.ticketIssuer = ticketIssuer;
    }

    ////////////////////////////////////////////////////////

    public BookingResponse createBooking(

            BookingRequest request

    ) {

        validateRequest(

                request

        );

        Itinerary itinerary =

                itineraryService.createItinerary(

                        request

                );

        BoardingAuthorization authorization =

                ticketIssuer.issueAuthorization(

                        itinerary

                );

        return new BookingResponse(

                itinerary.getBookingId(),

                authorization.getBoardingPassId(),

                authorization.getStatus(),

                LocalDateTime.now()

        );
    }

    ////////////////////////////////////////////////////////

    public BookingResponse reissueBoardingAuthorization(

            String bookingId

    ) {

        if (

                bookingId == null ||

                bookingId.isBlank()

        ) {

            throw new IllegalArgumentException(

                    "Booking identifier is required."

            );
        }

        Itinerary itinerary =

                itineraryService.findByBookingId(

                        bookingId

                );

        BoardingAuthorization authorization =

                ticketIssuer.issueAuthorization(

                        itinerary

                );

        return new BookingResponse(

                itinerary.getBookingId(),

                authorization.getBoardingPassId(),

                authorization.getStatus(),

                LocalDateTime.now()

        );
    }

    ////////////////////////////////////////////////////////

    public BookingDetails getBooking(

            String bookingId

    ) {

        Itinerary itinerary =

                itineraryService.findByBookingId(

                        bookingId

                );

        return new BookingDetails(

                itinerary

        );
    }

    ////////////////////////////////////////////////////////

    private void validateRequest(

            BookingRequest request

    ) {

        if (

                request == null

        ) {

            throw new IllegalArgumentException(

                    "Booking request cannot be null."

            );
        }

        if (

                isBlank(

                        request.getPassengerId()

                )

        ) {

            throw new IllegalArgumentException(

                    "Passenger identifier missing."

            );
        }

        if (

                isBlank(

                        request.getFlightNumber()

                )

        ) {

            throw new IllegalArgumentException(

                    "Flight number missing."

            );
        }

        if (

                isBlank(

                        request.getDepartureAirport()

                )

        ) {

            throw new IllegalArgumentException(

                    "Departure airport missing."

            );
        }

        if (

                isBlank(

                        request.getArrivalAirport()

                )

        ) {

            throw new IllegalArgumentException(

                    "Arrival airport missing."

            );
        }

        if (

                isBlank(

                        request.getTravelSegment()

                )

        ) {

            throw new IllegalArgumentException(

                    "Travel segment missing."

            );
        }
    }

    ////////////////////////////////////////////////////////

    private boolean isBlank(

            String value

    ) {

        return value == null ||

                value.isBlank();
