## FILE: ticketing/boarding_authorization.kt

```
package ticketing

import java.time.LocalDateTime

////////////////////////////////////////////////////////////

data class BoardingAuthorization(

    val authorizationId: String,

    val boardingPassId: String,

    val bookingId: String,

    val passengerId: String,

    val flightNumber: String,

    val departureAirport: String,

    val arrivalAirport: String,

    //
    // ======================================================
    // SECURITY-CRITICAL AUTHORIZATION ATTRIBUTE
    // ======================================================
    //
    // travelSegment uniquely identifies the portion of the
    // passenger journey approved for boarding.
    //
    // Examples:
    //
    // AI302: DEL -> BOM
    //
    // AI302: BOM -> BLR
    //
    // Although both segments belong to the same flight
    // itinerary, boarding authorization is granted for a
    // specific travel segment only.
    //
    // Downstream components must preserve this attribute
    // until the final boarding authorization decision.
    //
    // The first vulnerability of Scenario 050 will occur
    // when ManifestProjection transforms this canonical
    // authorization into an operational boarding manifest.
    // ======================================================
    //

    val travelSegment: String,

    val boardingGroup: String,

    val travelClass: String,

    val issuedAt: LocalDateTime,

    val expiresAt: LocalDateTime,

    val status: AuthorizationStatus
)

////////////////////////////////////////////////////////////

enum class AuthorizationStatus {

    APPROVED,

    REVOKED,

    EXPIRED
}

////////////////////////////////////////////////////////////

class BoardingAuthorizationValidator {

    ////////////////////////////////////////////////////////

    fun validate(

        authorization: BoardingAuthorization

    ) {

        requireNotBlank(

            authorization.authorizationId,

            "Authorization identifier missing."

        )

        requireNotBlank(

            authorization.boardingPassId,

            "Boarding pass identifier missing."

        )

        requireNotBlank(

            authorization.bookingId,

            "Booking identifier missing."

        )

        requireNotBlank(

            authorization.passengerId,

            "Passenger identifier missing."

        )

        requireNotBlank(

            authorization.flightNumber,

            "Flight number missing."

        )

        requireNotBlank(

            authorization.departureAirport,

            "Departure airport missing."

        )

        requireNotBlank(

            authorization.arrivalAirport,

            "Arrival airport missing."

        )

        requireNotBlank(

            authorization.travelSegment,

            "Travel segment missing."

        )

        requireNotBlank(

            authorization.boardingGroup,

            "Boarding group missing."

        )

        requireNotBlank(

            authorization.travelClass,

            "Travel class missing."

        )

        require(

            authorization.status ==

                AuthorizationStatus.APPROVED

        ) {

            "Boarding authorization is not approved."

        }

        require(

            authorization.expiresAt.isAfter(

                authorization.issuedAt

            )

        ) {

            "Authorization validity period is invalid."

        }
    }

    ////////////////////////////////////////////////////////

    private fun requireNotBlank(

        value: String,

        message: String

    ) {

        require(

            value.isNotBlank()

        ) {

            message
        }
    }
}

////////////////////////////////////////////////////////////

class AuthorizationInspector(

    private val validator:

        BoardingAuthorizationValidator =

            BoardingAuthorizationValidator()

) {

    ////////////////////////////////////////////////////////

    fun inspect(

        authorization: BoardingAuthorization

    ): BoardingAuthorization {

        validator.validate(

            authorization

        )

        //
        // Canonical authorization inspection.
        //
        // Every security-sensitive attribute,
        // including travelSegment, is still
        // present and correctly validated.
        //
        // The authorization object remains the
        // authoritative representation of the
        // boarding approval.
        //

        return authorization
    }

    ////////////////////////////////////////////////////////

    fun isEligible(

        authorization: BoardingAuthorization

    ): Boolean {

        return try {

            inspect(

                authorization

            )

            true

        }

        catch (

            _: Exception

        ) {

            false
        }
    }
}
