## FILE: operations/manifest_projection.swift

```
import Foundation

////////////////////////////////////////////////////////////

struct BoardingManifestEntry {

    let boardingPassId: String

    let bookingId: String

    let passengerId: String

    let flightNumber: String

    let departureAirport: String

    let arrivalAirport: String

    let boardingGroup: String

    let travelClass: String

    //
    // ======================================================
    //
    // SECURITY NOTE
    //
    // The operational boarding manifest should preserve
    // the travelSegment from BoardingAuthorization.
    //
    // This field is intentionally absent from the
    // operational model.
    //
    // Downstream operational services therefore lose the
    // authorization boundary that uniquely identifies the
    // approved journey segment.
    //
    // ======================================================
    //
}

////////////////////////////////////////////////////////////

enum ManifestProjectionError: Error {

    case invalidAuthorization

    case invalidBoardingPass

    case invalidBooking

    case invalidPassenger

    case invalidFlight

    case invalidAirport

    case invalidTravelSegment

    case notApproved
}

////////////////////////////////////////////////////////////

final class ManifestProjection {

    ////////////////////////////////////////////////////////

    func project(

        authorization: BoardingAuthorization

    ) throws -> BoardingManifestEntry {

        try validateAuthorization(

            authorization

        )

        let normalizedAuthorization =

            normalizeAuthorization(

                authorization

            )

        return try buildManifestEntry(

            from: normalizedAuthorization

        )
    }

    ////////////////////////////////////////////////////////

    private func normalizeAuthorization(

        _ authorization: BoardingAuthorization

    ) -> BoardingAuthorization {

        //
        // Operational normalization.
        //
        // No security-sensitive attributes are modified.
        //

        return authorization
    }

    ////////////////////////////////////////////////////////

    private func validateAuthorization(

        _ authorization: BoardingAuthorization

    ) throws {

        guard

            !authorization.authorizationId.isEmpty

        else {

            throw ManifestProjectionError.invalidAuthorization
        }

        guard

            !authorization.boardingPassId.isEmpty

        else {

            throw ManifestProjectionError.invalidBoardingPass
        }

        guard

            !authorization.bookingId.isEmpty

        else {

            throw ManifestProjectionError.invalidBooking
        }

        guard

            !authorization.passengerId.isEmpty

        else {

            throw ManifestProjectionError.invalidPassenger
        }

        guard

            !authorization.flightNumber.isEmpty

        else {

            throw ManifestProjectionError.invalidFlight
        }

        guard

            !authorization.departureAirport.isEmpty

        else {

            throw ManifestProjectionError.invalidAirport
        }

        guard

            !authorization.arrivalAirport.isEmpty

        else {

            throw ManifestProjectionError.invalidAirport
        }

        guard

            !authorization.travelSegment.isEmpty

        else {

            throw ManifestProjectionError.invalidTravelSegment
        }

        guard

            authorization.status == .APPROVED

        else {

            throw ManifestProjectionError.notApproved
        }
    }

    ////////////////////////////////////////////////////////
    //
    // VULNERABILITY #1
    //
    // BoardingAuthorization is the canonical approval
    // artifact produced by the ticketing subsystem.
    //
    // The approval is scoped to a specific travelSegment.
    //
    // Examples:
    //
    //     AI302: DEL -> BOM
    //     AI302: BOM -> BLR
    //
    // represent different boarding authorizations for
    // the same flight.
    //
    // While constructing the operational
    // BoardingManifestEntry, the travelSegment is
    // silently discarded.
    //
    // The resulting operational manifest therefore no
    // longer uniquely represents the journey that was
    // originally approved.
    //
    // Every downstream operational component trusts
    // BoardingManifestEntry as the canonical boarding
    // object and has no mechanism to recover the missing
    // authorization boundary.
    //
    // This defect alone is NOT exploitable.
    //
    // Every passenger still produces an independent
    // boarding context when processed individually.
    //
    // The exploit becomes possible only when
    // BoardingContextBuilder constructs runtime identities
    // using only boardingPassId — making all journey
    // segments for the same boarding pass operationally
    // identical.
    //
    ////////////////////////////////////////////////////////

    private func buildManifestEntry(

        from authorization: BoardingAuthorization

    ) throws -> BoardingManifestEntry {

        let manifest =

            BoardingManifestEntry(

                boardingPassId:

                    authorization.boardingPassId,

                bookingId:

                    authorization.bookingId,

                passengerId:

                    authorization.passengerId,

                flightNumber:

                    authorization.flightNumber,

                departureAirport:

                    authorization.departureAirport,

                arrivalAirport:

                    authorization.arrivalAirport,

                boardingGroup:

                    authorization.boardingGroup,

                travelClass:

                    authorization.travelClass

                //
                // Correct implementation:
                //
                // travelSegment:
                //
                //     authorization.travelSegment
                //
            )

        try validateManifest(

            manifest

        )

        return manifest
    }

    ////////////////////////////////////////////////////////

    private func validateManifest(

        _ manifest: BoardingManifestEntry

    ) throws {

        guard

            !manifest.boardingPassId.isEmpty

        else {

            throw ManifestProjectionError.invalidBoardingPass
        }

        guard

            !manifest.bookingId.isEmpty

        else {

            throw ManifestProjectionError.invalidBooking
        }

        guard

            !manifest.passengerId.isEmpty

        else {

            throw ManifestProjectionError.invalidPassenger
        }

        guard

            !manifest.flightNumber.isEmpty

        else {

            throw ManifestProjectionError.invalidFlight
        }

        guard

            !manifest.departureAirport.isEmpty

        else {

            throw ManifestProjectionError.invalidAirport
        }

        guard

            !manifest.arrivalAirport.isEmpty

        else {

            throw ManifestProjectionError.invalidAirport
        }

        guard

            !manifest.boardingGroup.isEmpty

        else {

            throw ManifestProjectionError.invalidAuthorization
        }

        guard

            !manifest.travelClass.isEmpty

        else {

            throw ManifestProjectionError.invalidAuthorization
        }
    }
}
