```
import Foundation

////////////////////////////////////////////////////////////

struct BoardingManifest {

    let flightNumber: String

    let departureAirport: String

    let arrivalAirport: String

    let generatedAt: Date

    var entries: [BoardingManifestEntry]
}

////////////////////////////////////////////////////////////

enum ManifestStatus {

    case pending

    case finalized

    case closed
}

////////////////////////////////////////////////////////////

final class BoardingManifestService {

    ////////////////////////////////////////////////////////

    func buildManifest(

        entries: [BoardingManifestEntry]

    ) throws -> BoardingManifest {

        guard

            !entries.isEmpty

        else {

            throw BoardingManifestError.emptyManifest
        }

        let representative =

            entries.first!

        try validateEntries(

            entries

        )

        let orderedEntries =

            orderEntries(

                entries

            )

        return BoardingManifest(

            flightNumber:

                representative.flightNumber,

            departureAirport:

                representative.departureAirport,

            arrivalAirport:

                representative.arrivalAirport,

            generatedAt:

                Date(),

            entries:

                orderedEntries
        )
    }

    ////////////////////////////////////////////////////////

    func appendPassenger(

        _ entry: BoardingManifestEntry,

        to manifest: BoardingManifest

    ) throws -> BoardingManifest {

        var updatedEntries =

            manifest.entries

        try validateEntry(

            entry

        )

        updatedEntries.append(

            entry

        )

        return BoardingManifest(

            flightNumber:

                manifest.flightNumber,

            departureAirport:

                manifest.departureAirport,

            arrivalAirport:

                manifest.arrivalAirport,

            generatedAt:

                manifest.generatedAt,

            entries:

                orderEntries(

                    updatedEntries

                )
        )
    }

    ////////////////////////////////////////////////////////

    func manifestStatus(

        for manifest: BoardingManifest

    ) -> ManifestStatus {

        if manifest.entries.isEmpty {

            return .pending
        }

        return .finalized
    }

    ////////////////////////////////////////////////////////

    private func validateEntries(

        _ entries: [BoardingManifestEntry]

    ) throws {

        let flight =

            entries.first!.flightNumber

        let departure =

            entries.first!.departureAirport

        let arrival =

            entries.first!.arrivalAirport

        for entry in entries {

            try validateEntry(

                entry

            )

            guard

                entry.flightNumber == flight

            else {

                throw BoardingManifestError.flightMismatch
            }

            guard

                entry.departureAirport == departure

            else {

                throw BoardingManifestError.departureMismatch
            }

            guard

                entry.arrivalAirport == arrival

            else {

                throw BoardingManifestError.arrivalMismatch
            }
        }
    }

    ////////////////////////////////////////////////////////

    private func validateEntry(

        _ entry: BoardingManifestEntry

    ) throws {

        guard

            !entry.boardingPassId.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        guard

            !entry.bookingId.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        guard

            !entry.passengerId.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        guard

            !entry.flightNumber.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        guard

            !entry.departureAirport.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        guard

            !entry.arrivalAirport.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        guard

            !entry.boardingGroup.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        guard

            !entry.travelClass.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }
    }

    ////////////////////////////////////////////////////////

    // Part 2
    //
    // - orderEntries(...)
    // - BoardingManifestInspector
    // - helper methods
    // - manifest queries
    // - completion of file
}

////////////////////////////////////////////////////////////

enum BoardingManifestError: Error {

    case emptyManifest

    case invalidEntry

    case flightMismatch

    case departureMismatch

    case arrivalMismatch
}
    ////////////////////////////////////////////////////////

    private func orderEntries(

        _ entries: [BoardingManifestEntry]

    ) -> [BoardingManifestEntry] {

        return entries.sorted {

            if $0.boardingGroup !=

                $1.boardingGroup {

                return

                    $0.boardingGroup <

                    $1.boardingGroup
            }

            if $0.travelClass !=

                $1.travelClass {

                return

                    $0.travelClass <

                    $1.travelClass
            }

            return

                $0.passengerId <

                $1.passengerId
        }
    }
}

////////////////////////////////////////////////////////////

final class BoardingManifestInspector {

    ////////////////////////////////////////////////////////

    func inspect(

        _ manifest: BoardingManifest

    ) throws {

        guard

            !manifest.entries.isEmpty

        else {

            throw BoardingManifestError.emptyManifest
        }

        for entry in

            manifest.entries {

            try inspect(

                entry

            )
        }
    }

    ////////////////////////////////////////////////////////

    private func inspect(

        _ entry: BoardingManifestEntry

    ) throws {

        guard

            !entry.boardingPassId.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        guard

            !entry.bookingId.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        guard

            !entry.passengerId.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        guard

            !entry.flightNumber.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        guard

            !entry.departureAirport.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        guard

            !entry.arrivalAirport.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        guard

            !entry.boardingGroup.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        guard

            !entry.travelClass.isEmpty

        else {

            throw BoardingManifestError.invalidEntry
        }

        //
        // Manifest inspection intentionally
        // validates only the operational
        // boarding representation.
        //
        // travelSegment is no longer present
        // because it was removed earlier by
        // ManifestProjection.
        //
        // Consequently, the inspector cannot
        // verify that every manifest entry
        // still corresponds to the originally
        // approved journey segment.
        //
        // This component is NOT vulnerable.
        // It simply trusts the operational
        // manifest produced upstream.
        //
    }

    ////////////////////////////////////////////////////////

    func passengers(

        in manifest: BoardingManifest

    ) -> [BoardingManifestEntry] {

        return manifest.entries
    }

    ////////////////////////////////////////////////////////

    func contains(

        boardingPassId: String,

        in manifest: BoardingManifest

    ) -> Bool {

        return manifest.entries.contains {

            $0.boardingPassId ==

            boardingPassId
        }
    }

    ////////////////////////////////////////////////////////

    func totalPassengers(

        in manifest: BoardingManifest

    ) -> Int {

        return manifest.entries.count
    }

    ////////////////////////////////////////////////////////

    func boardingGroups(

        in manifest: BoardingManifest

    ) -> [String] {

        return Array(

            Set(

                manifest.entries.map {

                    $0.boardingGroup

                }

            )

        ).sorted()
    }
}
