## FILE: boarding/boarding_context_builder.go

```
package boarding

import (
	"errors"
	"strings"
)

////////////////////////////////////////////////////////////

type BoardingManifestEntry struct {
	BoardingPassID   string
	BookingID        string
	PassengerID      string
	FlightNumber     string
	DepartureAirport string
	ArrivalAirport   string
	BoardingGroup    string
	TravelClass      string
}

////////////////////////////////////////////////////////////

type BoardingContext struct {
	RuntimeIdentity string

	BoardingPassID string

	BookingID string

	PassengerID string

	FlightNumber string

	DepartureAirport string

	ArrivalAirport string

	BoardingGroup string

	TravelClass string
}

////////////////////////////////////////////////////////////

type BoardingContextBuilder struct {
}

////////////////////////////////////////////////////////////

func NewBoardingContextBuilder() *BoardingContextBuilder {

	return &BoardingContextBuilder{}
}

////////////////////////////////////////////////////////////

func (b *BoardingContextBuilder) Build(

	entry BoardingManifestEntry,

) (BoardingContext, error) {

	if err := b.validate(

		entry,

	); err != nil {

		return BoardingContext{}, err
	}

	normalized := b.normalize(

		entry,

	)

	context := b.buildContext(

		normalized,

	)

	if err := b.validateContext(

		context,

	); err != nil {

		return BoardingContext{}, err
	}

	return context, nil
}

////////////////////////////////////////////////////////////

func (b *BoardingContextBuilder) normalize(

	entry BoardingManifestEntry,

) BoardingManifestEntry {

	entry.BoardingGroup =

		strings.TrimSpace(

			entry.BoardingGroup,
		)

	entry.TravelClass =

		strings.TrimSpace(

			entry.TravelClass,
		)

	return entry
}

////////////////////////////////////////////////////////////

func (b *BoardingContextBuilder) validate(

	entry BoardingManifestEntry,

) error {

	if entry.BoardingPassID == "" {

		return errors.New(

			"boarding pass missing",
		)
	}

	if entry.BookingID == "" {

		return errors.New(

			"booking identifier missing",
		)
	}

	if entry.PassengerID == "" {

		return errors.New(

			"passenger identifier missing",
		)
	}

	if entry.FlightNumber == "" {

		return errors.New(

			"flight number missing",
		)
	}

	if entry.DepartureAirport == "" {

		return errors.New(

			"departure airport missing",
		)
	}

	if entry.ArrivalAirport == "" {

		return errors.New(

			"arrival airport missing",
		)
	}

	if entry.BoardingGroup == "" {

		return errors.New(

			"boarding group missing",
		)
	}

	if entry.TravelClass == "" {

		return errors.New(

			"travel class missing",
		)
	}

	return nil
}

////////////////////////////////////////////////////////////

// Part 2 begins here.
//
// buildContext()
//
// contains Vulnerability #2.
//
// Runtime identity is constructed using only
// BoardingPassID even though the boarding
// authorization originally represented a
// specific approved travel segment.
//
// Because ManifestProjection already removed
// travelSegment, the runtime identity can no
// longer distinguish different approved
// journeys that share the same boarding pass.
//
// The interaction between this defect and
// ManifestProjection creates the complete
// Workflow Integrity failure.

////////////////////////////////////////////////////////////

func (b *BoardingContextBuilder) validateContext(

	context BoardingContext,

) error {

	if context.RuntimeIdentity == "" {

		return errors.New(

			"runtime identity missing",
		)
	}

	if context.BoardingPassID == "" {

		return errors.New(

			"boarding pass missing",
		)
	}

	if context.PassengerID == "" {

		return errors.New(

			"passenger identifier missing",
		)
	}

	return nil
}
////////////////////////////////////////////////////////////

func (b *BoardingContextBuilder) buildContext(

	entry BoardingManifestEntry,

) BoardingContext {

	//
	// ======================================================
	// VULNERABILITY #2
	//
	// BoardingContext represents the runtime identity used
	// by GateAuthorizer during boarding.
	//
	// The runtime identity should uniquely represent the
	// approved boarding authorization.
	//
	// Correct identity:
	//
	//     BoardingPassID
	//     +
	//     TravelSegment
	//
	// However, BoardingManifestEntry no longer contains
	// TravelSegment because ManifestProjection removed it.
	//
	// The builder therefore falls back to using only
	// BoardingPassID as the runtime identity.
	//
	// Different approved journey segments sharing the same
	// boarding pass become operationally identical.
	//
	// This defect alone is NOT exploitable because a correct
	// BoardingManifestEntry would still preserve the journey
	// boundary.
	//
	// The exploit only exists when combined with
	// ManifestProjection, which already discarded that
	// authorization context.
	//
	// ======================================================
	//

	runtimeIdentity :=

		entry.BoardingPassID

	// Correct implementation would have been:
	//
	// runtimeIdentity =
	//     entry.BoardingPassID +
	//     ":" +
	//     entry.TravelSegment
	//
	// or, preferably,
	//
	// runtimeIdentity =
	//     Hash(BoardingScope)
	//
	// Neither is possible because the operational
	// BoardingManifestEntry no longer carries the
	// approved travel segment.

	return BoardingContext{

		RuntimeIdentity: runtimeIdentity,

		BoardingPassID: entry.BoardingPassID,

		BookingID: entry.BookingID,

		PassengerID: entry.PassengerID,

		FlightNumber: entry.FlightNumber,

		DepartureAirport: entry.DepartureAirport,

		ArrivalAirport: entry.ArrivalAirport,

		BoardingGroup: entry.BoardingGroup,

		TravelClass: entry.TravelClass,
	}
}

////////////////////////////////////////////////////////////

func (b *BoardingContextBuilder) BuildBatch(

	entries []BoardingManifestEntry,

) ([]BoardingContext, error) {

	contexts := make(

		[]BoardingContext,

		0,

		len(entries),
	)

	for _, entry := range entries {

		context, err := b.Build(

			entry,
		)

		if err != nil {

			return nil, err
		}

		contexts = append(

			contexts,

			context,
		)
	}

	return contexts, nil
}

////////////////////////////////////////////////////////////

func (b *BoardingContextBuilder) RuntimeIdentities(

	contexts []BoardingContext,

) []string {

	identities := make(

		[]string,

		0,

		len(contexts),
	)

	for _, context := range contexts {

		identities = append(

			identities,

			context.RuntimeIdentity,
		)
	}

	return identities
}

////////////////////////////////////////////////////////////

func (b *BoardingContextBuilder) ContainsIdentity(

	contexts []BoardingContext,

	identity string,

) bool {

	for _, context := range contexts {

		if context.RuntimeIdentity == identity {

			return true
		}
	}

	return false
}
