package boarding

import (
	"errors"
)

////////////////////////////////////////////////////////////

type AuthorizationDecision struct {

	Allowed bool

	Reason string
}

////////////////////////////////////////////////////////////

type GateAuthorizer struct {
}

////////////////////////////////////////////////////////////

func NewGateAuthorizer() *GateAuthorizer {

	return &GateAuthorizer{}
}

////////////////////////////////////////////////////////////

func (g *GateAuthorizer) Authorize(

	context BoardingContext,

) (AuthorizationDecision, error) {

	if err := g.validateContext(

		context,

	); err != nil {

		return AuthorizationDecision{}, err
	}

	decision := AuthorizationDecision{

		Allowed: true,

		Reason: "Boarding authorization successful",
	}

	return decision, nil
}

////////////////////////////////////////////////////////////

func (g *GateAuthorizer) validateContext(

	context BoardingContext,

) error {

	//
	// ======================================================
	//
	// SECURITY NOTE
	//
	// GateAuthorizer is the authorization sink.
	//
	// It correctly validates the operational
	// BoardingContext produced by the boarding
	// pipeline.
	//
	// It intentionally does NOT reconstruct the
	// original BoardingAuthorization because the
	// boarding workflow treats BoardingContext as
	// the canonical runtime representation.
	//
	// travelSegment (or BoardingScope) has already
	// been discarded by ManifestProjection and
	// therefore cannot be recovered here.
	//
	// Consequently, the authorizer correctly
	// authorizes the runtime context it receives,
	// completing the cascading trust failure.
	//
	// ======================================================
	//

	if context.RuntimeIdentity == "" {

		return errors.New(

			"runtime identity missing",
		)
	}

	if context.BoardingPassID == "" {

		return errors.New(

			"boarding pass missing",
		)
	}

	if context.BookingID == "" {

		return errors.New(

			"booking identifier missing",
		)
	}

	if context.PassengerID == "" {

		return errors.New(

			"passenger identifier missing",
		)
	}

	if context.FlightNumber == "" {

		return errors.New(

			"flight number missing",
		)
	}

	if context.DepartureAirport == "" {

		return errors.New(

			"departure airport missing",
		)
	}

	if context.ArrivalAirport == "" {

		return errors.New(

			"arrival airport missing",
		)
	}

	if context.BoardingGroup == "" {

		return errors.New(

			"boarding group missing",
		)
	}

	if context.TravelClass == "" {

		return errors.New(

			"travel class missing",
		)
	}

	return nil
}

////////////////////////////////////////////////////////////

func (g *GateAuthorizer) AuthorizeBatch(

	contexts []BoardingContext,

) ([]AuthorizationDecision, error) {

	decisions := make(

		[]AuthorizationDecision,

		0,

		len(contexts),
	)

	for _, context := range contexts {

		decision, err := g.Authorize(

			context,
		)

		if err != nil {

			return nil, err
		}

		decisions = append(

			decisions,

			decision,
		)
	}

	return decisions, nil
}

////////////////////////////////////////////////////////////

func (g *GateAuthorizer) IsAuthorized(

	context BoardingContext,

) bool {

	decision, err := g.Authorize(

		context,
	)

	if err != nil {

		return false
	}

	return decision.Allowed
}
