package ticketing

import reservation.Itinerary
import java.time.LocalDateTime
import java.util.UUID

////////////////////////////////////////////////////////////

class TicketIssuer {

    ////////////////////////////////////////////////////////

    fun issueAuthorization(

        itinerary: Itinerary

    ): BoardingAuthorization {

        validate(

            itinerary

        )

        val authorization =

            BoardingAuthorization(

                authorizationId =

                    generateAuthorizationId(),

                boardingPassId =

                    generateBoardingPassId(

                        itinerary

                    ),

                bookingId =

                    itinerary.bookingId,

                passengerId =

                    itinerary.passengerId,

                flightNumber =

                    itinerary.flightNumber,

                departureAirport =

                    itinerary.departureAirport,

                arrivalAirport =

                    itinerary.arrivalAirport,

                travelSegment =

                    itinerary.travelSegment,

                boardingGroup =

                    itinerary.boardingGroup,

                travelClass =

                    itinerary.travelClass,

                issuedAt =

                    LocalDateTime.now(),

                expiresAt =

                    LocalDateTime.now()

                        .plusHours(6),

                status =

                    AuthorizationStatus.APPROVED
            )

        return authorization
    }

    ////////////////////////////////////////////////////////

    fun reissueAuthorization(

        authorization: BoardingAuthorization

    ): BoardingAuthorization {

        validate(

            authorization

        )

        return authorization.copy(

            authorizationId =

                generateAuthorizationId(),

            issuedAt =

                LocalDateTime.now(),

            expiresAt =

                LocalDateTime.now()

                    .plusHours(6)

        )
    }

    ////////////////////////////////////////////////////////

    private fun validate(

        itinerary: Itinerary

    ) {

        require(

            itinerary.bookingId.isNotBlank()

        )

        require(

            itinerary.passengerId.isNotBlank()

        )

        require(

            itinerary.flightNumber.isNotBlank()

        )

        require(

            itinerary.travelSegment.isNotBlank()

        )

        require(

            itinerary.boardingGroup.isNotBlank()

        )

        require(

            itinerary.travelClass.isNotBlank()

        )
    }

    ////////////////////////////////////////////////////////

    private fun validate(

        authorization: BoardingAuthorization

    ) {

        require(

            authorization.authorizationId.isNotBlank()

        )

        require(

            authorization.boardingPassId.isNotBlank()

        )

        require(

            authorization.travelSegment.isNotBlank()

        )

        require(

            authorization.status ==

                AuthorizationStatus.APPROVED

        )
    }

    ////////////////////////////////////////////////////////

    private fun generateAuthorizationId(): String {

