////////////////////////////////////////////////////////////

#[derive(Clone, Debug)]
pub struct BoardingRecord {

    pub runtime_identity: String,

    pub boarding_pass_id: String,

    pub booking_id: String,

    pub passenger_id: String,

    pub flight_number: String,

    pub departure_airport: String,

    pub arrival_airport: String,

    pub boarding_group: String,

    pub travel_class: String,
}

////////////////////////////////////////////////////////////

pub struct BoardingCodec;

////////////////////////////////////////////////////////////

impl BoardingCodec {

    ////////////////////////////////////////////////////////

    pub fn encode(

        record: &BoardingRecord,

    ) -> HashMap<String, String> {

        let mut payload =

            HashMap::new();

        payload.insert(

            "runtime_identity".into(),

            record.runtime_identity.clone()

        );

        payload.insert(

            "boarding_pass_id".into(),

            record.boarding_pass_id.clone()

        );

        payload.insert(

            "booking_id".into(),

            record.booking_id.clone()

        );

        payload.insert(

            "passenger_id".into(),

            record.passenger_id.clone()

        );

        payload.insert(

            "flight_number".into(),

            record.flight_number.clone()

        );

        payload.insert(

            "departure_airport".into(),

            record.departure_airport.clone()

        );

        payload.insert(

            "arrival_airport".into(),

            record.arrival_airport.clone()

        );

        payload.insert(

            "boarding_group".into(),

            record.boarding_group.clone()

        );

        payload.insert(

            "travel_class".into(),

            record.travel_class.clone()

        );

        payload
    }

    ////////////////////////////////////////////////////////

    pub fn decode(

        payload: &HashMap<String, String>,

    ) -> Result<BoardingRecord, String> {

        Ok(

            BoardingRecord {

                runtime_identity:

                    Self::required(

                        payload,

                        "runtime_identity"

                    )?,

                boarding_pass_id:

                    Self::required(

                        payload,

                        "boarding_pass_id"

                    )?,

                booking_id:

                    Self::required(

                        payload,

                        "booking_id"

                    )?,

                passenger_id:

                    Self::required(

                        payload,

                        "passenger_id"

                    )?,

                flight_number:

                    Self::required(

                        payload,

                        "flight_number"

                    )?,

                departure_airport:

                    Self::required(

                        payload,

                        "departure_airport"

                    )?,

                arrival_airport:

                    Self::required(

                        payload,

                        "arrival_airport"

                    )?,

                boarding_group:

                    Self::required(

                        payload,

                        "boarding_group"

                    )?,

                travel_class:

                    Self::required(

                        payload,

                        "travel_class"

                    )?,
            }

        )
    }

    ////////////////////////////////////////////////////////

    fn required(

        payload: &HashMap<String, String>,

        key: &str,

    ) -> Result<String, String> {

        payload

            .get(key)

            .cloned()

            .ok_or_else(

                || format!(

                    "{} missing",

                    key

                )

            )
    }
}

