package issuance

import java.time.Instant
import java.util.UUID

class CredentialIssuer(

    repository: CredentialRepository,
    signer: CredentialSigner,
    policy: IssuancePolicy

) {

    //------------------------------------------------------------------

    def issue(

        request: CredentialIssuanceRequest

    ): IssuedCredential = {

        validateRequest(

            request

        )

        policy.validateIssuer(

            request.issuerId,

            request.credentialType

        )

        val credential =

            buildCredential(

                request

            )

        val signature =

            signer.sign(

                credential.digest()

            )

        val issued =

            credential.withSignature(

                signature

            )

        repository.store(

            issued

        )

        issued

    }

    //------------------------------------------------------------------

    private def validateRequest(

        request: CredentialIssuanceRequest

    ): Unit = {

        require(

            request.studentId.nonEmpty,

            "Student identifier missing."

        )

        require(

            request.issuerId.nonEmpty,

            "Issuer identifier missing."

        )

        require(

            request.credentialType.nonEmpty,

            "Credential type missing."

        )

        require(

            request.delegationScope.nonEmpty,

            "Delegation scope missing."

        )

        require(

            request.revocationGeneration > 0,

            "Invalid revocation generation."

        )

    }

    //------------------------------------------------------------------

    private def buildCredential(

        request: CredentialIssuanceRequest

    ): Credential = {

        Credential(

            credentialId = UUID.randomUUID().toString,

            studentId = request.studentId,

            issuerId = request.issuerId,

            credentialType = request.credentialType,

            issuedAt = Instant.now(),

            status = CredentialStatus.Active,

            delegationScope = request.delegationScope,

            revocationGeneration =

                request.revocationGeneration,

            metadata = request.metadata

        )

    }

}
