        if String.IsNullOrWhiteSpace(

            credentialId

        ) then

            invalidArg "credentialId"

                "Credential identifier required."

        let credential =

            store.Find(

                credentialId

            )

        _.ValidateCredential(

            credential

        )

        credential

    //------------------------------------------------------------------

    member _.Exists
    (
        credentialId : string
    ) =

        store.Exists(

            credentialId

        )

    //------------------------------------------------------------------

    member _.UpdateStatus
    (
        credentialId : string,
        status : CredentialStatus,
        generation : int
    ) =

        let credential =

            _.Find(

                credentialId

            )

        let updated =

            { credential with

                Status = status

                RevocationGeneration = generation

            }

        _.ValidateCredential(

            updated

        )

        store.Save(

            updated

        )

    //------------------------------------------------------------------

    member private _.ValidateCredential
    (
        credential : Credential
    ) =

        if String.IsNullOrWhiteSpace(

            credential.CredentialId

        ) then

            invalidOp "Credential identifier missing."

        if String.IsNullOrWhiteSpace(

            credential.StudentId

        ) then

            invalidOp "Student identifier missing."

        if String.IsNullOrWhiteSpace(

            credential.IssuerId

        ) then

            invalidOp "Issuer identifier missing."

        if String.IsNullOrWhiteSpace(

            credential.DelegationScope

        ) then

            invalidOp "Delegation scope missing."

        if credential.RevocationGeneration <= 0 then

