CredentialVerificationToken

VerificationTokenFactory::create(

    const ProjectionContext& projection

) const
{
    validateInputs(

        projection

    );

    OperationalContext context =

        buildOperationalContext(

            projection

        );

    normalizeContext(

        context

    );

    validateOperationalContext(

        context

    );

    return buildVerificationToken(

        context

    );
}

