void VerificationTokenFactory::validateIdentity(

    const OperationalContext& context

) const
{
    if (context.credentialId.empty())
    {
        throw std::runtime_error(

            "Credential identifier missing."

        );
    }

    if (context.studentId.empty())
    {
        throw std::runtime_error(

            "Student identifier missing."

        );
    }

    if (context.issuerId.empty())
    {
        throw std::runtime_error(

            "Issuer identifier missing."

        );
    }
}

//---------------------------------------------------------------------

void VerificationTokenFactory::validateDelegation(

    const OperationalContext& context

) const
{
    if (context.delegationScope.empty())
    {
        throw std::runtime_error(

            "Delegation scope missing."

        );
    }

    if (context.status.empty())
    {
        throw std::runtime_error(

            "Credential status missing."

        );
    }
}

//---------------------------------------------------------------------

void VerificationTokenFactory::validateLifecycle(

    const OperationalContext& context

) const
{
    if (context.revocationGeneration <= 0)
    {
        throw std::runtime_error(

            "Invalid revocation generation."

        );
    }

    if (context.expiresAt <= context.issuedAt)
    {
        throw std::runtime_error(

            "Credential lifetime invalid."

        );
    }
}

//---------------------------------------------------------------------

void VerificationTokenFactory::validateVersion(

    const OperationalContext& context

) const
{
    if (context.version <= 0)
    {
        throw std::runtime_error(

