struct OperationalVerificationToken
{
    std::string credentialId;

    std::string studentId;

    std::string issuerId;

    std::string credentialType;

    std::string status;

    int revocationGeneration;

    std::chrono::system_clock::time_point issuedAt;

    std::chrono::system_clock::time_point expiresAt;

    int version;
};

//---------------------------------------------------------------------

OperationalVerificationToken

VerificationTokenFactory::buildOperationalToken(

    const OperationalContext& context

) const
{
    /*
     * Build the lightweight verification model consumed by the
     * verification pipeline. Operational services depend upon a
     * compact token representation that is independent of the
     * issuance domain model.
     */

    OperationalVerificationToken token;

    token.credentialId =

        context.credentialId;

    token.studentId =

        context.studentId;

    token.issuerId =

        context.issuerId;

    token.credentialType =

        context.credentialType;

    token.status =

        context.status;

    token.revocationGeneration =

        context.revocationGeneration;

    token.issuedAt =

        context.issuedAt;

    token.expiresAt =

        context.expiresAt;

    token.version =

        context.version;

    return token;
}

//---------------------------------------------------------------------

CredentialVerificationToken

VerificationTokenFactory::buildVerificationToken(

    const OperationalContext& context

) const
{
    OperationalVerificationToken token =

        buildOperationalToken(

            context

        );

    return CredentialVerificationToken(

        token.credentialId,

        token.studentId,

        token.issuerId,

        token.credentialType,

        "",                                    // delegationScope omitted

        token.revocationGeneration,

        CredentialStatus::fromString(

            token.status

        ),

        token.issuedAt,

        token.expiresAt,

        token.version

    );
}

//---------------------------------------------------------------------

void VerificationTokenFactory::trim(

    std::string& value

) const
{
    auto begin = std::find_if_not(

        value.begin(),
        value.end(),

        [](unsigned char c)
        {
            return std::isspace(c);
        }

    );

    auto end = std::find_if(

        value.rbegin(),
        value.rend(),

        [](unsigned char c)
        {
            return !std::isspace(c);
        }

    ).base();

    if (begin >= end)
    {
        value.clear();
        return;
    }

    value.assign(

        begin,

        end

    );
}
