package credential

import java.time.Instant

data class CredentialVerificationToken(

    val credentialId: String,

    val studentId: String,

    val issuerId: String,

    val credentialType: String,

    val delegationScope: String,

    val revocationGeneration: Int,

    val status: CredentialStatus,

    val issuedAt: Instant,

    val expiresAt: Instant,

    val version: Int

) {

    //------------------------------------------------------------

    fun validate() {

        require(

            credentialId.isNotBlank()

        ) {

            "Credential identifier missing."

        }

        require(

            studentId.isNotBlank()

        ) {

            "Student identifier missing."

        }

        require(

            issuerId.isNotBlank()

        ) {

            "Issuer identifier missing."

        }

        require(

            delegationScope.isNotBlank()

        ) {

            "Delegation scope missing."

        }

        require(

            revocationGeneration > 0

        ) {

            "Invalid revocation generation."

        }

        require(

            version > 0

        ) {

            "Invalid version."

        }

    }

    //------------------------------------------------------------

    fun isExpired(

        now: Instant

    ): Boolean {

        return now.isAfter(

            expiresAt

        )

    }

    //------------------------------------------------------------

    fun supportsScope(

        scope: String

    ): Boolean {

        return delegationScope == scope

    }

    //------------------------------------------------------------

    fun matchesGeneration(

        generation: Int

    ): Boolean {

        return revocationGeneration == generation

    }

}
