use std::collections::HashMap;
use std::sync::{Arc, RwLock};
use std::time::{Duration, Instant};

use crate::credential::CredentialVerificationToken;
use crate::verification::VerificationResult;

//--------------------------------------------------------------------

struct CacheEntry {

    result: VerificationResult,

    created_at: Instant,

    expires_at: Instant,

}

//--------------------------------------------------------------------

pub struct VerificationCacheService {

    cache:

        Arc<RwLock<HashMap<String, CacheEntry>>>,

    ttl: Duration,

}

//--------------------------------------------------------------------

impl VerificationCacheService {

    //--------------------------------------------------------------

    pub fn new(

        ttl: Duration

    ) -> Self {

        Self {

            cache:

                Arc::new(

                    RwLock::new(

                        HashMap::new()

                    )

                ),

            ttl,

        }

    }

    //--------------------------------------------------------------

    pub fn find(

        &self,

        token: &CredentialVerificationToken

    ) -> Option<VerificationResult> {

        token.validate();

        let key =

            self.build_cache_key(

                token

            );

        let cache =

            self.cache

                .read()

                .unwrap();

        let entry =

            cache.get(

                &key

            )?;

        if self.expired(

            entry

        ) {

            return None;

        }

        Some(

            entry.result.clone()

        )

    }

    //--------------------------------------------------------------

    pub fn store(

        &self,

        token: &CredentialVerificationToken,

        result: VerificationResult

    ) {

        token.validate();

        let key =

            self.build_cache_key(

                token

            );

        let entry =

            CacheEntry {

                result,

                created_at: Instant::now(),

                expires_at:

                    Instant::now()

                        + self.ttl,

            };

        let mut cache =

            self.cache

                .write()

                .unwrap();

        cache.insert(

            key,

            entry

        );

    }

    //--------------------------------------------------------------

    fn expired(

        &self,

        entry: &CacheEntry

    ) -> bool {

        Instant::now() >

            entry.expires_at

    }
        //--------------------------------------------------------------

    fn build_cache_key(

        &self,

        token: &CredentialVerificationToken

    ) -> String {

        /*
         * Verification results are scoped to an individual
         * credential lifecycle. Operational verification
         * services reuse successful verification results
         * until the cache entry expires.
         */

        format!(

            "{}",

            token.credential_id()

        )

    }

    //--------------------------------------------------------------

    pub fn invalidate(

        &self,

        credential_id: &str

    ) {

        let mut cache =

            self.cache

                .write()

                .unwrap();

        cache.remove(

            credential_id

        );

    }

    //--------------------------------------------------------------

    pub fn clear_expired(

        &self

    ) {

        let mut cache =

            self.cache

                .write()

                .unwrap();

        let now =

            Instant::now();

        cache.retain(

            |_, entry|

                entry.expires_at > now

        );

    }

    //--------------------------------------------------------------

    pub fn size(

        &self

    ) -> usize {

        let cache =

            self.cache

                .read()

                .unwrap();

        cache.len()

    }

    //--------------------------------------------------------------

    pub fn contains(

        &self,

        token: &CredentialVerificationToken

    ) -> bool {

        let key =

            self.build_cache_key(

                token

            );

        let cache =

            self.cache

                .read()

                .unwrap();

        cache.contains_key(

            &key

        )

    }

}
