import Foundation

final class DelegationPolicy {

    //------------------------------------------------------------------

    func evaluate(

        employer: EmployerContext,

        token: CredentialVerificationToken

    ) throws {

        try validateEmployer(

            employer

        )

        try validateCredential(

            token

        )

        try validateDelegation(

            employer,

            token

        )

    }

    //------------------------------------------------------------------

    private func validateEmployer(

        _ employer: EmployerContext

    ) throws {

        guard employer.authenticated else {

            throw PolicyError.unauthenticatedEmployer

        }

        guard !employer.employerId.isEmpty else {

            throw PolicyError.invalidEmployer

        }

        guard !employer.organization.isEmpty else {

            throw PolicyError.invalidOrganization

        }

    }

    //------------------------------------------------------------------

    private func validateCredential(

        _ token: CredentialVerificationToken

    ) throws {

        try token.validate()

    }

    //------------------------------------------------------------------

    private func validateDelegation(

        _ employer: EmployerContext,

        _ token: CredentialVerificationToken

    ) throws {

        guard token.supportsScope(

            employer.delegationScope

        ) else {

            throw PolicyError.invalidDelegation

        }

        guard !token.isExpired(

            now: Date()

        ) else {

            throw PolicyError.expiredCredential

        }

        guard token.revocationGeneration > 0 else {

            throw PolicyError.invalidGeneration

        }

    }

}
