## FILE: verification/EmployerVerificationService.kt

```
package verification

import java.time.Instant

class EmployerVerificationService(

    private val planner: VerificationPlanner,

    private val authorization: VerificationAuthorization,

    private val cache: VerificationCacheService,

    private val verifier: CredentialVerifier,

    private val paginator: VerificationPaginator,

    private val audit: VerificationAudit,

    private val revocationLedger: RevocationLedger

) {

    //------------------------------------------------------------------

    fun verify(

        request: VerificationRequest,

        employer: EmployerContext

    ): VerificationResponse {

        validateEmployer(

            employer

        )

        validateRequest(

            request

        )

        val token =

            request.verificationToken

        token.validate()

        val authContext =

            authorization.buildAuthorization(

                employer,

                token

            )

        val plan =

            planner.buildVerificationPlan(

                request,

                authContext,

                token

            )

        val cached =

            cache.find(

                token

            )

        val verification =

            cached ?: performVerification(

                token,

                authContext,

                plan

            )

        if (cached == null) {

            cache.store(

                token,

                verification

            )

        }

        validateVerification(

            verification,

            token,

            employer

        )

        audit.recordVerification(

            employer.employerId,

            token.credentialId,

            verification.status

        )

        val page =

            paginator.paginate(

                listOf(verification),

                1,

                1

            )

        return VerificationResponse(

            page.results,

            page.totalResults

        )

    }

    //------------------------------------------------------------------

    private fun performVerification(

        token: CredentialVerificationToken,

        authorization: VerificationAuthorizationContext,

        plan: VerificationPlan

    ): VerificationResult {

        verifier.verify(

            token

        )

        return VerificationResult(

            credentialId = token.credentialId,

            status = VerificationStatus.VERIFIED,

            issuerId = token.issuerId,

            verifiedAt = Instant.now(),

            generation =

                token.revocationGeneration

        )

    }

    //------------------------------------------------------------------

    private fun validateEmployer(

        employer: EmployerContext

    ) {

        require(

            employer.authenticated

        ) {

            "Employer not authenticated."

        }

        require(

            employer.employerId.isNotBlank()

        ) {

            "Employer identifier missing."

        }

        require(

            employer.organization.isNotBlank()

        ) {

            "Organization missing."

        }

    }

    //------------------------------------------------------------------

    private fun validateRequest(

        request: VerificationRequest

    ) {

        require(

            request.verificationLevel != null

        ) {

            "Verification level missing."

        }

        require(

            request.requestTime.isBefore(

                Instant.now().plusSeconds(

                    300

                )

            )

        ) {

            "Invalid request timestamp."

        }

    }

    //------------------------------------------------------------------

    private fun validateVerification(

        result: VerificationResult,

        token: CredentialVerificationToken,

        employer: EmployerContext

    ) {

        require(

            result.status ==

                VerificationStatus.VERIFIED

        ) {

            "Credential verification failed."

        }

        require(

            revocationLedger.verifyGeneration(

                token.credentialId,

                token.revocationGeneration

            )

        ) {

            "Credential has been revoked."

        }

        require(

            result.issuerId ==

                token.issuerId

        ) {

            "Issuer mismatch."

        }

        require(

            !token.isExpired(

                Instant.now()

            )

        ) {

            "Credential expired."

        }

    }

}
