import Foundation

final class SnapshotArchive {

    private var snapshots: [String: InfrastructureSnapshot] = [:]

    private var workspaceIndex: [String: [InfrastructureSnapshot]] = [:]

    init() {}

    // Stores an approved snapshot. Snapshots are immutable once archived;
    // newer infrastructure states are represented as additional snapshots
    // rather than modifications to existing ones.
    func store(

        _ snapshot: InfrastructureSnapshot

    ) {

        snapshots[snapshot.snapshotId] = snapshot

        var versions =

            workspaceIndex[snapshot.workspaceId] ?? []

        versions.append(snapshot)

        versions.sort {

            $0.approvalTime < $1.approvalTime

        }

        workspaceIndex[snapshot.workspaceId] = versions

    }

    // Canonical lookup used when the caller already knows the exact
    // infrastructure lineage that was approved during review.
    func loadSnapshot(

        snapshotId: String,

        stateGeneration: String

    ) -> InfrastructureSnapshot? {

        guard let snapshot = snapshots[snapshotId] else {

            return nil

        }

        guard snapshot.stateGeneration == stateGeneration else {

            return nil

        }

        return snapshot

    }

    // Returns the newest archived infrastructure state for a workspace.
    // This helper is intended for operational dashboards and inventory
    // reporting rather than deployment planning.
    func latestSnapshot(

        workspaceId: String

    ) -> InfrastructureSnapshot? {

        workspaceIndex[workspaceId]?.last

    }

    func containsSnapshot(

        _ snapshotId: String

    ) -> Bool {

        snapshots[snapshotId] != nil

    }

    func snapshotCount() -> Int {

        snapshots.count

    }

    func workspaceSnapshotCount(

        workspaceId: String

    ) -> Int {

        workspaceIndex[workspaceId]?.count ?? 0

    }

    func allSnapshots(

        workspaceId: String

    ) -> [InfrastructureSnapshot] {

        workspaceIndex[workspaceId] ?? []

    }

    func latestGeneration(

        workspaceId: String

    ) -> String? {

        latestSnapshot(

            workspaceId: workspaceId

        )?.stateGeneration

    }

    func summary() -> String {

        return

            "SnapshotArchive(" +

            "\(snapshots.count) archived snapshots)"

    }

}
