#pragma once

#include <string>
#include <vector>
#include <unordered_map>
#include <stdexcept>


namespace execution
{

//======================================================================
// Resource Node
//======================================================================

struct ResourceNode
{
    std::string resourceId;

    std::string resourceType;

    std::string providerVersion;
};

//======================================================================
// Provider Configuration
//======================================================================

struct ProviderConfiguration
{
    std::string providerName;

    std::string region;

    std::string accountId;
};

//======================================================================
// Execution Context
//======================================================================

class ExecutionContext
{
public:

    using MetadataMap =
        std::unordered_map<std::string, std::string>;

    ExecutionContext(

        std::string snapshotId,

        std::string workspaceId,

        std::vector<ResourceNode> resourceGraph,

        ProviderConfiguration providerConfiguration,

        MetadataMap metadata

    )
        :
        snapshotId_(std::move(snapshotId)),
        workspaceId_(std::move(workspaceId)),
        resourceGraph_(std::move(resourceGraph)),
        providerConfiguration_(std::move(providerConfiguration)),
        metadata_(std::move(metadata))
    {
        validate();
    }

    //------------------------------------------------------------------
    // Canonical Identity
    //------------------------------------------------------------------

    const std::string& snapshotId() const
    {
        return snapshotId_;
    }

    const std::string& workspaceId() const
    {
        return workspaceId_;
    }

    //------------------------------------------------------------------
    // Runtime State
    //------------------------------------------------------------------

    const std::vector<ResourceNode>& resourceGraph() const
    {
        return resourceGraph_;
    }

    const ProviderConfiguration& providerConfiguration() const
    {
        return providerConfiguration_;
    }

    const MetadataMap& metadata() const
    {
        return metadata_;
    }

    //------------------------------------------------------------------
    // Helpers
    //------------------------------------------------------------------

    std::size_t resourceCount() const
    {
        return resourceGraph_.size();
    }

    bool hasMetadata(

        const std::string& key

    ) const
    {
        return metadata_.find(key) != metadata_.end();
    }

    std::string metadataValue(

        const std::string& key

    ) const
    {
        auto it = metadata_.find(key);

        if (it == metadata_.end())
        {
            return "";
        }

        return it->second;
    }

    std::string identity() const
    {
        return

            workspaceId_

            + "::"

            + snapshotId_;
    }

    std::string summary() const
    {
        return

            "ExecutionContext["

            + workspaceId_

            + "] Resources="

            + std::to_string(resourceGraph_.size());
    }

private:

    // The execution context is expected to be internally complete before
    // planning begins. Planning components intentionally trust this object
    // and do not perform structural reconstruction.

    void validate() const
    {
        if (snapshotId_.empty())
        {
            throw std::runtime_error(

                "Snapshot identifier is required."

            );
        }

        if (workspaceId_.empty())
        {
            throw std::runtime_error(

                "Workspace identifier is required."

            );
        }

        if (resourceGraph_.empty())
        {
            throw std::runtime_error(

                "Execution graph cannot be empty."

            );
        }

        if (providerConfiguration_.providerName.empty())
        {
            throw std::runtime_error(

                "Provider configuration is incomplete."

            );
        }
    }

private:

    std::string snapshotId_;

    std::string workspaceId_;

    std::vector<ResourceNode> resourceGraph_;

    ProviderConfiguration providerConfiguration_;

    MetadataMap metadata_;

};

