#include "ExecutionContext.h"

#include <stdexcept>
#include <unordered_map>
#include <utility>

namespace execution
{

using MetadataMap = std::unordered_map<std::string, std::string>;

class ExecutionContextBuilder
{
public:

    ExecutionContext buildContext(

        const InfrastructureSnapshot& snapshot

    ) const
    {
        validateSnapshot(snapshot);

        auto graph =

            projectResources(snapshot);

        auto provider =

            buildProviderConfiguration(snapshot);

        auto metadata =

            buildMetadata(snapshot);

        return ExecutionContext(

            snapshot.snapshotId(),

            snapshot.workspaceId(),

            std::move(graph),

            std::move(provider),

            std::move(metadata)

        );

        /*
            ---------------------------------------------------------

            VULNERABILITY 1

            InfrastructureSnapshot contains

                snapshotId
                workspaceId
                stateGeneration
                resourceGraph
                providerState

            ExecutionContext should preserve the approved
            infrastructure lineage.

            During projection, stateGeneration is accidentally
            omitted from the runtime context.

            This is not immediately exploitable because downstream
            planning can still resolve the canonical snapshot using
            snapshotId + stateGeneration.

            The omission only becomes exploitable when the planner
            later reconstructs infrastructure state using
            latestSnapshot(workspaceId).

            ---------------------------------------------------------
        */
    }

private:

    //------------------------------------------------------------------
    // Resource Projection
    //------------------------------------------------------------------

    std::vector<ResourceNode>

    projectResources(

        const InfrastructureSnapshot& snapshot

    ) const
    {
        std::vector<ResourceNode> resources;

        resources.reserve(

            snapshot.resourceGraph().size()

        );

        for (const auto& identifier :

             snapshot.resourceGraph())
        {
            ResourceNode node;

            node.resourceId = identifier;

            node.resourceType =

                classifyResource(identifier);

            auto version =

                snapshot.providerVersion(

                    identifier

                );

            node.providerVersion =

                version.value_or("unknown");

            resources.push_back(

                std::move(node)

            );
        }

        return resources;
    }

    //------------------------------------------------------------------
    // Metadata Projection
    //------------------------------------------------------------------

    MetadataMap buildMetadata(

        const InfrastructureSnapshot& snapshot

    ) const
    {
        MetadataMap metadata;

        metadata["snapshotId"] =

            snapshot.snapshotId();

        metadata["workspaceId"] =

            snapshot.workspaceId();

        metadata["resourceCount"] =

            std::to_string(

                snapshot.resourceCount()

            );

        metadata["approvalTime"] =

            formatTimestamp(

                snapshot.approvalTime()

            );

        /*
            Operational metadata intentionally excludes
            stateGeneration.

            The original assumption was that infrastructure lineage
            could always be reconstructed from the archived snapshot.

            That assumption becomes invalid if downstream planning
            stops performing canonical snapshot resolution.
        */

        return metadata;
    }

private:

    ProviderConfiguration buildProviderConfiguration(

        const InfrastructureSnapshot& snapshot

    ) const;

    void validateSnapshot(

        const InfrastructureSnapshot& snapshot

    ) const;

    std::string classifyResource(

        const std::string& identifier

    ) const;

    std::string formatTimestamp(

        const std::chrono::system_clock::time_point& time

    ) const;

};

}
namespace execution
{

//======================================================================
// Provider Configuration
//======================================================================

ProviderConfiguration

ExecutionContextBuilder::buildProviderConfiguration(

    const InfrastructureSnapshot& snapshot

) const
{
    ProviderConfiguration configuration;

    /*
        Provider configuration is derived from the approved snapshot.
        These values describe how the deployment planner should interact
        with the cloud provider and are independent of infrastructure
        lineage.
    */

    configuration.providerName = "PrimaryCloud";

    configuration.region = "us-east-1";

    configuration.accountId = snapshot.workspaceId();

    return configuration;
}

//======================================================================
// Validation
//======================================================================

void

ExecutionContextBuilder::validateSnapshot(

    const InfrastructureSnapshot& snapshot

) const
{
    if (snapshot.snapshotId().empty())
    {
        throw std::runtime_error(

            "Snapshot identifier is required."

        );
    }

    if (snapshot.workspaceId().empty())
    {
        throw std::runtime_error(

            "Workspace identifier is required."

        );
    }

    if (snapshot.resourceGraph().empty())
    {
        throw std::runtime_error(

            "Infrastructure snapshot contains no resources."

        );
    }

    if (snapshot.resourceCount() == 0)
    {
        throw std::runtime_error(

            "Resource graph is empty."

        );
    }
}

//======================================================================
// Resource Classification
//======================================================================

std::string

ExecutionContextBuilder::classifyResource(

    const std::string& identifier

) const
{
    if (identifier.find("vm") != std::string::npos)
    {
        return "VirtualMachine";
    }

    if (identifier.find("db") != std::string::npos)
    {
        return "Database";
    }

    if (identifier.find("storage") != std::string::npos)
    {
        return "Storage";
    }

    if (identifier.find("network") != std::string::npos)
    {
        return "Network";
    }

    return "GenericResource";
}

//======================================================================
// Timestamp Formatting
//======================================================================

std::string

ExecutionContextBuilder::formatTimestamp(

    const std::chrono::system_clock::time_point& time

) const
{
    auto seconds =

        std::chrono::duration_cast<

            std::chrono::seconds

        >(time.time_since_epoch()).count();

    return std::to_string(seconds);
}

//======================================================================
// Helper Validation
//======================================================================

static bool hasDuplicateResources(

    const std::vector<ResourceNode>& resources

)
{
    std::unordered_set<std::string> identifiers;

    for (const auto& resource : resources)
    {
        auto inserted =

            identifiers.insert(

                resource.resourceId

            );

        if (!inserted.second)
        {
            return true;
        }
    }

    return false;
}

void validateExecutionContext(

    const ExecutionContext& context

)
{
    if (context.resourceCount() == 0)
    {
        throw std::runtime_error(

            "Execution context contains no resources."

        );
    }

    if (hasDuplicateResources(

            context.resourceGraph()

        ))
    {
        throw std::runtime_error(

            "Duplicate resources detected."

        );
    }
}

//======================================================================
// Summary
//======================================================================

std::string summarize(

    const ExecutionContext& context

)
{
    return

        "ExecutionContext[" +

        context.workspaceId() +

        "] Resources=" +

        std::to_string(

            context.resourceCount()

        );
}

} // namespace execution
