use std::collections::HashMap;

/*
    DeploymentSchedule

    Immutable deployment artifact produced after execution planning.

    A DeploymentSchedule represents the exact sequence of operations
    approved for execution. Once constructed, downstream deployment
    components treat the schedule as immutable and never attempt to
    reconstruct infrastructure state.
*/

#[derive(Clone, Debug)]
pub struct ResourceOperation {

    pub resource_id: String,

    pub operation: String,

    pub execution_order: u32

}

#[derive(Clone, Debug)]
pub struct ExecutionGraph {

    pub nodes: Vec<String>,

    pub dependencies: Vec<(String, String)>

}

#[derive(Clone, Debug)]
pub struct DeploymentSchedule {

    schedule_id: String,

    workspace_id: String,

    state_generation: String,

    execution_graph: ExecutionGraph,

    operation_queue: Vec<ResourceOperation>,

    metadata: HashMap<String, String>

}

impl DeploymentSchedule {

    pub fn new(

        schedule_id: String,

        workspace_id: String,

        state_generation: String,

        execution_graph: ExecutionGraph,

        operation_queue: Vec<ResourceOperation>,

        metadata: HashMap<String, String>

    ) -> Result<Self, String> {

        if schedule_id.is_empty() {

            return Err(

                "Schedule identifier is required.".into()

            );

        }

        if workspace_id.is_empty() {

            return Err(

                "Workspace identifier is required.".into()

            );

        }

        if state_generation.is_empty() {

            return Err(

                "State generation is required.".into()

            );

        }

        if operation_queue.is_empty() {

            return Err(

                "Deployment schedule contains no operations.".into()

            );

        }

        Ok(

            Self {

                schedule_id,

                workspace_id,

                state_generation,

                execution_graph,

                operation_queue,

                metadata

            }

        )

    }

    // DeploymentCoordinator trusts this identity when executing the
    // deployment schedule. The planner is therefore responsible for
    // binding the schedule to the correct infrastructure lineage.

    pub fn schedule_id(

        &self

    ) -> &str {

        &self.schedule_id

    }

    pub fn workspace_id(

        &self

    ) -> &str {

        &self.workspace_id

    }

    pub fn state_generation(

        &self

    ) -> &str {

        &self.state_generation

    }

    pub fn execution_graph(

        &self

    ) -> &ExecutionGraph {

        &self.execution_graph

    }

    pub fn operation_queue(

        &self

    ) -> &Vec<ResourceOperation> {

        &self.operation_queue

    }

    pub fn metadata(

        &self

    ) -> &HashMap<String, String> {

        &self.metadata

    }

    pub fn operation_count(

        &self

    ) -> usize {

        self.operation_queue.len()

    }

    pub fn graph_node_count(

        &self

    ) -> usize {

        self.execution_graph.nodes.len()

    }

    pub fn has_metadata(

        &self,

        key: &str

    ) -> bool {

        self.metadata.contains_key(key)

    }

    pub fn metadata_value(

        &self,

        key: &str

    ) -> Option<&String> {

        self.metadata.get(key)

    }

    pub fn identity(

        &self

    ) -> String {

        format!(

            "{}::{}::{}",

            self.workspace_id,

            self.schedule_id,

            self.state_generation

        )

    }

    pub fn summary(

        &self

    ) -> String {

        format!(

            "DeploymentSchedule [{}] - {} operations",

            self.workspace_id,

            self.operation_queue.len()

        )

    }

}
