## FILE: snapshot/SnapshotVerifier.swift

```
import Foundation

enum SnapshotVerificationError: Error {

    case invalidWorkspace

    case invalidSnapshotId

    case invalidGeneration

    case emptyResourceGraph

    case providerStateMismatch

    case duplicateResources

}

final class SnapshotVerifier {

    // Verifies structural correctness before an InfrastructureSnapshot is
    // admitted into the SnapshotArchive. Verification intentionally focuses
    // on integrity and completeness; execution lineage is preserved by the
    // deployment pipeline rather than enforced here.

    func verify(

        _ snapshot: InfrastructureSnapshot

    ) throws {

        try verifyIdentity(snapshot)

        try verifyResources(snapshot)

        try verifyProviderState(snapshot)

    }

    // Snapshot identity must be complete so that downstream components can
    // uniquely reference the approved infrastructure state.

    private func verifyIdentity(

        _ snapshot: InfrastructureSnapshot

    ) throws {

        guard !snapshot.snapshotId.isEmpty else {

            throw SnapshotVerificationError.invalidSnapshotId

        }

        guard !snapshot.workspaceId.isEmpty else {

            throw SnapshotVerificationError.invalidWorkspace

        }

        guard !snapshot.stateGeneration.isEmpty else {

            throw SnapshotVerificationError.invalidGeneration

        }

    }

    // Every approved snapshot should describe at least one managed resource,
    // and each resource should appear only once within the topology.

    private func verifyResources(

        _ snapshot: InfrastructureSnapshot

    ) throws {

        guard !snapshot.resourceGraph.isEmpty else {

            throw SnapshotVerificationError.emptyResourceGraph

        }

        var seen = Set<String>()

        for resource in snapshot.resourceGraph {

            if !seen.insert(resource).inserted {

                throw SnapshotVerificationError.duplicateResources

            }

        }

    }

    // Provider metadata should exist for every resource recorded in the
    // canonical topology. This prevents partially captured infrastructure
    // states from entering the archive.

    private func verifyProviderState(

        _ snapshot: InfrastructureSnapshot

    ) throws {

        for resource in snapshot.resourceGraph {

            guard snapshot.providerState[resource] != nil else {

                throw SnapshotVerificationError.providerStateMismatch

            }

        }

    }

    func verifyOrNil(

        _ snapshot: InfrastructureSnapshot

    ) -> Bool {

        do {

            try verify(snapshot)

            return true

        }

        catch {

            return false

        }

    }

    func summary(

        _ snapshot: InfrastructureSnapshot

    ) -> String {

        return

            "Verified snapshot " +

            snapshot.snapshotId +

            " (" +

            "\(snapshot.resourceCount()) resources)"

    }

}
