import java.time.Instant

class WorkerExecutor {

    private final CloudAdapter adapter

    WorkerExecutor(

        CloudAdapter adapter

    ) {

        this.adapter = adapter

    }

    //------------------------------------------------------------------
    // Deployment Execution
    //------------------------------------------------------------------

    boolean execute(

        DeploymentSchedule schedule

    ) {

        validate(schedule)

        schedule.operationQueue().each {

            operation ->

            adapter.applyOperation(

                operation

            )

        }

        return true

    }

    //------------------------------------------------------------------
    // Validation
    //------------------------------------------------------------------

    private void validate(

        DeploymentSchedule schedule

    ) {

        if (

            schedule.operationCount() == 0

        ) {

            throw new IllegalStateException(

                "Deployment schedule contains no operations."

            )

        }

    }

    //------------------------------------------------------------------
    // Execution Summary
    //------------------------------------------------------------------

    Map<String, Object> executionSummary(

        DeploymentSchedule schedule

    ) {

        [

            workspace :

                schedule.workspaceId(),

            stateGeneration :

                schedule.stateGeneration(),

            operations :

                schedule.operationCount(),

            completedAt :

                Instant.now()

        ]

    }

}
