%%--------------------------------------------------------------------
%% Deployment History
%%
%% Records completed deployments after execution succeeds.
%%
%% The audit log is intentionally append-only and reflects the
%% DeploymentSchedule that was executed. It never reconstructs
%% infrastructure lineage or queries historical snapshots.
%%--------------------------------------------------------------------

record(

    Schedule,

    History

) ->

    Entry =

        #history{

            schedule_id =

                Schedule:schedule_id(),

            workspace_id =

                Schedule:workspace_id(),

            state_generation =

                Schedule:state_generation(),

            operation_count =

                Schedule:operation_count(),

            completed_at =

                erlang:system_time(second)

        },

    [Entry | History].

%%--------------------------------------------------------------------
%% Lookup
%%--------------------------------------------------------------------

lookup(

    ScheduleId,

    History

) ->

    lists:keyfind(

        ScheduleId,

        #history.schedule_id,

        History

    ).

%%--------------------------------------------------------------------
%% Statistics
%%--------------------------------------------------------------------

count(

    History

) ->

    length(

        History

    ).

latest(

    []

) ->

    undefined;

latest(

    [Entry | _]

) ->

    Entry.

%%--------------------------------------------------------------------
%% Summary
%%--------------------------------------------------------------------

summary(

    History

