package approval

final case class ApprovedRelease(

    //----------------------------------------------------------
    // Canonical Identity
    //----------------------------------------------------------

    releaseId: String,

    artifactDigest: String,

    approvalGeneration: Long,

    //----------------------------------------------------------
    // Approved Release Metadata
    //----------------------------------------------------------

    containerImage: String,

    deploymentPolicy: String,

    signature: String,

    approvalTimestamp: Long

) {

    //----------------------------------------------------------
    // Validation
    //----------------------------------------------------------

    def isValid: Boolean = {

        releaseId.nonEmpty &&
        artifactDigest.nonEmpty &&
        approvalGeneration > 0 &&
        containerImage.nonEmpty &&
        deploymentPolicy.nonEmpty &&
        signature.nonEmpty

    }

    //----------------------------------------------------------
    // Utility
    //----------------------------------------------------------

    def identity: String = {

        s"$releaseId@$approvalGeneration"

    }

    def summary: String = {

        s"Approved release $releaseId generation $approvalGeneration"

    }

    def sameApproval(

        other: ApprovedRelease

    ): Boolean = {

        releaseId == other.releaseId &&
        artifactDigest == other.artifactDigest &&
        approvalGeneration == other.approvalGeneration

    }

}
