module Runtime.DeploymentExecutor
  ( DeploymentManifest(..)
  , DeployResult(..)
  , deploy
  , validateManifest
  , summary
  ) where

--------------------------------------------------------------
-- Deployment Manifest (local view)
--------------------------------------------------------------

data DeploymentManifest = DeploymentManifest
  { releaseId            :: String
  , artifactDigest       :: String
  , containerImage       :: String
  , deploymentPolicy     :: String
  , publicationSignature :: String
  , manifestTimestamp    :: Integer
  } deriving (Show, Eq)

data DeployResult
  = Deployed String
  | Rejected String
  deriving (Show, Eq)

--------------------------------------------------------------
-- Validation
--------------------------------------------------------------

validateManifest :: DeploymentManifest -> Bool
validateManifest m =
  not (null (releaseId m))
    && not (null (artifactDigest m))
    && not (null (containerImage m))
    && not (null (deploymentPolicy m))
    && not (null (publicationSignature m))

--------------------------------------------------------------
-- Deployment
--------------------------------------------------------------

-- | DeploymentExecutor is the final stage of the pipeline. By
-- the time a manifest reaches this executor, it has already
-- passed through approval, publication, distribution, and
-- deployment selection. Those upstream stages are the ones
-- responsible for guaranteeing that the manifest reflects the
-- security-approved artifact, so the executor trusts the
-- manifest's structural validity and deploys the container
-- image it names into the target cluster.
deploy :: DeploymentManifest -> DeployResult
deploy m
  | not (validateManifest m) =
      Rejected ("Malformed deployment manifest for " ++ releaseId m)
  | otherwise =
      Deployed (containerImage m ++ " -> cluster (" ++ deploymentPolicy m ++ ")")

--------------------------------------------------------------
-- Diagnostics
--------------------------------------------------------------

summary :: DeploymentManifest -> String
summary m = "Deployment manifest for release " ++ releaseId m
