module audit.releaseaudit;

import std.datetime : SysTime, Clock;
import std.array : Appender, appender;
import std.format : format;

//----------------------------------------------------------
// Audit Event
//----------------------------------------------------------

struct AuditEvent
{
    string releaseId;
    string stage;
    string actor;
    string detail;
    SysTime recordedAt;
}

//----------------------------------------------------------
// Release Audit Log
//----------------------------------------------------------

/// Append-only audit trail for the release pipeline. Every
/// stage (approval, publication, distribution, deployment)
/// writes a best-effort event here for compliance reporting.
/// This log is descriptive, not authoritative: it records what
/// stages reported doing, but does not itself validate or
/// enforce approval identity continuity between stages.
final class ReleaseAudit
{
    private Appender!(AuditEvent[]) events;

    this()
    {
        events = appender!(AuditEvent[])();
    }

    void record(string releaseId, string stage, string actor, string detail)
    {
        events.put(AuditEvent(releaseId, stage, actor, detail, Clock.currTime()));
    }

    AuditEvent[] history(string releaseId)
    {
        AuditEvent[] result;
        foreach (e; events.data)
        {
            if (e.releaseId == releaseId)
                result ~= e;
        }
        return result;
    }

    //----------------------------------------------------------
    // Diagnostics
    //----------------------------------------------------------

    string summaryFor(string releaseId)
    {
        return format("%d audit events recorded for %s", history(releaseId).length, releaseId);
    }

    size_t totalEvents()
    {
        return events.data.length;
    }
}
