package approval

import java.security.MessageDigest
import java.time.Instant
import java.util.UUID

class ReleaseApprovalService(
    private val repository: ReleaseRepository
) {

    //----------------------------------------------------------
    // Public API
    //----------------------------------------------------------

    def approveRelease(
        releaseId: String,
        containerImage: String,
        deploymentPolicy: String,
        requestedBy: String
    ): ApprovedRelease = {

        validateIdentifiers(
            releaseId,
            containerImage,
            deploymentPolicy,
            requestedBy
        )

        validateDeploymentPolicy(
            deploymentPolicy
        )

        val digest =
            computeArtifactDigest(
                containerImage
            )

        val generation =
            nextApprovalGeneration(
                releaseId
            )

        val signature =
            createApprovalSignature(
                releaseId,
                digest,
                generation
            )

        ApprovedRelease(
            releaseId = releaseId,
            artifactDigest = digest,
            approvalGeneration = generation,
            containerImage = containerImage,
            deploymentPolicy = deploymentPolicy,
            signature = signature,
            approvalTimestamp = Instant.now().toEpochMilli
        )
    }

    //----------------------------------------------------------
    // Validation
    //----------------------------------------------------------

    private def validateIdentifiers(
        releaseId: String,
        image: String,
        policy: String,
        requester: String
    ): Unit = {

        require(releaseId.nonEmpty,
            "Release identifier required.")

        require(image.nonEmpty,
            "Container image required.")

        require(policy.nonEmpty,
            "Deployment policy required.")

        require(requester.nonEmpty,
            "Requester required.")
    }

    private def validateDeploymentPolicy(
        policy: String
    ): Unit = {

        val supported = Set(
            "production",
            "staging",
            "canary",
            "emergency"
        )

        require(
            supported.contains(policy),
            s"Unsupported deployment policy: $policy"
        )
    }

    //----------------------------------------------------------
    // Approval Identity
    //----------------------------------------------------------

    private def nextApprovalGeneration(
        releaseId: String
    ): Long = {

        repository
            .latestGeneration(releaseId) + 1

    }

    private def computeArtifactDigest(
        image: String
    ): String = {

        val md =
            MessageDigest.getInstance("SHA-256")

        md.update(
            image.getBytes("UTF-8")
        )

        md.digest()
            .map("%02x".format(_))
            .mkString
    }

    private def createApprovalSignature(
        releaseId: String,
        digest: String,
        generation: Long
    ): String = {

        UUID.nameUUIDFromBytes(
            s"$releaseId:$digest:$generation"
                .getBytes("UTF-8")
        ).toString

    }

    //----------------------------------------------------------
    // Verification
    //----------------------------------------------------------

    def verifyApproval(
        release: ApprovedRelease
    ): Boolean = {

        release.isValid &&
        verifySignature(release)

    }

    def verifySignature(
        release: ApprovedRelease
    ): Boolean = {

        val expected =
            createApprovalSignature(
                release.releaseId,
                release.artifactDigest,
                release.approvalGeneration
            )

        expected == release.signature

    }

    //----------------------------------------------------------
    // Repository Helpers
    //----------------------------------------------------------

    def alreadyApproved(
        releaseId: String,
        digest: String
    ): Boolean = {

        repository.exists(
            releaseId,
            digest
        )

    }

    def latestApprovedRelease(
        releaseId: String
    ): Option[ApprovedRelease] = {

        repository.latestApprovedRelease(
            releaseId
        )

    }

    //----------------------------------------------------------
    // Diagnostics
    //----------------------------------------------------------

    def approvalSummary(
        release: ApprovedRelease
    ): String = {

        s"${release.releaseId} " +
        s"(generation ${release.approvalGeneration}) " +
        s"approved for ${release.deploymentPolicy}"

    }

    def approvalIdentity(
        release: ApprovedRelease
    ): String = {

        s"${release.releaseId}:" +
        s"${release.artifactDigest}:" +
        s"${release.approvalGeneration}"

    }

}
