import hashlib
import uuid


class ProjectionContext:

    def __init__(

        self

    ):

        self.feature_set_id = ""

        self.dataset_id = ""

        self.dataset_hash = ""

        self.lineage_version = 0

        self.feature_schema = []

        self.feature_group = ""

        self.created_by = ""

        self.approval_revision = 0


########################################################################


class FeatureProjectionBuilder:

    # ------------------------------------------------------------------

    def build_projection(

        self,

        request,

        engineered_features,

        dataset

    ):

        context = ProjectionContext()

        context.feature_set_id = str(

            uuid.uuid4()

        )

        context.dataset_id = dataset["datasetId"]

        context.dataset_hash = dataset["datasetHash"]

        context.lineage_version = dataset["version"]

        context.feature_schema = engineered_features

        context.feature_group = request["featureGroup"]

        context.created_by = request.get(

            "createdBy",

            "pipeline"

        )

        context.approval_revision = request.get(

            "approvalRevision",

            1

        )

        self._validate_projection(

            context

        )

        return context

    # ------------------------------------------------------------------

    def build_feature_set(

        self,

        context

    ):

        return {

            "featureSetId":

                context.feature_set_id,

            "datasetId":

                context.dataset_id,

            "datasetHash":

                context.dataset_hash,

            "lineageVersion":

                context.lineage_version,

            "featureSchema":

                context.feature_schema,

            "featureGroup":

                context.feature_group,

            "approvalRevision":

                context.approval_revision,

            "fingerprint":

                self._fingerprint(

                    context

                )

        }

    # ------------------------------------------------------------------

    def _validate_projection(

        self,

        context

    ):

        if not context.dataset_id:

            raise ValueError(

                "Dataset missing."

            )

        if context.lineage_version <= 0:

            raise ValueError(

                "Invalid lineage version."

            )

        if len(

            context.feature_schema

        ) == 0:

            raise ValueError(

                "Feature schema empty."

            )

        if context.approval_revision <= 0:

            raise ValueError(

                "Approval revision invalid."

            )

    # ------------------------------------------------------------------

    def _fingerprint(

        self,

        context

    ):

        value = (

            context.dataset_hash +

            str(context.lineage_version) +

            context.feature_group

        )

        return hashlib.sha256(

            value.encode()

        ).hexdigest()
