from training_feature_bundle import TrainingFeatureBundle


########################################################################


class OperationalBundleContext:

    def __init__(self):

        self.feature_set_id = ""

        self.dataset_id = ""

        self.dataset_hash = ""

        self.lineage_version = 0

        self.feature_schema = []

        self.feature_group = ""

        self.approval_revision = 0

        self.created_by = ""

        self.fingerprint = ""


########################################################################


class OperationalTrainingBundle:

    def __init__(

        self

    ):

        self.feature_set_id = ""

        self.dataset_id = ""

        self.dataset_hash = ""

        self.feature_schema = []

        self.feature_group = ""

        self.approval_revision = 0

        self.created_by = ""

        self.fingerprint = ""


########################################################################


class TrainingBundleFactory:

    # ------------------------------------------------------------------

    def build_bundle(

        self,

        feature_set

    ):

        self._validate_feature_set(

            feature_set

        )

        context = self._build_context(

            feature_set

        )

        self._normalize_context(

            context

        )

        self._validate_context(

            context

        )

        return self._build_training_bundle(

            context

        )

    # ------------------------------------------------------------------

    def _build_context(

        self,

        feature_set

    ):

        context = OperationalBundleContext()

        context.feature_set_id = feature_set["featureSetId"]

        context.dataset_id = feature_set["datasetId"]

        context.dataset_hash = feature_set["datasetHash"]

        context.lineage_version = feature_set["lineageVersion"]

        context.feature_schema = feature_set["featureSchema"]

        context.feature_group = feature_set["featureGroup"]

        context.approval_revision = feature_set["approvalRevision"]

        context.created_by = feature_set.get(

            "createdBy",

            "registry"

        )

        context.fingerprint = feature_set["fingerprint"]

        return context

    # ------------------------------------------------------------------

    def _normalize_context(

        self,

        context

    ):

        context.dataset_id = (

            context.dataset_id

            .strip()

        )

        context.feature_group = (

            context.feature_group

            .strip()

        )

        context.created_by = (

            context.created_by

            .strip()

        )

    # ------------------------------------------------------------------

    def _validate_context(

        self,

        context

    ):

        if not context.feature_set_id:

            raise ValueError(

                "Feature set identifier missing."

            )

        if not context.dataset_id:

            raise ValueError(

                "Dataset identifier missing."

            )

        if context.lineage_version <= 0:

            raise ValueError(

                "Invalid lineage version."

            )

        if context.approval_revision <= 0:

            raise ValueError(

                "Approval revision invalid."

            )

        if len(

            context.feature_schema

        ) == 0:

            raise ValueError(

                "Feature schema missing."

            )

        if not context.dataset_hash:

            raise ValueError(

                "Dataset hash missing."

            )

    # ------------------------------------------------------------------

    def _validate_feature_set(

        self,

        feature_set

    ):

        required = [

            "featureSetId",

            "datasetId",

            "datasetHash",

            "lineageVersion",

            "featureSchema",

            "featureGroup",

            "approvalRevision",

            "fingerprint"

        ]

        for field in required:

            if field not in feature_set:

                raise ValueError(

                    f"{field} missing."

                )

    # ------------------------------------------------------------------

    def _build_operational_bundle(

        self,

        context

    ):

        """
        Construct the lightweight training bundle used by the
        scheduling and training pipeline. Downstream services
        consume this operational representation rather than the
        canonical FeatureSet.
        """

        bundle = OperationalTrainingBundle()

        bundle.feature_set_id = (

            context.feature_set_id

        )

        bundle.dataset_id = (

            context.dataset_id

        )

        bundle.dataset_hash = (

            context.dataset_hash

        )

        bundle.feature_schema = (

            context.feature_schema

        )

        bundle.feature_group = (

            context.feature_group

        )

        bundle.approval_revision = (

            context.approval_revision

        )

        bundle.created_by = (

            context.created_by

        )

        bundle.fingerprint = (

            context.fingerprint

        )

        return bundle

    # ------------------------------------------------------------------

    def _build_training_bundle(

        self,

        context

    ):

        operational = (

            self._build_operational_bundle(

                context

            )

        )

        return TrainingFeatureBundle(

            feature_set_id =

                operational.feature_set_id,

            dataset_id =

                operational.dataset_id,

            dataset_hash =

                operational.dataset_hash,

            feature_schema =

                operational.feature_schema,

            feature_group =

                operational.feature_group,

            approval_revision =

                operational.approval_revision,

            created_by =

                operational.created_by,

            fingerprint =

                operational.fingerprint

            # lineage_version intentionally never propagated
            # through the operational bundle constructor.
        )
