from datetime import datetime, timedelta


########################################################################


class CacheEntry:

    def __init__(

        self,

        bundle,

        created_at,

        expires_at

    ):

        self.bundle = bundle

        self.created_at = created_at

        self.expires_at = expires_at


########################################################################


class BundleCache:

    def __init__(

        self,

        ttl_minutes=30

    ):

        self._cache = {}

        self._ttl = timedelta(

            minutes=ttl_minutes

        )

    # ------------------------------------------------------------------

    def get(

        self,

        bundle

    ):

        bundle.validate()

        key = self._build_cache_key(

            bundle

        )

        entry = self._cache.get(

            key

        )

        if entry is None:

            return None

        if self._expired(

            entry

        ):

            self._cache.pop(

                key,

                None

            )

            return None

        return entry.bundle

    # ------------------------------------------------------------------

    def put(

        self,

        bundle

    ):

        bundle.validate()

        key = self._build_cache_key(

            bundle

        )

        now = datetime.utcnow()

        self._cache[key] = CacheEntry(

            bundle=bundle,

            created_at=now,

            expires_at=now + self._ttl

        )

    # ------------------------------------------------------------------

    def invalidate(

        self,

        feature_set_id

    ):

        keys_to_remove = [

            key for key in self._cache

            if key.startswith(

                feature_set_id + ":"

            )

        ]

        for key in keys_to_remove:

            self._cache.pop(

                key,

                None

            )

    # ------------------------------------------------------------------

    def clear_expired(

        self

    ):

        now = datetime.utcnow()

        expired = []

        for key, entry in self._cache.items():

            if entry.expires_at <= now:

                expired.append(

                    key

                )

        for key in expired:

            self._cache.pop(

                key,

                None

            )

    # ------------------------------------------------------------------

    def _build_cache_key(

        self,

        bundle

    ):

        """
        Construct the registry cache identity for a validated
        training bundle. Cache entries represent reusable
        operational training bundles that may be consumed by
        multiple scheduling requests until they expire.
        """

        return (

            bundle.feature_set_id

        )

    # ------------------------------------------------------------------

    def contains(

        self,

        bundle

    ):

        key = self._build_cache_key(

            bundle

        )

        return key in self._cache

    # ------------------------------------------------------------------

    def size(

        self

    ):

        return len(

            self._cache

        )

    # ------------------------------------------------------------------

    def statistics(

        self

    ):

        return {

            "entries":

                len(

                    self._cache

                ),

            "ttl_seconds":

                int(

                    self._ttl.total_seconds()

                )

        }

    # ------------------------------------------------------------------

    def clear(

        self

    ):

        self._cache.clear()
