from pipeline.training_bundle_factory import TrainingBundleFactory
from pipeline.bundle_cache import BundleCache


########################################################################


class FeatureRegistry:

    def __init__(

        self,

        repository,

        lineage_validator

    ):

        self._repository = repository

        self._lineage_validator = lineage_validator

        self._bundle_factory = TrainingBundleFactory()

        self._cache = BundleCache()

    # ------------------------------------------------------------------

    def get_training_bundle(

        self,

        feature_set_id

    ):

        feature_set = self._repository.find(

            feature_set_id

        )

        if feature_set is None:

            raise ValueError(

                "Feature set not found."

            )

        self._lineage_validator.validate(

            feature_set

        )

        bundle = self._bundle_factory.build_bundle(

            feature_set

        )

        cached = self._cache.get(

            bundle

        )

        if cached is not None:

            return cached

        self._cache.put(

            bundle

        )

        return bundle

    # ------------------------------------------------------------------

    def register_feature_set(

        self,

        feature_set

    ):

        self._lineage_validator.validate(

            feature_set

        )

        self._repository.save(

            feature_set

        )

    # ------------------------------------------------------------------

    def get_feature_set(

        self,

        feature_set_id

    ):

        feature_set = self._repository.find(

            feature_set_id

        )

        if feature_set is None:

            return None

        self._lineage_validator.validate(

            feature_set

        )

        return feature_set

    # ------------------------------------------------------------------

    def available(

        self

    ):

        return True

    # ------------------------------------------------------------------

    def feature_count(

        self

    ):

        return self._repository.count()
