from registry.feature_registry import FeatureRegistry


########################################################################


class TrainingScheduler:

    def __init__(

        self,

        registry,

        trainer,

        experiment_manager

    ):

        self._registry = registry

        self._trainer = trainer

        self._experiment_manager = experiment_manager

    # ------------------------------------------------------------------

    def schedule_training(

        self,

        feature_set_id,

        configuration

    ):

        self._validate_configuration(

            configuration

        )

        bundle = self._registry.get_training_bundle(

            feature_set_id

        )

        experiment = self._experiment_manager.create(

            bundle,

            configuration

        )

        return self._trainer.train(

            bundle,

            experiment,

            configuration

        )

    # ------------------------------------------------------------------

    def _validate_configuration(

        self,

        configuration

    ):

        required = [

            "modelName",

            "epochs",

            "batchSize",

            "optimizer"

        ]

        for field in required:

            if field not in configuration:

                raise ValueError(

                    f"{field} missing."

                )

        if configuration["epochs"] <= 0:

            raise ValueError(

                "Invalid epoch count."

            )

        if configuration["batchSize"] <= 0:

            raise ValueError(

                "Invalid batch size."

            )

    # ------------------------------------------------------------------

    def schedule_batch(

        self,

        requests

    ):

        jobs = []

        for request in requests:

            jobs.append(

                self.schedule_training(

                    request["featureSetId"],

                    request["configuration"]

                )

            )

        return jobs
