            "modelId":

                model["modelId"],

            "status":

                "COMPLETED",

            "trainedAt":

                datetime.utcnow(),

            "experimentId":

                experiment["experimentId"]

        }

    # ------------------------------------------------------------------

    def _validate_training_request(

        self,

        bundle,

        configuration

    ):

        self._approval_policy.validate_training_approval(

            {

                "datasetId":

                    bundle.dataset_id,

                "datasetHash":

                    bundle.dataset_hash,

                "featureSchema":

                    bundle.feature_schema,

                "approvalRevision":

                    bundle.approval_revision,

                "fingerprint":

                    bundle.fingerprint

            }

        )

        self._schema_validator.validate(

            {

                "featureSetId":

                    bundle.feature_set_id,

                "lineageVersion":

                    1,

                "featureSchema":

                    bundle.feature_schema

            },

            configuration["expectedSchema"]

        )

    # ------------------------------------------------------------------

    def _validate_bundle(

        self,

        bundle

    ):

        bundle.validate()

        self._dataset_validator.validate(

            {

                "datasetId":

                    bundle.dataset_id,

                "datasetHash":

                    bundle.dataset_hash

            },

            {

                "datasetId":

                    bundle.dataset_id,

                "datasetHash":

                    bundle.dataset_hash,

                "approved":

                    True,

                "version":

                    1

            }

        )

    # ------------------------------------------------------------------

    def _validate_experiment(

        self,

        experiment

    ):

        if not experiment.get(

            "experimentId"

        ):

            raise ValueError(

                "Experiment identifier missing."

            )

        if experiment.get(

            "status"

        ) != "READY":

            raise ValueError(

                "Experiment not ready."

            )

    # ------------------------------------------------------------------

    def _build_training_context(

        self,

        bundle,

        experiment,

        configuration

    ):

        return {

            "featureSetId":

                bundle.feature_set_id,

            "datasetId":

                bundle.dataset_id,

            "datasetHash":

                bundle.dataset_hash,

            "featureSchema":

                bundle.feature_schema,

            "approvalRevision":

