package projection;

import java.time.Instant;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;


public final class RuntimeToolInvocation {

    private final String toolId;

    private final Map<String, String> allowedArguments;

    private final long timeoutSeconds;

    private final Instant approvalTimestamp;

    public RuntimeToolInvocation(

        String toolId,

        Map<String, String> allowedArguments,

        long timeoutSeconds,

        Instant approvalTimestamp

    ) {

        if (

            toolId == null ||

            toolId.isBlank()

        ) {

            throw new IllegalArgumentException(

                "Tool identifier is required."

            );

        }

        if (

            allowedArguments == null

        ) {

            throw new IllegalArgumentException(

                "Allowed arguments cannot be null."

            );

        }

        if (

            timeoutSeconds <= 0

        ) {

            throw new IllegalArgumentException(

                "Timeout must be greater than zero."

            );

        }

        if (

            approvalTimestamp == null

        ) {

            throw new IllegalArgumentException(

                "Approval timestamp is required."

            );

        }

        this.toolId =

            toolId;

        this.allowedArguments =

            Collections.unmodifiableMap(

                new HashMap<>(

                    allowedArguments

                )

            );

        this.timeoutSeconds =

            timeoutSeconds;

        this.approvalTimestamp =

            approvalTimestamp;

    }

    //------------------------------------------------------------------
    // Identity
    //------------------------------------------------------------------

    public String toolId() {

        return toolId;

    }

    //------------------------------------------------------------------
    // Runtime Arguments
    //------------------------------------------------------------------

    public Map<String, String> allowedArguments() {

        return allowedArguments;

    }

    public boolean allowsArgument(

        String name

    ) {

        return allowedArguments.containsKey(

            name

        );

    }

    public String argumentValue(

        String name

    ) {

        return allowedArguments.get(

            name

        );

    }

    public int argumentCount() {

        return allowedArguments.size();

    }

    //------------------------------------------------------------------
    // Runtime Metadata
    //------------------------------------------------------------------

    public long timeoutSeconds() {

        return timeoutSeconds;

    }

    public Instant approvalTimestamp() {

        return approvalTimestamp;

    }

    //------------------------------------------------------------------
    // Summary
    //------------------------------------------------------------------

    public String summary() {

        return

            toolId +

            " (" +

            argumentCount() +

            " approved arguments)";

    }

}
