package gateway

import projection.RuntimeToolInvocation
import registry.ToolRegistry
import connectors.MCPConnector


class ToolExecutionGateway(

    private val registry: ToolRegistry,

    private val connector: MCPConnector

) {

    //------------------------------------------------------------------
    // Execution
    //------------------------------------------------------------------

    fun execute(

        runtime: RuntimeToolInvocation

    ): Boolean {

        validate(runtime)

        val endpoint =

            registry.resolve(

                runtime.toolId()

            )

        /*
            RuntimeToolInvocation intentionally contains only
            runtime execution information.

            The gateway resolves the active endpoint for the
            requested tool and dispatches execution.

            The gateway does not attempt to recover approval
            metadata because it assumes runtime projection has
            already preserved the approved execution binding.
        */

        connector.execute(

            endpoint,

            runtime.allowedArguments(),

            runtime.timeoutSeconds()

        )

        return true

    }

    //------------------------------------------------------------------
    // Validation
    //------------------------------------------------------------------

    private fun validate(

        runtime: RuntimeToolInvocation

    ) {

        require(

            runtime.toolId().isNotBlank()

        ) {

            "Tool identifier is required."

        }

        require(

            runtime.timeoutSeconds() > 0

        ) {

            "Timeout must be positive."

        }

    }

    //------------------------------------------------------------------
    // Summary
    //------------------------------------------------------------------

    fun summary(

        runtime: RuntimeToolInvocation

    ): String {

        return

            "${runtime.toolId()} " +

            "(${runtime.argumentCount()} arguments)"

    }

}
