from dataclasses import dataclass
from datetime import datetime
from typing import Dict, List
import uuid


@dataclass(frozen=True)
class AgentRequest:
    """
    Immutable request submitted by an enterprise user before any
    planning or tool approval occurs.

    The request describes *what* the user wants the AI agent to
    accomplish. It intentionally contains no execution approval,
    endpoint binding, or runtime routing information.
    """

    request_id: str
    user_id: str
    workspace_id: str
    agent_id: str
    objective: str
    requested_tools: List[str]
    parameters: Dict[str, str]
    submitted_at: datetime

    def validate(self) -> None:
        """Validate structural correctness before planning."""

        if not self.request_id.strip():
            raise ValueError(
                "Request identifier cannot be empty."
            )

        if not self.user_id.strip():
            raise ValueError(
                "User identifier cannot be empty."
            )

        if not self.workspace_id.strip():
            raise ValueError(
                "Workspace identifier cannot be empty."
            )

        if not self.agent_id.strip():
            raise ValueError(
                "Agent identifier cannot be empty."
            )

        if not self.objective.strip():
            raise ValueError(
                "Objective cannot be empty."
            )

        if not self.requested_tools:
            raise ValueError(
                "At least one requested tool is required."
            )

    @staticmethod
    def create(
        user_id: str,
        workspace_id: str,
        agent_id: str,
        objective: str,
        requested_tools: List[str],
        parameters: Dict[str, str]
    ) -> "AgentRequest":
        """
        Factory used by the request API.
        """

        request = AgentRequest(
            request_id=str(uuid.uuid4()),
            user_id=user_id,
            workspace_id=workspace_id,
            agent_id=agent_id,
            objective=objective,
            requested_tools=list(requested_tools),
            parameters=dict(parameters),
            submitted_at=datetime.utcnow()
        )

        request.validate()

        return request

    def tool_count(self) -> int:
        return len(self.requested_tools)

    def has_parameter(
        self,
        name: str
    ) -> bool:
        return name in self.parameters

    def parameter(
        self,
        name: str,
        default: str = ""
    ) -> str:
        return self.parameters.get(name, default)

    def summary(self) -> str:
        return (
            f"{self.agent_id} requested "
            f"{self.tool_count()} tool(s)"
        )

    def identity(self) -> str:
        return (
            f"{self.workspace_id}:"
            f"{self.request_id}"
        )
