## FILE: api/CommandController.go

```
package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"robot-control-platform/models"
	"robot-control-platform/services"
)

type CommandController struct {
	dispatchService *services.CommandDispatchService
}

func NewCommandController(
	dispatchService *services.CommandDispatchService,
) *CommandController {

	return &CommandController{
		dispatchService: dispatchService,
	}
}

func (c *CommandController) SubmitCommand(
	ctx *gin.Context,
) {

	var request models.CommandRequest

	if err := ctx.ShouldBindJSON(&request); err != nil {

		ctx.JSON(
			http.StatusBadRequest,
			gin.H{
				"error": "invalid request",
			},
		)

		return
	}

	userID := ctx.GetHeader(
		"X-User-Id",
	)

	role := ctx.GetHeader(
		"X-User-Role",
	)

	if userID == "" {

		ctx.JSON(
			http.StatusUnauthorized,
			gin.H{
				"error": "missing user identity",
			},
		)

		return
	}

	command := models.Command{
		ID:        request.ID,
		RobotID:   request.RobotID,
		Type:      request.Type,
		Payload:   request.Payload,
		CreatedBy: userID,
		UserRole:  role,
	}

	err := c.dispatchService.Dispatch(
		command,
	)

	if err != nil {

		ctx.JSON(
			http.StatusForbidden,
			gin.H{
				"error": err.Error(),
			},
		)

		return
	}

	ctx.JSON(
		http.StatusAccepted,
		gin.H{
			"status":     "queued",
			"command_id": command.ID,
		},
	)
}
