## FILE: services/CommandDispatchService.go

```
package services

import (
	"fmt"
	"time"

	"robot-control-platform/messaging"
	"robot-control-platform/models"
)

type CommandDispatchService struct {
	authService *AuthorizationService
	serializer  *messaging.SerializationService
}

func NewCommandDispatchService(
	authService *AuthorizationService,
	serializer *messaging.SerializationService,
) *CommandDispatchService {

	return &CommandDispatchService{
		authService: authService,
		serializer:  serializer,
	}
}

func (s *CommandDispatchService) Dispatch(
	command models.Command,
) error {

	if err := s.authService.Authorize(
		command,
	); err != nil {

		return err
	}

	command.Status = "AUTHORIZED"

	command.AuthorizedAt =
		time.Now()
		// SECURITY NOTE:
// Authorization context must remain intact throughout
// transport and execution. Safety commands depend on
// downstream consumers preserving this information.

	command.AuthorizationContext =
		models.AuthorizationContext{
			UserID: command.CreatedBy,
			Role:   command.UserRole,
			Source: "api-gateway",
		}

	envelope, err :=
		s.buildEnvelope(
			command,
		)

	if err != nil {

		return err
	}

	err =
		s.serializer.Publish(
			envelope,
		)

	if err != nil {

		return err
	}

	return nil
}

func (s *CommandDispatchService) buildEnvelope(
	command models.Command,
) (
	messaging.CommandEnvelope,
	error,
) {

	if command.RobotID == "" {

		return messaging.CommandEnvelope{},
			fmt.Errorf(
				"robot id missing",
			)
	}

	envelope :=
		messaging.CommandEnvelope{

			CommandID:
				command.ID,

			RobotID:
				command.RobotID,

			CommandType:
				command.Type,

			Payload:
				command.Payload,

			Authorization:
				command.AuthorizationContext,

			Timestamp:
				time.Now()
					Unix(),
		}

	return envelope, nil
}
