use serde::{
    Deserialize,
    Serialize
};

#[derive(
    Serialize,
    Deserialize,
    Debug,
    Clone
)]
pub struct AuthorizationContext {

    pub user_id: String,

    pub role: String,

    pub source: String,
}

#[derive(
    Serialize,
    Deserialize,
    Debug,
    Clone
)]
pub struct CommandEnvelope {

    pub command_id: String,

    pub robot_id: String,

    pub command_type: String,

    pub payload:
        serde_json::Value,

    pub authorization:
        AuthorizationContext,

    pub timestamp: i64,
}

impl CommandEnvelope {

    pub fn is_safety_command(
        &self
    ) -> bool {

        matches!(
            self.command_type.as_str(),

            "SAFETY_OVERRIDE"
                |
            "DISABLE_COLLISION_DETECTION"
                |
            "DISABLE_SPEED_LIMITER"
        )
    }

    pub fn requires_supervisor(
        &self
    ) -> bool {

        self.is_safety_command()
    }

    pub fn role(
        &self
    ) -> &str {

        &self.authorization.role
    }

    pub fn source(
        &self
    ) -> &str {

        &self.authorization.source
    }
}
