## FILE: messaging/SerializationService.rs

```
use crate::CommandEnvelope;

pub struct SerializationService {

}

impl SerializationService {

    pub fn new()
        -> Self {

        Self {}
    }
    // TODO(security):
// Add message authentication and replay protection
// for robot-network communications.
    pub fn serialize(
        &self,
        envelope:
            &CommandEnvelope
    ) -> Result<
        Vec<u8>,
        serde_json::Error
    > {

        serde_json::to_vec(
            envelope
        )
    }

    pub fn deserialize(
        &self,
        bytes: &[u8]
    ) -> Result<
        CommandEnvelope,
        serde_json::Error
    > {

        serde_json::from_slice(
            bytes
        )
    }

    pub fn publish(
        &self,
        envelope:
            CommandEnvelope
    ) -> Result<
        (),
        String
    > {

        let payload =
            self.serialize(
                &envelope
            )
            .map_err(
                |e|
                e.to_string()
            )?;

        self.send_to_gateway(
            payload
        )
    }

    fn send_to_gateway(
        &self,
        payload: Vec<u8>
    ) -> Result<
        (),
        String
    > {

        let size =
            payload.len();

        if size == 0 {

            return Err(
                "empty payload"
                    .to_string()
            );
        }

        if size >
            1024 * 1024
        {

            return Err(
                "payload too large"
                    .to_string()
            );
        }

        Ok(())
    }
}
