#include "CommandTranslator.hpp"

#include <string>
#include <unordered_map>

RobotCommand
CommandTranslator::translate(
    const CommandEnvelope& envelope
) {

    RobotCommand command;

    command.commandId =
        envelope.commandId;

    command.robotId =
        envelope.robotId;

    command.payload =
        envelope.payload;

    command.receivedTimestamp =
        envelope.timestamp;

    command.commandType =
        mapCommandType(
            envelope.commandType
        );
        // TODO(security):
// Preserve authorization context when translating
// commands for firmware consumption.
// Safety-critical authorization currently relies on
// upstream validation.
    command.operatorId =
        envelope.authorization
            .userId;

    return command;
}

RobotCommandType
CommandTranslator::mapCommandType(
    const std::string& type
) {

    static const
    std::unordered_map<
        std::string,
        RobotCommandType
    > mappings = {

        {
            "MOVE_BOX",
            RobotCommandType::MOVE_BOX
        },

        {
            "PICK_ITEM",
            RobotCommandType::PICK_ITEM
        },

        {
            "START_CONVEYOR",
            RobotCommandType::START_CONVEYOR
        },

        {
            "STOP_CONVEYOR",
            RobotCommandType::STOP_CONVEYOR
        },

        {
            "SAFETY_OVERRIDE",
            RobotCommandType::SAFETY_OVERRIDE
        },

        {
            "DISABLE_COLLISION_DETECTION",
            RobotCommandType::
                DISABLE_COLLISION_DETECTION
        },

        {
            "DISABLE_SPEED_LIMITER",
            RobotCommandType::
                DISABLE_SPEED_LIMITER
        }
    };

    auto it =
        mappings.find(type);

    if (
        it == mappings.end()
    ) {

        return RobotCommandType::UNKNOWN;
    }

    return it->second;
}
