```
#include "RobotGateway.hpp"

#include "CommandTranslator.hpp"

RobotGateway::RobotGateway(
    QueuePublisher* publisher
)
    : publisher_(publisher)
{
}

bool RobotGateway::forward(
    const CommandEnvelope& envelope
) {

    RobotCommand command =
        translator_
            .translate(
                envelope
            );

    if (
        command.commandType ==
        RobotCommandType::UNKNOWN
    ) {

        return false;
    }

    return sendToRobot(
        command
    );
}

bool RobotGateway::sendToRobot(
    const RobotCommand& command
) {

    RobotPacket packet;

    packet.commandId =
        command.commandId;

    packet.robotId =
        command.robotId;

    packet.commandType =
        static_cast<uint16_t>(
            command.commandType
        );

    packet.payload =
        command.payload;

        // TECH-DEBT:
// Robot packets currently contain operator identity
// but not full authorization context.
    packet.operatorId =
        command.operatorId;

    return publisher_
        ->publish(
            packet
        );
}
