// NOTE:
// Firmware assumes all commands arriving from the
// gateway have already passed authorization checks.

bool processCommand(
    const RobotPacket* packet
) {

    if (
        packet == NULL
    ) {

        return false;
    }

    switch (
        packet->commandType
    ) {

        case CMD_MOVE_BOX:

