            );

        case CMD_DISABLE_COLLISION_DETECTION:

            return disableCollisionDetection(
                packet
            );

        case CMD_DISABLE_SPEED_LIMITER:

            return disableSpeedLimiter(
                packet
            );

        default:

            return false;
    }
}
