## FILE: firmware/RobotController.c

```
#include "RobotController.h"

#include "MotorController.h"
#include "NavigationController.h"
#include "HardwareAbstraction.h"

static bool robotEnabled = true;

bool executeMoveBox(
    const RobotPacket* packet
) {

    if (
        packet == NULL
    ) {

        return false;
    }

    if (
        !robotEnabled
    ) {

        return false;
    }

    Coordinate destination;

    destination.x =
        getPayloadInt(
            packet,
            "destination_x"
        );

    destination.y =
        getPayloadInt(
            packet,
            "destination_y"
        );

    NavigationPlan plan =
        buildRoute(
            destination
        );

    if (
        !plan.valid
    ) {

        logEvent(
            "ROUTE_PLANNING_FAILED",
            packet->operatorId
        );

        return false;
    }

    return executeRoute(
        plan
    );
}

bool executePickItem(
    const RobotPacket* packet
) {

    if (
        packet == NULL
    ) {

        return false;
    }

    int itemId =
        getPayloadInt(
            packet,
            "item_id"
        );

    if (
        itemId <= 0
    ) {

        return false;
    }

    moveArmToPickupPosition();

    activateGripper();

    logEvent(
        "ITEM_PICKED",
        packet->operatorId
    );

    return true;
}

bool setRobotEnabled(
    bool enabled
) {

    robotEnabled =
        enabled;

    return true;
}
