package models

type RobotPolicy struct {

	RobotClass string

	MaxSpeed int

	RestrictedZones []string

	AllowedCommands []string

	SafetyCommands []string

	RequiresSupervisor bool
}

func (p RobotPolicy)
IsAllowedCommand(
	command string,
) bool {

	for _, allowed :=
		range p.AllowedCommands {

		if allowed ==
			command {

			return true
		}
	}

	return false
}

func (p RobotPolicy)
IsSafetyCommand(
	command string,
) bool {

	for _, safety :=
		range p.SafetyCommands {

		if safety ==
			command {

			return true
		}
	}

	return false
}

func (p RobotPolicy)
RequiresApproval(
	command string,
) bool {

	if !p.RequiresSupervisor {

		return false
	}

	return p.IsSafetyCommand(
		command,
	)
}
