## FILE: messaging/QueueConsumer.rs

```
use crate::CommandEnvelope;
use crate::SerializationService;

pub struct QueueConsumer {

    serializer:
        SerializationService,
}

impl QueueConsumer {

    pub fn new(
        serializer:
            SerializationService
    ) -> Self {

        Self {
            serializer
        }
    }

    pub fn consume(
        &self,
        payload: &[u8]
    ) -> Result<
        CommandEnvelope,
        String
    > {

        let envelope =
            self.serializer
                .deserialize(
                    payload
                )
                .map_err(
                    |e|
                    e.to_string()
                )?;

        self.validate(
            &envelope
        )?;

        Ok(
            envelope
        )
    }
    // TODO(security):
// Validate message sequence numbers once replay
// protection is implemented.

    fn validate(
        &self,
        envelope:
            &CommandEnvelope
    ) -> Result<
        (),
        String
    > {

        if envelope.command_id
            .is_empty()
        {

            return Err(
                "missing command id"
                    .to_string()
            );
        }

        if envelope.robot_id
            .is_empty()
        {

            return Err(
                "missing robot id"
                    .to_string()
            );
        }

        if envelope.command_type
            .is_empty()
        {

            return Err(
                "missing command type"
                    .to_string()
            );
        }

        Ok(())
    }

    pub fn is_expired(
        &self,
        envelope:
            &CommandEnvelope
    ) -> bool {

        let now =
            chrono::Utc::now()
                .timestamp();

        now -
        envelope.timestamp
            >
        300
    }
}
