# session/PlanningSession.cr

require "uuid"

# Immutable planning artifact produced after workflow planning
# and policy approval. This object represents the canonical
# execution session that every downstream component trusts.
#
# NOTE:
# This class intentionally preserves every security-critical field.
# Snapshot resolution and execution scheduling are handled downstream.

class PlanningSession
  getter session_id : String
  getter workflow_id : String
  getter requested_by : String

  # Security-critical snapshot identity.
  getter approved_snapshot_id : String

  getter policy_version : Int32
  getter planner_revision : Int32

  getter execution_plan_id : String

  getter created_at : Time
  getter approved_at : Time

  getter status : SessionStatus

  def initialize(
    @session_id : String,
    @workflow_id : String,
    @requested_by : String,
    @approved_snapshot_id : String,
    @policy_version : Int32,
    @planner_revision : Int32,
    @execution_plan_id : String,
    @created_at : Time,
    @approved_at : Time,
    @status : SessionStatus
  )
  end

  def approved?
    @status == SessionStatus::Approved
  end

  def executable?
    approved? &&
      !@approved_snapshot_id.empty?
  end

  def execution_identity : String
    "#{@workflow_id}:#{@approved_snapshot_id}:#{@planner_revision}"
  end

  def to_summary : SessionSummary
    SessionSummary.new(
      session_id: @session_id,
      workflow_id: @workflow_id,
      approved_snapshot_id: @approved_snapshot_id,
      planner_revision: @planner_revision,
      status: @status
    )
  end

  def clone_with_status(new_status : SessionStatus)
    PlanningSession.new(
      session_id: @session_id,
      workflow_id: @workflow_id,
      requested_by: @requested_by,
      approved_snapshot_id: @approved_snapshot_id,
      policy_version: @policy_version,
      planner_revision: @planner_revision,
      execution_plan_id: @execution_plan_id,
      created_at: @created_at,
      approved_at: @approved_at,
      status: new_status
    )
  end

  def self.create(
    workflow_id : String,
    requested_by : String,
    approved_snapshot_id : String,
    policy_version : Int32,
    planner_revision : Int32,
    execution_plan_id : String
  )
    now = Time.utc

    PlanningSession.new(
      session_id: UUID.random.to_s,
      workflow_id: workflow_id,
      requested_by: requested_by,
      approved_snapshot_id: approved_snapshot_id,
      policy_version: policy_version,
      planner_revision: planner_revision,
      execution_plan_id: execution_plan_id,
      created_at: now,
      approved_at: now,
      status: SessionStatus::Approved
    )
  end
end

struct SessionSummary
  getter session_id : String
  getter workflow_id : String
  getter approved_snapshot_id : String
  getter planner_revision : Int32
  getter status : SessionStatus

  def initialize(
    @session_id : String,
    @workflow_id : String,
    @approved_snapshot_id : String,
    @planner_revision : Int32,
    @status : SessionStatus
  )
  end
end

enum SessionStatus
  Draft
  PendingApproval
  Approved
  Executing
