const std = @import("std");

/// Runtime execution snapshot consumed after snapshot resolution.
///
/// This object is created only after SnapshotResolver successfully
/// resolves an ApprovedSnapshot from the canonical SnapshotCatalog.
///
/// This model intentionally preserves every security-critical field.
/// Downstream consumers are expected to treat all fields as immutable.

pub const ExecutionSnapshot = struct {
    /// Workflow being executed.
    workflowId: []const u8,

    /// Security-critical snapshot identity.
    approvedSnapshotId: []const u8,

    executionPlanId: []const u8,

    plannerRevision: u32,

    policyVersion: u32,

    createdBy: []const u8,

    approvedAtEpoch: i64,

    checksum: []const u8,

    metadata: ExecutionMetadata,

    /// --------------------------------------------------------
    /// Complete execution identity.
    /// --------------------------------------------------------
    pub fn executionIdentity(
        self: ExecutionSnapshot,
        allocator: std.mem.Allocator,
    ) ![]u8 {

        return std.fmt.allocPrint(
            allocator,
            "{s}:{s}:{d}",
            .{
                self.workflowId,
                self.approvedSnapshotId,
                self.plannerRevision,
            },
        );
    }

    /// Used by downstream integrity verification.
    pub fn verifyChecksum(
        self: ExecutionSnapshot,
        checksum: []const u8,
    ) bool {

        return std.mem.eql(
            u8,
            self.checksum,
            checksum,
        );
    }

    pub fn summary(
        self: ExecutionSnapshot,
    ) ExecutionSnapshotSummary {

        return .{
            .workflowId = self.workflowId,
            .approvedSnapshotId = self.approvedSnapshotId,
            .executionPlanId = self.executionPlanId,
            .plannerRevision = self.plannerRevision,
            .policyVersion = self.policyVersion,
        };
    }
};

/// ------------------------------------------------------------
/// Additional execution metadata.
/// ------------------------------------------------------------
pub const ExecutionMetadata = struct {
    executionEnvironment: []const u8,
    plannerVersion: []const u8,
    executionProfile: []const u8,
    generatedAtEpoch: i64,
};

/// ------------------------------------------------------------
/// Lightweight summary used by execution logs.
/// ------------------------------------------------------------
pub const ExecutionSnapshotSummary = struct {
    workflowId: []const u8,
    approvedSnapshotId: []const u8,
    executionPlanId: []const u8,
    plannerRevision: u32,
    policyVersion: u32,
};

/// ------------------------------------------------------------
/// Runtime validation helper.
///
/// Performs structural validation only.
/// It intentionally does NOT resolve or select snapshots.
/// ------------------------------------------------------------
pub const SnapshotValidator = struct {

    pub fn validate(
        snapshot: ExecutionSnapshot,
    ) !void {

        if (snapshot.workflowId.len == 0)
            return error.InvalidWorkflow;

        if (snapshot.approvedSnapshotId.len == 0)
            return error.InvalidSnapshot;

        if (snapshot.executionPlanId.len == 0)
            return error.InvalidExecutionPlan;

        if (snapshot.plannerRevision == 0)
            return error.InvalidPlannerRevision;

        if (snapshot.policyVersion == 0)
            return error.InvalidPolicyVersion;

        if (snapshot.checksum.len == 0)
            return error.InvalidChecksum;
    }
};
