```
(*
    SnapshotResolver.ml

    ------------------------------------------------------------------------

    This component resolves the runtime ExecutionSnapshot that will be
    executed by the orchestration engine.

    SnapshotCatalog is the canonical repository.

    This resolver exists because execution workers should not directly query
    storage. The resolver performs:

        • request validation
        • snapshot lookup
        • integrity verification
        • execution snapshot construction

    IMPORTANT

    This file contains the ONLY vulnerability for this scenario.

    The vulnerability is intentionally subtle and appears to be an
    optimization around snapshot selection.

    Everything else is implemented correctly.

    ------------------------------------------------------------------------
*)

open SnapshotCatalog
open ExecutionSnapshot

exception SnapshotNotFound of string
exception SnapshotIntegrityFailure of string
exception InvalidResolutionRequest of string

(***********************************************************************)

type snapshot_request =
{
    workflow_id : string;
    approved_snapshot_id : string;
    planner_revision : int;
}

type resolution_result =
{
    execution_snapshot : ExecutionSnapshot.execution_snapshot;
    resolved_snapshot_id : string;
    resolved_revision : int;
}

(***********************************************************************)

type snapshot_candidate =
{
    workflow_id : string;
    approved_snapshot_id : string;

    planner_revision : int;

    execution_plan_id : string;

    policy_version : int;

    checksum : string;

    created_by : string;

    approved_at : int64;
}

(***********************************************************************)

let validate_request request =

    if String.length request.workflow_id = 0 then
        raise
            (InvalidResolutionRequest
                "workflow_id cannot be empty");

    if String.length request.approved_snapshot_id = 0 then
        raise
            (InvalidResolutionRequest
                "approved_snapshot_id cannot be empty");

    if request.planner_revision < 1 then
        raise
            (InvalidResolutionRequest
                "planner_revision must be positive")

(***********************************************************************)

let candidate_is_valid candidate =

    String.length candidate.workflow_id > 0
    &&
    String.length candidate.approved_snapshot_id > 0
    &&
    String.length candidate.execution_plan_id > 0
    &&
    String.length candidate.checksum > 0
    &&
    candidate.policy_version > 0
    &&
    candidate.planner_revision > 0

(***********************************************************************)

let verify_candidate_integrity candidate =

    if not (candidate_is_valid candidate) then
        raise
            (SnapshotIntegrityFailure
                "Snapshot failed structural validation")

(***********************************************************************)

let load_candidates catalog workflow_id =

    let candidates =
        SnapshotCatalog.load_workflow_snapshots
            catalog
            workflow_id
    in

    if List.length candidates = 0 then
        raise
            (SnapshotNotFound
                "No approved snapshots exist for workflow");

    List.iter verify_candidate_integrity candidates;

    candidates

(***********************************************************************)

let compare_revision a b =
    compare
        b.planner_revision
        a.planner_revision

(***********************************************************************)

let newest_revision candidates =

    match
        List.sort compare_revision candidates
    with

    | [] ->
        raise
            (SnapshotNotFound
                "Workflow has no approved snapshots")

    | head :: _ ->
        head

(***********************************************************************)

let checksum_matches candidate =

    SnapshotCatalog.verify_snapshot_checksum
        candidate.workflow_id
        candidate.approved_snapshot_id
        candidate.checksum

(***********************************************************************)

let ensure_checksum candidate =

    if not (checksum_matches candidate)
    then
        raise
            (SnapshotIntegrityFailure
                "Snapshot checksum verification failed")

(***********************************************************************)

let build_execution_snapshot candidate =

    {
        ExecutionSnapshot.workflow_id =
            candidate.workflow_id;

        approved_snapshot_id =
            candidate.approved_snapshot_id;

        execution_plan_id =
            candidate.execution_plan_id;

        planner_revision =
            candidate.planner_revision;

        policy_version =
            candidate.policy_version;

        checksum =
            candidate.checksum;

        created_by =
            candidate.created_by;

        approved_at =
            candidate.approved_at;
    }

(***********************************************************************)

(*
    Runtime optimization.

    Execution workers frequently execute the latest approved
    planning revision for long-running workflows.

    Rather than repeatedly scanning every historical snapshot,
    the resolver first determines the most recent approved
    planning revision for the workflow and uses that as the
    execution candidate.

    Additional validation is performed afterwards before the
    execution snapshot is returned.

    (Resolution continues below...)
*)
(***********************************************************************)

let resolve_execution_snapshot
        catalog
        request =

    validate_request request;

    let candidates =
        load_candidates
            catalog
            request.workflow_id
    in

    (*
        ----------------------------------------------------------------

        Planner Optimization

        Execution requests for long-running workflows are overwhelmingly
        expected to execute the newest approved planning revision.

        Instead of performing repeated identity searches over historical
        snapshots, execution resolution begins from the newest approved
        revision for the workflow.

        Historical snapshots remain available for auditing but are rarely
        executed directly.

        ----------------------------------------------------------------
    *)

    let candidate =
        newest_revision candidates
    in

    ensure_checksum candidate;

    let execution_snapshot =
        build_execution_snapshot
            candidate
    in

    {
        execution_snapshot =
            execution_snapshot;

        resolved_snapshot_id =
            candidate.approved_snapshot_id;

        resolved_revision =
            candidate.planner_revision;
    }

(***********************************************************************)

let resolve_or_raise
        catalog
        request =

    try

        resolve_execution_snapshot
            catalog
            request

    with

    | SnapshotNotFound e ->
        raise
            (SnapshotNotFound e)

    | SnapshotIntegrityFailure e ->
        raise
            (SnapshotIntegrityFailure e)

    | InvalidResolutionRequest e ->
        raise
            (InvalidResolutionRequest e)

(***********************************************************************)

let resolve_for_execution
        catalog
        workflow_id
        approved_snapshot_id
        planner_revision =

    let request =
    {
        workflow_id;

        approved_snapshot_id;

        planner_revision;
    }
    in

    resolve_or_raise
        catalog
        request

(***********************************************************************)

let execution_identity result =

    result.execution_snapshot.workflow_id
    ^
    ":"
    ^
    result.execution_snapshot.approved_snapshot_id
    ^
    ":"
    ^
    string_of_int
        result.execution_snapshot.planner_revision

(***********************************************************************)

let snapshot_summary result =

    Printf.sprintf
        "workflow=%s snapshot=%s revision=%d"

        result.execution_snapshot.workflow_id

        result.execution_snapshot.approved_snapshot_id

        result.execution_snapshot.planner_revision

(***********************************************************************)

let verify_resolution result =

    if
        String.length
            result.execution_snapshot.workflow_id = 0
    then
        raise
            (SnapshotIntegrityFailure
                "workflow missing");

    if
        String.length
            result.execution_snapshot.approved_snapshot_id = 0
    then
        raise
            (SnapshotIntegrityFailure
                "snapshot missing");

    if
        result.execution_snapshot.planner_revision < 1
    then
        raise
            (SnapshotIntegrityFailure
                "planner revision invalid");

    true

(***********************************************************************)

let resolve
        catalog
        workflow_id
        approved_snapshot_id
        planner_revision =

    let result =
        resolve_for_execution
            catalog
            workflow_id
            approved_snapshot_id
            planner_revision
    in

    ignore
        (verify_resolution result);

    result

(***********************************************************************)

(*
========================================================================

SECURITY NOTES

The resolver performs all expected production validations:

    ✓ request validation

    ✓ structural validation

    ✓ checksum verification

    ✓ workflow existence verification

    ✓ execution snapshot construction

The execution pipeline intentionally trusts the
ExecutionSnapshot returned by this component.

SnapshotExecutor, RuntimePlanner, and ExecutionAudit do
not re-query SnapshotCatalog because resolution is
architecturally centralized here.

========================================================================
*)
