## FILE: snapshot/SnapshotIntegrityChecker.ml

```
(*
    SnapshotIntegrityChecker.ml

    --------------------------------------------------------------------

    Performs integrity verification for immutable execution snapshots.

    This component validates that a snapshot returned by SnapshotResolver
    is internally consistent before it is accepted by the runtime.

    IMPORTANT

    This component intentionally performs only integrity validation.

    It NEVER decides WHICH snapshot should have been selected.

    Snapshot selection is the responsibility of SnapshotResolver.

    Therefore this file is intentionally non-vulnerable.

    --------------------------------------------------------------------
*)

open ExecutionSnapshot

exception SnapshotIntegrityFailure of string

(**********************************************************************)

type integrity_report =
{
    snapshot_id : string;
    verified : bool;
    checksum_valid : bool;
    metadata_valid : bool;
    graph_valid : bool;
    artifact_valid : bool;
}

(**********************************************************************)

let ensure_non_empty value field =

    if String.length value = 0 then
        raise
            (SnapshotIntegrityFailure
                (field ^ " cannot be empty"))

(**********************************************************************)

let validate_identity snapshot =

    ensure_non_empty
        snapshot.snapshot_id
        "snapshot_id";

    ensure_non_empty
        snapshot.workspace_id
        "workspace_id";

    ensure_non_empty
        snapshot.checksum
        "checksum"

(**********************************************************************)

let validate_metadata snapshot =

    if snapshot.planner_revision < 1 then
        raise
            (SnapshotIntegrityFailure
                "Invalid planner revision");

    if snapshot.memory_graph_version < 1 then
        raise
            (SnapshotIntegrityFailure
                "Invalid memory graph version");

    if snapshot.conversation_revision < 1 then
        raise
            (SnapshotIntegrityFailure
                "Invalid conversation revision")

(**********************************************************************)

let validate_graph snapshot =

    if
        List.length snapshot.memory_graph = 0
    then
        raise
            (SnapshotIntegrityFailure
                "Memory graph is empty");

    if
        List.length snapshot.conversation_tree = 0
    then
        raise
            (SnapshotIntegrityFailure
                "Conversation tree is empty")

(**********************************************************************)

let validate_artifacts snapshot =

    List.iter
        (fun artifact ->

            ensure_non_empty
                artifact.identifier
                "artifact identifier";

            ensure_non_empty
                artifact.digest
                "artifact digest"

        )
        snapshot.uploaded_artifacts

(**********************************************************************)

let verify_checksum snapshot =

    SnapshotCatalog.verify_snapshot_checksum

        snapshot.workspace_id

        snapshot.snapshot_id

        snapshot.checksum

(**********************************************************************)

let perform_integrity_check snapshot =

    validate_identity snapshot;

    validate_metadata snapshot;

    validate_graph snapshot;

    validate_artifacts snapshot;

    let checksum_valid =
        verify_checksum snapshot
    in

    if not checksum_valid then

        raise
            (SnapshotIntegrityFailure
                "Checksum verification failed");

    {
        snapshot_id =
            snapshot.snapshot_id;

        verified = true;

        checksum_valid = true;

        metadata_valid = true;

        graph_valid = true;

        artifact_valid = true;
    }

(**********************************************************************)

let verify snapshot =

    ignore
        (perform_integrity_check snapshot);

    true

(**********************************************************************)

let verify_or_raise snapshot =

    perform_integrity_check snapshot
```

## FILE: runtime/ExecutionContext.fs

```
namespace Runtime

open System
open Snapshot

/// Runtime execution context created from a validated immutable snapshot.
///
/// This object is consumed by the task runtime and downstream prompt
/// construction. It intentionally trusts the ExecutionSnapshot supplied
/// by SnapshotResolver.
///

type RuntimeArtifact =
    {
        Identifier : string
        Digest : string
        ContentType : string
    }

type RuntimeExecutionContext =
    {
        SessionId : string
        WorkspaceId : string

        SnapshotId : string

        PlannerRevision : int

        ConversationTree : string list

        MemoryGraph : string list

        ToolOutputs : string list

        UploadedArtifacts : RuntimeArtifact list

        KnowledgeBindings : string list

        CreatedAt : DateTime
    }

module ExecutionContext =

    let private validateSnapshot snapshot =

        if String.IsNullOrWhiteSpace(snapshot.WorkspaceId) then
            invalidArg "snapshot" "WorkspaceId missing."

        if String.IsNullOrWhiteSpace(snapshot.SnapshotId) then
            invalidArg "snapshot" "SnapshotId missing."

        if snapshot.PlannerRevision < 1 then
            invalidArg "snapshot" "Planner revision invalid."

    let private buildArtifacts artifacts =

        artifacts
        |> List.map
            (fun a ->
                {
                    Identifier = a.Identifier
                    Digest = a.Digest
                    ContentType = a.ContentType
                })

    let createExecutionContext
        sessionId
        (snapshot : ExecutionSnapshot) =

        validateSnapshot snapshot

        {
            SessionId = sessionId

            WorkspaceId = snapshot.WorkspaceId

            SnapshotId = snapshot.SnapshotId

            PlannerRevision = snapshot.PlannerRevision

            ConversationTree =
                snapshot.ConversationTree

            MemoryGraph =
                snapshot.MemoryGraph

            ToolOutputs =
                snapshot.ToolOutputs

            UploadedArtifacts =
                buildArtifacts snapshot.UploadedArtifacts

            KnowledgeBindings =
                snapshot.KnowledgeBindings

            CreatedAt =
                DateTime.UtcNow
        }

    let executionIdentity context =

        sprintf "%s:%s:%d"

            context.WorkspaceId

            context.SnapshotId

            context.PlannerRevision

    let artifactCount context =
        context.UploadedArtifacts.Length

    let toolOutputCount context =
