import 'dart:convert';
import 'dart:io';

import '../session/PlanningSession.cr.dart';
import '../session/SessionCoordinator.cr.dart';

class ExecutionGateway {
  final SessionCoordinator _sessionCoordinator;

  ExecutionGateway(this._sessionCoordinator);

  Future<GatewayResponse> submitExecution(HttpRequest request) async {
    try {
      final ExecutionRequest executionRequest =
          await _parseExecutionRequest(request);

      _validateExecutionRequest(executionRequest);

      final PlanningSession planningSession =
          await _sessionCoordinator.loadApprovedPlanningSession(
        executionRequest.sessionId,
        executionRequest.requestedBy,
      );

      final ExecutionSubmission submission =
          await _sessionCoordinator.prepareExecutionSubmission(
        planningSession,
        executionRequest.executionReason,
      );

      return GatewayResponse.accepted(
        executionId: submission.executionId,
        sessionId: planningSession.sessionId,
        snapshotId: planningSession.approvedSnapshotId,
        plannerRevision: planningSession.plannerRevision,
        submittedAt: submission.submittedAt,
      );
    } on GatewayValidationException catch (e) {
      return GatewayResponse.badRequest(e.message);
    } on SessionNotFoundException {
      return GatewayResponse.notFound(
          "Approved planning session could not be located.");
    } on SessionStateException catch (e) {
      return GatewayResponse.conflict(e.message);
    }
  }

  Future<ExecutionRequest> _parseExecutionRequest(
      HttpRequest request) async {
    final payload = jsonDecode(await utf8.decoder.bind(request).join());

    return ExecutionRequest(
      sessionId: payload["sessionId"],
      requestedBy: payload["requestedBy"],
      executionReason: payload["executionReason"] ?? "user-request",
    );
  }

  void _validateExecutionRequest(ExecutionRequest request) {
    if (request.sessionId.trim().isEmpty) {
      throw GatewayValidationException("sessionId is required.");
    }

    if (request.requestedBy.trim().isEmpty) {
      throw GatewayValidationException("requestedBy is required.");
    }

    if (request.executionReason.length > 256) {
      throw GatewayValidationException(
          "executionReason exceeds maximum length.");
    }
  }
}

class ExecutionRequest {
  final String sessionId;
  final String requestedBy;
  final String executionReason;

  ExecutionRequest({
    required this.sessionId,
    required this.requestedBy,
    required this.executionReason,
  });
}

class ExecutionSubmission {
  final String executionId;
  final DateTime submittedAt;

  ExecutionSubmission({
    required this.executionId,
    required this.submittedAt,
  });
}

class GatewayResponse {
  final int statusCode;
  final Map<String, dynamic> body;

  GatewayResponse._(this.statusCode, this.body);

  factory GatewayResponse.accepted({
    required String executionId,
    required String sessionId,
    required String snapshotId,
    required int plannerRevision,
    required DateTime submittedAt,
  }) {
    return GatewayResponse._(
      202,
      {
        "executionId": executionId,
        "sessionId": sessionId,
        "approvedSnapshotId": snapshotId,
        "plannerRevision": plannerRevision,
        "submittedAt": submittedAt.toUtc().toIso8601String(),
        "status": "QUEUED",
      },
    );
  }

  factory GatewayResponse.badRequest(String message) {
    return GatewayResponse._(
      400,
      {
        "error": message,
      },
    );
  }

  factory GatewayResponse.notFound(String message) {
    return GatewayResponse._(
      404,
      {
        "error": message,
      },
    );
  }

  factory GatewayResponse.conflict(String message) {
    return GatewayResponse._(
      409,
      {
        "error": message,
      },
    );
  }
}

class GatewayValidationException implements Exception {
  final String message;

  GatewayValidationException(this.message);
}

class SessionNotFoundException implements Exception {}

class SessionStateException implements Exception {
  final String message;

  SessionStateException(this.message);
}
