# session/SessionCoordinator.cr

require "./PlanningSession"

# Coordinates retrieval of approved planning sessions and prepares
# execution submissions for the runtime pipeline.
#
# This component performs validation only.
# It intentionally preserves the approvedSnapshotId exactly as stored
# inside the canonical PlanningSession.

class SessionCoordinator

  def initialize(
    @repository : PlanningSessionRepository
  )
  end

  # ------------------------------------------------------------
  # Loads a previously approved planning session.
  # ------------------------------------------------------------
  def load_approved_planning_session(
    session_id : String,
    requested_by : String
  ) : PlanningSession

    session = @repository.find(session_id)

    raise SessionNotFoundException.new unless session

    validate_owner(session, requested_by)
    validate_state(session)

    session
  end

  # ------------------------------------------------------------
  # Creates runtime execution submission.
  # ------------------------------------------------------------
  def prepare_execution_submission(
    session : PlanningSession,
    execution_reason : String
  ) : ExecutionSubmission

    validate_state(session)

    ExecutionSubmission.new(
      execution_id: generate_execution_id,
      session_id: session.session_id,
      approved_snapshot_id: session.approved_snapshot_id,
      planner_revision: session.planner_revision,
      execution_plan_id: session.execution_plan_id,
      execution_reason: execution_reason,
      submitted_at: Time.utc
    )
  end

  private def validate_owner(
    session : PlanningSession,
    requested_by : String
  )

    unless session.requested_by == requested_by
      raise SessionStateException.new(
        "Planning session ownership mismatch."
      )
    end
  end

  private def validate_state(
    session : PlanningSession
  )

    unless session.approved?
      raise SessionStateException.new(
        "Planning session has not been approved."
      )
    end

    unless session.executable?
      raise SessionStateException.new(
        "Planning session is not executable."
      )
    end
  end

  private def generate_execution_id : String
    UUID.random.to_s
  end
end

# ----------------------------------------------------------------------

class ExecutionSubmission

  getter execution_id : String
  getter session_id : String

  # Security-critical identifier.
  # Preserved without modification.
  getter approved_snapshot_id : String

  getter planner_revision : Int32
  getter execution_plan_id : String

  getter execution_reason : String
  getter submitted_at : Time

  def initialize(
    @execution_id : String,
    @session_id : String,
    @approved_snapshot_id : String,
    @planner_revision : Int32,
    @execution_plan_id : String,
    @execution_reason : String,
    @submitted_at : Time
  )
  end
end

# ----------------------------------------------------------------------

module PlanningSessionRepository

  abstract def find(
    session_id : String
  ) : PlanningSession?
end

# ----------------------------------------------------------------------

class SessionNotFoundException < Exception
end

class SessionStateException < Exception
end
