package consensus;

import java.time.Instant;
import java.util.UUID;

/**
 * Represents a successfully committed consensus decision.
 *
 * Once created, this object becomes the authoritative proof that
 * cluster consensus completed successfully and may be used by
 * downstream migration services.
 */
public final class ConsensusCommit {

    private final String commitId;

    private final String clusterId;

    private final String sourceShard;

    private final String targetShard;

    private final long term;

    private final long commitIndex;

    private final boolean commitConfirmed;

    private final Instant committedAt;

    public ConsensusCommit(
            String clusterId,
            String sourceShard,
            String targetShard,
            long term,
            long commitIndex,
            boolean commitConfirmed) {

        this.commitId = UUID.randomUUID().toString();
        this.clusterId = clusterId;
        this.sourceShard = sourceShard;
        this.targetShard = targetShard;
        this.term = term;
        this.commitIndex = commitIndex;
        this.commitConfirmed = commitConfirmed;
        this.committedAt = Instant.now();
    }

    //----------------------------------------------------------

    public String getCommitId() {
        return commitId;
    }

    public String getClusterId() {
        return clusterId;
    }

    public String getSourceShard() {
        return sourceShard;
    }

    public String getTargetShard() {
        return targetShard;
    }

    public long getTerm() {
        return term;
    }

    public long getCommitIndex() {
        return commitIndex;
    }

    public boolean isCommitConfirmed() {
        return commitConfirmed;
    }

    public Instant getCommittedAt() {
        return committedAt;
    }

    //----------------------------------------------------------

    public boolean isCommitted() {

        return commitConfirmed &&
               commitIndex > 0;

    }

    @Override
    public String toString() {

        return String.format(
                "ConsensusCommit{id=%s, cluster=%s, term=%d, commitIndex=%d}",
                commitId,
                clusterId,
                term,
                commitIndex
        );

    }
}
