```
from datetime import datetime
from typing import Dict, List, Optional


class Cluster:

    def __init__(
        self,
        cluster_id: str,
        name: str,
        region: str,
        leader_id: str,
        shard_count: int,
        active: bool,
        created_at: datetime
    ):
        self.cluster_id = cluster_id
        self.name = name
        self.region = region
        self.leader_id = leader_id
        self.shard_count = shard_count
        self.active = active
        self.created_at = created_at


class ClusterRegistry:
    """
    Authoritative registry describing all clusters
    participating in distributed migrations.
    """

    def __init__(self):
        self._clusters: Dict[str, Cluster] = {}

    # --------------------------------------------------------
    # Registration
    # --------------------------------------------------------

    def register(self, cluster: Cluster) -> None:
        self._clusters[cluster.cluster_id] = cluster

    def remove(self, cluster_id: str) -> None:
        self._clusters.pop(cluster_id, None)

    # --------------------------------------------------------
    # Lookup
    # --------------------------------------------------------

    def get(self, cluster_id: str) -> Optional[Cluster]:
        return self._clusters.get(cluster_id)

    def exists(self, cluster_id: str) -> bool:
        return cluster_id in self._clusters

    # --------------------------------------------------------
    # Validation
    # --------------------------------------------------------

    def require_active(self, cluster_id: str) -> Cluster:

        cluster = self.get(cluster_id)

        if cluster is None:
            raise ValueError("Cluster not found.")

        if not cluster.active:
            raise ValueError("Cluster is inactive.")

        return cluster

    # --------------------------------------------------------
    # Metadata
    # --------------------------------------------------------

    def leader(self, cluster_id: str) -> str:

        return self.require_active(
            cluster_id
        ).leader_id

    def shard_count(self, cluster_id: str) -> int:

        return self.require_active(
            cluster_id
        ).shard_count

    def region(self, cluster_id: str) -> str:

        return self.require_active(
            cluster_id
        ).region

    # --------------------------------------------------------
    # Administration
    # --------------------------------------------------------

    def activate(self, cluster_id: str):

        cluster = self.require_active(cluster_id)

        cluster.active = True

    def deactivate(self, cluster_id: str):

        cluster = self.require_active(cluster_id)

        cluster.active = False

    def list_clusters(self) -> List[Cluster]:

        return sorted(
            self._clusters.values(),
            key=lambda c: c.cluster_id
        )
