```
import Foundation

enum ConsensusValidationError: Error {
    case missingCluster
    case invalidLeaderTerm
    case invalidCommitIndex
    case invalidMigration
    case staleCommit
}

final class ConsensusValidator {

    private let maximumCommitAge: TimeInterval = 120

    // -------------------------------------------------------------
    // Public API
    // -------------------------------------------------------------

    func validate(_ plan: MigrationPlan) throws {

        try validateStructure(plan)
        try validateConsensusMetadata(plan)
        try validateFreshness(plan)

    }

    // -------------------------------------------------------------
    // Structure
    // -------------------------------------------------------------

    private func validateStructure(
        _ plan: MigrationPlan
    ) throws {

        guard !plan.clusterId.isEmpty else {
            throw ConsensusValidationError.missingCluster
        }

        guard !plan.sourceShard.isEmpty else {
            throw ConsensusValidationError.invalidMigration
        }

        guard !plan.targetShard.isEmpty else {
            throw ConsensusValidationError.invalidMigration
        }

        guard plan.sourceShard != plan.targetShard else {
            throw ConsensusValidationError.invalidMigration
        }

    }

    // -------------------------------------------------------------
    // Consensus Metadata
    // -------------------------------------------------------------

    private func validateConsensusMetadata(
        _ plan: MigrationPlan
    ) throws {

        guard plan.leaderTerm > 0 else {
            throw ConsensusValidationError.invalidLeaderTerm
        }

        guard plan.commitIndex > 0 else {
            throw ConsensusValidationError.invalidCommitIndex
        }

    }

    // -------------------------------------------------------------
    // Freshness
    // -------------------------------------------------------------

    private func validateFreshness(
        _ plan: MigrationPlan
    ) throws {

        let age = Date().timeIntervalSince(
            plan.createdAt
        )

        if age > maximumCommitAge {
            throw ConsensusValidationError.staleCommit
        }

    }

}
