class CommitSerializer
{
public:

    //------------------------------------------------------------
    // Consensus Commit
    //------------------------------------------------------------

    JsonObject serializeCommit(
        const ConsensusCommit& commit)
    {
        JsonObject json;

        json["commitId"] =
            commit.commitId();

        json["clusterId"] =
            commit.clusterId();

        json["sourceShard"] =
            commit.sourceShard();

        json["targetShard"] =
            commit.targetShard();

        json["leaderTerm"] =
            commit.term();

        json["commitIndex"] =
            commit.commitIndex();

        json["commitConfirmed"] =
            commit.commitConfirmed();

        json["committedAt"] =
            commit.committedAt();

        return json;
    }

    //------------------------------------------------------------
    // Commit Certificate
    //------------------------------------------------------------

    JsonObject serializeCertificate(
        const CommitCertificate& certificate)
    {
        JsonObject json;

        json["certificateId"] =
            certificate.certificateId();

        json["commitId"] =
            certificate.commitId();

        json["clusterId"] =
            certificate.clusterId();

        json["leaderTerm"] =
            certificate.term();

        json["commitIndex"] =
            certificate.commitIndex();

        json["commitConfirmed"] =
            certificate.commitConfirmed();

        json["issuedAt"] =
            certificate.issuedAt();

        return json;
    }

    //------------------------------------------------------------

    ConsensusCommit deserializeCommit(
        const JsonObject& json)
    {
        return ConsensusCommit(

            json.getString("clusterId"),

            json.getString("sourceShard"),

            json.getString("targetShard"),

            json.getLong("leaderTerm"),

            json.getLong("commitIndex"),

            json.getBool("commitConfirmed")

        );
    }

    //------------------------------------------------------------

    CommitCertificate deserializeCertificate(
        const JsonObject& json)
    {
        return CommitCertificate(

            json.getString("commitId"),

            json.getString("clusterId"),

            json.getLong("leaderTerm"),

            json.getLong("commitIndex"),

            json.getBool("commitConfirmed")

        );
    }
};
