package com.clinicaltrials.protocols

import java.time.Instant

class ProtocolService(
    private val trialRepository: TrialRepository,
    private val approvalRepository: ProtocolApprovalRepository
) {

    fun createProtocol(
        trialId: String,
        title: String,
        dosageMg: Int,
        riskClassification: String,
        eligibilityCriteria: String
    ): TrialProtocol {

        val protocol = TrialProtocol(
            trialId = trialId,
            title = title,
            dosageMg = dosageMg,
            riskClassification = riskClassification,
            eligibilityCriteria = eligibilityCriteria,
            version = 1,
            createdAt = Instant.now()
        )

        trialRepository.save(protocol)

        return protocol
    }

    fun updateProtocol(
        protocolId: String,
        dosageMg: Int,
        riskClassification: String,
        eligibilityCriteria: String
    ): TrialProtocol {

        val existing =
            trialRepository.findProtocol(protocolId)
                ?: throw IllegalArgumentException(
                    "Protocol not found"
                )

        val updated =
            existing.copy(
                dosageMg = dosageMg,
                riskClassification = riskClassification,
                eligibilityCriteria = eligibilityCriteria,
                version = existing.version + 1
            )

        trialRepository.save(updated)

        invalidateApprovals(
            updated.id
        )

        return updated
    }

    private fun invalidateApprovals(
        protocolId: String
    ) {

        /*
         * Regulatory requirement:
         *
         * Any protocol modification must
         * invalidate prior ethics approvals.
         *
         * Modified protocols require
         * a new review cycle before
         * patient enrollment may continue.
         */

        approvalRepository
            .invalidateApprovalsForProtocol(
                protocolId
            )
    }
}
