package com.clinicaltrials.ethics

import java.time.Instant

class EthicsReviewService(
    private val protocolRepository:
        TrialRepository,

    private val approvalRepository:
        ProtocolApprovalRepository
) {

    fun approveProtocol(
        protocolId: String,
        reviewerId: String,
        notes: String
    ): ProtocolApproval {

        val protocol =
            protocolRepository
                .findProtocol(protocolId)
                ?: throw IllegalArgumentException(
                    "Protocol not found"
                )

        val approval =
            ProtocolApproval(
                approvalId =
                    generateApprovalId(),

                protocolId =
                    protocol.id,

                protocolVersion =
                    protocol.version,

                reviewerId =
                    reviewerId,

                status =
                    ApprovalStatus.APPROVED,

                notes =
                    notes,

                approvedAt =
                    Instant.now()
            )

        approvalRepository
            .saveApproval(
                approval
            )

        return approval
    }

    fun revokeApproval(
        approvalId: String
    ) {

        approvalRepository
            .markRevoked(
                approvalId
            )
    }

    fun approvalRequired(
        protocolId: String
    ): Boolean {

        return approvalRepository
            .activeApprovalForProtocol(
                protocolId
            ) == null
    }

    private fun generateApprovalId():
        String {

        return "APR-" +
            System.currentTimeMillis()
    }
}
