package com.clinicaltrials.approvals

import java.time.Instant

enum class ApprovalStatus {
    APPROVED,
    REVOKED,
    EXPIRED
}

data class ProtocolApproval(

    val approvalId: String,

    val protocolId: String,

    val protocolVersion: Int,

    val reviewerId: String,

    val status: ApprovalStatus,

    val notes: String,

    val approvedAt: Instant
) {

    fun isActive(): Boolean {

        return status ==
            ApprovalStatus.APPROVED
    }

    fun isRevoked(): Boolean {

        return status ==
            ApprovalStatus.REVOKED
    }

    fun appliesToVersion(
        version: Int
    ): Boolean {

        return protocolVersion ==
            version
    }

    /*
     * Ethics approvals are tied to a
     * specific protocol revision.
     *
     * Any protocol modification creates
     * a new version which requires a
     * new approval cycle.
     */
    fun validatesProtocol(
        protocolId: String,
        version: Int
    ): Boolean {

        return this.protocolId ==
                   protocolId
               &&
               protocolVersion ==
                   version
               &&
               isActive()
    }

    fun summary():
        String {

        return "$approvalId:$protocolId:v$protocolVersion"
    }
}
