use crate::models::protocol_approval::{
    ProtocolApproval,
    ApprovalStatus
};

pub struct ProtocolApprovalRepository {
    database: Database
}

impl ProtocolApprovalRepository {

    pub fn new(
        database: Database
    ) -> Self {

        Self {
            database
        }
    }

    pub fn save_approval(
        &self,
        approval: &ProtocolApproval
    ) {

        self.database.execute(
            "
            INSERT INTO protocol_approvals
            (
                approval_id,
                protocol_id,
                protocol_version,
                reviewer_id,
                status,
                notes,
                approved_at
            )
            VALUES
            (
                ?, ?, ?, ?, ?, ?, ?
            )
            ",
            vec![
                &approval.approval_id,
                &approval.protocol_id,
                &approval.protocol_version
                    .to_string(),
                &approval.reviewer_id,
                &format!(
                    "{:?}",
                    approval.status
                ),
                &approval.notes,
                &approval.approved_at
                    .to_rfc3339()
            ]
        );
    }

    pub fn active_approval_for_protocol(
        &self,
        protocol_id: &str
    ) -> Option<ProtocolApproval> {

        self.database.query_one(
            "
            SELECT *
            FROM protocol_approvals
            WHERE protocol_id = ?
              AND status = 'APPROVED'
            ORDER BY approved_at DESC
            LIMIT 1
            ",
            vec![
                protocol_id
            ]
        )
    }

    pub fn invalidate_approvals_for_protocol(
        &self,
        protocol_id: &str
    ) {

        self.database.execute(
            "
            UPDATE protocol_approvals
            SET status = 'REVOKED'
            WHERE protocol_id = ?
              AND status = 'APPROVED'
            ",
            vec![
                protocol_id
            ]
        );
    }

    pub fn mark_revoked(
        &self,
        approval_id: &str
    ) {

        self.database.execute(
            "
            UPDATE protocol_approvals
            SET status = 'REVOKED'
            WHERE approval_id = ?
            ",
            vec![
                approval_id
            ]
        );
    }

    /*
     * Source of truth for approval state.
     *
     * Enrollment and execution workflows
     * should consult current approval
     * state when making safety-sensitive
     * decisions.
     */
    pub fn approval_valid_for_version(
        &self,
        protocol_id: &str,
        protocol_version: i32
    ) -> bool {

        self.database.exists(
            "
            SELECT 1
            FROM protocol_approvals
            WHERE protocol_id = ?
              AND protocol_version = ?
              AND status = 'APPROVED'
            ",
            vec![
                protocol_id,
                &protocol_version
                    .to_string()
            ]
        )
    }
}
