package com.clinicaltrials.snapshots

import java.time.Instant

data class ProtocolApprovalSnapshot(

    val snapshotId: String,

    val approvalId: String,

    val protocolId: String,

    val protocolVersion: Int,

    val reviewerId: String,

    val approvalStatus: String,

    val capturedAt: Instant
) {

    fun isApproved(): Boolean {

        return approvalStatus ==
            "APPROVED"
    }

    fun matchesProtocol(
        protocolId: String
    ): Boolean {

        return this.protocolId ==
            protocolId
    }

    /*
     * Snapshot represents approval
     * state at capture time.
     *
     * Snapshot consumers should not
     * assume approval status remains
     * valid indefinitely.
     */
    fun summary():
        String {

        return "$protocolId:v$protocolVersion:$approvalStatus"
    }
}
