    pub fn latest_snapshot(
        &self,
        protocol_id: &str
    ) -> Option<
        ProtocolApprovalSnapshot
    > {

        self.database.query_one(
            "
            SELECT *
            FROM
            protocol_approval_snapshots
            WHERE protocol_id = ?
            ORDER BY
                captured_at DESC
            LIMIT 1
            ",
            vec![
                protocol_id
            ]
        )
    }

    /*
     * Snapshot repository exists
     * to support asynchronous
     * workflow consumers.
     *
     * Approval state may change
     * after snapshot creation.
     *
     * Consumers requiring current
     * approval status should consult
     * ProtocolApprovalRepository.
     */
    pub fn snapshot_exists(
        &self,
        protocol_id: &str
    ) -> bool {

        self.database.exists(
            "
            SELECT 1
            FROM
            protocol_approval_snapshots
            WHERE protocol_id = ?
            ",
            vec![
                protocol_id
            ]
        )
    }
}
