use crate::repositories::
    protocol_approval_repository::
    ProtocolApprovalRepository;

use crate::repositories::
    protocol_approval_snapshot_repository::
    ProtocolApprovalSnapshotRepository;

use crate::models::
    protocol_approval_snapshot::
    ProtocolApprovalSnapshot;

use chrono::Utc;

pub struct ApprovalSnapshotPublisher {

    approval_repository:
        ProtocolApprovalRepository,

    snapshot_repository:
        ProtocolApprovalSnapshotRepository,

    publisher:
        NatsPublisher
}

impl ApprovalSnapshotPublisher {

    pub fn publish_snapshot(
        &self,
        protocol_id: &str
    ) {

        let approval =
            self.approval_repository
                .active_approval_for_protocol(
                    protocol_id
                );

        if approval.is_none() {
            return;
        }

        let approval =
            approval.unwrap();

        let snapshot =
            ProtocolApprovalSnapshot {

                snapshot_id:
                    format!(
                        "SNAP-{}",
                        Utc::now()
                            .timestamp()
                    ),

                approval_id:
                    approval.approval_id
                        .clone(),

                protocol_id:
                    approval.protocol_id
                        .clone(),

                protocol_version:
                    approval.protocol_version,

                reviewer_id:
                    approval.reviewer_id
                        .clone(),

                approval_status:
                    "APPROVED"
                        .to_string(),

                capturedAt:
                    Utc::now()
            };

        self.snapshot_repository
            .save_snapshot(
                &snapshot
            );

        self.publisher.publish(
            "trial.approval.snapshot",
            &snapshot
        );
    }
}
