use crate::repositories::
    protocol_approval_snapshot_repository::
    ProtocolApprovalSnapshotRepository;

use crate::services::
    enrollment_service::
    EnrollmentService;

pub struct EnrollmentCoordinator {

    snapshot_repository:
        ProtocolApprovalSnapshotRepository,

    enrollment_service:
        EnrollmentService
}

impl EnrollmentCoordinator {

    pub fn process_enrollment(
        &self,
        protocol_id: &str,
        patient_id: &str
    ) -> Result<(), String> {

        let snapshot =
            self.snapshot_repository
                .latest_snapshot(
                    protocol_id
                );

        if snapshot.is_none() {

            return Err(
                "Protocol approval required"
                    .to_string()
            );
        }

        let snapshot =
            snapshot.unwrap();

        if !snapshot.isApproved() {

            return Err(
                "Protocol approval required"
                    .to_string()
            );
        }

        /*
         * NOTE:
         *
         * Enrollment workflows depend
         * on approval snapshots to avoid
         * querying approval state during
         * high-volume enrollment periods.
         *
         * TODO:
         * Evaluate whether enrollment
         * should revalidate approval
         * state against the authoritative
         * approval repository.
         */

        self.enrollment_service
            .enroll_patient(
                protocol_id,
                patient_id
            )
    }
}
