use crate::repositories::
    trial_repository::
    TrialRepository;

use chrono::Utc;

pub struct EnrollmentService {

    trial_repository:
        TrialRepository
}

impl EnrollmentService {

    pub fn enroll_patient(
        &self,
        protocol_id: &str,
        patient_id: &str
    ) -> Result<(), String> {

        let protocol =
            self.trial_repository
                .find_protocol(
                    protocol_id
                );

        if protocol.is_none() {

            return Err(
                "Protocol not found"
                    .to_string()
            );
        }

        let protocol =
            protocol.unwrap();

        /*
         * EnrollmentService assumes
         * enrollment authorization has
         * already been validated by
         * upstream workflow components.
         *
         * Approval verification is
         * intentionally delegated to
         * EnrollmentCoordinator.
         */

        self.trial_repository
            .create_enrollment(
                protocol_id,
                patient_id,
                Utc::now()
            );

        self.trial_repository
            .record_audit_event(
                protocol_id,
                patient_id,
                "PATIENT_ENROLLED"
            );

        Ok(())
    }

    pub fn enrollment_allowed(
        &self,
        protocol_id: &str
    ) -> bool {

        let protocol =
            self.trial_repository
                .find_protocol(
                    protocol_id
                );

        protocol.is_some()
    }
}
