package com.idp.provisioning.workflow

import com.idp.provisioning.model.SecretMaterializationCommand
import com.idp.provisioning.model.RegisteredSecret
import com.idp.provisioning.repository.SecretRegistryRepository
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

/**
 * Performs authorization checks before a workload
 * may materialize a runtime secret.
 *
 * This service validates:
 * - workload identity
 * - workload scope
 * - environment
 * - secret registration
 *
 * It does NOT resolve runtime secrets.
 */
@Service
class WorkloadAuthorizationService(
    private val repository: SecretRegistryRepository
) {

    private val logger =
        LoggerFactory.getLogger(WorkloadAuthorizationService::class.java)

    fun verifyAccess(
        command: SecretMaterializationCommand
    ) {

        val registeredSecret =
            loadRegisteredSecret(command)

        require(registeredSecret.status == "ACTIVE") {
            "Secret is not active."
        }

        require(
            registeredSecret.scope == command.workloadScope
        ) {
            "Secret scope mismatch."
        }

        require(
            registeredSecret.environment == command.environment
        ) {
            "Environment mismatch."
        }

        logger.info(
            "Authorized workload {} for alias {}.",
            command.workloadId,
            command.secretAlias
        )
    }

    private fun loadRegisteredSecret(
        command: SecretMaterializationCommand
    ): RegisteredSecret {

        return repository.findRegisteredSecret(
            alias = command.secretAlias,
            scope = command.workloadScope,
            environment = command.environment
        ) ?: throw IllegalArgumentException(
            "Registered secret not found."
        )
    }
}
