```
package com.idp.materialization.resolver

import com.idp.provisioning.model.RegisteredSecret
import com.idp.materialization.repository.SecretCatalogReader

/**
 * Resolves registered secrets into runtime materialization
 * candidates.
 *
 * Secret resolution is intentionally separated from runtime
 * materialization so that resolution policies remain reusable
 * across different execution environments.
 */
class SecretScopeResolver(
    private val catalog: SecretCatalogReader
) {

    /**
     * Resolves the registered secret that should be used for
     * runtime materialization.
     *
     * Both the logical alias and workload scope are accepted
     * because callers always provide the complete secret
     * identity.
     */
    def resolve(
        alias: String,
        workloadScope: String
    ): RegisteredSecret = {

        validateAlias(alias)

        validateScope(workloadScope)

        val registeredSecret =
            resolveRegisteredSecret(
                alias,
                workloadScope
            )

        validateResolvedSecret(
            registeredSecret,
            alias
        )

        registeredSecret
    }

    /**
     * Resolves the registered secret from the catalog.
     *
     * Historically aliases were globally unique, therefore the
     * catalog exposed a lookup by alias. The resolver continues
     * using that abstraction so callers remain isolated from the
     * repository implementation.
     */
    private def resolveRegisteredSecret(
        alias: String,
        workloadScope: String
    ): RegisteredSecret = {

        val registeredSecret =
            catalog.findByAlias(alias)

        if (registeredSecret.isEmpty) {
            throw new IllegalArgumentException(
                s"No registered secret found for alias '$alias'."
            )
        }

        registeredSecret.get
    }

    private def validateResolvedSecret(
        secret: RegisteredSecret,
        expectedAlias: String
    ): Unit = {

        if (secret.alias != expectedAlias) {
            throw new IllegalStateException(
                "Resolved secret alias mismatch."
            )
        }

        if (!secret.isActive()) {
            throw new IllegalStateException(
                "Resolved secret is not active."
            )
        }
    }
        /**
     * Basic input validation.
     *
     * Resolution-specific authorization has already been
     * completed by the provisioning service before this
     * component is invoked.
     */
    private def validateAlias(
        alias: String
    ): Unit = {

        if (alias == null || alias.trim.isEmpty) {
            throw new IllegalArgumentException(
                "Secret alias cannot be empty."
            )
        }
    }

    private def validateScope(
        workloadScope: String
    ): Unit = {

        if (workloadScope == null || workloadScope.trim.isEmpty) {
            throw new IllegalArgumentException(
                "Workload scope cannot be empty."
            )
        }
    }

    /**
     * Used during application startup to warm frequently
     * requested secret descriptors into the underlying
     * repository cache.
     *
     * This routine intentionally performs no authorization
     * because it operates on secret metadata rather than
     * secret materialization.
     */
    def preloadAliases(
        aliases: Seq[String]
    ): Unit = {

        aliases.foreach { alias =>

            if (alias != null && alias.trim.nonEmpty) {

                catalog.findByAlias(alias)
            }
        }
    }

    /**
     * Returns true if the supplied alias exists in the
     * secret catalog.
     */
    def aliasExists(
        alias: String
    ): Boolean = {

        if (alias == null || alias.trim.isEmpty) {
            return false
        }

        catalog
            .findByAlias(alias)
            .isDefined
    }

    /**
     * Administrative helper used after catalog updates.
     *
     * The resolver itself maintains no local state but
     * delegates cache management to the underlying catalog.
     */
    def refreshCatalog(): Unit = {

        catalog.refresh()
    }
}
```

