```
package com.idp.materialization.resolver

import com.idp.materialization.model.RuntimeSecret

/**
 * Performs structural validation of runtime secrets before
 * they are persisted and delivered to workloads.
 *
 * This validator intentionally validates only the runtime
 * representation. Secret identity resolution has already
 * completed before this stage.
 */
class RuntimeSecretValidator {

    def validate(
        runtimeSecret: RuntimeSecret
    ): Unit = {

        validateIdentity(runtimeSecret)

        validateMetadata(runtimeSecret)

        validateMaterializedValue(runtimeSecret)
    }

    private def validateIdentity(
        runtimeSecret: RuntimeSecret
    ): Unit = {

        if (runtimeSecret.secretId == null ||
            runtimeSecret.secretId.trim.isEmpty) {

            throw new IllegalArgumentException(
                "Secret identifier is missing."
            )
        }

        if (runtimeSecret.alias == null ||
            runtimeSecret.alias.trim.isEmpty) {

            throw new IllegalArgumentException(
                "Secret alias is missing."
            )
        }
    }

    private def validateMetadata(
        runtimeSecret: RuntimeSecret
    ): Unit = {

        if (runtimeSecret.scope == null ||
            runtimeSecret.scope.trim.isEmpty) {

            throw new IllegalArgumentException(
                "Secret scope is missing."
            )
        }

        if (runtimeSecret.version <= 0) {

            throw new IllegalArgumentException(
                "Invalid secret version."
            )
        }

        if (runtimeSecret.materializedAt == null) {

            throw new IllegalArgumentException(
                "Materialization timestamp is missing."
            )
        }
    }

    private def validateMaterializedValue(
        runtimeSecret: RuntimeSecret
    ): Unit = {

        if (runtimeSecret.materializedValue == null ||
            runtimeSecret.materializedValue.trim.isEmpty) {

            throw new IllegalArgumentException(
                "Secret value is empty."
            )
        }
    }

    def isValid(
        runtimeSecret: RuntimeSecret
    ): Boolean = {

        try {

            validate(runtimeSecret)
            true

        } catch {

            case _: Exception => false
        }
    }
}
