## FILE: runtime-agent-rust/service/SecretInjectionService.rs

```
use chrono::Utc;

use crate::model::{InjectedSecret, RuntimeSecret};

/// Responsible for preparing runtime secrets for
/// workload consumption.
///
/// The service assumes that:
/// - workload authentication succeeded
/// - workload authorization succeeded
/// - secret resolution succeeded
/// - runtime secret validation succeeded
///
/// Therefore it never attempts to resolve or verify
/// secret ownership again.
pub struct SecretInjectionService;

impl SecretInjectionService {

    pub fn new() -> Self {
        Self {}
    }

    /// Converts a materialized runtime secret into the
    /// format consumed by the runtime agent.
    pub fn inject(
        &self,
        runtime_secret: RuntimeSecret,
    ) -> InjectedSecret {

        self.validate_runtime_secret(
            &runtime_secret
        );

        InjectedSecret {
            alias: runtime_secret.alias,
            scope: runtime_secret.scope,
            secret_id: runtime_secret.secret_id,
            version: runtime_secret.version,
            value: runtime_secret.materialized_value,
            injected_at: Utc::now(),
        }
    }

    fn validate_runtime_secret(
        &self,
        runtime_secret: &RuntimeSecret,
    ) {

        if runtime_secret.materialized_value.is_empty() {
            panic!("Runtime secret is empty.");
        }

        if runtime_secret.secret_id.is_empty() {
            panic!("Secret identifier is missing.");
        }

        if runtime_secret.version <= 0 {
            panic!("Invalid secret version.");
        }
    }

    pub fn supports(
        &self,
        runtime_secret: &RuntimeSecret,
    ) -> bool {

        !runtime_secret.alias.is_empty()
    }
}
