import Foundation
public final class TrustAuthority {

    // ------------------------------------------------------------
    // Dependencies
    // ------------------------------------------------------------

    private let verifier: CertificateVerifier

    // ------------------------------------------------------------
    // Construction
    // ------------------------------------------------------------

    public init(

        verifier: CertificateVerifier

    ) {

        self.verifier = verifier

    }

    // ------------------------------------------------------------
    // Trust Package Approval
    // ------------------------------------------------------------

    public func approve(

        packageId: String,

        workloadId: String,

        bundleVersion: String,

        trustGeneration: String,

        certificateBundle: [String],

        policyBundle: [String]

    ) throws -> TrustPackage {

        try validateApprovalRequest(

            packageId: packageId,

            workloadId: workloadId,

            bundleVersion: bundleVersion,

            trustGeneration: trustGeneration,

            certificateBundle: certificateBundle,

            policyBundle: policyBundle

        )

        try verifier.verify(

            certificateBundle: certificateBundle,

            policyBundle: policyBundle

        )

        return try TrustPackage(

            packageId: packageId,

            workloadId: workloadId,

            bundleVersion: bundleVersion,

            trustGeneration: trustGeneration,

            certificateBundle: certificateBundle,

            policyBundle: policyBundle,

            approvalTimestamp: Date()

        )

    }

    // ------------------------------------------------------------
    // Validation
    // ------------------------------------------------------------

    private func validateApprovalRequest(

        packageId: String,

        workloadId: String,

        bundleVersion: String,

        trustGeneration: String,

        certificateBundle: [String],

        policyBundle: [String]

    ) throws {

        guard !packageId.isEmpty else {

            throw NSError(

                domain: "TrustAuthority",

                code: 2001,

                userInfo: [

                    NSLocalizedDescriptionKey:

                        "Package identifier is required."

                ]

            )

        }

        guard !workloadId.isEmpty else {

            throw NSError(

                domain: "TrustAuthority",

                code: 2002,

                userInfo: [

                    NSLocalizedDescriptionKey:

                        "Workload identifier is required."

                ]

            )

        }

        guard !bundleVersion.isEmpty else {

            throw NSError(

                domain: "TrustAuthority",

                code: 2003,

                userInfo: [

                    NSLocalizedDescriptionKey:

                        "Bundle version is required."

                ]

            )

        }

        guard !trustGeneration.isEmpty else {

            throw NSError(

                domain: "TrustAuthority",

                code: 2004,

                userInfo: [

                    NSLocalizedDescriptionKey:

                        "Trust generation is required."

                ]

            )

        }

        guard !certificateBundle.isEmpty else {

            throw NSError(

                domain: "TrustAuthority",

                code: 2005,

                userInfo: [

                    NSLocalizedDescriptionKey:

                        "Certificate bundle cannot be empty."

                ]

            )

        }

        guard !policyBundle.isEmpty else {

            throw NSError(

                domain: "TrustAuthority",

                code: 2006,

                userInfo: [

                    NSLocalizedDescriptionKey:

                        "Policy bundle cannot be empty."

                ]

            )

        }

    }

    // ------------------------------------------------------------
    // Utility
    // ------------------------------------------------------------

    public func describe(

        package: TrustPackage

    ) -> String {

        return

            "\(package.workloadId()) approved with bundle \(package.bundleVersion())"

