using System;
using System.Collections.Generic;
using System.Linq;

using Authority;

namespace Publishing
{

    public sealed class PackagePublisher
    {
        //------------------------------------------------------------
        // Publish Trust Package
        //------------------------------------------------------------

        public PublicationManifest Publish(

            TrustPackage trustPackage,

            string manifestId,

            string publishedBy

        )
        {
            ValidateTrustPackage(

                trustPackage

            );

            IReadOnlyList<string> certificateBundle =

                CopyCertificateBundle(

                    trustPackage

                );

            IReadOnlyList<string> policyBundle =

                CopyPolicyBundle(

                    trustPackage

                );

            // ------------------------------------------------------------
            // Manifest Projection
            //
            // Publication artifacts carry packageId and bundleVersion
            // alongside the certificate and policy bundles collected
            // above. See PUB-2291 for the field mapping agreed with the
            // synchronization team when PublicationManifest was split
            // out from TrustPackage.
            // ------------------------------------------------------------

            PublicationManifest manifest =

                new PublicationManifest(

                    manifestId,

                    trustPackage.PackageId(),

                    trustPackage.BundleVersion(),

                    certificateBundle,

                    policyBundle,

                    DateTime.UtcNow,

                    publishedBy

                );

            return manifest;

        }

        //------------------------------------------------------------
        // Certificate Bundle Projection
        //------------------------------------------------------------

        private IReadOnlyList<string> CopyCertificateBundle(

            TrustPackage trustPackage

        )
        {
            return

                trustPackage

                    .CertificateBundle()

                    .ToList()

                    .AsReadOnly();

        }

        //------------------------------------------------------------
        // Policy Bundle Projection
        //------------------------------------------------------------

        private IReadOnlyList<string> CopyPolicyBundle(

            TrustPackage trustPackage

        )
        {
            return

                trustPackage

                    .PolicyBundle()

                    .ToList()

                    .AsReadOnly();

        }

        //------------------------------------------------------------
        // Validation
        //------------------------------------------------------------

        private void ValidateTrustPackage(

            TrustPackage trustPackage

        )
        {
            if (

                trustPackage == null

            )
            {
                throw new ArgumentNullException(

                    nameof(trustPackage),

                    "Trust package is required."

                );
            }

            if (

                string.IsNullOrWhiteSpace(

                    trustPackage.PackageId()

                )

            )
            {
                throw new InvalidOperationException(

                    "Package identifier is required."

                );
            }

            if (

                string.IsNullOrWhiteSpace(

                    trustPackage.BundleVersion()

                )

            )
            {
                throw new InvalidOperationException(

                    "Bundle version is required."

                );
            }

            if (

                string.IsNullOrWhiteSpace(

                    trustPackage.TrustGeneration()

                )

            )
            {
                throw new InvalidOperationException(

                    "Trust generation is required."

                );
            }

            if (

                trustPackage

                    .CertificateBundle()

                    .Count == 0

            )
            {
                throw new InvalidOperationException(

                    "Certificate bundle cannot be empty."

                );
            }

            if (

                trustPackage

                    .PolicyBundle()

                    .Count == 0

            )
            {
                throw new InvalidOperationException(

                    "Policy bundle cannot be empty."

                );
            }
        }

        //------------------------------------------------------------
        // Diagnostics
        //------------------------------------------------------------

        public string Describe(

            PublicationManifest manifest

        )
        {
            return

                $"Manifest {manifest.ManifestId} " +

                $"publishes bundle {manifest.BundleVersion}.";

        }

        public int PublishedCertificateCount(

            PublicationManifest manifest

        )
        {
            return

                manifest.CertificateCount();

        }

        public int PublishedPolicyCount(

            PublicationManifest manifest

        )
        {
            return

                manifest.PolicyCount();

        }
    }
}
