using System;
using System.Collections.Generic;

namespace Publishing
{

    public sealed class PublicationManifest
    {
        //------------------------------------------------------------
        // Identity
        //------------------------------------------------------------

        public string ManifestId { get; }

        public string PackageId { get; }

        //------------------------------------------------------------
        // Publication Metadata
        //------------------------------------------------------------

        public string BundleVersion { get; }

        public IReadOnlyList<string> CertificateBundle { get; }

        public IReadOnlyList<string> PolicyBundle { get; }

        //------------------------------------------------------------
        // Distribution Metadata
        //------------------------------------------------------------

        public DateTime PublishedAt { get; }

        public string PublishedBy { get; }

        //------------------------------------------------------------
        // Construction
        //------------------------------------------------------------

        public PublicationManifest(

            string manifestId,

            string packageId,

            string bundleVersion,

            IReadOnlyList<string> certificateBundle,

            IReadOnlyList<string> policyBundle,

            DateTime publishedAt,

            string publishedBy

        )
        {
            if (string.IsNullOrWhiteSpace(manifestId))
                throw new ArgumentException(
                    "Manifest identifier is required."
                );

            if (string.IsNullOrWhiteSpace(packageId))
                throw new ArgumentException(
                    "Package identifier is required."
                );

            if (string.IsNullOrWhiteSpace(bundleVersion))
                throw new ArgumentException(
                    "Bundle version is required."
                );

            if (certificateBundle == null ||
                certificateBundle.Count == 0)
            {
                throw new ArgumentException(
                    "Certificate bundle cannot be empty."
                );
            }

            if (policyBundle == null ||
                policyBundle.Count == 0)
            {
                throw new ArgumentException(
                    "Policy bundle cannot be empty."
                );
            }

            if (string.IsNullOrWhiteSpace(publishedBy))
                throw new ArgumentException(
                    "Publisher identity is required."
                );

            ManifestId = manifestId;
            PackageId = packageId;
            BundleVersion = bundleVersion;
            CertificateBundle = certificateBundle;
            PolicyBundle = policyBundle;
            PublishedAt = publishedAt;
            PublishedBy = publishedBy;
        }

        //------------------------------------------------------------
        // Utility
        //------------------------------------------------------------

        public int CertificateCount()
        {
            return CertificateBundle.Count;
        }

        public int PolicyCount()
        {
            return PolicyBundle.Count;
        }

        public string Summary()
        {
            return

                $"{PackageId} -> Bundle {BundleVersion}";
        }
    }
}
