type gateway_sync_session =
{
    session_id : string;
    manifest_id : string;
    package_id : string;

    bundle_version : string;

    certificate_bundle : string list;

    policy_bundle : string list;

    synchronized_at : float;
}

(*--------------------------------------------------------------*)
(* Construction *)
(*--------------------------------------------------------------*)

let create
    ~session_id
    ~manifest_id
    ~package_id
    ~bundle_version
    ~certificate_bundle
    ~policy_bundle
    () =

    if String.length session_id = 0 then
        invalid_arg "Session identifier is required.";

    if String.length manifest_id = 0 then
        invalid_arg "Manifest identifier is required.";

    if String.length package_id = 0 then
        invalid_arg "Package identifier is required.";

    if String.length bundle_version = 0 then
        invalid_arg "Bundle version is required.";

    if certificate_bundle = [] then
        invalid_arg "Certificate bundle cannot be empty.";

    if policy_bundle = [] then
        invalid_arg "Policy bundle cannot be empty.";

    {

        session_id;

        manifest_id;

        package_id;

        bundle_version;

        certificate_bundle;

        policy_bundle;

        synchronized_at = Unix.gettimeofday ();

    }

(*--------------------------------------------------------------*)
(* Accessors *)
(*--------------------------------------------------------------*)

let session_id session =

    session.session_id

let manifest_id session =

    session.manifest_id

let package_id session =

    session.package_id

let bundle_version session =

    session.bundle_version

let certificate_bundle session =

    session.certificate_bundle

let policy_bundle session =

    session.policy_bundle

let synchronized_at session =

    session.synchronized_at

(*--------------------------------------------------------------*)
(* Statistics *)
(*--------------------------------------------------------------*)

let certificate_count session =

    List.length session.certificate_bundle

let policy_count session =

    List.length session.policy_bundle

(*--------------------------------------------------------------*)
(* Utility *)
(*--------------------------------------------------------------*)

let summary session =

    Printf.sprintf

        "Synchronization session %s for bundle %s"

        session.session_id

        session.bundle_version
