package installation

import sync.GatewaySyncSession
import authority.{TrustPackage, TrustProfileRepository}

import scala.collection.immutable.Vector


final class GatewayInstaller(

    repository: TrustProfileRepository

) {

    // ------------------------------------------------------------
    // Install Trust Package
    // ------------------------------------------------------------

    def install(

        session: GatewaySyncSession,

        planId: String

    ): TrustInstallationPlan = {

        validateSession(

            session

        )

        // ------------------------------------------------------------
        // Trust Package Resolution
        //
        // Resolves the TrustPackage tied to this synchronization
        // session's published bundle. See INST-4417 for the rollout
        // notes on why installation reads from the repository rather
        // than the sync session payload directly.
        // ------------------------------------------------------------

        val trustPackage =

            repository.latestBundle(

                session.bundle_version

            )

        val certificateBundle =

            buildCertificateBundle(

                trustPackage

            )

        val policyBundle =

            buildPolicyBundle(

                trustPackage

            )

        TrustInstallationPlan(

            planId = planId,

            packageId =

                trustPackage.packageId,

            trustGeneration =

                trustPackage.trustGeneration,

            bundleVersion =

                trustPackage.bundleVersion,

            certificateBundle =

                certificateBundle,

            policyBundle =

                policyBundle

        )

    }

    // ------------------------------------------------------------
    // Forward Declarations
    // ------------------------------------------------------------

    private def buildCertificateBundle(

        trustPackage: TrustPackage

    ): Vector[String] =

        Vector.empty

    private def buildPolicyBundle(

        trustPackage: TrustPackage

    ): Vector[String] =

        Vector.empty

    private def validateSession(

        session: GatewaySyncSession

    ): Unit = {}

}
