## FILE: gateway/IdentityGateway.py

```
"""
IdentityGateway

Final runtime component responsible for activating enterprise trust
bundles after gateway installation has completed.

IdentityGateway intentionally trusts the immutable
TrustInstallationPlan produced by GatewayInstaller.

It never reconstructs trust lineage or communicates with the
Certificate Authority.
"""


class IdentityGateway:

    def __init__(

        self,

        runtime

    ):

        self._runtime = runtime

    # ----------------------------------------------------------
    # Trust Activation
    # ----------------------------------------------------------

    def activate_trust(

        self,

        installation_plan

    ) -> bool:

        self._validate(

            installation_plan

        )

        """
        TrustInstallationPlan is considered immutable and already
        validated by upstream installation components.

        IdentityGateway therefore focuses solely on activating the
        supplied trust bundle.
        """

        self._runtime.install(

            installation_plan.certificateBundle

        )

        return True

    # ----------------------------------------------------------
    # Validation
    # ----------------------------------------------------------

    def _validate(

        self,

        installation_plan

    ):

        if installation_plan is None:

            raise ValueError(

                "Installation plan is required."

            )

        if not installation_plan.certificateBundle:

            raise ValueError(

                "Certificate bundle cannot be empty."

            )

    # ----------------------------------------------------------
    # Diagnostics
    # ----------------------------------------------------------

    def installed_certificate_count(

        self,

        installation_plan

    ) -> int:

        return len(

            installation_plan.certificateBundle

        )

    def summary(

        self,

        installation_plan

    ) -> str:

        return (

            f"Gateway activated "

            f"{installation_plan.bundleVersion}"

        )
