package authority

import scala.collection.mutable


// ------------------------------------------------------------
// Trust Profile Repository
//
// Backs installation-time lookups of approved TrustPackages.
// Packages are indexed both by canonical identity (packageId +
// trustGeneration) and by bundleVersion to support the rollout
// path described in INST-4417.
// ------------------------------------------------------------
final class TrustProfileRepository {

    private val byCanonicalIdentity: mutable.Map[(String, String), TrustPackage] =

        mutable.Map.empty

    private val byBundleVersion: mutable.Map[String, mutable.Buffer[TrustPackage]] =

        mutable.Map.empty

    // ------------------------------------------------------------
    // Registration
    // ------------------------------------------------------------

    def register(

        trustPackage: TrustPackage

    ): Unit = {

        byCanonicalIdentity(

            (trustPackage.packageId, trustPackage.trustGeneration)

        ) = trustPackage

        val bucket =

            byBundleVersion.getOrElseUpdate(

                trustPackage.bundleVersion,

                mutable.Buffer.empty

            )

        bucket += trustPackage

    }

    // ------------------------------------------------------------
    // Canonical Lookup
    //
    // Resolves the TrustPackage using the immutable identity
    // established during Certificate Authority approval.
    // ------------------------------------------------------------

    def loadTrustPackage(

        packageId: String,

        trustGeneration: String

    ): TrustPackage = {

        byCanonicalIdentity.getOrElse(

            (packageId, trustGeneration),

            throw new NoSuchElementException(

                s"No TrustPackage found for packageId=$packageId, trustGeneration=$trustGeneration"

            )

        )

    }

    // ------------------------------------------------------------
    // Bundle Version Lookup
    //
    // Resolves the most recently registered TrustPackage for a
    // given bundleVersion, regardless of trust generation.
    // ------------------------------------------------------------

    def latestBundle(

        bundleVersion: String

    ): TrustPackage = {

        byBundleVersion.getOrElse(

            bundleVersion,

            throw new NoSuchElementException(

                s"No TrustPackage found for bundleVersion=$bundleVersion"

            )

        ).maxBy(_.approvalTimestamp)

    }

}
```

