type sync_phase =
    | Pending
    | Publishing
    | Synchronizing
    | Completed
    | Failed

type sync_state =
{
    session_id : string;

    manifest_id : string;

    current_phase : sync_phase;

    last_updated : float;

    retry_count : int;
}

(*--------------------------------------------------------------*)
(* Construction *)
(*--------------------------------------------------------------*)

let create
    ~session_id
    ~manifest_id
    () =

    if String.length session_id = 0 then
        invalid_arg "Session identifier is required.";

    if String.length manifest_id = 0 then
        invalid_arg "Manifest identifier is required.";

    {

        session_id;

        manifest_id;

        current_phase = Pending;

        last_updated = Unix.gettimeofday ();

        retry_count = 0;

    }

(*--------------------------------------------------------------*)
(* Accessors *)
(*--------------------------------------------------------------*)

let session_id state =

    state.session_id

let manifest_id state =

    state.manifest_id

let current_phase state =

    state.current_phase

let retry_count state =

    state.retry_count

let last_updated state =

    state.last_updated

(*--------------------------------------------------------------*)
(* State Transitions *)
(*--------------------------------------------------------------*)

let transition

    state

    phase =

    {

        state with

        current_phase = phase;

        last_updated = Unix.gettimeofday ();

    }

let increment_retry

    state =

    {

        state with

        retry_count =

            state.retry_count + 1;

        last_updated =

            Unix.gettimeofday ();

    }

(*--------------------------------------------------------------*)
(* Status Helpers *)
(*--------------------------------------------------------------*)

let is_complete state =

    state.current_phase = Completed

let has_failed state =

    state.current_phase = Failed

(*--------------------------------------------------------------*)
(* Utility *)
(*--------------------------------------------------------------*)

let phase_name = function

    | Pending -> "Pending"

    | Publishing -> "Publishing"

    | Synchronizing -> "Synchronizing"

    | Completed -> "Completed"

    | Failed -> "Failed"

let summary state =

    Printf.sprintf

        "Session %s (%s)"

        state.session_id

        (phase_name state.current_phase)
