package gateway

import (
	"errors"
	"time"

	"cloud-cluster-manager/consensus"
)

type MigrationJob struct {
	MigrationID string
	ClusterID   string
	SourceShard string
	TargetShard string
	InitiatedBy string
	CreatedAt   time.Time
}

type MigrationGateway struct {
	coordinator *consensus.ConsensusCoordinator
}

func NewMigrationGateway(
	coordinator *consensus.ConsensusCoordinator,
) *MigrationGateway {

	return &MigrationGateway{
		coordinator: coordinator,
	}
}

// ------------------------------------------------------
// Public API
// ------------------------------------------------------

func (g *MigrationGateway) StartMigration(
	job MigrationJob,
) (*consensus.ConsensusCommit, error) {

	if err := g.validate(job); err != nil {
		return nil, err
	}

	commit, err := g.coordinator.BeginConsensus(
		job.ClusterID,
		job.SourceShard,
		job.TargetShard,
	)

	if err != nil {
		return nil, err
	}

	return commit, nil
}

// ------------------------------------------------------
// Validation
// ------------------------------------------------------

func (g *MigrationGateway) validate(
	job MigrationJob,
) error {

	if job.ClusterID == "" {
		return errors.New("cluster id required")
	}

	if job.SourceShard == "" {
		return errors.New("source shard required")
	}

	if job.TargetShard == "" {
		return errors.New("target shard required")
	}

	if job.SourceShard == job.TargetShard {
		return errors.New("source and target must differ")
	}

	if job.InitiatedBy == "" {
		return errors.New("missing initiator")
	}

	return nil
}
