package consensus

data class QuorumResult(

    val clusterId: String,

    val leaderId: String,

    val term: Long,

    val commitIndex: Long,

    val totalNodes: Int,

    val affirmativeVotes: Int,

    val quorumReached: Boolean

)

class QuorumTracker {

    /**
     * Collects votes from participating
     * cluster members.
     *
     * This class only determines whether
     * quorum has been reached.
     */
    fun collectVotes(
        clusterId: String
    ): Result<QuorumResult> {

        val votes = requestVotes(clusterId)

        val majority =
            (votes.totalNodes / 2) + 1

        val reached =
            votes.affirmativeVotes >= majority

        return Result.success(

            QuorumResult(

                clusterId = clusterId,

                leaderId = votes.leaderId,

                term = votes.term,

                commitIndex = votes.commitIndex,

                totalNodes = votes.totalNodes,

                affirmativeVotes = votes.affirmativeVotes,

                quorumReached = reached

            )

        )

    }

    //------------------------------------------------------------------

    private fun requestVotes(
        clusterId: String
    ): VoteSnapshot {

        /*
         * Simulated cluster state.
         * In production this would gather
         * votes from peer nodes.
         */

        return VoteSnapshot(

            leaderId = "node-1",

            term = 41,

            commitIndex = 845,

            totalNodes = 5,

            affirmativeVotes = 5

        )

    }

}

