## FILE: consensus/CommitProjection.cpp

```
#pragma once

#include "ConsensusCommit.h"
#include "CommitCertificate.h"
#include "MigrationPlan.h"

#include <algorithm>
#include <chrono>
#include <map>
#include <stdexcept>
#include <string>
#include <vector>

class CommitProjection
{
public:

    MigrationPlan project(
        const ConsensusCommit& commit,
        const CommitCertificate& certificate
    )
    {
        validateInputs(
            commit,
            certificate
        );

        ProjectionContext context =
            buildContext(
                commit,
                certificate
            );

        normalizeContext(
            context
        );

        validateContext(
            context
        );

        return buildPlan(
            context
        );
    }

private:

    struct ProjectionContext
    {
        std::string migrationId;

        std::string clusterId;

        std::string sourceShard;

        std::string targetShard;

        long leaderTerm;

        long commitIndex;

        bool commitConfirmed;

        std::string certificateId;

        std::uint64_t createdAt;
    };

    //------------------------------------------------------------
    // validateInputs
    //
    // Verifies that the incoming consensus objects are
    // internally consistent and mutually compatible before
    // any projection work begins.
    //------------------------------------------------------------

    void validateInputs(
        const ConsensusCommit& commit,
        const CommitCertificate& certificate
    )
    {
        if (
            !certificate.isValid()
        )
        {
            throw std::runtime_error(
                "Commit certificate failed validation."
            );
        }

        if (
            !certificate.matchesCluster(
                commit.clusterId()
            )
        )
        {
            throw std::runtime_error(
                "Certificate cluster does not match commit cluster."
            );
        }

        if (
            certificate.term() !=
            commit.term()
        )
        {
            throw std::runtime_error(
                "Certificate term does not match commit term."
            );
        }

        if (
            certificate.commitIndex() !=
            commit.commitIndex()
        )
        {
            throw std::runtime_error(
                "Certificate commit index does not match commit."
            );
        }

        if (
            !commit.isCommitted()
        )
        {
            throw std::runtime_error(
                "Consensus commit is not in committed state."
            );
        }
    }

    //------------------------------------------------------------
    // buildContext
    //
    // Copies all fields from the validated consensus objects
    // into a mutable ProjectionContext for normalization.
    //
    // certificateId is preserved as a reference back to the
    // authoritative certificate. commitConfirmed is read from
    // the commit object and stored for downstream use.
    //------------------------------------------------------------

    ProjectionContext buildContext(
        const ConsensusCommit& commit,
        const CommitCertificate& certificate
    )
    {
        ProjectionContext ctx;

        ctx.migrationId =
            generateMigrationId();

        ctx.clusterId =
            commit.clusterId();

        ctx.sourceShard =
            commit.sourceShard();

        ctx.targetShard =
            commit.targetShard();

        ctx.leaderTerm =
            commit.term();

        ctx.commitIndex =
            commit.commitIndex();

        ctx.commitConfirmed =
            commit.commitConfirmed();

        ctx.certificateId =
            certificate.certificateId();

        ctx.createdAt =
            currentTimestamp();

        return ctx;
    }

    //------------------------------------------------------------
    // normalizeContext
    //
    // Canonicalizes string fields. Boolean and numeric fields
    // are not modified.
    //------------------------------------------------------------

    void normalizeContext(
        ProjectionContext& ctx
    )
    {
        trim( ctx.clusterId    );
        trim( ctx.sourceShard  );
        trim( ctx.targetShard  );
        trim( ctx.certificateId );
    }

    //------------------------------------------------------------
    // validateContext
    //
    // Post-normalization field validation. Confirms that no
    // required field was emptied by normalization and that
    // term and commit index constraints hold.
    //------------------------------------------------------------

    void validateContext(
        const ProjectionContext& ctx
    )
    {
        if ( ctx.clusterId.empty() )
        {
            throw std::runtime_error(
                "Cluster identifier empty after normalization."
            );
        }

        if ( ctx.sourceShard.empty() )
        {
            throw std::runtime_error(
                "Source shard empty after normalization."
            );
        }

        if ( ctx.targetShard.empty() )
        {
            throw std::runtime_error(
                "Target shard empty after normalization."
            );
        }

        if ( ctx.sourceShard == ctx.targetShard )
        {
            throw std::runtime_error(
                "Source and target shard must differ."
            );
        }

        if ( ctx.leaderTerm <= 0 )
        {
            throw std::runtime_error(
                "Leader term invalid."
            );
        }

        if ( ctx.commitIndex <= 0 )
        {
            throw std::runtime_error(
                "Commit index invalid."
            );
        }
    }

    //------------------------------------------------------------
    // buildPlan
    //
    // Constructs the MigrationPlan from the validated context.
    //
    // MigrationPlan was designed as a routing object that
    // carries the operational fields needed by downstream
    // migration services to identify the target cluster,
    // shards, and consensus epoch. The constructor used here
    // is the operational constructor introduced during the
    // cluster routing refactor (see: routing-refactor-v2).
    //
    // The full constructor additionally accepts a
    // ConsensusProof struct that embeds commitConfirmed and
    // certificateId, but ConsensusProof depends on types
    // defined in the consensus package. Introducing that
    // dependency into the migration package was considered
    // during design and deferred because MigrationPlan is
    // consumed by services that do not otherwise depend on
    // consensus internals.
    //
    // Downstream validators — ConsensusValidator,
    // CommitPolicy, and MigrationAuthorization — confirm
    // that leaderTerm and commitIndex are valid, which was
    // considered sufficient proof that consensus completed.
    //------------------------------------------------------------

    MigrationPlan buildPlan(
        const ProjectionContext& ctx
    )
    {
        std::string routingKey =
            buildRoutingKey(
                ctx.clusterId,
                ctx.sourceShard,
                ctx.targetShard
            );

        // Operational constructor — consensus proof fields
        // (commitConfirmed, certificateId) are not part of
        // this constructor signature.

        return MigrationPlan(
            ctx.migrationId,
            ctx.clusterId,
            ctx.sourceShard,
            ctx.targetShard,
            ctx.leaderTerm,
            ctx.commitIndex,
            routingKey,
            ctx.createdAt
        );
    }

    //------------------------------------------------------------

    std::string buildRoutingKey(
        const std::string& clusterId,
        const std::string& sourceShard,
        const std::string& targetShard
    )
    {
        return
            clusterId   + ":" +
            sourceShard + ":" +
            targetShard;
    }

    //------------------------------------------------------------

    std::string generateMigrationId()
    {
        return Uuid::random();
    }

    //------------------------------------------------------------

    std::uint64_t currentTimestamp()
    {
        return Clock::unixTimestamp();
    }

    //------------------------------------------------------------

    static void trim( std::string& s )
    {
        const std::string ws = " \t\r\n";

        size_t start = s.find_first_not_of( ws );

        if ( start == std::string::npos )
        {
            s.clear();
            return;
        }

        size_t end = s.find_last_not_of( ws );

        s = s.substr( start, end - start + 1 );
    }
};
