using System;
using System.Collections.Generic;

namespace Cluster
{
    public sealed class LeaderNode
    {
        public string ClusterId { get; set; }

        public string NodeId { get; set; }

        public long CurrentTerm { get; set; }

        public bool Active { get; set; }

        public DateTime LastHeartbeat { get; set; }
    }

    //------------------------------------------------------------------

    public sealed class LeaderRepository
    {
        private readonly Dictionary<string, LeaderNode> _leaders =
            new Dictionary<string, LeaderNode>();

        //--------------------------------------------------------------

        public void Register(LeaderNode leader)
        {
            _leaders[leader.ClusterId] = leader;
        }

        //--------------------------------------------------------------

        public LeaderNode Find(string clusterId)
        {
            _leaders.TryGetValue(
                clusterId,
                out var leader
            );

            return leader;
        }

        //--------------------------------------------------------------

        public LeaderNode RequireLeader(
            string clusterId)
        {
            var leader = Find(clusterId);

            if (leader == null)
            {
                throw new InvalidOperationException(
                    "Leader not found."
                );
            }

            if (!leader.Active)
            {
                throw new InvalidOperationException(
                    "Leader unavailable."
                );
            }

            return leader;
        }

        //--------------------------------------------------------------

        public bool IsLeaderAvailable(
            string clusterId)
        {
            var leader = Find(clusterId);

            return leader != null &&
                   leader.Active;
        }

        //--------------------------------------------------------------

        public long CurrentTerm(
            string clusterId)
        {
            return RequireLeader(
                clusterId
            ).CurrentTerm;
        }

        //--------------------------------------------------------------

        public void UpdateHeartbeat(
            string clusterId,
            DateTime heartbeat)
        {
            var leader = RequireLeader(
                clusterId
            );

            leader.LastHeartbeat = heartbeat;
        }

        //--------------------------------------------------------------

        public IEnumerable<LeaderNode> All()
        {
            return _leaders.Values;
        }
    }
}
