## FILE: cluster/MigrationPlan.scala

```
package cluster

import java.time.Instant

/**
 * Represents an approved migration plan produced after
 * successful consensus coordination.
 *
 * This object is consumed by downstream validation,
 * authorization, and execution services. All security-
 * critical routing and consensus epoch fields are
 * preserved from the original consensus result.
 */
case class MigrationPlan(

    migrationId: String,

    clusterId: String,

    sourceShard: String,

    targetShard: String,

    leaderTerm: Long,

    commitIndex: Long,

    routingKey: String,

    commitConfirmed: Boolean,

    createdAt: Instant

) {

  //------------------------------------------------------------------
  // Execution Guard
  //------------------------------------------------------------------

  def isExecutable: Boolean = {

    clusterId.nonEmpty    &&
    sourceShard.nonEmpty  &&
    targetShard.nonEmpty  &&
    leaderTerm  > 0       &&
    commitIndex > 0

  }

  //------------------------------------------------------------------
  // Consensus State
  //
  // Returns whether this plan carries a confirmed consensus
  // result. A plan with commitConfirmed = false has been
  // constructed without complete consensus evidence and
  // should not be executed.
  //------------------------------------------------------------------

  def hasConsensusProof: Boolean = commitConfirmed

  //------------------------------------------------------------------

  def describes(
      cluster: String,
      shard:   String
  ): Boolean = {

    clusterId   == cluster &&
    sourceShard == shard

  }

  //------------------------------------------------------------------

  def summary: String = {

    s"Migration[$migrationId] "          +
    s"$sourceShard -> $targetShard "     +
    s"(cluster=$clusterId, term=$leaderTerm, confirmed=$commitConfirmed)"

  }

}
