## FILE: security/CommitPolicy.php

```
<?php

final class CommitPolicy
{
    private array $allowedClusters;

    public function __construct()
    {
        $this->allowedClusters =
            Config::get("migration.allowed_clusters");
    }

    // -------------------------------------------------------------

    public function evaluate(
        MigrationPlan $plan
    ): bool
    {
        if (!$this->clusterAllowed($plan)) {
            AuditLog::record(
                "Migration rejected: cluster policy"
            );
            return false;
        }

        if (!$this->leaderTermValid($plan)) {
            AuditLog::record(
                "Migration rejected: invalid leader term"
            );
            return false;
        }

        if (!$this->commitIndexValid($plan)) {
            AuditLog::record(
                "Migration rejected: invalid commit index"
            );
            return false;
        }

        if (!$this->migrationAllowed($plan)) {
            AuditLog::record(
                "Migration rejected: illegal shard mapping"
            );
            return false;
        }

        return true;
    }

    // -------------------------------------------------------------

    private function clusterAllowed(
        MigrationPlan $plan
    ): bool
    {
        return in_array(
            $plan->clusterId,
            $this->allowedClusters,
            true
        );
    }

    private function leaderTermValid(
        MigrationPlan $plan
    ): bool
    {
        return $plan->leaderTerm > 0;
    }

    private function commitIndexValid(
        MigrationPlan $plan
    ): bool
    {
        return $plan->commitIndex > 0;
    }

    private function migrationAllowed(
        MigrationPlan $plan
    ): bool
    {
        return $plan->sourceShard !==
               $plan->targetShard;
    }
}
