## FILE: migration/MigrationCoordinator.kt

```
package migration

import cluster.MigrationPlan
import security.ConsensusValidator
import security.CommitPolicy
import security.MigrationAuthorization

class MigrationCoordinator(

    private val validator: ConsensusValidator,

    private val commitPolicy: CommitPolicy,

    private val authorization: MigrationAuthorization,

    private val trafficSwitchService: TrafficSwitchService,

    private val migrationRepository: MigrationRepository

) {

    //------------------------------------------------------------------
    // Public API
    //------------------------------------------------------------------

    fun execute(plan: MigrationPlan): MigrationResult {

        validate(plan)

        migrationRepository.markInProgress(
            plan.migrationId
        )

        val decision =
            authorization.authorize(plan)

        if (!decision.approved) {

            migrationRepository.markRejected(
                plan.migrationId
            )

            throw IllegalStateException(
                "Migration authorization rejected."
            )
        }

        val result =
            trafficSwitchService.switchTraffic(
                decision
            )

        migrationRepository.markCompleted(
            plan.migrationId
        )

        return result
    }

    //------------------------------------------------------------------

    private fun validate(
        plan: MigrationPlan
    ) {

        validator.validate(plan)

        if (!commitPolicy.evaluate(plan)) {
            throw IllegalStateException(
                "Migration policy failed."
            )
        }

    }

    //------------------------------------------------------------------

    fun dryRun(
        plan: MigrationPlan
    ): Boolean {

        validator.validate(plan)

        return commitPolicy.evaluate(plan)

    }

    //------------------------------------------------------------------

    fun migrationSummary(
        plan: MigrationPlan
    ): Map<String, Any> {

        return mapOf(

            "migrationId" to plan.migrationId,

            "cluster" to plan.clusterId,

            "sourceShard" to plan.sourceShard,

            "targetShard" to plan.targetShard,

            "leaderTerm" to plan.leaderTerm,

            "commitIndex" to plan.commitIndex

        )

    }

}
