defmodule Shared.MetricsCollector do

  @moduledoc """
  Collects operational metrics for migration and
  consensus workflows.

  Metrics are used only for monitoring and have
  no impact on authorization or execution.
  """

  def migration_started(cluster) do

    increment(
      "migration.started",
      cluster
    )

  end

  def migration_completed(cluster) do

    increment(
      "migration.completed",
      cluster
    )

  end

  def migration_failed(cluster) do

    increment(
      "migration.failed",
      cluster
    )

  end

  def consensus_completed(cluster) do

    increment(
      "consensus.completed",
      cluster
    )

  end

  def consensus_failed(cluster) do

    increment(
      "consensus.failed",
      cluster
    )

  end

  #-------------------------------------------------------------

  defp increment(metric, cluster) do

    :telemetry.execute(

      [String.to_atom(metric)],

      %{count: 1},

      %{cluster: cluster}

    )

  end

end
