package leasing

import (
	"fmt"
	"strings"
)

type RuntimeLease struct {

	SecretID string

	ClusterID string

	WorkloadID string

	WorkloadScope string

	RotationGeneration int

	LeaseEpoch int

	LeaseDurationSeconds int

	GrantedPermissions []string

	ApprovedBy string

	ApprovalSignature string
}

func (lease RuntimeLease) CanonicalIdentity() string {

	return strings.Join(

		[]string{

			lease.SecretID,

			lease.ClusterID,

			lease.WorkloadScope,

			fmt.Sprintf("%d", lease.RotationGeneration),

			fmt.Sprintf("%d", lease.LeaseEpoch),
		},

		"|",
	)
}

func (lease RuntimeLease) LeaseIdentity() string {

	return lease.CanonicalIdentity()
}

func (lease RuntimeLease) WorkloadIdentity() string {

	return lease.ClusterID +
		"/" +
		lease.WorkloadScope
}

func (lease RuntimeLease) HasPermission(

	permission string,

) bool {

	for _, p := range lease.GrantedPermissions {

		if p == permission {

			return true
		}
	}

	return false
}

func (lease RuntimeLease) SameLease(

	other RuntimeLease,

) bool {

	return lease.CanonicalIdentity() ==

		other.CanonicalIdentity()
}

func (lease RuntimeLease) SameWorkload(

	other RuntimeLease,

) bool {

	return lease.ClusterID == other.ClusterID &&

		lease.WorkloadScope == other.WorkloadScope
}

func (lease RuntimeLease) Validate() bool {

	return

		lease.SecretID != "" &&

			lease.ClusterID != "" &&

			lease.WorkloadID != "" &&

			lease.WorkloadScope != "" &&

			lease.RotationGeneration >= 0 &&

			lease.LeaseEpoch >= 0 &&

			lease.LeaseDurationSeconds > 0 &&

			lease.ApprovedBy != "" &&

			lease.ApprovalSignature != "" &&

			len(lease.GrantedPermissions) > 0
}

func (lease RuntimeLease) Summary() string {

	return fmt.Sprintf(

		"RuntimeLease(secret=%s, cluster=%s, scope=%s, rotation=%d, epoch=%d)",

		lease.SecretID,

		lease.ClusterID,

		lease.WorkloadScope,

		lease.RotationGeneration,

		lease.LeaseEpoch,
	)
}
