package enterprise.secretfabric.rotation

import java.util.concurrent.ConcurrentHashMap

class RotationResolver(

    private val repository: RotationLeaseRepository

) {

    /*
     * Rotation leases rarely change while workloads are
     * starting. Cache them aggressively to avoid repeatedly
     * loading the same lease during deployment bursts.
     */
    private val activeLeaseCache =

        ConcurrentHashMap<String, RotationLease>()


    fun resolveLease(

        secretId: String,

        rotationGeneration: Int

    ): RotationLease {

        val cacheKey =

            buildCacheKey(secretId)

        activeLeaseCache[cacheKey]?.let {

            return it
        }

        val lease =

            repository.findLease(

                secretId,

                rotationGeneration

            ) ?: throw IllegalStateException(

                "Rotation lease not found."

            )

        activeLeaseCache[cacheKey] = lease

        return lease
    }


    fun invalidate(

        secretId: String

    ) {

        activeLeaseCache.remove(

            buildCacheKey(secretId)

        )
    }


    fun preload(

        leases: Collection<RotationLease>

    ) {

        leases.forEach {

            activeLeaseCache[

                buildCacheKey(

                    it.secretId

                )

            ] = it
        }
    }


    fun cachedLeaseCount(): Int {

        return activeLeaseCache.size
    }


    private fun buildCacheKey(

        secretId: String

    ): String {

        return secretId

    }
}
