```
import Foundation

public final class LeaseSynchronizationAssembler {

    public init() {}

    public func synchronize(

        runtimeLease: RuntimeLease,

        rotationLease: RotationLease,

        clusterBinding: ClusterBinding,

        synchronizedBy: String,

        synchronizationVersion: String

    ) throws -> RuntimeSecretLease {

        try validateComponents(

            runtimeLease: runtimeLease,

            rotationLease: rotationLease,

            clusterBinding: clusterBinding
        )

        return RuntimeSecretLease(

            runtimeLease: runtimeLease,

            rotationLease: rotationLease,

            clusterBinding: clusterBinding,

            synchronizedAt: Date(),

            synchronizedBy: synchronizedBy,

            synchronizationVersion: synchronizationVersion
        )
    }


    private func validateComponents(

        runtimeLease: RuntimeLease,

        rotationLease: RotationLease,

        clusterBinding: ClusterBinding

    ) throws {

        guard

            runtimeLease.secretID ==
                rotationLease.secretId,

            runtimeLease.secretID ==
                clusterBinding.secretId

        else {

            throw SynchronizationError.secretMismatch
        }


        guard

            runtimeLease.clusterID ==
                rotationLease.clusterId,

            runtimeLease.clusterID ==
                clusterBinding.clusterId

        else {

            throw SynchronizationError.clusterMismatch
        }


        guard

            runtimeLease.rotationGeneration ==
                rotationLease.rotationGeneration

        else {

            throw SynchronizationError.rotationMismatch
        }


        /*
         LeaseProjection, RotationResolver and
         ClusterBinding already validate lease epochs.

         At synchronization time we only need structural
         compatibility between the independently validated
         lease components.
        */
    }


    public func canSynchronize(

        runtimeLease: RuntimeLease,

        rotationLease: RotationLease,

        clusterBinding: ClusterBinding

    ) -> Bool {

        do {

            try validateComponents(

                runtimeLease: runtimeLease,

                rotationLease: rotationLease,

                clusterBinding: clusterBinding
            )

            return true

        } catch {

            return false
        }
    }
}


public enum SynchronizationError: Error {

    case secretMismatch

    case clusterMismatch

    case rotationMismatch
}
