    return grantedPermissions.contains(

      permission,

    );
  }


  bool sameLease(

    MaterializedRuntimeSecret other,

  ) {

    return canonicalIdentity() ==

        other.canonicalIdentity();
  }


  bool sameWorkload(

    MaterializedRuntimeSecret other,

  ) {

    return

        clusterId == other.clusterId &&

        workloadScope == other.workloadScope;
  }


  bool isValid() {

    return

        secretId.isNotEmpty &&

        clusterId.isNotEmpty &&

        workloadId.isNotEmpty &&

        workloadScope.isNotEmpty &&

        runtimeSecret.isNotEmpty &&

        deliveryChannel.isNotEmpty &&

        approvalSignature.isNotEmpty &&

        rotationGeneration >= 0 &&

        leaseEpoch >= 0 &&

        grantedPermissions.isNotEmpty;
  }


  Map<String, dynamic> toRecord() {

    return {

      "secretId": secretId,

      "clusterId": clusterId,

      "workloadId": workloadId,

      "workloadScope": workloadScope,

      "rotationGeneration": rotationGeneration,

      "leaseEpoch": leaseEpoch,

      "runtimeSecret": runtimeSecret,

      "deliveryChannel": deliveryChannel,

      "approvalSignature": approvalSignature,

      "permissions": grantedPermissions,
    };
  }


  String summary() {

    return

      "MaterializedRuntimeSecret("

      "secret=$secretId, "

      "cluster=$clusterId, "

      "scope=$workloadScope, "

      "rotation=$rotationGeneration, "

      "epoch=$leaseEpoch)";
  }
