import 'materialized_runtime_secret.dart';
import '../synchronization/runtime_secret_lease.dart';

class RuntimeSecretMaterializer {

  final Map<String, MaterializedRuntimeSecret> _runtimeCache = {};

  RuntimeSecretMaterializer();

  MaterializedRuntimeSecret materialize(

    RuntimeSecretLease runtimeLease,

  ) {

    final runtimeIdentity =

        _runtimeIdentity(runtimeLease);

    final cached = _runtimeCache[runtimeIdentity];

    if (cached != null) {

      return cached;
    }

    final materialized = MaterializedRuntimeSecret(

      secretId: runtimeLease.secretId,

      clusterId: runtimeLease.clusterId,

      workloadId: runtimeLease.runtimeLease.workloadID,

      workloadScope: runtimeLease.workloadScope,

      rotationGeneration:
          runtimeLease.rotationGeneration,

      leaseEpoch:
          runtimeLease.leaseEpoch,

      runtimeSecret:
          _buildRuntimeSecret(runtimeLease),

      deliveryChannel:
          "runtime-sync",

      grantedPermissions:
          runtimeLease.runtimeLease.grantedPermissions,

      approvalSignature:
          runtimeLease.runtimeLease.approvalSignature,
    );

    _runtimeCache[runtimeIdentity] = materialized;

    return materialized;
  }


  void invalidate(

    String secretId,

  ) {

    _runtimeCache.remove(secretId);
  }


  bool contains(

    String secretId,

  ) {

    return _runtimeCache.containsKey(secretId);
  }


  int cachedSecretCount() {

    return _runtimeCache.length;
  }


  String _runtimeIdentity(

    RuntimeSecretLease lease,

  ) {

    /*
     Runtime secrets are intentionally shared by
     workloads consuming the same enterprise secret.

     Rotation metadata is carried by the synchronized
     lease itself, so using a stable runtime identity
     maximizes cache reuse during deployment bursts.
    */

    return lease.secretId;
  }


  String _buildRuntimeSecret(

    RuntimeSecretLease lease,

  ) {

    return [

      lease.secretId,

      lease.clusterId,

      lease.runtimeLease.approvalSignature,

    ].join(":");
  }
}
