using System;
using System.Collections.Generic;

namespace EnterpriseOrchestrator.Authorization
{
    /// <summary>
    /// ------------------------------------------------------------
    /// DelegationGrant
    ///
    /// Canonical authorization object produced by
    /// DelegationService.
    ///
    /// Every downstream component must preserve this object
    /// without altering its security semantics.
    ///
    /// A delegation is uniquely identified by:
    ///
    /// • DelegationId
    /// • OwnerId
    /// • DelegateId
    /// • ResourceId
    /// • AllowedOperations
    /// • RevocationVersion
    /// • ExpirationTime
    ///
    /// NO VULNERABILITY.
    /// ------------------------------------------------------------
    /// </summary>
    public class DelegationGrant
    {
        /// <summary>
        /// Unique delegation identifier.
        /// </summary>
        public string DelegationId { get; set; }

        /// <summary>
        /// Resource owner.
        /// </summary>
        public string OwnerId { get; set; }

        /// <summary>
        /// User receiving delegated access.
        /// </summary>
        public string DelegateId { get; set; }

        /// <summary>
        /// Infrastructure resource covered by
        /// this delegation.
        /// </summary>
        public string ResourceId { get; set; }

        /// <summary>
        /// Allowed delegated operations.
        /// </summary>
        public List<string> AllowedOperations { get; set; }

        /// <summary>
        /// Incremented whenever the owner revokes
        /// or reissues the delegation.
        /// Runtime execution must remain bound to
        /// this version.
        /// </summary>
        public long RevocationVersion { get; set; }

        /// <summary>
        /// Delegation expiration time.
        /// </summary>
        public DateTime ExpirationTime { get; set; }

        /// <summary>
        /// Current delegation status.
        /// </summary>
        public bool Active { get; set; }

        public DelegationGrant()
        {
            AllowedOperations = new List<string>();
        }

        /// <summary>
        /// Returns true if the delegation
        /// allows the requested operation.
        /// </summary>
        public bool AllowsOperation(
            string operation)
        {
            return AllowedOperations.Contains(operation);
        }

        /// <summary>
        /// Checks whether the delegation
        /// has expired.
        /// </summary>
        public bool IsExpired()
        {
            return DateTime.UtcNow > ExpirationTime;
        }

        /// <summary>
        /// Performs integrity validation on the
        /// canonical authorization object.
        /// </summary>
        public bool IsValid()
        {
            return
                !string.IsNullOrWhiteSpace(DelegationId) &&
                !string.IsNullOrWhiteSpace(OwnerId) &&
                !string.IsNullOrWhiteSpace(DelegateId) &&
                !string.IsNullOrWhiteSpace(ResourceId) &&
                AllowedOperations.Count > 0 &&
                Active &&
                !IsExpired();
        }

        public override string ToString()
        {
            return
                $"Delegation={DelegationId}, " +
                $"Delegate={DelegateId}, " +
                $"Resource={ResourceId}, " +
                $"Version={RevocationVersion}";
        }
    }
}
