package runtime

import authorization.DelegationGrant
import java.time.Instant

/*
-------------------------------------------------------------
RuntimeSessionBuilder

Responsibilities
----------------
• Transform a canonical DelegationGrant into an
  operational ExecutionSession.
• Preserve the delegated authorization boundary.
• Build the runtime object consumed by RuntimeExecutor.

IMPORTANT
-------------------------------------------------------------

This is the ONLY vulnerable component.

DelegationService produces a correct DelegationGrant.

RuntimeExecutor correctly validates the
ExecutionSession it receives.

The vulnerability is introduced while constructing
the operational execution session.

-------------------------------------------------------------
*/

class RuntimeSessionBuilder {

    /**
     * Build an execution session from a validated
     * delegation grant.
     */
    fun buildSession(
        grant: DelegationGrant,
        requestedOperation: String
    ): ExecutionSession {

        validateGrant(
            grant,
            requestedOperation
        )

        val session = ExecutionSession()

        // -------------------------------------------------
        // Canonical delegation identity
        // -------------------------------------------------

        session.delegationId =
            grant.delegationId

        session.delegateId =
            grant.delegateId

        session.resourceId =
            grant.resourceId

        session.operation =
            requestedOperation

        session.expirationTime =
            grant.expirationTime

        /*
        -------------------------------------------------

        VULNERABILITY

        A runtime execution session must remain bound
        to the exact version of the delegation that
        authorized it.

        The canonical DelegationGrant contains

            revocationVersion

        but the RuntimeSessionBuilder fails to
        propagate this field into the operational
        ExecutionSession.

        As a result, the RuntimeExecutor has no way
        to determine whether the delegation has been
        revoked after the session was created.

        Correct implementation:

            session.revocationVersion =
                grant.revocationVersion

        This assignment is mistakenly omitted.

        -------------------------------------------------
        */

        session.createdAt =
            Instant.now()

        session.active = true

        return session
    }

    /*
    -------------------------------------------------
    Validate the canonical delegation.

    This logic is correct.

    -------------------------------------------------
    */

    private fun validateGrant(
        grant: DelegationGrant,
        requestedOperation: String
    ) {

        if (!grant.active) {
            throw IllegalStateException(
                "Delegation has been revoked."
            )
        }

        if (grant.isExpired()) {
            throw IllegalStateException(
                "Delegation has expired."
            )
        }

        if (!grant.allowsOperation(requestedOperation)) {
            throw IllegalStateException(
                "Delegated operation not permitted."
            )
        }
                if (grant.delegationId.isBlank()) {
            throw IllegalStateException(
                "Delegation identifier is missing."
            )
        }

        if (grant.ownerId.isBlank()) {
            throw IllegalStateException(
                "Owner identifier is missing."
            )
        }

        if (grant.delegateId.isBlank()) {
            throw IllegalStateException(
                "Delegate identifier is missing."
            )
        }

        if (grant.resourceId.isBlank()) {
            throw IllegalStateException(
                "Delegated resource is missing."
            )
        }

        if (grant.allowedOperations.isEmpty()) {
            throw IllegalStateException(
                "Delegation contains no permitted operations."
            )
        }

        if (grant.expirationTime.isBefore(Instant.now())) {
            throw IllegalStateException(
                "Delegation has expired."
            )
        }
    }
}
