package runtime

import java.time.Instant

/*
-------------------------------------------------------------
ExecutionSession

Operational authorization object consumed by RuntimeExecutor.

This object represents a delegated execution session that
has already been authorized by DelegationService.

IMPORTANT

This is NOT the canonical authorization object.

It is an operational representation derived from
DelegationGrant.

The vulnerability is NOT here.

RuntimeSessionBuilder fails to propagate the
RevocationVersion into this object.

As a result, RuntimeExecutor cannot bind the session
to the current version of the canonical delegation.

NO VULNERABILITY.
-------------------------------------------------------------
*/

class ExecutionSession {

    /**
     * Canonical delegation identifier.
     */
    var delegationId: String = ""

    /**
     * User executing the delegated action.
     */
    var delegateId: String = ""

    /**
     * Infrastructure resource that should
     * receive the delegated operation.
     */
    var resourceId: String = ""

    /**
     * Operation being executed.
     */
    var operation: String = ""

    /**
     * Session expiration time.
     */
    var expirationTime: Instant = Instant.now()

    /**
     * Session creation timestamp.
     */
    var createdAt: Instant = Instant.now()

    /**
     * Indicates whether this runtime session
     * is still active.
     */
    var active: Boolean = true

    /*
    ---------------------------------------------------------

    IMPORTANT

    RuntimeSessionBuilder SHOULD populate

        revocationVersion

    from DelegationGrant.

    That assignment is mistakenly omitted.

    The field intentionally exists so that
    RuntimeExecutor can compare it against the
    latest version stored in DelegationRepository.

    ---------------------------------------------------------
    */

    var revocationVersion: Long = -1

    /**
     * Determines whether the runtime session
     * has expired.
     */
    fun isExpired(): Boolean {
        return Instant.now().isAfter(expirationTime)
    }

    /**
     * Basic runtime integrity validation.
     */
    fun isValid(): Boolean {

        return delegationId.isNotBlank() &&
                delegateId.isNotBlank() &&
                resourceId.isNotBlank() &&
                operation.isNotBlank() &&
                active &&
                !isExpired()
    }

    override fun toString(): String {

        return "ExecutionSession(" +
                "delegation=$delegationId, " +
                "delegate=$delegateId, " +
                "resource=$resourceId, " +
                "operation=$operation, " +
                "revocationVersion=$revocationVersion)"
    }
}
