## FILE: runtime/RuntimeExecutor.kt

```
package runtime

import authorization.DelegationRepository
import executor.KubernetesExecutor

/*
-------------------------------------------------------------
RuntimeExecutor

Responsibilities
----------------
• Execute validated runtime sessions
• Ensure the delegation has not expired
• Verify the session is still bound to the latest
  canonical delegation
• Forward execution to KubernetesExecutor

IMPORTANT
-------------------------------------------------------------

This component is CORRECT.

It expects ExecutionSession to contain the
RevocationVersion copied from DelegationGrant.

RuntimeSessionBuilder fails to populate that field,
making the comparison below impossible.

NO VULNERABILITY.
-------------------------------------------------------------
*/

class RuntimeExecutor(
    private val delegationRepository: DelegationRepository,
    private val kubernetesExecutor: KubernetesExecutor
) {

    fun execute(
        session: ExecutionSession
    ): Result<String> {

        validateSession(session)

        val latestGrant =
            delegationRepository.findByDelegationId(
                session.delegationId
            )
                ?: throw IllegalStateException(
                    "Delegation no longer exists."
                )

        /*
        -------------------------------------------------

        Runtime protection against revoked delegations.

        RuntimeSessionBuilder SHOULD have copied

            grant.revocationVersion

        into

            session.revocationVersion

        Since the builder forgets to do so, this
        comparison never succeeds correctly.

        -------------------------------------------------
        */

        if (session.revocationVersion !=
            latestGrant.revocationVersion)
        {
            throw IllegalStateException(
                "Delegation has been revoked or updated."
            )
        }

        val executionResult =
            kubernetesExecutor.execute(
                session.resourceId,
                session.operation,
                session.delegateId
            )

        return Result.success(
            executionResult
        )
    }

    /*
    -------------------------------------------------------------
    Runtime validation.

    This logic is correct.

    -------------------------------------------------------------
    */

    private fun validateSession(
        session: ExecutionSession
    ) {

        if (!session.isValid()) {
            throw IllegalStateException(
                "Invalid execution session."
            )
        }

        if (session.isExpired()) {
            throw IllegalStateException(
                "Execution session has expired."
            )
        }

        if (session.operation.isBlank()) {
            throw IllegalStateException(
                "Operation is missing."
            )
        }

        if (session.resourceId.isBlank()) {
            throw IllegalStateException(
                "Resource identifier is missing."
            )
        }
    }
}
