## FILE: authorization/DelegationRepository.scala

```
package repositories

import authorization.DelegationGrant

import java.time.Instant
import scala.collection.mutable

/**
 * ------------------------------------------------------------
 * DelegationRepository
 *
 * Repository responsible for persisting and retrieving
 * canonical DelegationGrant objects.
 *
 * Responsibilities
 * ----------------
 * • Store delegation grants
 * • Retrieve grants by delegation identifier
 * • Update revocation version
 * • Revoke delegations
 *
 * This repository represents the source of truth for
 * delegation state.
 *
 * NO VULNERABILITY.
 * ------------------------------------------------------------
 */
class DelegationRepository {

  private val delegations =
    mutable.Map[String, DelegationGrant]()

  /**
   * Retrieves a delegation by its unique identifier.
   */
  def findByDelegationId(
      delegationId: String
  ): DelegationGrant = {

    delegations.getOrElse(
      delegationId,
      null
    )
  }

  /**
   * Persists a delegation.
   */
  def save(
      grant: DelegationGrant
  ): Unit = {

    delegations.put(
      grant.DelegationId,
      grant
    )
  }

  /**
   * Marks a delegation as revoked.
   *
   * Every revocation increments the
   * revocation version.
   */
  def revoke(
      delegationId: String
  ): Unit = {

    val grant =
      findByDelegationId(delegationId)

    if (grant != null) {

      grant.Active = false
      grant.RevocationVersion += 1

      delegations.update(
        delegationId,
        grant
      )
    }
  }

  /**
   * Refreshes an existing delegation.
   *
   * Used when owners modify delegated
   * permissions.
   */
  def update(
      grant: DelegationGrant
  ): Unit = {

    grant.RevocationVersion += 1

    delegations.update(
      grant.DelegationId,
      grant
    )
  }

  /**
   * Returns true if the delegation exists.
   */
  def exists(
      delegationId: String
  ): Boolean = {

    delegations.contains(
      delegationId
    )
  }

  /**
   * Removes expired delegations.
   */
  def purgeExpired(): Unit = {

    val now = Instant.now()

    delegations.retain { (_, grant) =>
      grant.ExpirationTime.toInstant.isAfter(now)
    }
  }
}
```

