package models

import java.time.Instant

/**
 * ------------------------------------------------------------
 * RevocationRecord
 *
 * Represents the current revocation state of a delegated
 * authorization.
 *
 * Every modification to a delegation increments the
 * RevocationVersion.
 *
 * RuntimeExecutor compares the version stored in an
 * ExecutionSession against the latest RevocationRecord
 * to determine whether a delegation has been revoked
 * or replaced.
 *
 * This is a passive domain model.
 *
 * NO VULNERABILITY.
 * ------------------------------------------------------------
 */
case class RevocationRecord(

  /**
   * Canonical delegation identifier.
   */
  delegationId: String,

  /**
   * Current revocation version.
   */
  revocationVersion: Long,

  /**
   * Indicates whether the delegation
   * has been revoked.
   */
  revoked: Boolean,

  /**
   * Time of the latest update.
   */
  updatedAt: Instant,

  /**
   * Optional audit reason.
   */
  reason: Option[String]
) {

  /**
   * Returns true if the supplied
   * runtime session version is still
   * current.
   */
  def matches(
      sessionVersion: Long
  ): Boolean = {

    sessionVersion == revocationVersion
  }

  /**
   * Returns true if execution
   * should no longer be permitted.
   */
  def isRevoked: Boolean = {
    revoked
  }

  /**
   * Creates a new revocation record
   * after a delegation update.
   */
  def nextVersion(
      revokeReason: String
  ): RevocationRecord = {

    copy(
      revocationVersion = revocationVersion + 1,
      revoked = true,
      updatedAt = Instant.now(),
      reason = Some(revokeReason)
    )
  }

  /**
   * Reactivates a delegation.
   */
  def reactivate: RevocationRecord = {

    copy(
      revoked = false,
      updatedAt = Instant.now()
    )
  }
}
