package security

import runtime.ExecutionSession

/*
-------------------------------------------------------------
SessionValidator

Responsibilities
----------------
• Validate the structural integrity of an
  ExecutionSession.
• Verify mandatory runtime fields.
• Ensure the session is suitable for execution.

IMPORTANT
-------------------------------------------------------------

This validator performs ONLY structural validation.

It does NOT:

• Query DelegationRepository
• Compare revocation versions
• Perform authorization
• Check permissions

Those responsibilities belong to RuntimeExecutor.

NO VULNERABILITY.
-------------------------------------------------------------
*/

class SessionValidator {

    /**
     * Validate the runtime execution session.
     */
    fun validate(
        session: ExecutionSession
    ): Boolean {

        validateIdentifiers(session)

        validateExecutionTarget(session)

        validateSessionState(session)

        return true
    }

    /**
     * Validate runtime identifiers.
     */
    private fun validateIdentifiers(
        session: ExecutionSession
    ) {

        if (session.delegationId.isBlank()) {
            throw IllegalStateException(
                "Delegation identifier is missing."
            )
        }

        if (session.delegateId.isBlank()) {
            throw IllegalStateException(
                "Delegate identifier is missing."
            )
        }
    }

    /**
     * Validate execution target.
     */
    private fun validateExecutionTarget(
        session: ExecutionSession
    ) {

        if (session.resourceId.isBlank()) {
            throw IllegalStateException(
                "Deployment resource is missing."
            )
        }

        if (session.operation.isBlank()) {
            throw IllegalStateException(
                "Requested operation is missing."
            )
        }
    }

    /**
     * Validate runtime state.
     */
    private fun validateSessionState(
        session: ExecutionSession
    ) {

        if (!session.active) {
            throw IllegalStateException(
                "Execution session is inactive."
            )
        }

        if (session.isExpired()) {
            throw IllegalStateException(
                "Execution session has expired."
            )
        }

        /*
        -----------------------------------------------------

        Structural validation only.

        The validator intentionally does NOT verify
        revocationVersion because it has no access
        to the canonical DelegationGrant stored in
        DelegationRepository.

        RuntimeExecutor performs the authoritative
        comparison against the latest delegation
        before infrastructure execution.

        -----------------------------------------------------
        */

        if (!session.isValid()) {
            throw IllegalStateException(
                "Execution session integrity check failed."
            )
        }
    }
}
