package repositories

import models.Deployment

import scala.collection.mutable

/**
 * ------------------------------------------------------------
 * DeploymentRepository
 *
 * Repository responsible for storing infrastructure
 * deployment metadata.
 *
 * Responsibilities
 * ----------------
 * • Retrieve deployments
 * • Persist deployment updates
 * • Verify deployment existence
 *
 * This repository does NOT perform authorization.
 *
 * NO VULNERABILITY.
 * ------------------------------------------------------------
 */
class DeploymentRepository {

  private val deployments =
    mutable.Map[String, Deployment]()

  /**
   * Retrieve a deployment.
   */
  def findByResourceId(
      resourceId: String
  ): Deployment = {

    deployments.getOrElse(
      resourceId,
      null
    )
  }

  /**
   * Persist deployment changes.
   */
  def save(
      deployment: Deployment
  ): Unit = {

    deployments.update(
      deployment.resourceId,
      deployment
    )
  }

  /**
   * Verify deployment existence.
   */
  def exists(
      resourceId: String
  ): Boolean = {

    deployments.contains(
      resourceId
    )
  }

  /**
   * Remove deployment.
   */
  def delete(
      resourceId: String
  ): Unit = {

    deployments.remove(resourceId)
  }

  /**
   * Return all deployments.
   */
  def findAll(): List[Deployment] = {

    deployments.values.toList
  }
}
