use crate::authorization::delegation_grant::DelegationGrant;
use crate::authorization::delegation_service::DelegationService;
use crate::gateway::request_router::RequestRouter;

/// ------------------------------------------------------------
/// DelegationController
///
/// Entry point for delegated infrastructure operations.
///
/// Responsibilities
/// ----------------
/// • Validate incoming requests
/// • Invoke DelegationService
/// • Obtain the canonical DelegationGrant
/// • Forward authorized requests to RequestRouter
///
/// This component contains NO security vulnerability.
/// ------------------------------------------------------------
pub struct DelegationController {
    delegation_service: DelegationService,
    request_router: RequestRouter,
}

impl DelegationController {
    pub fn new(
        delegation_service: DelegationService,
        request_router: RequestRouter,
    ) -> Self {
        Self {
            delegation_service,
            request_router,
        }
    }

    /// Handles delegated execution requests.
    pub fn handle_request(
        &self,
        delegation_id: &str,
        requested_operation: &str,
    ) -> Result<String, String> {

        self.validate_request(
            delegation_id,
            requested_operation,
        )?;

        // Obtain the canonical delegation.
        let delegation: DelegationGrant =
            self.delegation_service.authorize(
                delegation_id,
                requested_operation,
            )?;

        // Forward to the runtime pipeline.
        self.request_router.route(
            delegation,
            requested_operation.to_string(),
        )
    }

    /// Performs basic request validation.
    fn validate_request(
        &self,
        delegation_id: &str,
        requested_operation: &str,
    ) -> Result<(), String> {

        if delegation_id.trim().is_empty() {
            return Err(
                "Delegation identifier is required."
                    .to_string(),
            );
        }

        if requested_operation.trim().is_empty() {
            return Err(
                "Requested operation is required."
                    .to_string(),
            );
        }

        Ok(())
    }
}
