use crate::authorization::delegation_grant::DelegationGrant;
use crate::runtime::execution_session::ExecutionSession;
use crate::runtime::runtime_executor::RuntimeExecutor;
use crate::runtime::runtime_session_builder::RuntimeSessionBuilder;

/// ------------------------------------------------------------
/// RequestRouter
///
/// Coordinates the runtime execution pipeline.
///
/// Responsibilities
/// ----------------
/// • Receive an authorized DelegationGrant
/// • Build an operational ExecutionSession
/// • Forward the session to RuntimeExecutor
///
/// This component performs no authorization decisions.
/// It simply orchestrates the runtime workflow.
///
/// NO VULNERABILITY.
/// ------------------------------------------------------------
pub struct RequestRouter {
    session_builder: RuntimeSessionBuilder,
    runtime_executor: RuntimeExecutor,
}

impl RequestRouter {
    pub fn new(
        session_builder: RuntimeSessionBuilder,
        runtime_executor: RuntimeExecutor,
    ) -> Self {
        Self {
            session_builder,
            runtime_executor,
        }
    }

    /// Routes an authorized request into the execution pipeline.
    pub fn route(
        &self,
        delegation: DelegationGrant,
        requested_operation: String,
    ) -> Result<String, String> {

        // Build an operational execution session.
        let session: ExecutionSession =
            self.session_builder.build_session(
                delegation,
                requested_operation,
            )?;

        // Forward the session for execution.
        self.runtime_executor.execute(session)
    }
}
