package models

import java.time.Instant

/**
 * ------------------------------------------------------------
 * Deployment
 *
 * Represents an infrastructure deployment managed by the
 * Enterprise Orchestrator.
 *
 * A Deployment is the physical execution target inside the
 * infrastructure platform.
 *
 * Authorization decisions are NOT made here.
 *
 * This model is consumed by DeploymentRepository and
 * DeploymentService.
 *
 * NO VULNERABILITY.
 * ------------------------------------------------------------
 */
case class Deployment(

  /**
   * Unique deployment identifier.
   */
  deploymentId: String,

  /**
   * Human-readable deployment name.
   */
  name: String,

  /**
   * Infrastructure resource identifier.
   */
  resourceId: String,

  /**
   * Namespace in which the deployment exists.
   */
  namespace: String,

  /**
   * Kubernetes cluster.
   */
  cluster: String,

  /**
   * Current deployment version.
   */
  version: String,

  /**
   * Desired replica count.
   */
  replicas: Int,

  /**
   * Current runtime status.
   */
  status: String,

  /**
   * Last modification timestamp.
   */
  updatedAt: Instant
) {

  /**
   * Returns true if the deployment
   * is currently active.
   */
  def isRunning: Boolean = {
    status == "Running"
  }

  /**
   * Returns true if the deployment
   * can accept runtime operations.
   */
  def isOperational: Boolean = {
    status match {
      case "Running" | "Ready" => true
      case _ => false
    }
  }

  /**
   * Creates a restarted copy of
   * the deployment.
   */
  def restart: Deployment = {
    copy(
      status = "Restarting",
      updatedAt = Instant.now()
    )
  }

  /**
   * Creates a scaled copy of
   * the deployment.
   */
  def scale(
      replicaCount: Int
  ): Deployment = {

    copy(
      replicas = replicaCount,
      updatedAt = Instant.now()
    )
  }

  /**
   * Updates deployment status.
   */
  def withStatus(
      newStatus: String
  ): Deployment = {

    copy(
      status = newStatus,
      updatedAt = Instant.now()
    )
  }
}
