## FILE: recovery/RecoveryRequestService.go

```
package recovery

import (
	"fmt"
	"time"

	"freelancer-marketplace/storage"
)

type RecoveryRequestService struct {
	UserRepository     storage.UserRepository
	RecoveryRepository storage.RecoveryRepository
}

func (s *RecoveryRequestService)
	CreateRecoveryRequest(
		userID string,
		recoveryEmail string,
	) (*RecoveryRequest, error) {

	identity, err :=
		s.UserRepository.
			LoadIdentity(
				userID,
			)

	if err != nil {
		return nil, err
	}

	if !identity.Active {

		return nil,
			fmt.Errorf(
				"account inactive",
			)
	}

	membership, err :=
		s.UserRepository.
			CurrentMembership(
				userID,
			)

	if err != nil {
		return nil, err
	}

	request :=
		&RecoveryRequest{

			RequestId:
				generateRequestId(),

			UserId:
				userID,

			OrganizationId:
				membership.
					OrganizationId,

			RequestedOrganizationId:
				membership.
					OrganizationId,

			RecoveryEmail:
				recoveryEmail,

			Status:
				"PENDING_APPROVAL",

			CreatedAt:
				time.Now(),

			ExpiresAt:
				time.Now().
					Add(
						72 *
							time.Hour,
					),
		}

	err =
		s.RecoveryRepository.
			SaveRequest(
				request,
			)

	if err != nil {
		return nil, err
	}

	return request, nil
}

func (s *RecoveryRequestService)
	RecoveryContext(
		requestID string,
	) (map[string]string, error) {

	request, err :=
		s.RecoveryRepository.
			LoadRequest(
				requestID,
			)

	if err != nil {
		return nil, err
	}

	return map[string]string{

		"user_id":
			request.UserId,

		"organization_id":
			request.
				OrganizationId,

		"status":
			request.Status,
	}, nil
}

func generateRequestId() string {
	return "rr-" +
		fmt.Sprintf(
			"%d",
			time.Now().
				UnixNano(),
		)
}
