            set;
        } =
            new List<string>();

        public bool CanAuthenticate()
        {
            return Active &&
                   EmailVerified &&
                   !Suspended;
        }

        public bool IsPrivilegedUser()
        {
            foreach (
                var role
                in Roles
            )
            {
                if (
                    role ==
                    "organization-admin"
                )
                {
                    return true;
                }

                if (
                    role ==
                    "security-admin"
                )
                {
                    return true;
                }
            }

            return false;
        }

        public void RecordLogin()
        {
            LastLoginAt =
                DateTime.UtcNow;
        }

        public void RecordRecovery()
        {
            LastRecoveryAt =
                DateTime.UtcNow;
        }

        public void Suspend(
            string reason
        )
        {
            Suspended = true;
        }

        public void Reactivate()
        {
            Suspended = false;
        }

        public bool RequiresRecoveryReview()
        {
            if (
                LastRecoveryAt ==
                DateTime.MinValue
            )
            {
                return false;
            }

            return (
                DateTime.UtcNow -
                LastRecoveryAt
            ).TotalDays < 30;
        }
    }
}
