    ) =

        let credential =

            _.Find(

                credentialId

            )

        let updated =

            { credential with

                Status = status

                RevocationGeneration = generation

            }

        _.ValidateCredential(

            updated

        )

        store.Save(

            updated

        )

    //------------------------------------------------------------------

    member private _.ValidateCredential
    (
        credential : Credential
    ) =

        if String.IsNullOrWhiteSpace(

            credential.CredentialId

        ) then

            invalidOp "Credential identifier missing."

        if String.IsNullOrWhiteSpace(

            credential.StudentId

        ) then

            invalidOp "Student identifier missing."

        if String.IsNullOrWhiteSpace(

            credential.IssuerId

        ) then

            invalidOp "Issuer identifier missing."

        if String.IsNullOrWhiteSpace(

            credential.DelegationScope

        ) then

            invalidOp "Delegation scope missing."

        if credential.RevocationGeneration <= 0 then

            invalidOp "Invalid revocation generation."

        if credential.Status = CredentialStatus.Unknown then

            invalidOp "Invalid credential status."
