const std = @import("std");

pub const ProjectionContext = struct {

    credential_id: []const u8,

    student_id: []const u8,

    issuer_id: []const u8,

    credential_type: []const u8,

    status: []const u8,

    delegation_scope: []const u8,

    revocation_generation: u32,

    issued_at: i64,

    expires_at: i64,

    version: u32,

};

/////////////////////////////////////////////////////////////////

pub fn buildProjectionContext(

    credential: Credential

) !ProjectionContext {

    try validateCredential(

        credential

    );

    var context = ProjectionContext{

        .credential_id =

            credential.credential_id,

        .student_id =

            credential.student_id,

        .issuer_id =

            credential.issuer_id,

        .credential_type =

            credential.credential_type,

        .status =

            credential.status,

        .delegation_scope =

            credential.delegation_scope,

        .revocation_generation =

            credential.revocation_generation,

        .issued_at =

            credential.issued_at,

        .expires_at =

            credential.expires_at,

        .version =

            credential.version,

    };

    normalizeContext(

        &context

    );

    try validateProjection(

        context

    );

    return context;

}

/////////////////////////////////////////////////////////////////

fn validateCredential(

    credential: Credential

) !void {

    if (credential.credential_id.len == 0)

        return error.MissingCredentialId;

    if (credential.student_id.len == 0)

        return error.MissingStudentId;

    if (credential.issuer_id.len == 0)

        return error.MissingIssuerId;

    if (credential.delegation_scope.len == 0)

        return error.MissingDelegationScope;

    if (credential.revocation_generation == 0)

        return error.InvalidGeneration;

}

/////////////////////////////////////////////////////////////////

fn normalizeContext(

    context: *ProjectionContext

) void {

    context.status =

        std.ascii.allocLowerString(

            std.heap.page_allocator,

            context.status

        ) catch context.status;

}

/////////////////////////////////////////////////////////////////

fn validateProjection(

    context: ProjectionContext

) !void {

    if (context.delegation_scope.len == 0)

        return error.InvalidDelegationScope;

    if (context.revocation_generation == 0)

        return error.InvalidGeneration;

    if (context.version == 0)

        return error.InvalidVersion;

}
