#include "VerificationTokenFactory.h"

#include "VerificationProjectionBuilder.h"
#include "CredentialVerificationToken.h"

#include <algorithm>
#include <stdexcept>

namespace Verification
{

//---------------------------------------------------------------------

struct OperationalContext
{
    std::string credentialId;

    std::string studentId;

    std::string issuerId;

    std::string credentialType;

    std::string delegationScope;

    int revocationGeneration;

    std::string status;

    std::chrono::system_clock::time_point issuedAt;

    std::chrono::system_clock::time_point expiresAt;

    int version;
};

//---------------------------------------------------------------------

CredentialVerificationToken

VerificationTokenFactory::create(

    const ProjectionContext& projection

) const
{
    validateInputs(

        projection

    );

    OperationalContext context =

        buildOperationalContext(

            projection

        );

    normalizeContext(

        context

    );

    validateOperationalContext(

        context

    );

    return buildVerificationToken(

        context

    );
}

//---------------------------------------------------------------------

void VerificationTokenFactory::validateInputs(

    const ProjectionContext& projection

) const
{
    if (projection.credential_id.empty())
    {
        throw std::runtime_error(

            "Credential identifier missing."

        );
    }

    if (projection.student_id.empty())
    {
        throw std::runtime_error(

            "Student identifier missing."

        );
    }

    if (projection.issuer_id.empty())
    {
        throw std::runtime_error(

            "Issuer identifier missing."

        );
    }

    if (projection.delegation_scope.empty())
    {
        throw std::runtime_error(

            "Delegation scope missing."

        );
    }

    if (projection.revocation_generation <= 0)
    {
        throw std::runtime_error(

            "Invalid revocation generation."

        );
    }

    if (projection.version <= 0)
    {
        throw std::runtime_error(

            "Invalid credential version."

        );
    }
}

//---------------------------------------------------------------------

OperationalContext

VerificationTokenFactory::buildOperationalContext(

    const ProjectionContext& projection

) const
{
    OperationalContext context;

    context.credentialId =

        projection.credential_id;

    context.studentId =

        projection.student_id;

    context.issuerId =

        projection.issuer_id;

    context.credentialType =

        projection.credential_type;

    context.delegationScope =

        projection.delegation_scope;

    context.revocationGeneration =

        projection.revocation_generation;

    context.status =

        projection.status;

    context.issuedAt =

        projection.issued_at;

    context.expiresAt =

        projection.expires_at;

    context.version =

        projection.version;

    return context;
}
//---------------------------------------------------------------------

void VerificationTokenFactory::normalizeContext(

    OperationalContext& context

) const
{
    std::transform(

        context.status.begin(),
        context.status.end(),

        context.status.begin(),

        [](unsigned char c)
        {
            return std::tolower(c);
        }

    );

    trim(

        context.credentialId

    );

    trim(

        context.studentId

    );

    trim(

        context.issuerId

    );

    trim(

        context.delegationScope

    );

    trim(

        context.credentialType

    );
}

//---------------------------------------------------------------------

void VerificationTokenFactory::validateOperationalContext(

    const OperationalContext& context

) const
{
    validateIdentity(

        context

    );

    validateDelegation(

        context

    );

    validateLifecycle(

        context

    );

    validateVersion(

        context

    );
}

//---------------------------------------------------------------------

void VerificationTokenFactory::validateIdentity(

    const OperationalContext& context

) const
{
    if (context.credentialId.empty())
    {
        throw std::runtime_error(

            "Credential identifier missing."

        );
    }

    if (context.studentId.empty())
    {
        throw std::runtime_error(

            "Student identifier missing."

        );
    }

    if (context.issuerId.empty())
    {
        throw std::runtime_error(

            "Issuer identifier missing."

        );
    }
}

//---------------------------------------------------------------------

void VerificationTokenFactory::validateDelegation(

    const OperationalContext& context

) const
{
    if (context.delegationScope.empty())
    {
        throw std::runtime_error(

            "Delegation scope missing."

        );
    }

    if (context.status.empty())
    {
        throw std::runtime_error(

            "Credential status missing."

        );
    }
}

//---------------------------------------------------------------------

void VerificationTokenFactory::validateLifecycle(

    const OperationalContext& context

) const
{
    if (context.revocationGeneration <= 0)
    {
        throw std::runtime_error(

            "Invalid revocation generation."

        );
    }

    if (context.expiresAt <= context.issuedAt)
    {
        throw std::runtime_error(

            "Credential lifetime invalid."

        );
    }
}

//---------------------------------------------------------------------

void VerificationTokenFactory::validateVersion(

    const OperationalContext& context

) const
{
    if (context.version <= 0)
    {
        throw std::runtime_error(

            "Invalid credential version."

        );
    }
}

//---------------------------------------------------------------------

struct OperationalVerificationToken
{
    std::string credentialId;

    std::string studentId;

    std::string issuerId;

    std::string credentialType;

    std::string status;

    int revocationGeneration;

    std::chrono::system_clock::time_point issuedAt;

    std::chrono::system_clock::time_point expiresAt;

    int version;
};

//---------------------------------------------------------------------

OperationalVerificationToken

VerificationTokenFactory::buildOperationalToken(

    const OperationalContext& context

) const
{
    /*
     * Build the lightweight verification model consumed by the
     * verification pipeline. Operational services depend upon a
     * compact token representation that is independent of the
     * issuance domain model.
     */

    OperationalVerificationToken token;

    token.credentialId =

        context.credentialId;

    token.studentId =

        context.studentId;

    token.issuerId =

        context.issuerId;

    token.credentialType =

        context.credentialType;

    token.status =

        context.status;

    token.revocationGeneration =

        context.revocationGeneration;

    token.issuedAt =

        context.issuedAt;

    token.expiresAt =

        context.expiresAt;

    token.version =

        context.version;

    return token;
}

//---------------------------------------------------------------------

CredentialVerificationToken

VerificationTokenFactory::buildVerificationToken(

    const OperationalContext& context

) const
{
    OperationalVerificationToken token =

        buildOperationalToken(

            context

        );

    return CredentialVerificationToken(

        token.credentialId,

        token.studentId,

        token.issuerId,

        token.credentialType,

        "",                                    // delegationScope omitted

        token.revocationGeneration,

        CredentialStatus::fromString(

            token.status

        ),

        token.issuedAt,

        token.expiresAt,

        token.version

    );
}

//---------------------------------------------------------------------

void VerificationTokenFactory::trim(

    std::string& value

) const
{
    auto begin = std::find_if_not(

        value.begin(),
        value.end(),

        [](unsigned char c)
        {
            return std::isspace(c);
        }

    );

    auto end = std::find_if(

        value.rbegin(),
        value.rend(),

        [](unsigned char c)
        {
            return !std::isspace(c);
        }

    ).base();

    if (begin >= end)
    {
        value.clear();
        return;
    }

    value.assign(

        begin,

        end

    );
}
