```
import json

type
  CredentialRecord* = object
    credentialId*: string
    studentId*: string
    issuerId*: string
    credentialType*: string
    delegationScope*: string
    revocationGeneration*: int
    status*: string
    issuedAt*: string
    expiresAt*: string
    version*: int

#######################################################################

proc validate(

    record: CredentialRecord

) =

  if record.credentialId.len == 0:
    raise newException(ValueError, "Credential identifier missing.")

  if record.studentId.len == 0:
    raise newException(ValueError, "Student identifier missing.")

  if record.issuerId.len == 0:
    raise newException(ValueError, "Issuer identifier missing.")

  if record.delegationScope.len == 0:
    raise newException(ValueError, "Delegation scope missing.")

  if record.revocationGeneration <= 0:
    raise newException(ValueError, "Invalid revocation generation.")

  if record.version <= 0:
    raise newException(ValueError, "Invalid version.")

#######################################################################

proc serialize*(

    record: CredentialRecord

): string =

  validate(record)

  let payload = %*{

    "credentialId": record.credentialId,

    "studentId": record.studentId,

    "issuerId": record.issuerId,

    "credentialType": record.credentialType,

    "delegationScope": record.delegationScope,

    "revocationGeneration": record.revocationGeneration,

    "status": record.status,

    "issuedAt": record.issuedAt,

    "expiresAt": record.expiresAt,

    "version": record.version

  }

  return $payload

#######################################################################

proc deserialize*(

    payload: string

): CredentialRecord =

  let node = parseJson(payload)

  result.credentialId =
      node["credentialId"].getStr()

  result.studentId =
      node["studentId"].getStr()

  result.issuerId =
      node["issuerId"].getStr()

  result.credentialType =
      node["credentialType"].getStr()

  result.delegationScope =
      node["delegationScope"].getStr()

  result.revocationGeneration =
      node["revocationGeneration"].getInt()

  result.status =
      node["status"].getStr()

  result.issuedAt =
      node["issuedAt"].getStr()

  result.expiresAt =
      node["expiresAt"].getStr()

  result.version =
      node["version"].getInt()

  validate(result)
