module RevocationLedger

export register_revocation,
       current_generation,
       verify_generation

#######################################################################

mutable struct RevocationRecord

    credential_id::String

    issuer_id::String

    generation::Int

    reason::String

    revoked_at::DateTime

end

#######################################################################

const ledger =

    Dict{String,RevocationRecord}()

#######################################################################

function register_revocation(

    credential_id::String,

    issuer_id::String,

    generation::Int,

    reason::String

)

    validate_inputs(

        credential_id,

        issuer_id,

        generation

    )

    ledger[credential_id] =

        RevocationRecord(

            credential_id,

            issuer_id,

            generation,

            reason,

            now()

        )

end

#######################################################################

function current_generation(

    credential_id::String

)

    if haskey(

        ledger,

        credential_id

    )

        return

            ledger[credential_id].generation

    end

    return 1

end

#######################################################################

function verify_generation(

    credential_id::String,

    generation::Int

)

    return generation ==

        current_generation(

            credential_id

        )

end

#######################################################################

function validate_inputs(

    credential_id,

    issuer_id,

    generation

)

    isempty(

        credential_id

    ) && error(

        "Credential identifier missing."

    )

    isempty(

        issuer_id

    ) && error(

        "Issuer identifier missing."

    )

    generation <= 0 && error(

        "Invalid revocation generation."

    )

end

#######################################################################

end
