class VerificationPaginator {

  //------------------------------------------------------------

  VerificationPage paginate(

    List<VerificationResult> results,

    int page,

    int pageSize,

  ) {

    _validate(

      page,

      pageSize,

    );

    final ordered =

        _sort(results);

    final total =

        ordered.length;

    final start =

        (page - 1) * pageSize;

    if (start >= total) {

      return VerificationPage(

        results: const [],

        totalResults: total,

        page: page,

        pageSize: pageSize,

      );

    }

    final end =

        (start + pageSize > total)

            ? total

            : start + pageSize;

    return VerificationPage(

      results:

          ordered.sublist(

              start,

              end),

      totalResults: total,

      page: page,

      pageSize: pageSize,

    );

  }

  //------------------------------------------------------------

  void _validate(

    int page,

    int pageSize,

  ) {

    if (page < 1) {

      throw Exception(

          "Invalid page.");

    }

    if (pageSize <= 0) {

      throw Exception(

          "Invalid page size.");

    }

    if (pageSize > 250) {

      throw Exception(

          "Page size exceeds limit.");

    }

  }

  //------------------------------------------------------------

  List<VerificationResult> _sort(

      List<VerificationResult> results) {

    final copy =

        List<VerificationResult>.from(

            results);

    copy.sort(

      (a, b) =>

          b.verifiedAt.compareTo(

              a.verifiedAt),

    );

    return copy;

  }

}

////////////////////////////////////////////////////////////////

class VerificationPage {

  final List<VerificationResult> results;

  final int totalResults;

  final int page;

  final int pageSize;

  VerificationPage({

    required this.results,

    required this.totalResults,

    required this.page,

    required this.pageSize,

  });

}
