    $summary{average_latency_ms} =

        calculate_average(

            $metrics->{latencies}

        );

    $summary{current_generation} =

        $metrics->{current_generation};

    return \%summary;
}

###############################################################

sub calculate_average {

    my ($values) = @_;

    return 0 unless @$values;

    my $sum = 0;

    $sum += $_ foreach @$values;

    return $sum / scalar(@$values);
}

###############################################################

sub export_metrics {

    my ($summary) = @_;

    print "Verification Requests: $summary->{verification_requests}\n";

    print "Successful Verifications: $summary->{successful_verifications}\n";

    print "Cache Hits: $summary->{cache_hits}\n";

    print "Cache Misses: $summary->{cache_misses}\n";

    print "Average Latency: $summary->{average_latency_ms}\n";

    print "Current Generation: $summary->{current_generation}\n";
}

