package com.research.identity.controllers

import com.research.identity.models.FederationProfile
import com.research.identity.services.IdentityMappingService
import com.research.identity.services.UserProvisioningService
import org.slf4j.LoggerFactory
import org.springframework.http.ResponseEntity
import org.springframework.web.bind.annotation.*

@RestController
@RequestMapping("/federation")
class FederationController(

    private val identityMappingService: IdentityMappingService,

    private val userProvisioningService: UserProvisioningService

) {

    private val logger =
        LoggerFactory.getLogger(
            FederationController::class.java
        )

    @GetMapping("/{provider}")
    fun federatedLogin(

        @PathVariable
        provider: String,

        @RequestParam
        userId: String

    ): ResponseEntity<Any> {

        logger.info(
            "Federated login requested. provider={}, user={}",
            provider,
            userId
        )

        val profile =
            loadFederationProfile(
                provider,
                userId
            )

        if (!profile.active) {

            logger.warn(
                "Inactive federation profile. provider={}, user={}",
                provider,
                userId
            )

            return ResponseEntity
                .status(403)
                .body(
                    mapOf(
                        "error" to
                            "Federation account disabled"
                    )
                )
        }

        val mappedIdentity =
            identityMappingService
                .mapFederatedIdentity(
                    profile
                )

        val user =
            userProvisioningService
                .provisionOrUpdateUser(
                    mappedIdentity,
                    profile
                )

        logger.info(
            "Federated login successful. provider={}, user={}, role={}",
            provider,
            user.email,
            user.role
        )

        return ResponseEntity.ok(
            mapOf(
                "id" to user.id,
                "email" to user.email,
                "displayName" to user.displayName,
                "organization" to user.organization,
                "role" to user.role,
                "projects" to mappedIdentity.projects
            )
        )
    }

    private fun loadFederationProfile(
        provider: String,
        userId: String
    ): FederationProfile {

        /*
         * Simulates external federation providers.
         * In production this would be replaced by:
         *
         * SAML
         * OIDC
         * LDAP Federation
         */

        return when (provider.lowercase()) {

            "mit" ->
                FederationProfile(
                    providerId = "MIT",
                    externalUserId = userId,
                    email = "$userId@mit.edu",
                    organization = "MIT",
                    organizationRoles =
                        listOf(
                            "faculty"
                        ),
                    projectRoles =
                        mutableMapOf(
                            "quantum-ai" to
                                "researcher"
                        ),
                    attributes =
                        mutableMapOf(
                            "department" to
                                "Computer Science",
                            "employeeType" to
                                "Faculty"
                        )
                )

            "oxford" ->
                FederationProfile(
                    providerId = "OXFORD",
                    externalUserId = userId,
                    email = "$userId@ox.ac.uk",
                    organization = "Oxford",
                    organizationRoles =
                        listOf(
                            "faculty"
                        ),
                    projectRoles =
                        mutableMapOf(
                            "quantum-ai" to
                                "researcher"
                        ),
                    attributes =
                        mutableMapOf(
                            "department" to
                                "Engineering"
                        )
                )

            "stanford" ->
                FederationProfile(
                    providerId = "STANFORD",
                    externalUserId = userId,
                    email = "$userId@stanford.edu",
                    organization = "Stanford",
                    organizationRoles =
                        listOf(
                            "researcher"
                        ),
                    projectRoles =
                        mutableMapOf(
                            "quantum-ai" to
                                "researcher"
                        ),
                    attributes =
                        mutableMapOf(
                            "department" to
                                "AI Lab"
                        )
                )

            else ->
                throw IllegalArgumentException(
                    "Unsupported provider"
                )
        }
    }
}
