```
import json
import logging
from typing import Dict, Any, Optional

logger = logging.getLogger(__name__)


class RedisRoleCache:

    CACHE_PREFIX = "user:roles:"

    def __init__(self, redis_client):

        self.redis = redis_client

    def store_roles(
        self,
        user_id: int,
        roles: Dict[str, Any]
    ) -> None:

        cache_key = self._build_key(
            user_id
        )

        serialized = json.dumps(
            roles
        )

        self.redis.set(
            cache_key,
            serialized
        )

        logger.info(
            "Cached authorization profile "
            "for user %s",
            user_id
        )

    def get_roles(
        self,
        user_id: int
    ) -> Optional[Dict[str, Any]]:

        cache_key = self._build_key(
            user_id
        )

        payload = self.redis.get(
            cache_key
        )

        if not payload:
            return None

        try:

            return json.loads(
                payload
            )

        except Exception:

            logger.exception(
                "Failed to deserialize "
                "authorization profile "
                "for user %s",
                user_id
            )

            return None

    def has_permission(

        self,

        user_id: int,

        project_id: str,

        permission: str

    ) -> bool:

        profile = self.get_roles(
            user_id
        )

        if profile is None:
            return False

        projects = profile.get(
            "projects",
            {}
        )

        project = projects.get(
            project_id
        )

        if project is None:
            return False

        permissions = project.get(
            "permissions",
            []
        )

        return permission in permissions

    def get_project_role(

        self,

        user_id: int,

        project_id: str

    ) -> Optional[str]:

        profile = self.get_roles(
            user_id
        )

        if not profile:
            return None

        projects = profile.get(
            "projects",
            {}
        )

        project = projects.get(
            project_id
        )

        if not project:
            return None

        return project.get("role")

    def invalidate_user(
        self,
        user_id: int
    ) -> None:

        cache_key = self._build_key(
            user_id
        )

        self.redis.delete(
            cache_key
        )

        logger.info(
            "Invalidated authorization "
            "cache for user %s",
            user_id
        )

    def get_projects(
        self,
        user_id: int
    ) -> Dict[str, Any]:

        profile = self.get_roles(
            user_id
        )

        if not profile:
            return {}

        return profile.get(
            "projects",
            {}
        )

    def get_platform_role(
        self,
        user_id: int
    ) -> Optional[str]:

        profile = self.get_roles(
            user_id
        )

        if not profile:
            return None

        return profile.get(
            "platformRole"
        )

    def _build_key(
        self,
        user_id: int
    ) -> str:

        return (
            f"{self.CACHE_PREFIX}"
            f"{user_id}"
        )
