package com.research.identity.repositories

import com.research.identity.models.FederationProfile
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Repository
import java.time.Instant
import java.util.concurrent.ConcurrentHashMap

@Repository
class FederationRepository {

    private val logger =
        LoggerFactory.getLogger(
            FederationRepository::class.java
        )

    private val profiles =
        ConcurrentHashMap<String,
                FederationProfile>()

    init {

        seedProfiles()
    }

    fun findProfile(

        providerId: String,

        externalUserId: String

    ): FederationProfile? {

        val key =
            buildKey(
                providerId,
                externalUserId
            )

        return profiles[key]
    }

    fun saveProfile(
        profile: FederationProfile
    ) {

        val key =
            buildKey(
                profile.providerId,
                profile.externalUserId
            )

        profiles[key] = profile
    }

    fun updateSyncTime(

        providerId: String,

        externalUserId: String

    ) {

        findProfile(
            providerId,
            externalUserId
        )?.updateSyncTime()
    }

    fun getOrganizationRoles(

        providerId: String,

        externalUserId: String

    ): List<String> {

        return findProfile(
            providerId,
            externalUserId
        )?.organizationRoles

            ?: emptyList()
    }

    fun getProjectRoles(

        providerId: String,

        externalUserId: String

    ): Map<String, String> {

        return findProfile(
            providerId,
            externalUserId
        )?.projectRoles

            ?: emptyMap()
    }

    fun getFederationAttributes(

        providerId: String,

        externalUserId: String

    ): Map<String, String> {

        return findProfile(
            providerId,
            externalUserId
        )?.attributes

            ?: emptyMap()
    }

    fun deactivateProfile(

        providerId: String,

        externalUserId: String

    ) {

        findProfile(
            providerId,
            externalUserId
        )?.deactivate()
    }

    fun activateProfile(

        providerId: String,

        externalUserId: String

    ) {

        findProfile(
            providerId,
            externalUserId
        )?.activate()
    }

    fun findByOrganization(
        organization: String
    ): List<FederationProfile> {

        return profiles.values.filter {

            it.organization.equals(
                organization,
                ignoreCase = true
            )
        }
    }

    private fun buildKey(

        providerId: String,

        externalUserId: String

    ): String {

        return "$providerId:$externalUserId"
    }

    private fun seedProfiles() {

        val mitUser =
            FederationProfile(

                providerId = "MIT",

                externalUserId = "researcher1",

                email =
                    "researcher1@mit.edu",

                organization = "MIT",

                organizationRoles =
                    listOf(
