@Component
class RolePolicy {

    fun canViewProject(
        role: ProjectRole
    ): Boolean {

        return true
    }

    fun canEditProject(
        role: ProjectRole
    ): Boolean {

        return role ==
                ProjectRole.DATA_MANAGER ||

                role ==
                ProjectRole.PROJECT_ADMIN ||

                role ==
                ProjectRole.PRINCIPAL_INVESTIGATOR
    }

    fun canManageDatasets(
        role: ProjectRole
    ): Boolean {

        return role.canManageDatasets()
    }

    fun canManageCollaborators(
        role: ProjectRole
    ): Boolean {

        return role.canManageCollaborators()
    }

    fun canManageBudgets(
        role: ProjectRole
    ): Boolean {

        return role.canManageBudgets()
    }

    fun canExportResearchData(
        role: ProjectRole
    ): Boolean {

        return role.canExportData()
    }

    fun canDeleteProject(
        role: ProjectRole
    ): Boolean {

        return role ==
                ProjectRole
                    .PRINCIPAL_INVESTIGATOR
    }

    fun canModifyComplianceRules(
        role: ProjectRole
    ): Boolean {

        return role ==
                ProjectRole
                    .PRINCIPAL_INVESTIGATOR
    }

    fun canApproveResearchers(
        role: ProjectRole
    ): Boolean {

        return role ==
                ProjectRole
                    .PROJECT_ADMIN ||

                role ==
                ProjectRole
                    .PRINCIPAL_INVESTIGATOR
    }

    fun canManageFunding(
        role: ProjectRole
    ): Boolean {

        return role ==
                ProjectRole
                    .PRINCIPAL_INVESTIGATOR
    }
}
