const express = require("express");
const axios = require("axios");

const router = express.Router();

const PROVIDERS = {

    mit:
        "http://identity-service/federation/mit",

    oxford:
        "http://identity-service/federation/oxford",

    stanford:
        "http://identity-service/federation/stanford"
};

router.get(
    "/login",
    async (req, res) => {

        try {

            const provider =
                req.query.provider;

            const userId =
                req.query.user;

            const endpoint =
                PROVIDERS[provider];

            if (!endpoint) {

                return res
                    .status(400)
                    .json({
                        error:
                            "Unknown provider"
                    });
            }

            const response =
                await axios.get(
                    endpoint,
                    {
                        params: {
                            userId
                        }
                    }
                );

            const user =
                response.data;

            req.session.user = {

                id: user.id,
                email: user.email,
                displayName:
                    user.displayName,
                organization:
                    user.organization,
                role:
                    user.role,
                projects:
                    user.projects
            };

            return res.redirect(
                "/dashboard"
            );

        } catch (err) {

            console.error(
                "Federation login failed",
                err.message
            );

            return res
                .status(500)
                .json({
                    error:
                        "Federation login failed"
                });
        }
    }
);

module.exports = router;
