package com.research.identity.services

import com.research.identity.models.ProjectRole
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Component

@Component
class RoleTranslator {

    private val logger =
        LoggerFactory.getLogger(
            RoleTranslator::class.java
        )

    /*
     * Maps federation-provided organization roles
     * into platform roles.
     *
     * Examples:
     * faculty -> researcher
     * department_admin -> project_admin
     */

    fun translateOrganizationRoles(
        organizationRoles: List<String>
    ): ProjectRole {

        logger.debug(
            "Translating organization roles {}",
            organizationRoles
        )

        if (organizationRoles.isEmpty()) {
            return ProjectRole.RESEARCHER
        }

        if (organizationRoles.any {
                equalsIgnoreCase(
                    it,
                    "principal_investigator"
                )
            }) {

            return ProjectRole.PRINCIPAL_INVESTIGATOR
        }

        if (organizationRoles.any {
                equalsIgnoreCase(
                    it,
                    "department_admin"
                )
            }) {

            return ProjectRole.PROJECT_ADMIN
        }

        if (organizationRoles.any {
                equalsIgnoreCase(
                    it,
                    "faculty"
                )
            }) {

            return ProjectRole.RESEARCHER
        }

        if (organizationRoles.any {
                equalsIgnoreCase(
                    it,
                    "researcher"
                )
            }) {

            return ProjectRole.RESEARCHER
        }

        return ProjectRole.RESEARCHER
    }

    /*
     * Used by provisioning flows
     * to determine whether a role
     * should be synchronized.
     */

    fun isRecognizedRole(
        role: String
    ): Boolean {

        return when (
            role.lowercase()
        ) {

            "faculty",
            "researcher",
            "department_admin",
            "principal_investigator" -> true

            else -> false
        }
    }

    /*
     * Federation providers may use
     * different naming conventions.
     */

    fun normalizeRole(
        role: String
    ): String {

        return role
            .trim()
            .lowercase()
            .replace("-", "_")
            .replace(" ", "_")
    }

    fun normalizeRoles(
        roles: List<String>
    ): List<String> {

        return roles.map {
            normalizeRole(it)
        }
    }

    fun translateProviderRole(
        provider: String,
        role: String
    ): String {

        val normalized =
            normalizeRole(role)

        return when (
            provider.lowercase()
        ) {

            "mit" ->
                translateMitRole(
                    normalized
                )

            "oxford" ->
                translateOxfordRole(
                    normalized
                )

            "stanford" ->
                translateStanfordRole(
                    normalized
                )

            else ->
                normalized
        }
    }

    private fun translateMitRole(
        role: String
    ): String {

        return when (role) {

            "faculty_member" ->
                "faculty"

            else ->
                role
        }
    }

    private fun translateOxfordRole(
        role: String
    ): String {

        return when (role) {

            "academic_staff" ->
                "faculty"

            else ->
                role
        }
    }

    private fun translateStanfordRole(
        role: String
    ): String {

        return when (role) {

            "research_faculty" ->
                "faculty"

            else ->
                role
        }
    }

    private fun equalsIgnoreCase(
        left: String,
        right: String
    ): Boolean {

        return left.equals(
            right,
            ignoreCase = true
        )
    }
}
