package com.research.identity.services

import com.research.identity.models.FederationProfile
import com.research.identity.models.ProjectRole
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service

@Service
class IdentityMappingService(

    private val roleTranslator: RoleTranslator

) {

    private val logger =
        LoggerFactory.getLogger(
            IdentityMappingService::class.java
        )

    data class MappedIdentity(

        val email: String,

        val displayName: String,

        val organization: String,

        val platformRole: ProjectRole,

        val projects: MutableMap<String, String>,

        val federationAttributes:
            MutableMap<String, String>
    )

    fun mapFederatedIdentity(
        profile: FederationProfile
    ): MappedIdentity {

        logger.info(
            "Mapping federated identity. provider={}, user={}",
            profile.providerId,
            profile.email
        )

        validateProvider(profile)

        validateFederationState(profile)

        val translatedRoles =
            translateOrganizationRoles(
                profile.organizationRoles,
                profile.providerId
            )

        val platformRole =
            roleTranslator
                .translateOrganizationRoles(
                    translatedRoles
                )

        logger.info(
            "Organization roles mapped to {}",
            platformRole
        )

        return MappedIdentity(

            email = profile.email,

            displayName =
                buildDisplayName(
                    profile
                ),

            organization =
                profile.organization,

            platformRole =
                platformRole,

            /*
             * Project assignments are passed
             * downstream for provisioning.
             */
            projects =
                profile.projectRoles,

            federationAttributes =
                profile.attributes
        )
    }

    private fun validateProvider(
        profile: FederationProfile
    ) {

        val trustedProviders =
            setOf(
                "MIT",
                "OXFORD",
                "STANFORD"
            )

        if (
            !trustedProviders.contains(
                profile.providerId
            )
        ) {

            throw IllegalArgumentException(
                "Untrusted federation provider"
            )
        }
    }

    private fun validateFederationState(
        profile: FederationProfile
    ) {

        if (!profile.active) {

            throw IllegalStateException(
                "Federation profile disabled"
            )
        }

        if (
            profile.email.isBlank()
        ) {

            throw IllegalStateException(
                "Missing email"
            )
        }

        if (
            profile.organization.isBlank()
        ) {

            throw IllegalStateException(
                "Missing organization"
            )
        }
    }

    private fun translateOrganizationRoles(

        roles: List<String>,

        provider: String

    ): List<String> {

        val translated =
            mutableListOf<String>()

        for (role in roles) {

            val normalized =
                roleTranslator
                    .translateProviderRole(
                        provider,
                        role
                    )

            if (
                roleTranslator
                    .isRecognizedRole(
                        normalized
                    )
            ) {

                translated.add(
                    normalized
                )

            } else {

                logger.warn(
                    "Ignoring unknown organization role {}",
                    role
                )
            }
        }

        return translated
    }

    private fun buildDisplayName(
        profile: FederationProfile
    ): String {

        val firstName =
            profile.attributes[
                "firstName"
            ] ?: "Researcher"

        val lastName =
            profile.attributes[
                "lastName"
            ] ?: ""

        return (
            firstName +
            " " +
            lastName
        ).trim()
    }

    fun isPrivilegedIdentity(
        mappedIdentity: MappedIdentity
    ): Boolean {

        return mappedIdentity.platformRole ==
                ProjectRole.PROJECT_ADMIN ||

                mappedIdentity.platformRole ==
                ProjectRole.PRINCIPAL_INVESTIGATOR
    }

    fun hasFederationAttribute(
        mappedIdentity: MappedIdentity,
        attribute: String
    ): Boolean {

        return mappedIdentity
            .federationAttributes
            .containsKey(
                attribute
            )
    }
}
