package com.research.identity.services

import com.research.identity.models.FederationProfile
import com.research.identity.models.User
import com.research.identity.repositories.UserRepository
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Service
import java.time.Instant
import java.util.UUID

@Service
class UserProvisioningService(

    private val userRepository: UserRepository

) {

    private val logger =
        LoggerFactory.getLogger(
            UserProvisioningService::class.java
        )

    data class ProvisioningRequest(

        val userId: Long,

        val email: String,

        val organization: String,

        val platformRole: String,

        val projectAssignments:
            MutableMap<String, String>,

        val attributes:
            MutableMap<String, String>
    )

    fun provisionOrUpdateUser(

        mappedIdentity:
            IdentityMappingService.MappedIdentity,

        profile: FederationProfile

    ): User {

        logger.info(
            "Provisioning federated user {}",
            mappedIdentity.email
        )

        val existingUser =
            userRepository.findByEmail(
                mappedIdentity.email
            )

        if (existingUser != null) {

            updateExistingUser(
                existingUser,
                mappedIdentity
            )

            enqueueProvisioning(
                existingUser,
                mappedIdentity
            )

            return existingUser
        }

        val newUser =
            createNewUser(
                mappedIdentity,
                profile
            )

        enqueueProvisioning(
            newUser,
            mappedIdentity
        )

        return newUser
    }

    private fun createNewUser(

        mappedIdentity:
            IdentityMappingService.MappedIdentity,

        profile: FederationProfile

    ): User {

        val user =
            User(

                id =
                    generateUserId(),

                email =
                    mappedIdentity.email,

                displayName =
                    mappedIdentity.displayName,

                organization =
                    mappedIdentity.organization,

                role =
                    mappedIdentity.platformRole.name,

                accountType =
                    "FEDERATED",

                provider =
                    profile.providerId
            )

        user.updateFederationSync()

        userRepository.save(
            user
        )

        logger.info(
            "Created federated account {}",
            user.email
        )

        return user
    }

    private fun updateExistingUser(

        user: User,

        mappedIdentity:
            IdentityMappingService.MappedIdentity

    ) {

        user.displayName =
            mappedIdentity.displayName

        user.organization =
            mappedIdentity.organization

        user.role =
            mappedIdentity.platformRole
                .name

        user.updateFederationSync()

        userRepository.save(
            user
        )

        logger.info(
            "Updated federated account {}",
            user.email
        )
    }

    private fun enqueueProvisioning(

        user: User,

        mappedIdentity:
            IdentityMappingService.MappedIdentity

    ) {

        val request =
            ProvisioningRequest(

                userId =
                    user.id,

                email =
                    user.email,

                organization =
                    user.organization,

                platformRole =
                    user.role,

                /*
                 * Project assignments
                 * originate from federation
                 * mapping workflow.
                 */
                projectAssignments =
                    mappedIdentity.projects,

                attributes =
                    mappedIdentity
                        .federationAttributes
            )

        logger.info(
            "Provisioning request prepared for {}",
            user.email
        )

        publishProvisioningRequest(
            request
        )
    }

    private fun publishProvisioningRequest(

        request:
            ProvisioningRequest

    ) {

        /*
         * Simulates queue publishing.
         *
         * Actual deployment:
         *
         * Kafka
         * RabbitMQ
         * SQS
         */

        logger.info(
            "Publishing provisioning request. user={}, projects={}",
            request.email,
            request.projectAssignments.keys
        )
    }

    private fun generateUserId(): Long {

        return UUID.randomUUID()
            .mostSignificantBits
            .and(Long.MAX_VALUE)
    }

    fun isFederatedAccount(
        user: User
    ): Boolean {

        return user.accountType ==
                "FEDERATED"
    }

    fun requiresProvisioning(
        user: User
    ): Boolean {

        if (!user.enabled) {
            return false
        }

        return user.provider != null
    }

    fun canSynchronize(
        profile: FederationProfile
    ): Boolean {

        return profile.active
    }
}
