import logging
from typing import Dict, Any

from cache.RedisRoleCache import RedisRoleCache

logger = logging.getLogger(__name__)


class ProvisioningWorker:

    def __init__(
        self,
        role_cache: RedisRoleCache
    ):

        self.role_cache = role_cache

    def process_provisioning_event(
        self,
        event: Dict[str, Any]
    ) -> None:

        logger.info(
            "Processing provisioning event for %s",
            event.get("email")
        )

        self._validate_event(event)

        user_id = event["userId"]

        organization = event["organization"]

        platform_role = event["platformRole"]

        project_assignments = \
            event.get(
                "projectAssignments",
                {}
            )

        access_profile = \
            self._build_access_profile(
                organization,
                platform_role,
                project_assignments
            )

        self.role_cache.store_roles(
            user_id=user_id,
            roles=access_profile
        )

        logger.info(
            "Provisioning completed for %s",
            event["email"]
        )

    def _validate_event(
        self,
        event: Dict[str, Any]
    ) -> None:

        required_fields = [

            "userId",
            "email",
            "organization",
            "platformRole"
        ]

        for field in required_fields:

            if field not in event:

                raise ValueError(
                    f"Missing field {field}"
                )

    def _build_access_profile(

        self,

        organization: str,

        platform_role: str,

        project_assignments: Dict[
            str,
            str
        ]

    ) -> Dict[str, Any]:

        profile = {

            "organization":
                organization,

            "platformRole":
                platform_role,

            "projects":
                {}
        }

        for project_id, role \
                in project_assignments.items():

            profile["projects"][
                project_id
            ] = {

                "role": role,

                "permissions":
                    self._permissions_for_role(
                        role
                    )
            }

        return profile

    def _permissions_for_role(
        self,
        role: str
    ):

        role = role.upper()

        if role == \
                "PRINCIPAL_INVESTIGATOR":

            return [

                "project.read",
                "project.write",
                "budget.manage",
                "dataset.export",
                "collaborator.manage"
            ]

        if role == \
                "PROJECT_ADMIN":

            return [

                "project.read",
                "project.write",
                "dataset.export",
                "collaborator.manage"
            ]

        if role == \
                "DATA_MANAGER":

            return [

                "project.read",
                "dataset.export"
            ]

        return [

            "project.read"
        ]
