                    ),

                attributes =
                    mutableMapOf(

                        "department" to
                                "Computer Science",

                        "employeeType" to
                                "Faculty"
                    ),

                lastSyncTime =
                    Instant.now()
            )

        saveProfile(
            mitUser
        )
    }
}
