package com.research.identity.repositories

import com.research.identity.models.User
import org.slf4j.LoggerFactory
import org.springframework.stereotype.Repository
import java.time.Instant
import java.util.concurrent.ConcurrentHashMap

@Repository
class UserRepository {

    private val logger =
        LoggerFactory.getLogger(
            UserRepository::class.java
        )

    private val users =
        ConcurrentHashMap<Long, User>()

    fun save(
        user: User
    ): User {

        users[user.id] = user

        logger.debug(
            "Saved user {}",
            user.email
        )

        return user
    }

    fun findById(
        userId: Long
    ): User? {

        return users[userId]
    }

    fun findByEmail(
        email: String
    ): User? {

        return users.values.firstOrNull {

            it.email.equals(
                email,
                ignoreCase = true
            )
        }
    }

    fun findByProvider(

        provider: String,

        externalId: String

    ): User? {

        return users.values.firstOrNull {

            it.provider?.equals(
                provider,
                ignoreCase = true
            ) == true &&

            it.getAttribute(
                "externalUserId"
            ) == externalId
        }
    }

    fun updateRole(

        userId: Long,

        role: String

    ) {

        val user =
            users[userId]
                ?: return

        user.updateRole(role)

        logger.info(
            "Updated role for {} -> {}",
            user.email,
            role
        )
    }

    fun updateLastLogin(
        userId: Long
    ) {

        val user =
            users[userId]
                ?: return

        user.updateLastLogin()
    }

    fun updateFederationSync(
        userId: Long
    ) {

        val user =
            users[userId]
                ?: return

        user.lastFederationSync =
            Instant.now()
    }

    fun disableUser(
        userId: Long
    ) {

        val user =
            users[userId]
                ?: return

        user.disableAccount()
    }

    fun enableUser(
        userId: Long
    ) {

        val user =
            users[userId]
                ?: return

        user.enableAccount()
    }

    fun findByOrganization(
        organization: String
    ): List<User> {

        return users.values.filter {

            it.organization.equals(
                organization,
                ignoreCase = true
            )
        }
    }

    fun findFederatedUsers():
            List<User> {

        return users.values.filter {

            it.isFederated()
        }
    }

    fun delete(
        userId: Long
    ) {

        users.remove(userId)
    }

    fun count(): Int {

        return users.size
    }

    fun findAll():
            List<User> {

        return users.values.toList()
    }
}
