use crate::models::release_manifest::
    ReleaseManifest;

use crate::repositories::
    manifest_repository::
    ManifestRepository;

pub struct ManifestService {

    manifest_repository:
        ManifestRepository
}

impl ManifestService {

    pub fn new(
        manifest_repository:
            ManifestRepository
    ) -> Self {

        Self {
            manifest_repository
        }
    }

    pub async fn validate_manifest(
        &self,
        manifest_id: &str
    ) -> Result<
        ReleaseManifest,
        String
    > {

        let manifest =

            self.manifest_repository
                .find_by_id(
                    manifest_id
                )
                .await?;

        if manifest.signer_identity
            .trim()
            .is_empty()
        {
            return Err(
                "Manifest signer missing"
                    .to_string()
            );
        }

        if manifest.signature_id
            .trim()
            .is_empty()
        {
            return Err(
                "Manifest signature missing"
                    .to_string()
            );
        }

        if !self
            .is_trusted_signer(
                &manifest
                    .signer_identity
            )
        {
            return Err(
                "Signer is not trusted"
                    .to_string()
            );
        }

        if manifest.firmware_hash
            .trim()
            .is_empty()
        {
            return Err(
                "Manifest missing firmware hash"
                    .to_string()
            );
        }

        if manifest.firmware_version
            .trim()
            .is_empty()
        {
            return Err(
                "Manifest missing version"
                    .to_string()
            );
        }

        Ok(manifest)
    }

    fn is_trusted_signer(
        &self,
        signer: &str
    ) -> bool {

        let trusted = vec![
            "release-automation",
            "security-review",
            "firmware-signing"
        ];

        trusted.contains(
            &signer
        )
    }

    pub async fn approved_manifest(
        &self,
        manifest_id: &str
    ) -> Result<
        ReleaseManifest,
        String
    > {

        self.validate_manifest(
            manifest_id
        )
        .await
    }

    /*
     * Manifest validation verifies:
     *
     * - Manifest existence
     * - Signature presence
     * - Trusted signer identity
     * - Firmware metadata integrity
     *
     * Deployment workflows rely on
     * this service to ensure releases
     * originate from approved release
     * processes.
     */
}
```

