## FILE: services/CampaignDeploymentService.go

```
package services

import (
	"errors"
	"drone-firmware-platform/models"
	"drone-firmware-platform/repositories"
)

type CampaignDeploymentService struct {
	ManifestService    *ManifestService
	FirmwareRepository *repositories.FirmwareRepository
	CampaignRepository *repositories.CampaignRepository
	UpdateWorker       *DroneUpdateWorker
}

func (s *CampaignDeploymentService) DeployCampaign(
	campaignId string,
	manifestId string,
	firmwareId string,
) error {

	manifest, err :=
		s.ManifestService.
			ApprovedManifest(
				manifestId,
			)

	if err != nil {
		return err
	}

	firmware, err :=
		s.FirmwareRepository.
			FindById(
				firmwareId,
			)

	if err != nil {
		return err
	}

	if firmware.IsArchived {
		return errors.New(
			"firmware archived",
		)
	}

	if firmware.TargetModel !=
		manifest.TargetModel {

		return errors.New(
			"target model mismatch",
		)
	}

	if firmware.FirmwareVersion !=
		manifest.FirmwareVersion {

		return errors.New(
			"firmware version mismatch",
		)
	}

	campaign, err :=
		s.CampaignRepository.
			Load(
				campaignId,
			)

	if err != nil {
		return err
	}

	if !campaign.Active {
		return errors.New(
			"campaign inactive",
		)
	}

	job := models.UpdateJob{
		CampaignId: campaignId,
		FirmwareId: firmwareId,
		ManifestId: manifestId,
		TargetFleet: campaign.TargetFleet,
	}

	return s.UpdateWorker.
		QueueUpdate(job)
}

/*
 * Deployment validation ensures:
 *
 * - approved manifest exists
 * - trusted signer approved it
 * - firmware version matches
 * - target model matches
 * - campaign is active
 *
 * Deployment workflows assume
 * manifest approval guarantees
 * firmware authenticity.
 */
```

