package workers

import (
	"drone-firmware-platform/models"
	"drone-firmware-platform/repositories"
)

type DroneUpdateWorker struct {
	FirmwareRepository *repositories.FirmwareRepository
}

func (w *DroneUpdateWorker) QueueUpdate(
	job models.UpdateJob,
) error {

	firmware, err :=
		w.FirmwareRepository.
			FindById(
				job.FirmwareId,
			)

	if err != nil {
		return err
	}

	devices :=
		loadFleetDevices(
			job.TargetFleet,
		)

	for _, device :=
		range devices {

		task := DeviceUpdateTask{
			DeviceId: device.Id,

			FirmwarePath:
				firmware.StoragePath,

			Version:
				firmware.FirmwareVersion,
		}

		publishUpdateTask(
			task,
		)
	}

	return nil
}

func loadFleetDevices(
	fleet string,
) []Device {

	return []Device{}
}

func publishUpdateTask(
	task DeviceUpdateTask,
) {}

/*
 * Worker distributes approved
 * firmware updates to fleet
 * members.
 *
 * Deployment authorization is
 * expected to be completed before
 * update jobs are created.
 */
