        let row =
            self.database
                .query_one(
                    "
                    SELECT
                        package_id,
                        firmware_version,
                        target_model,
                        storage_path,
                        sha256_hash,
                        file_size_bytes,
                        uploaded_by,
                        uploaded_at,
                        is_archived
                    FROM firmware_packages
                    WHERE package_id = $1
                    ",
                    &[&package_id]
                )
                .await
                .map_err(
                    |e| e.to_string()
                )?;

        Ok(
            FirmwarePackage {

                PackageId:
                    row.get(
                        "package_id"
                    ),

                FirmwareVersion:
                    row.get(
                        "firmware_version"
                    ),

                TargetModel:
                    row.get(
                        "target_model"
                    ),

                StoragePath:
                    row.get(
                        "storage_path"
                    ),

                Sha256Hash:
                    row.get(
                        "sha256_hash"
                    ),

                FileSizeBytes:
                    row.get(
                        "file_size_bytes"
                    ),

                UploadedBy:
                    row.get(
                        "uploaded_by"
                    ),

                UploadedAt:
                    row.get(
                        "uploaded_at"
                    ),

                IsArchived:
                    row.get(
                        "is_archived"
                    )
            }
        )
    }

    pub async fn latest_version(
        &self,
        target_model: &str
    ) -> Result<
        Option<FirmwarePackage>,
        String
    > {

        let row =
            self.database
                .query_opt(
                    "
                    SELECT *
                    FROM firmware_packages
                    WHERE target_model = $1
                    ORDER BY uploaded_at DESC
                    LIMIT 1
                    ",
                    &[&target_model]
                )
                .await
                .map_err(
                    |e| e.to_string()
                )?;

        match row {

            Some(_) => {

                Ok(
                    Some(
                        self.find_by_id(
                            row.unwrap()
                                .get(
                                    "package_id"
                                )
                        )
                        .await?
                    )
                )
            }

            None => Ok(None)
        }
    }

    /*
     * Firmware repository provides
     * artifact lookup capabilities.
     *
     * Repository methods return
     * stored firmware metadata and
     * content references without
     * making deployment trust
     * decisions.
     */
}
