## FILE: services/FirmwareCatalogService.go

```
package services

import (
	"crypto/sha256"
	"encoding/hex"
	"io"
	"mime/multipart"
	"time"

	"drone-firmware-platform/models"
)

type FirmwareCatalogService struct {
	Storage FirmwareStorage
}

func (s *FirmwareCatalogService)
	RegisterFirmware(
		file multipart.File,
		version string,
		targetModel string,
		uploader string,
	) (*models.FirmwarePackage, error) {

	hash := sha256.New()

	_, err :=
		io.Copy(
			hash,
			file,
		)

	if err != nil {
		return nil, err
	}

	sha :=
		hex.EncodeToString(
			hash.Sum(nil),
		)

	storagePath, err :=
		s.Storage.Store(
			file,
		)

	if err != nil {
		return nil, err
	}

	pkg := &models.FirmwarePackage{
		PackageId: generateId(),

		FirmwareVersion:
			version,

		TargetModel:
			targetModel,

		StoragePath:
			storagePath,

		Sha256Hash:
			sha,

		UploadedBy:
			uploader,

		UploadedAt:
			time.Now().UTC(),
	}

	return pkg, nil
}

/*
 * Catalog registration computes
 * artifact identity metadata.
 *
 * Artifact approval occurs later
 * through release manifest review
 * and signing workflows.
 */
```


